{
  "name": "ModaGestão - Vendas a Prazo",
  "description": "Um sistema completo para lojas de roupas gerenciarem vendas a prazo, parcelamentos e abatimentos, com insights inteligentes via Gemini.",
  "requestFramePermissions": [
    "camera"
  ]
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  createdAt: number;
}

export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  PARTIAL = 'PARTIAL'
}

export interface Installment {
  id: string;
  saleId: string;
  amount: number;
  paidAmount: number;
  dueDate: string;
  status: PaymentStatus;
}

export interface Sale {
  id: string;
  customerId: string;
  description: string;
  totalAmount: number;
  date: string;
  installments: Installment[];
  status: PaymentStatus;
}

export interface PaymentLog {
  id: string;
  installmentId: string;
  amount: number;
  date: string;
}

export type View = 'dashboard' | 'customers' | 'sales' | 'assistant';

import { GoogleGenAI, Type } from "@google/genai";
import { Sale, Customer, Installment } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const getFinancialInsights = async (
  sales: Sale[],
  customers: Customer[]
) => {
  const model = "gemini-3-flash-preview";

  const context = {
    totalSales: sales.length,
    totalVolume: sales.reduce((acc, s) => acc + s.totalAmount, 0),
    customersCount: customers.length,
    pendingPayments: sales.flatMap(s => s.installments).filter(i => i.status !== 'PAID').length,
    sampleData: sales.slice(0, 10).map(s => ({
      desc: s.description,
      total: s.totalAmount,
      date: s.date
    }))
  };

  const prompt = `Analise os seguintes dados financeiros de uma loja de roupas e forneça 3 insights estratégicos curtos sobre vendas a prazo e cobranças. Seja profissional e direto em português brasileiro.
  Dados: ${JSON.stringify(context)}`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        temperature: 0.7,
        maxOutputTokens: 500,
      }
    });

    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Não foi possível gerar insights no momento. Verifique sua conexão.";
  }
};

import React, { useState, useEffect } from 'react';
import { Sale, Customer, PaymentStatus } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DashboardProps {
  sales: Sale[];
  customers: Customer[];
}

const Dashboard: React.FC<DashboardProps> = ({ sales, customers }) => {
  const [insights, setInsights] = useState<string>('Carregando insights inteligentes...');
  const [isSyncing, setIsSyncing] = useState(false);

  const totalReceivable = sales.reduce((acc, s) => {
    return acc + s.installments.reduce((sum, i) => sum + (i.amount - i.paidAmount), 0);
  }, 0);

  const totalReceived = sales.reduce((acc, s) => {
    return acc + s.installments.reduce((sum, i) => sum + i.paidAmount, 0);
  }, 0);

  const overdueSales = sales.filter(s => 
    s.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date())
  );

  const chartData = [
    { name: 'Recebido', value: totalReceived, color: '#10b981' },
    { name: 'A Receber', value: totalReceivable, color: '#6366f1' },
  ];

  const fetchInsights = async () => {
    setIsSyncing(true);
    const result = await getFinancialInsights(sales, customers);
    setInsights(result || "Nenhum insight disponível.");
    setIsSyncing(false);
  };

  useEffect(() => {
    fetchInsights();
  }, [sales.length]);

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">Total a Receber</p>
          <h3 className="text-2xl font-bold text-indigo-600">R$ {totalReceivable.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</h3>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">Total Recebido</p>
          <h3 className="text-2xl font-bold text-emerald-600">R$ {totalReceived.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</h3>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">Vendas em Atraso</p>
          <h3 className="text-2xl font-bold text-rose-500">{overdueSales.length}</h3>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-80">
          <h4 className="font-semibold text-slate-800 mb-4">Fluxo de Caixa (Pendentes vs Recebidos)</h4>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} />
              <YAxis axisLine={false} tickLine={false} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
              <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-indigo-50 p-6 rounded-2xl border border-indigo-100 flex flex-col h-80 overflow-hidden">
          <div className="flex justify-between items-center mb-4">
            <h4 className="font-bold text-indigo-900 flex items-center gap-2">
              <svg className="w-5 h-5 text-indigo-600" fill="currentColor" viewBox="0 0 20 20"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 14.95a1 1 0 010-1.414l.707-.707a1 1 0 011.414 1.414l-.707.707a1 1 0 01-1.414 0zM6.464 14.95l.707-.707a1 1 0 011.414 1.414l-.707.707a1 1 0 01-1.414 0l-.707-.707z" /></svg>
              Insights da IA
            </h4>
            <button 
              onClick={fetchInsights}
              disabled={isSyncing}
              className="text-xs font-semibold text-indigo-600 hover:text-indigo-800 disabled:opacity-50"
            >
              {isSyncing ? 'Analisando...' : 'Atualizar'}
            </button>
          </div>
          <div className="flex-1 overflow-y-auto text-indigo-800 text-sm leading-relaxed space-y-3">
             {insights.split('\n').map((line, i) => (
               <p key={i}>{line}</p>
             ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Customer } from '../types';

interface CustomerListProps {
  customers: Customer[];
  onAdd: (customer: Omit<Customer, 'id' | 'createdAt'>) => void;
  onDelete: (id: string) => void;
}

const CustomerList: React.FC<CustomerListProps> = ({ customers, onAdd, onDelete }) => {
