export default CustomerList;

import React, { useState } from 'react';
import { Customer, Sale, PaymentStatus, Installment } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, onAddSale, onUpdateSale }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [description, setDescription] = useState('');
  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [numInstallments, setNumInstallments] = useState<number>(1);

  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [paymentValue, setPaymentValue] = useState<number>(0);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    if (!customerId || !description || totalAmount <= 0) return;

    const installmentAmount = totalAmount / numInstallments;
    const installments: Installment[] = [];

    for (let i = 1; i <= numInstallments; i++) {
      const dueDate = new Date();
      dueDate.setMonth(dueDate.getMonth() + i);

      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', // Will be filled by parent or during creation
        amount: installmentAmount,
        paidAmount: 0,
        dueDate: dueDate.toISOString().split('T')[0],
        status: PaymentStatus.PENDING
      });
    }

    onAddSale({
      customerId,
      description,
      totalAmount,
      date: new Date().toISOString().split('T')[0],
      installments,
      status: PaymentStatus.PENDING
    });

    setShowAdd(false);
    resetForm();
  };

  const resetForm = () => {
    setCustomerId('');
    setDescription('');
    setTotalAmount(0);
    setNumInstallments(1);
  };

  const handleAbatePayment = (sale: Sale, installmentId: string) => {
    if (paymentValue <= 0) return;

    const newInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const remainingToPay = inst.amount - inst.paidAmount;
        const actualPayment = Math.min(paymentValue, remainingToPay);
        const newPaidAmount = inst.paidAmount + actualPayment;

        return {
          ...inst,
          paidAmount: newPaidAmount,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });

    const allPaid = newInstallments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = newInstallments.some(i => i.status !== PaymentStatus.PENDING);

    onUpdateSale({
      ...sale,
      installments: newInstallments,
      status: allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING)
    });

    setPaymentValue(0);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-bold text-slate-800">Vendas a Prazo</h2>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-700"
        >
          {showAdd ? 'Cancelar' : 'Nova Venda'}
        </button>
      </div>

      {showAdd && (
        <form onSubmit={handleAddSale} className="bg-white p-6 rounded-2xl shadow-sm border border-indigo-100 space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="md:col-span-1">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Cliente</label>
              <select 
                value={customerId} 
                onChange={e => setCustomerId(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
              >
                <option value="">Selecione...</option>
                {customers.map(c => (
                  <option key={c.id} value={c.id}>{c.name}</option>
                ))}
              </select>
            </div>
            <div className="md:col-span-1">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Descrição Itens</label>
              <input 
                type="text" 
                value={description} 
                onChange={e => setDescription(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
                placeholder="Ex: 2 Calças, 1 Blusa"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Valor Total (R$)</label>
              <input 
                type="number" 
                step="0.01"
                value={totalAmount || ''} 
                onChange={e => setTotalAmount(Number(e.target.value))}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nº Parcelas</label>
              <input 
                type="number" 
                min="1"
                max="24"
                value={numInstallments} 
                onChange={e => setNumInstallments(Number(e.target.value))}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>
          <div className="flex justify-end">
            <button type="submit" className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-sm font-semibold">
              Registrar Venda
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {sales.length === 0 && (
          <div className="bg-white p-12 text-center rounded-2xl border border-dashed border-slate-200 text-slate-400">
            Nenhuma venda a prazo registrada.
          </div>
        )}
        {sales.map(sale => {
          const customer = customers.find(c => c.id === sale.customerId);
          const isOverdue = sale.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date());

          return (
            <div key={sale.id} className={`bg-white rounded-2xl shadow-sm border ${isOverdue ? 'border-rose-200' : 'border-slate-100'} overflow-hidden`}>
              <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <div className="flex items-center gap-2">
                    <h3 className="font-bold text-slate-800">{customer?.name || 'Cliente Excluído'}</h3>
                    {isOverdue && <span className="bg-rose-100 text-rose-600 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Atrasado</span>}
                  </div>
                  <p className="text-sm text-slate-500">{sale.description}</p>
                  <p className="text-xs text-slate-400">Data: {new Date(sale.date).toLocaleDateString('pt-BR')}</p>
                </div>

                <div className="flex items-center gap-6">
                  <div className="text-right">
                    <p className="text-xs font-bold text-slate-400 uppercase">Total</p>
                    <p className="font-bold text-slate-800">R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
                  <button 
                    onClick={() => setSelectedSale(selectedSale?.id === sale.id ? null : sale)}
                    className="bg-slate-50 text-slate-600 px-3 py-2 rounded-lg text-xs font-bold uppercase hover:bg-slate-100"
                  >
                    {selectedSale?.id === sale.id ? 'Fechar Detalhes' : 'Ver Parcelas'}
                  </button>
                </div>
              </div>

              {selectedSale?.id === sale.id && (
                <div className="border-t border-slate-50 bg-slate-50/50 p-5 animate-in slide-in-from-top-2">
                  <h4 className="text-xs font-bold text-slate-500 uppercase mb-4 tracking-wider">Cronograma de Pagamentos</h4>
                  <div className="space-y-3">
                    {sale.installments.map((inst, idx) => (
                      <div key={inst.id} className="bg-white p-3 rounded-xl border border-slate-200 flex flex-wrap justify-between items-center gap-4">
                        <div className="flex items-center gap-4">
                          <span className="w-6 h-6 flex items-center justify-center bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-bold">
                            {idx + 1}
                          </span>
                          <div>
                            <p className="text-xs font-semibold text-slate-700">Vencimento: {new Date(inst.dueDate).toLocaleDateString('pt-BR')}</p>
                            <p className="text-[10px] text-slate-400 uppercase">{inst.status === PaymentStatus.PAID ? 'Liquidado' : inst.status === PaymentStatus.PARTIAL ? 'Parcial' : 'Pendente'}</p>
                          </div>
                        </div>

                        <div className="flex items-center gap-4">
                          <div className="text-right">
                            <p className="text-sm font-bold text-indigo-600">R$ {inst.amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                            <p className="text-[10px] text-emerald-500 font-medium">Pago: R$ {inst.paidAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                          </div>

                          {inst.status !== PaymentStatus.PAID && (
                            <div className="flex items-center gap-2">
                              <input 
                                type="number" 
                                placeholder="Valor"
                                className="w-20 bg-slate-50 border border-slate-200 rounded px-2 py-1 text-xs"
                                onChange={(e) => setPaymentValue(Number(e.target.value))}
                              />
                              <button 
                                onClick={() => handleAbatePayment(sale, inst.id)}
                                className="bg-emerald-500 text-white px-3 py-1 rounded text-xs font-bold hover:bg-emerald-600 transition"
                              >
                                Abater
                              </button>
                            </div>
                          )}
                          {inst.status === PaymentStatus.PAID && (
                            <div className="text-emerald-500">
                              <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                            </div>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default SalesManager;

import React, { useState, useEffect } from 'react';
import { View, Customer, Sale } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);

  // Load data from localStorage on mount
  useEffect(() => {
    const savedCustomers = localStorage.getItem('modagestao_customers');
    const savedSales = localStorage.getItem('modagestao_sales');
    if (savedCustomers) setCustomers(JSON.parse(savedCustomers));
    if (savedSales) setSales(JSON.parse(savedSales));
  }, []);

  // Save data whenever it changes
  useEffect(() => {
    localStorage.setItem('modagestao_customers', JSON.stringify(customers));
  }, [customers]);

  useEffect(() => {
    localStorage.setItem('modagestao_sales', JSON.stringify(sales));
  }, [sales]);

  const addCustomer = (data: Omit<Customer, 'id' | 'createdAt'>) => {
    const newCustomer: Customer = {
      ...data,
