    if (paymentValue <= 0) return;

    const newInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const remainingToPay = inst.amount - inst.paidAmount;
        const actualPayment = Math.min(paymentValue, remainingToPay);
        const newPaidAmount = inst.paidAmount + actualPayment;

        return {
          ...inst,
          paidAmount: newPaidAmount,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });

    updateSaleState(sale, newInstallments);
    setPaymentValue(0);
  };

  const startEditing = (inst: Installment) => {
    setEditingInstId(inst.id);
    setEditFields({
      amount: inst.amount,
      paidAmount: inst.paidAmount,
      dueDate: inst.dueDate
    });
  };

  const saveEdit = (sale: Sale) => {
    const newInstallments = sale.installments.map(inst => {
      if (inst.id === editingInstId) {
        const status = editFields.paidAmount >= editFields.amount ? PaymentStatus.PAID : 
                       editFields.paidAmount > 0 ? PaymentStatus.PARTIAL : PaymentStatus.PENDING;
        return {
          ...inst,
          amount: editFields.amount,
          paidAmount: editFields.paidAmount,
          dueDate: editFields.dueDate,
          status
        };
      }
      return inst;
    });

    // Re-calculate total amount of the sale based on installments
    const newTotal = newInstallments.reduce((sum, i) => sum + i.amount, 0);

    onUpdateSale({
      ...sale,
      totalAmount: newTotal,
      installments: newInstallments,
      status: newInstallments.every(i => i.status === PaymentStatus.PAID) ? PaymentStatus.PAID :
              newInstallments.some(i => i.status !== PaymentStatus.PENDING) ? PaymentStatus.PARTIAL : PaymentStatus.PENDING
    });

    setEditingInstId(null);
  };

  const updateSaleState = (sale: Sale, newInstallments: Installment[]) => {
    const allPaid = newInstallments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = newInstallments.some(i => i.status !== PaymentStatus.PENDING);

    onUpdateSale({
      ...sale,
      installments: newInstallments,
      status: allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING)
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-bold text-slate-800">Vendas a Prazo</h2>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-700 transition shadow-sm"
        >
          {showAdd ? 'Cancelar' : 'Nova Venda'}
        </button>
      </div>

      {showAdd && (
        <form onSubmit={handleAddSale} className="bg-white p-6 rounded-2xl shadow-sm border border-indigo-100 space-y-4 animate-in fade-in zoom-in duration-200">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            <div className="md:col-span-1">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Cliente</label>
              <select 
                value={customerId} 
                onChange={e => setCustomerId(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
              >
                <option value="">Selecione...</option>
                {customers.map(c => (
                  <option key={c.id} value={c.id}>{c.name}</option>
                ))}
              </select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Descrição Itens</label>
              <input 
                type="text" 
                value={description} 
                onChange={e => setDescription(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
                placeholder="Ex: 2 Calças, 1 Blusa"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Valor Total (R$)</label>
              <input 
                type="number" 
                step="0.01"
                value={totalAmount || ''} 
                onChange={e => setTotalAmount(Number(e.target.value))}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
              />
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nº Parcelas</label>
                <input 
                  type="number" 
                  min="1"
                  max="24"
                  value={numInstallments} 
                  onChange={e => setNumInstallments(Number(e.target.value))}
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Dia Vencimento</label>
                <input 
                  type="number" 
                  min="1"
                  max="31"
                  value={dueDay} 
                  onChange={e => setDueDay(Number(e.target.value))}
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
                />
              </div>
            </div>
          </div>
          <div className="flex justify-end">
            <button type="submit" className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-700 transition">
              Registrar Venda
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {sales.length === 0 && (
          <div className="bg-white p-12 text-center rounded-2xl border border-dashed border-slate-200 text-slate-400">
            Nenhuma venda a prazo registrada.
          </div>
        )}
        {sales.map(sale => {
          const customer = customers.find(c => c.id === sale.customerId);
          const isOverdue = sale.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date());

          return (
            <div key={sale.id} className={`bg-white rounded-2xl shadow-sm border ${isOverdue ? 'border-rose-200' : 'border-slate-100'} overflow-hidden transition-all hover:border-indigo-200`}>
              <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <div className="flex items-center gap-2">
                    <h3 className="font-bold text-slate-800">{customer?.name || 'Cliente Excluído'}</h3>
                    {isOverdue && <span className="bg-rose-100 text-rose-600 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Possui Atraso</span>}
                  </div>
                  <p className="text-sm text-slate-500">{sale.description}</p>
                  <p className="text-xs text-slate-400">Venda realizada em: {new Date(sale.date).toLocaleDateString('pt-BR')}</p>
                </div>

                <div className="flex items-center gap-6">
                  <div className="text-right">
                    <p className="text-xs font-bold text-slate-400 uppercase">Total da Venda</p>
                    <p className="font-bold text-slate-800">R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
                  <button 
                    onClick={() => setSelectedSale(selectedSale?.id === sale.id ? null : sale)}
                    className={`px-3 py-2 rounded-lg text-xs font-bold uppercase transition ${
                        selectedSale?.id === sale.id ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-50 text-slate-600 hover:bg-slate-100'
                    }`}
                  >
                    {selectedSale?.id === sale.id ? 'Fechar Detalhes' : 'Ver Parcelas'}
                  </button>
                </div>
              </div>

              {selectedSale?.id === sale.id && (
                <div className="border-t border-slate-50 bg-slate-50/50 p-5 animate-in slide-in-from-top-2 duration-200">
                  <h4 className="text-xs font-bold text-slate-500 uppercase mb-4 tracking-wider">Detalhamento das Parcelas</h4>
                  <div className="space-y-3">
                    {sale.installments.map((inst, idx) => {
                      const isEditing = editingInstId === inst.id;
                      const instOverdue = inst.status !== PaymentStatus.PAID && new Date(inst.dueDate) < new Date();

                      return (
                        <div key={inst.id} className={`bg-white p-3 rounded-xl border ${instOverdue ? 'border-rose-200 bg-rose-50/10' : 'border-slate-200'} flex flex-col gap-3`}>
                          <div className="flex flex-wrap justify-between items-center gap-4">
                            <div className="flex items-center gap-4">
                              <span className={`w-7 h-7 flex items-center justify-center rounded-full text-[10px] font-bold ${inst.status === PaymentStatus.PAID ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                                {idx + 1}
                              </span>

                              {isEditing ? (
                                <div className="flex flex-wrap gap-3 items-end">
                                  <div>
                                    <label className="block text-[9px] font-bold text-slate-400 uppercase">Vencimento</label>
                                    <input 
                                      type="date" 
                                      value={editFields.dueDate}
                                      onChange={(e) => setEditFields({...editFields, dueDate: e.target.value})}
                                      className="text-xs bg-slate-50 border border-slate-300 rounded px-2 py-1 focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                  </div>
                                  <div>
                                    <label className="block text-[9px] font-bold text-slate-400 uppercase">Valor Parcela</label>
                                    <input 
                                      type="number" 
                                      value={editFields.amount}
                                      onChange={(e) => setEditFields({...editFields, amount: Number(e.target.value)})}
                                      className="w-24 text-xs bg-slate-50 border border-slate-300 rounded px-2 py-1 focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                  </div>
                                  <div>
                                    <label className="block text-[9px] font-bold text-slate-400 uppercase">Valor Pago</label>
                                    <input 
                                      type="number" 
                                      value={editFields.paidAmount}
                                      onChange={(e) => setEditFields({...editFields, paidAmount: Number(e.target.value)})}
                                      className="w-24 text-xs bg-slate-50 border border-slate-300 rounded px-2 py-1 focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                  </div>
                                  <div className="flex gap-2">
                                    <button 
                                      onClick={() => saveEdit(sale)}
                                      className="bg-emerald-500 text-white px-3 py-1 rounded text-[10px] font-bold uppercase hover:bg-emerald-600 transition"
                                    >
                                      Salvar
                                    </button>
                                    <button 
                                      onClick={() => setEditingInstId(null)}
                                      className="bg-slate-200 text-slate-600 px-3 py-1 rounded text-[10px] font-bold uppercase hover:bg-slate-300 transition"
                                    >
                                      Cancelar
                                    </button>
                                  </div>
                                </div>
                              ) : (
                                <div>
                                  <div className="flex items-center gap-2">
                                    <p className="text-xs font-semibold text-slate-700">Vencimento: {new Date(inst.dueDate).toLocaleDateString('pt-BR')}</p>
                                    <button 
                                      onClick={() => startEditing(inst)}
                                      className="text-slate-400 hover:text-indigo-600 transition p-1"
                                      title="Editar parcela (valor e data)"
                                    >
                                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                                    </button>
                                  </div>
                                  <p className={`text-[10px] uppercase font-bold ${instOverdue ? 'text-rose-500' : 'text-slate-400'}`}>
                                    {inst.status === PaymentStatus.PAID ? 'Liquidado' : inst.status === PaymentStatus.PARTIAL ? 'Pagamento Parcial' : instOverdue ? 'Vencida (Atraso)' : 'Pendente'}
                                  </p>
                                </div>
                              )}
                            </div>

                            {!isEditing && (
                              <div className="flex items-center gap-4 ml-auto">
                                <div className="text-right">
                                  <p className="text-sm font-bold text-indigo-600">R$ {inst.amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                                  <p className="text-[10px] text-emerald-500 font-medium">Pago: R$ {inst.paidAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                                </div>

                                {inst.status !== PaymentStatus.PAID && (
                                  <div className="flex items-center gap-2">
                                    <input 
                                      type="number" 
                                      placeholder="Valor"
                                      className="w-20 bg-slate-50 border border-slate-200 rounded px-2 py-1 text-xs outline-none focus:ring-1 focus:ring-emerald-500"
                                      onChange={(e) => setPaymentValue(Number(e.target.value))}
                                    />
                                    <button 
                                      onClick={() => handleAbatePayment(sale, inst.id)}
                                      className="bg-emerald-500 text-white px-3 py-1 rounded text-xs font-bold hover:bg-emerald-600 transition shadow-sm"
                                    >
                                      Abater
                                    </button>
                                  </div>
                                )}
                                {inst.status === PaymentStatus.PAID && (
                                  <div className="text-emerald-500 bg-emerald-50 p-1.5 rounded-full">
                                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                                  </div>
                                )}
                              </div>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default SalesManager;

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  address?: string;
  cpf?: string;
  createdAt: number;
}

export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  PARTIAL = 'PARTIAL'
}

export interface Installment {
  id: string;
  saleId: string;
  amount: number;
  paidAmount: number;
  dueDate: string;
  status: PaymentStatus;
}

export interface Sale {
  id: string;
  customerId: string;
  description: string;
  totalAmount: number;
  date: string;
  installments: Installment[];
  status: PaymentStatus;
}

export interface PaymentLog {
  id: string;
  installmentId: string;
  amount: number;
  date: string;
}

export type View = 'dashboard' | 'customers' | 'sales' | 'agenda';

import React, { useState } from 'react';
import { Customer, Sale, PaymentStatus } from '../types';

interface CustomerListProps {
  customers: Customer[];
  sales: Sale[];
  onAdd: (customer: Omit<Customer, 'id' | 'createdAt'>) => void;
  onDelete: (id: string) => void;
}

const CustomerList: React.FC<CustomerListProps> = ({ customers, sales, onAdd, onDelete }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [cpf, setCpf] = useState('');
  const [address, setAddress] = useState('');

  const getCustomerStats = (customerId: string) => {
    const customerSales = sales.filter(s => s.customerId === customerId);
    let totalPurchased = 0;
    let totalPaid = 0;

    customerSales.forEach(sale => {
      totalPurchased += sale.totalAmount;
      sale.installments.forEach(inst => {
        totalPaid += inst.paidAmount;
      });
    });

    return {
      totalPurchased,
      totalPaid,
      debt: totalPurchased - totalPaid
    };
  };

  const globalStats = customers.reduce((acc, customer) => {
    const stats = getCustomerStats(customer.id);
    acc.totalDebt += stats.debt;
    acc.totalPurchased += stats.totalPurchased;
    return acc;
  }, { totalDebt: 0, totalPurchased: 0 });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || !phone) return;
    onAdd({ name, phone, email, cpf, address });
    setName('');
    setPhone('');
    setEmail('');
    setCpf('');
    setAddress('');
    setShowAdd(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-800">Gerenciamento de Clientes</h2>
          <p className="text-sm text-slate-500">Acompanhe o saldo devedor individual e total.</p>
        </div>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-700 transition shadow-sm"
        >
          {showAdd ? 'Cancelar' : 'Novo Cliente'}
        </button>
      </div>

      {/* Global Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">Dívida Total Acumulada</p>
          <p className="text-2xl font-bold text-rose-600">
            R$ {globalStats.totalDebt.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
          </p>
        </div>
        <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">Total em Vendas (Histórico)</p>
          <p className="text-2xl font-bold text-indigo-600">
            R$ {globalStats.totalPurchased.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
          </p>
        </div>
      </div>

      {showAdd && (
        <form onSubmit={handleSubmit} className="bg-white p-6 rounded-2xl shadow-sm border border-indigo-100 space-y-4 animate-in fade-in slide-in-from-top-4 duration-300">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nome *</label>
              <input 
                type="text" 
                value={name} 
                required
                onChange={e => setName(e.target.value)} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                placeholder="Ex: Maria Silva"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Telefone *</label>
              <input 
                type="text" 
                value={phone} 
                required
                onChange={e => setPhone(e.target.value)} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                placeholder="(00) 00000-0000"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">CPF (Opcional)</label>
              <input 
                type="text" 
                value={cpf} 
                onChange={e => setCpf(e.target.value)} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                placeholder="000.000.000-00"
              />
            </div>
            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Endereço (Opcional)</label>
              <input 
                type="text" 
                value={address} 
                onChange={e => setAddress(e.target.value)} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                placeholder="Rua, Número, Bairro, Cidade"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">E-mail (Opcional)</label>
              <input 
                type="email" 
                value={email} 
                onChange={e => setEmail(e.target.value)} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                placeholder="maria@email.com"
              />
            </div>
          </div>
          <div className="flex justify-end">
            <button type="submit" className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-700 transition">
              Salvar Cliente
            </button>
          </div>
        </form>
      )}

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Informações do Cliente</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Total Comprado</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Total Pago</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Dívida Atual</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {customers.map(customer => {
                const stats = getCustomerStats(customer.id);
                return (
                  <tr key={customer.id} className="hover:bg-slate-50 transition group">
                    <td className="px-6 py-4">
                      <div className="font-semibold text-slate-800">{customer.name}</div>
                      <div className="flex flex-col gap-0.5 mt-1">
                        <div className="flex items-center gap-2">
                           <span className="text-[10px] bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded font-mono uppercase">{customer.phone}</span>
                           {customer.cpf && <span className="text-[10px] text-slate-400 font-mono">CPF: {customer.cpf}</span>}
                        </div>
                        {customer.address && (
                          <div className="text-[10px] text-slate-400 italic mt-0.5">
                            <span className="font-bold uppercase not-italic">End:</span> {customer.address}
                          </div>
                        )}
                        {customer.email && <div className="text-[10px] text-indigo-400 underline">{customer.email}</div>}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <span className="text-sm text-slate-600">R$ {stats.totalPurchased.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                    </td>
                    <td className="px-6 py-4 text-right text-emerald-600">
                      <span className="text-sm font-medium">R$ {stats.totalPaid.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <span className={`text-sm font-bold ${stats.debt > 0 ? 'text-rose-500' : 'text-slate-400'}`}>
                        R$ {stats.debt.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <button 
                        onClick={() => onDelete(customer.id)}
                        className="text-slate-300 hover:text-rose-500 transition-colors p-1"
                        title="Excluir Cliente"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                      </button>
                    </td>
                  </tr>
                );
              })}
              {customers.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-10 text-center text-slate-400">
                    Nenhum cliente cadastrado.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default CustomerList;

import React, { useState } from 'react';
import { Customer, Sale, PaymentStatus, Installment } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, onAddSale, onUpdateSale }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [description, setDescription] = useState('');
  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [paymentValue, setPaymentValue] = useState<number>(0);

  // State for detailed editing of an installment
  const [editingInstId, setEditingInstId] = useState<string | null>(null);
  const [editFields, setEditFields] = useState({
    amount: 0,
    paidAmount: 0,
    dueDate: ''
  });

  // State for re-parceling (changing installment count)
  const [isReparceling, setIsReparceling] = useState(false);
  const [newTotalInstallments, setNewTotalInstallments] = useState<number>(1);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    if (!customerId || !description || totalAmount <= 0) return;

    const installmentAmount = totalAmount / numInstallments;
    const installments: Installment[] = [];
    const today = new Date();

    for (let i = 1; i <= numInstallments; i++) {
      const dueDate = calculateDueDate(today, i, dueDay);

      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: installmentAmount,
        paidAmount: 0,
        dueDate: dueDate.toISOString().split('T')[0],
        status: PaymentStatus.PENDING
      });
    }

    onAddSale({
      customerId,
      description,
      totalAmount,
      date: today.toISOString().split('T')[0],
      installments,
      status: PaymentStatus.PENDING
    });

    setShowAdd(false);
    resetForm();
  };

  const calculateDueDate = (baseDate: Date, monthsToAdd: number, targetDay: number) => {
    let targetMonth = baseDate.getMonth() + monthsToAdd;
    let targetYear = baseDate.getFullYear();

    while (targetMonth > 11) {
      targetMonth -= 12;
      targetYear += 1;
    }

    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const resetForm = () => {
    setCustomerId('');
    setDescription('');
    setTotalAmount(0);
    setNumInstallments(1);
    setDueDay(new Date().getDate());
  };

  const handleAbatePayment = (sale: Sale, installmentId: string) => {
    if (paymentValue <= 0) return;

    const newInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const remainingToPay = inst.amount - inst.paidAmount;
        const actualPayment = Math.min(paymentValue, remainingToPay);
        const newPaidAmount = inst.paidAmount + actualPayment;

        return {
          ...inst,
          paidAmount: newPaidAmount,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });

    updateSaleState(sale, newInstallments);
    setPaymentValue(0);
  };

  const startEditing = (inst: Installment) => {
    setEditingInstId(inst.id);
    setEditFields({
      amount: inst.amount,
      paidAmount: inst.paidAmount,
      dueDate: inst.dueDate
    });
  };

  const saveEdit = (sale: Sale) => {
    const newInstallments = sale.installments.map(inst => {
      if (inst.id === editingInstId) {
        const status = editFields.paidAmount >= editFields.amount ? PaymentStatus.PAID : 
                       editFields.paidAmount > 0 ? PaymentStatus.PARTIAL : PaymentStatus.PENDING;
        return {
          ...inst,
          amount: editFields.amount,
          paidAmount: editFields.paidAmount,
          dueDate: editFields.dueDate,
          status
        };
      }
      return inst;
    });

    const newTotal = newInstallments.reduce((sum, i) => sum + i.amount, 0);

    onUpdateSale({
      ...sale,
      totalAmount: newTotal,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    });

    setEditingInstId(null);
  };

  const handleReparcel = (sale: Sale) => {
    // 1. Identify "Protected" installments (those already fully or partially paid)
    const protectedInstallments = sale.installments.filter(i => i.paidAmount > 0 || i.status === PaymentStatus.PAID);

    if (newTotalInstallments < protectedInstallments.length) {
      alert(`Não é possível reduzir para ${newTotalInstallments} parcelas pois já existem ${protectedInstallments.length} parcelas com pagamentos registrados.`);
      return;
    }

    const totalPaid = protectedInstallments.reduce((sum, i) => sum + i.paidAmount, 0);
    const balanceRemaining = sale.totalAmount - totalPaid;
    const newInstallmentsNeeded = newTotalInstallments - protectedInstallments.length;

    const newInstallments: Installment[] = [...protectedInstallments];

    if (newInstallmentsNeeded > 0) {
      const amountPerNewInst = balanceRemaining / newInstallmentsNeeded;
      const lastDate = protectedInstallments.length > 0 
        ? new Date(protectedInstallments[protectedInstallments.length - 1].dueDate)
        : new Date(sale.date);

      const targetDay = lastDate.getDate();

      for (let i = 1; i <= newInstallmentsNeeded; i++) {
        const dueDate = calculateDueDate(lastDate, i, targetDay);
        newInstallments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: sale.id,
          amount: amountPerNewInst,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onUpdateSale({
      ...sale,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    });

    setIsReparceling(false);
    // Update local selected sale reference
    setSelectedSale({ ...sale, installments: newInstallments });
  };

  const calculateSaleStatus = (installments: Installment[]) => {
    const allPaid = installments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = installments.some(i => i.status !== PaymentStatus.PENDING);
    return allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING);
  };

  const updateSaleState = (sale: Sale, newInstallments: Installment[]) => {
    onUpdateSale({
      ...sale,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-bold text-slate-800">Vendas a Prazo</h2>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-700 transition shadow-sm"
        >
          {showAdd ? 'Cancelar' : 'Nova Venda'}
        </button>
      </div>

      {showAdd && (
        <form onSubmit={handleAddSale} className="bg-white p-6 rounded-2xl shadow-sm border border-indigo-100 space-y-4 animate-in fade-in zoom-in duration-200">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            <div className="md:col-span-1">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Cliente</label>
              <select 
                value={customerId} 
                onChange={e => setCustomerId(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
              >
                <option value="">Selecione...</option>
                {customers.map(c => (
                  <option key={c.id} value={c.id}>{c.name}</option>
                ))}
              </select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Descrição Itens</label>
              <input 
                type="text" 
                value={description} 
                onChange={e => setDescription(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
                placeholder="Ex: 2 Calças, 1 Blusa"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Valor Total (R$)</label>
              <input 
                type="number" 
                step="0.01"
                value={totalAmount || ''} 
                onChange={e => setTotalAmount(Number(e.target.value))}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
              />
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nº Parcelas</label>
                <input 
                  type="number" 
                  min="1"
                  max="24"
                  value={numInstallments} 
                  onChange={e => setNumInstallments(Number(e.target.value))}
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Dia Vencimento</label>
                <input 
                  type="number" 
                  min="1"
                  max="31"
                  value={dueDay} 
                  onChange={e => setDueDay(Number(e.target.value))}
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500"
                />
              </div>
            </div>
          </div>
          <div className="flex justify-end">
            <button type="submit" className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-700 transition">
              Registrar Venda
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {sales.length === 0 && (
          <div className="bg-white p-12 text-center rounded-2xl border border-dashed border-slate-200 text-slate-400">
            Nenhuma venda a prazo registrada.
          </div>
        )}
        {sales.map(sale => {
          const customer = customers.find(c => c.id === sale.customerId);
          const isOverdue = sale.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date());

          return (
            <div key={sale.id} className={`bg-white rounded-2xl shadow-sm border ${isOverdue ? 'border-rose-200' : 'border-slate-100'} overflow-hidden transition-all hover:border-indigo-200`}>
              <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <div className="flex items-center gap-2">
                    <h3 className="font-bold text-slate-800">{customer?.name || 'Cliente Excluído'}</h3>
                    {isOverdue && <span className="bg-rose-100 text-rose-600 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Possui Atraso</span>}
                  </div>
                  <p className="text-sm text-slate-500">{sale.description}</p>
                  <p className="text-xs text-slate-400">Venda realizada em: {new Date(sale.date).toLocaleDateString('pt-BR')}</p>
                </div>

                <div className="flex items-center gap-6">
                  <div className="text-right">
                    <p className="text-xs font-bold text-slate-400 uppercase">Total da Venda</p>
                    <p className="font-bold text-slate-800">R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
                  <button 
                    onClick={() => setSelectedSale(selectedSale?.id === sale.id ? null : sale)}
                    className={`px-3 py-2 rounded-lg text-xs font-bold uppercase transition ${
                        selectedSale?.id === sale.id ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-50 text-slate-600 hover:bg-slate-100'
                    }`}
                  >
                    {selectedSale?.id === sale.id ? 'Fechar Detalhes' : 'Ver Parcelas'}
                  </button>
                </div>
              </div>

              {selectedSale?.id === sale.id && (
                <div className="border-t border-slate-50 bg-slate-50/50 p-5 animate-in slide-in-from-top-2 duration-200">
                  <div className="flex justify-between items-center mb-4">
                    <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Detalhamento das Parcelas</h4>

                    <div className="flex items-center gap-2">
                      {isReparceling ? (
                        <div className="flex items-center gap-2 bg-indigo-50 p-2 rounded-lg border border-indigo-100 animate-in zoom-in duration-150">
                          <label className="text-[10px] font-bold text-indigo-600 uppercase">Nova Qtd:</label>
                          <input 
                            type="number" 
                            min="1" 
                            max="24"
                            value={newTotalInstallments}
                            onChange={(e) => setNewTotalInstallments(Number(e.target.value))}
                            className="w-12 text-xs border border-indigo-200 rounded px-1 py-0.5 outline-none focus:ring-1 focus:ring-indigo-500"
                          />
                          <button 
                            onClick={() => handleReparcel(sale)}
                            className="bg-indigo-600 text-white px-2 py-0.5 rounded text-[10px] font-bold uppercase hover:bg-indigo-700 transition"
                          >
                            Aplicar
                          </button>
                          <button 
                            onClick={() => setIsReparceling(false)}
                            className="text-slate-400 hover:text-rose-500 transition px-1"
                          >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                          </button>
                        </div>
                      ) : (
                        <button 
                          onClick={() => {
                            setIsReparceling(true);
                            setNewTotalInstallments(sale.installments.length);
                          }}
                          className="flex items-center gap-1.5 text-indigo-600 hover:text-indigo-800 transition text-[10px] font-bold uppercase border border-indigo-200 bg-indigo-50/50 px-2 py-1 rounded-lg"
                        >
                          <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
                          Alterar Parcelamento
                        </button>
                      )}
                    </div>
                  </div>

                  <div className="space-y-3">
                    {sale.installments.map((inst, idx) => {
                      const isEditing = editingInstId === inst.id;
                      const instOverdue = inst.status !== PaymentStatus.PAID && new Date(inst.dueDate) < new Date();

                      return (
                        <div key={inst.id} className={`bg-white p-3 rounded-xl border ${instOverdue ? 'border-rose-200 bg-rose-50/10' : 'border-slate-200'} flex flex-col gap-3`}>
                          <div className="flex flex-wrap justify-between items-center gap-4">
                            <div className="flex items-center gap-4">
                              <span className={`w-7 h-7 flex items-center justify-center rounded-full text-[10px] font-bold ${inst.status === PaymentStatus.PAID ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                                {idx + 1}
                              </span>

                              {isEditing ? (
                                <div className="flex flex-wrap gap-3 items-end">
                                  <div>
                                    <label className="block text-[9px] font-bold text-slate-400 uppercase">Vencimento</label>
                                    <input 
                                      type="date" 
                                      value={editFields.dueDate}
                                      onChange={(e) => setEditFields({...editFields, dueDate: e.target.value})}
                                      className="text-xs bg-slate-50 border border-slate-300 rounded px-2 py-1 focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                  </div>
                                  <div>
                                    <label className="block text-[9px] font-bold text-slate-400 uppercase">Valor Parcela</label>
                                    <input 
                                      type="number" 
                                      value={editFields.amount}
                                      onChange={(e) => setEditFields({...editFields, amount: Number(e.target.value)})}
                                      className="w-24 text-xs bg-slate-50 border border-slate-300 rounded px-2 py-1 focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                  </div>
                                  <div>
                                    <label className="block text-[9px] font-bold text-slate-400 uppercase">Valor Pago</label>
                                    <input 
                                      type="number" 
                                      value={editFields.paidAmount}
                                      onChange={(e) => setEditFields({...editFields, paidAmount: Number(e.target.value)})}
                                      className="w-24 text-xs bg-slate-50 border border-slate-300 rounded px-2 py-1 focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                  </div>
                                  <div className="flex gap-2">
                                    <button 
                                      onClick={() => saveEdit(sale)}
                                      className="bg-emerald-500 text-white px-3 py-1 rounded text-[10px] font-bold uppercase hover:bg-emerald-600 transition"
                                    >
                                      Salvar
                                    </button>
                                    <button 
                                      onClick={() => setEditingInstId(null)}
                                      className="bg-slate-200 text-slate-600 px-3 py-1 rounded text-[10px] font-bold uppercase hover:bg-slate-300 transition"
                                    >
                                      Cancelar
                                    </button>
                                  </div>
                                </div>
                              ) : (
                                <div>
                                  <div className="flex items-center gap-2">
                                    <p className="text-xs font-semibold text-slate-700">Vencimento: {new Date(inst.dueDate).toLocaleDateString('pt-BR')}</p>
                                    <button 
                                      onClick={() => startEditing(inst)}
                                      className="text-slate-400 hover:text-indigo-600 transition p-1"
                                      title="Editar parcela (valor e data)"
                                    >
                                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                                    </button>
                                  </div>
                                  <p className={`text-[10px] uppercase font-bold ${instOverdue ? 'text-rose-500' : 'text-slate-400'}`}>
                                    {inst.status === PaymentStatus.PAID ? 'Liquidado' : inst.status === PaymentStatus.PARTIAL ? 'Pagamento Parcial' : instOverdue ? 'Vencida (Atraso)' : 'Pendente'}
                                  </p>
                                </div>
                              )}
                            </div>

                            {!isEditing && (
                              <div className="flex items-center gap-4 ml-auto">
                                <div className="text-right">
                                  <p className="text-sm font-bold text-indigo-600">R$ {inst.amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                                  <p className="text-[10px] text-emerald-500 font-medium">Pago: R$ {inst.paidAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                                </div>

                                {inst.status !== PaymentStatus.PAID && (
                                  <div className="flex items-center gap-2">
                                    <input 
                                      type="number" 
                                      placeholder="Valor"
                                      className="w-20 bg-slate-50 border border-slate-200 rounded px-2 py-1 text-xs outline-none focus:ring-1 focus:ring-emerald-500"
                                      onChange={(e) => setPaymentValue(Number(e.target.value))}
                                    />
                                    <button 
                                      onClick={() => handleAbatePayment(sale, inst.id)}
                                      className="bg-emerald-500 text-white px-3 py-1 rounded text-xs font-bold hover:bg-emerald-600 transition shadow-sm"
                                    >
                                      Abater
                                    </button>
                                  </div>
                                )}
                                {inst.status === PaymentStatus.PAID && (
                                  <div className="text-emerald-500 bg-emerald-50 p-1.5 rounded-full">
                                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                                  </div>
                                )}
                              </div>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

