import React from 'react';
import { Customer, Sale } from '../types';

interface SettingsProps {
  customers: Customer[];
  sales: Sale[];
  onImport: (data: { customers: Customer[], sales: Sale[] }) => void;
  onClear: () => void;
}

const Settings: React.FC<SettingsProps> = ({ customers, sales, onImport, onClear }) => {

  const handleExport = () => {
    const data = {
      customers,
      sales,
      exportDate: new Date().toISOString(),
      version: '1.0'
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup_modagestao_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.customers && json.sales) {
          if (window.confirm('Isso irá substituir todos os dados atuais. Deseja continuar?')) {
            onImport({ customers: json.customers, sales: json.sales });
            alert('Dados importados com sucesso!');
          }
        } else {
          alert('Arquivo de backup inválido.');
        }
      } catch (err) {
        alert('Erro ao ler o arquivo.');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-100">
        <h2 className="text-xl font-bold text-slate-800 mb-2">Configurações e Backup</h2>
        <p className="text-sm text-slate-500 mb-8">Gerencie a segurança dos dados da sua loja.</p>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="space-y-4">
            <h3 className="text-sm font-bold text-slate-700 uppercase">Exportar Dados</h3>
            <p className="text-xs text-slate-500">Baixe uma cópia de segurança de todos os seus clientes e vendas. Recomendado fazer semanalmente.</p>
            <button 
              onClick={handleExport}
              className="bg-indigo-600 text-white px-6 py-3 rounded-xl text-sm font-semibold hover:bg-indigo-700 transition flex items-center gap-2"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
              Fazer Backup Agora
            </button>
          </div>

          <div className="space-y-4">
            <h3 className="text-sm font-bold text-slate-700 uppercase">Importar Backup</h3>
            <p className="text-xs text-slate-500">Restaure os dados de um arquivo de backup (.json) gerado anteriormente.</p>
            <label className="inline-block">
              <span className="bg-slate-100 text-slate-700 px-6 py-3 rounded-xl text-sm font-semibold hover:bg-slate-200 transition cursor-pointer flex items-center gap-2 border border-slate-200">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                Selecionar Arquivo
              </span>
              <input type="file" className="hidden" accept=".json" onChange={handleImport} />
            </label>
          </div>
        </div>

        <div className="mt-12 pt-8 border-t border-slate-100">
          <h3 className="text-sm font-bold text-rose-600 uppercase mb-4">Zona de Perigo</h3>
          <button 
            onClick={() => {
              if (window.confirm('ATENÇÃO: Isso apagará TODOS os dados permanentemente. Você tem um backup salvo?')) {
                onClear();
              }
            }}
            className="text-rose-600 hover:bg-rose-50 border border-rose-200 px-6 py-2 rounded-xl text-sm font-semibold transition"
          >
            Limpar Todo o Sistema
          </button>
        </div>
      </div>

      <div className="bg-indigo-900 text-indigo-100 p-8 rounded-2xl">
        <h3 className="text-lg font-bold mb-4">Guia Rápido de Uso</h3>
        <ul className="space-y-3 text-sm opacity-90">
