            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeView === 'settings' ? 'bg-indigo-800 text-white shadow-inner' : 'text-indigo-400 hover:bg-indigo-800/50'}`}
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            Configurações
          </button>
          <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest text-center">ModaGestão v1.0</p>
        </div>
      </nav>

      <main className="flex-1 p-4 md:p-10 max-w-7xl mx-auto w-full overflow-y-auto">
        {activeView === 'dashboard' && <Dashboard sales={sales} customers={customers} />}
        {activeView === 'agenda' && <Agenda sales={sales} customers={customers} />}
        {activeView === 'customers' && <CustomerList customers={customers} sales={sales} onAdd={addCustomer} onDelete={deleteCustomer} />}
        {activeView === 'sales' && <SalesManager sales={sales} customers={customers} onAddSale={addSale} onUpdateSale={updateSale} />}
        {activeView === 'settings' && <Settings customers={customers} sales={sales} onImport={handleImportData} onClear={handleClearData} />}
      </main>
    </div>
  );
};

