        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-bold text-slate-800 text-sm uppercase tracking-wider">Recebimentos Realizados p/ Mês</h4>
            <span className="bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Histórico</span>
          </div>
          {sortedReceivedMonths.length > 0 ? (
            <div className="space-y-3">
              {sortedReceivedMonths.map(([month, amount]) => (
                <div key={month} className="flex items-center justify-between p-3 bg-emerald-50/30 rounded-xl border border-emerald-100/50">
                  <p className="text-xs font-bold text-slate-600 capitalize">{month}</p>
                  <p className="text-sm font-bold text-emerald-600">R$ {amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
