import React, { useState } from 'react';
import { User } from '../types';

interface LandingProps {
  onLogin: (user: User) => void;
}

const Landing: React.FC<LandingProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const savedUsers = JSON.parse(localStorage.getItem('modagestao_users') || '[]');

    if (isRegistering) {
      if (!name || !email || !password) {
        setError('Preencha todos os campos.');
        return;
      }
      if (savedUsers.find((u: User) => u.email === email)) {
        setError('Este e-mail já está cadastrado.');
        return;
      }
      const newUser = { id: Math.random().toString(36).substr(2, 9), name, email, password };
      localStorage.setItem('modagestao_users', JSON.stringify([...savedUsers, newUser]));
      onLogin(newUser);
    } else {
      const user = savedUsers.find((u: User) => u.email === email && u.password === password);
      if (user) {
        onLogin(user);
      } else {
        setError('E-mail ou senha incorretos.');
      }
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-white">
      {/* Visual Section */}
      <div className="hidden md:flex md:w-1/2 lg:w-2/3 relative overflow-hidden">
        <div className="absolute inset-0 z-10 bg-gradient-to-t from-indigo-900/90 via-indigo-900/40 to-transparent"></div>

        {/* Collage-style background */}
        <div className="absolute inset-0 grid grid-cols-2 grid-rows-2 gap-2 p-2">
          <img 
            src="https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&q=80&w=800" 
            className="w-full h-full object-cover rounded-lg" 
            alt="Storefront" 
          />
          <img 
            src="https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&q=80&w=800" 
            className="w-full h-full object-cover rounded-lg" 
            alt="Fashion Model" 
          />
          <img 
            src="https://images.unsplash.com/photo-1556742044-3c52d6e88c62?auto=format&fit=crop&q=80&w=800" 
            className="w-full h-full object-cover rounded-lg" 
            alt="Business Interaction" 
          />
          <img 
            src="https://images.unsplash.com/photo-1525507119028-ed4c629a60a3?auto=format&fit=crop&q=80&w=800" 
            className="w-full h-full object-cover rounded-lg" 
            alt="Clothing details" 
          />
        </div>

        <div className="absolute bottom-12 left-12 z-20 max-w-lg text-white">
          <div className="flex items-center gap-3 mb-6">
            <div className="bg-white p-2 rounded-xl shadow-xl">
              <svg className="w-8 h-8 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
            </div>
            <h1 className="text-4xl font-black tracking-tighter italic">MODAGESTÃO</h1>
          </div>
          <h2 className="text-3xl font-bold leading-tight mb-4">
            Gerencie suas vendas a prazo com o poder da inteligência artificial.
          </h2>
          <p className="text-lg text-indigo-100 opacity-90 leading-relaxed">
            Controle parcelamentos, acompanhe inadimplências e tome decisões estratégicas para o crescimento da sua loja de roupas.
          </p>
        </div>
      </div>

      {/* Auth Section */}
      <div className="flex-1 flex flex-col justify-center p-8 md:p-12 lg:p-20 bg-slate-50">
        <div className="max-w-md w-full mx-auto">
          <div className="md:hidden flex items-center gap-2 mb-10">
            <div className="bg-indigo-600 p-1.5 rounded-lg">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
            </div>
            <span className="text-xl font-black text-indigo-900 tracking-tighter italic">MODAGESTÃO</span>
          </div>

          <div className="mb-10">
            <h3 className="text-3xl font-bold text-slate-800 mb-2">
              {isRegistering ? 'Crie sua conta' : 'Seja bem-vindo(a)'}
            </h3>
            <p className="text-slate-500">
              {isRegistering 
                ? 'Comece a profissionalizar o financeiro da sua loja hoje mesmo.' 
                : 'Acesse seu painel administrativo para gerenciar seus recebíveis.'}
            </p>
          </div>

          <form onSubmit={handleAuth} className="space-y-5">
            {isRegistering && (
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Nome Completo</label>
                <input 
                  type="text" 
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none transition"
                  placeholder="Seu nome"
                />
              </div>
            )}
            <div className="space-y-1">
              <label className="text-xs font-bold text-slate-500 uppercase">E-mail Corporativo</label>
              <input 
                type="email" 
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none transition"
                placeholder="seu@email.com"
              />
