            <div className="space-y-1">
              <label className="text-xs font-bold text-slate-500 uppercase">Senha de Acesso</label>
              <input 
                type="password" 
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none transition"
                placeholder="••••••••"
              />
            </div>

            {error && <p className="text-rose-500 text-xs font-bold bg-rose-50 p-3 rounded-lg border border-rose-100">{error}</p>}

            <button 
              type="submit" 
              className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl hover:bg-indigo-700 transition shadow-lg shadow-indigo-200"
            >
              {isRegistering ? 'Cadastrar e Começar' : 'Entrar no Sistema'}
            </button>
          </form>

          <div className="mt-8 text-center">
            <button 
              onClick={() => setIsRegistering(!isRegistering)}
              className="text-sm font-semibold text-indigo-600 hover:text-indigo-800 transition"
            >
              {isRegistering ? 'Já tem uma conta? Faça login' : 'Ainda não tem conta? Cadastre sua loja'}
            </button>
          </div>

          <div className="mt-12 flex items-center justify-center gap-8 opacity-40">
            <img src="https://cdn-icons-png.flaticon.com/512/300/300221.png" className="h-6 grayscale" alt="Google" />
            <img src="https://cdn-icons-png.flaticon.com/512/732/732221.png" className="h-6 grayscale" alt="Microsoft" />
          </div>
        </div>
      </div>
    </div>
  );
};

