const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check for existing session
    const savedUser = localStorage.getItem('modagestao_current_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }

    const savedCustomers = localStorage.getItem('modagestao_customers');
    const savedSales = localStorage.getItem('modagestao_sales');
    if (savedCustomers) setCustomers(JSON.parse(savedCustomers));
    if (savedSales) setSales(JSON.parse(savedSales));

    setLoading(false);
  }, []);

  useEffect(() => {
    if (user) {
      localStorage.setItem('modagestao_current_user', JSON.stringify(user));
    } else {
      localStorage.removeItem('modagestao_current_user');
    }
  }, [user]);

  useEffect(() => {
    localStorage.setItem('modagestao_customers', JSON.stringify(customers));
  }, [customers]);

  useEffect(() => {
    localStorage.setItem('modagestao_sales', JSON.stringify(sales));
  }, [sales]);

  const handleLogin = (userData: User) => {
    setUser(userData);
  };

  const handleLogout = () => {
    setUser(null);
    setActiveView('dashboard');
  };

  const addCustomer = (data: Omit<Customer, 'id' | 'createdAt'>) => {
    const newCustomer: Customer = {
      ...data,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now()
    };
    setCustomers(prev => [newCustomer, ...prev]);
  };

  const deleteCustomer = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir este cliente? Isso não removerá as vendas, mas elas ficarão órfãs.')) {
      setCustomers(prev => prev.filter(c => c.id !== id));
    }
  };

  const addSale = (saleData: Omit<Sale, 'id'>) => {
    const newSale: Sale = {
      ...saleData,
      id: Math.random().toString(36).substr(2, 9),
    };
    setSales(prev => [newSale, ...prev]);
  };

  const updateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  const handleImportData = (data: { customers: Customer[], sales: Sale[] }) => {
    setCustomers(data.customers);
    setSales(data.sales);
  };

  const handleClearData = () => {
    setCustomers([]);
    setSales([]);
    localStorage.removeItem('modagestao_customers');
    localStorage.removeItem('modagestao_sales');
    setActiveView('dashboard');
  };

  if (loading) return null;

  if (!user) {
    return <Landing onLogin={handleLogin} />;
  }

  return (
