          </div>
          <h1 className="text-xl font-bold tracking-tight italic">ModaGestão</h1>
        </div>

        <div className="mb-8 p-3 bg-indigo-800/30 rounded-xl border border-indigo-700/30">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-indigo-400 flex items-center justify-center text-[10px] font-black uppercase tracking-tighter">
