          </div>
          {sortedReceivedMonths.length > 0 ? (
            <div className="space-y-3">
              {/* FIX: Explicitly typing the destructured parameters to avoid 'unknown' type error (line 122 fix) */}
              {sortedReceivedMonths.map(([month, amount]: [string, number]) => (
                <div key={month} className="flex items-center justify-between p-3 bg-emerald-50/30 rounded-xl border border-emerald-100/50">
                  <p className="text-xs font-bold text-slate-600 capitalize">{month}</p>
                  <p className="text-sm font-bold text-emerald-600">R$ {formatCurrency(amount)}</p>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-slate-400 text-sm text-center py-8">Nenhum valor recebido ainda.</p>
          )}
        </div>

        {/* Future Forecast Section */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-bold text-slate-800 text-sm uppercase tracking-wider">Previsão de Recebimentos Futuros</h4>
            <span className="bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Projeção</span>
          </div>
          {sortedPendingMonths.length > 0 ? (
            <div className="space-y-3">
              {/* FIX: Explicitly typing the destructured parameters to avoid 'unknown' type error (line 142 fix) */}
              {sortedPendingMonths.map(([month, amount]: [string, number]) => (
                <div key={month} className="flex items-center justify-between p-3 bg-indigo-50/30 rounded-xl border border-indigo-100/50">
                  <p className="text-xs font-bold text-slate-600 capitalize">{month}</p>
                  <p className="text-sm font-bold text-indigo-600">R$ {formatCurrency(amount)}</p>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-slate-400 text-sm text-center py-8">Nenhum recebimento futuro previsto.</p>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-80">
          <h4 className="font-semibold text-slate-800 mb-4">Fluxo de Caixa (Pendentes vs Recebidos)</h4>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} />
              <YAxis axisLine={false} tickLine={false} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
              <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-indigo-50 p-6 rounded-2xl border border-indigo-100 flex flex-col h-80 overflow-hidden">
          <div className="flex justify-between items-center mb-4">
            <h4 className="font-bold text-indigo-900 flex items-center gap-2">
              <svg className="w-5 h-5 text-indigo-600" fill="currentColor" viewBox="0 0 20 20"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 14.95a1 1 0 010-1.414l.707-.707a1 1 0 011.414 1.414l-.707.707a1 1 0 01-1.414 0zM6.464 14.95l.707-.707a1 1 0 011.414 1.414l-.707.707a1 1 0 01-1.414 0l-.707-.707z" /></svg>
              Insights da IA
            </h4>
            <button 
              onClick={fetchInsights}
              disabled={isSyncing}
              className="text-xs font-semibold text-indigo-600 hover:text-indigo-800 disabled:opacity-50"
            >
              {isSyncing ? 'Analisando...' : 'Atualizar'}
            </button>
          </div>
          <div className="flex-1 overflow-y-auto text-indigo-800 text-sm leading-relaxed space-y-3">
             {insights.split('\n').map((line, i) => (
               <p key={i}>{line}</p>
             ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { User } from '../types';

interface LandingProps {
  onLogin: (user: User) => void;
}

const Landing: React.FC<LandingProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const savedUsers = JSON.parse(localStorage.getItem('modagestao_users') || '[]');

    if (isRegistering) {
      if (!name || !email || !password) {
        setError('Preencha todos os campos.');
        return;
      }
      if (savedUsers.find((u: User) => u.email === email)) {
        setError('Este e-mail já está cadastrado.');
        return;
      }
      const newUser = { id: Math.random().toString(36).substr(2, 9), name, email, password };
      localStorage.setItem('modagestao_users', JSON.stringify([...savedUsers, newUser]));
      onLogin(newUser);
    } else {
      const user = savedUsers.find((u: User) => u.email === email && u.password === password);
      if (user) {
        onLogin(user);
      } else {
        setError('E-mail ou senha incorretos.');
      }
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-white">
      {/* Visual Section */}
      <div className="hidden md:flex md:w-1/2 lg:w-2/3 relative overflow-hidden">
        <div className="absolute inset-0 z-10 bg-gradient-to-t from-indigo-900/90 via-indigo-900/40 to-transparent"></div>

        {/* Collage-style background */}
        <div className="absolute inset-0 grid grid-cols-2 grid-rows-2 gap-2 p-2">
          <div className="relative overflow-hidden rounded-lg">
            <img 
              src="https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&q=80&w=800" 
              className="w-full h-full object-cover" 
              alt="Storefront" 
            />
          </div>
          <div className="relative overflow-hidden rounded-lg">
            <img 
              src="https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&q=80&w=800" 
              className="w-full h-full object-cover" 
              alt="Fashion Model" 
            />
          </div>
          <div className="relative overflow-hidden rounded-lg group">
            <img 
              src="https://images.unsplash.com/photo-1556742044-3c52d6e88c62?auto=format&fit=crop&q=80&w=800" 
              className="w-full h-full object-cover transform group-hover:scale-105 transition duration-700" 
              alt="Business Interaction" 
            />
            {/* Inspirational Quote Overlay */}
            <div className="absolute inset-0 flex items-center justify-center p-6 bg-indigo-900/20">
              <p className="text-white text-xl lg:text-3xl font-black text-center uppercase tracking-widest leading-none drop-shadow-2xl italic">
                Faça hoje o seu futuro
              </p>
            </div>
          </div>
          <div className="relative overflow-hidden rounded-lg">
            <img 
              src="https://images.unsplash.com/photo-1525507119028-ed4c629a60a3?auto=format&fit=crop&q=80&w=800" 
              className="w-full h-full object-cover" 
              alt="Clothing details" 
            />
          </div>
        </div>

        <div className="absolute bottom-12 left-12 z-20 max-w-lg text-white">
          <div className="flex items-center gap-3 mb-6">
            <div className="bg-white p-2 rounded-xl shadow-xl">
              <svg className="w-8 h-8 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
            </div>
            <h1 className="text-4xl font-black tracking-tighter italic">MODAGESTÃO</h1>
