            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <h1 className="text-xl font-bold tracking-tight italic">ModaGestão</h1>
        </div>

        <div className="mb-8 p-3 bg-indigo-50 rounded-xl border border-white/20 shadow-lg">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-full bg-indigo-600 text-white flex items-center justify-center text-[10px] font-black uppercase tracking-tighter shadow-md">
              {user.name.substring(0, 2)}
            </div>
            <div className="truncate">
              <p className="text-sm font-black text-slate-900 truncate leading-tight">{user.name}</p>
              <p className="text-[10px] text-indigo-600 font-medium truncate">{user.email}</p>
            </div>
          </div>
        </div>

        <div className="space-y-2 flex-1">
          <button 
            onClick={() => setActiveView('dashboard')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeView === 'dashboard' ? 'bg-indigo-800 text-white shadow-inner' : 'text-indigo-300 hover:bg-indigo-800/50'}`}
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>
