    await new Promise(resolve => setTimeout(resolve, 1200));

    const cloudCustomers = localStorage.getItem(`cloud_customers_${userId}`);
    const cloudSales = localStorage.getItem(`cloud_sales_${userId}`);

    if (cloudCustomers) setCustomers(JSON.parse(cloudCustomers));
    if (cloudSales) setSales(JSON.parse(cloudSales));

    setSyncStatus('synced');
  }, []);

  useEffect(() => {
    const savedUser = localStorage.getItem('modagestao_current_user');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      fetchCloudData(parsedUser.id);
    }
    setLoading(false);
  }, [fetchCloudData]);

  // Effect to handle automatic saving to "Cloud" (simulated via namespaced localStorage)
  useEffect(() => {
    if (!loading && user) {
      setSyncStatus('syncing');
      const timer = setTimeout(() => {
        // Here, in a real production app, you would use: 
        // fetch('/api/save', { method: 'POST', body: JSON.stringify({ customers, sales }) })
        localStorage.setItem(`cloud_customers_${user.id}`, JSON.stringify(customers));
        localStorage.setItem(`cloud_sales_${user.id}`, JSON.stringify(sales));
