  const [activeTab, setActiveTab] = useState<'backup' | 'cloud' | 'deployment' | 'help'>('backup');

  const handleExport = () => {
    const data = {
      customers,
      sales,
      exportDate: new Date().toISOString(),
      version: '1.0'
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup_modagestao_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.customers && json.sales) {
          if (window.confirm('Isso irá substituir todos os dados atuais. Deseja continuar?')) {
            onImport({ customers: json.customers, sales: json.sales });
            alert('Dados importados com sucesso!');
