      {/* Auth Section */}
      <div className="flex-1 flex flex-col justify-center p-8 md:p-12 lg:p-20 bg-slate-50">
        <div className="max-w-md w-full mx-auto">
          <div className="md:hidden flex items-center gap-2 mb-10">
            <div className="bg-indigo-600 p-1.5 rounded-lg">
              <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
            </div>
            <span className="text-xl font-black text-indigo-900 tracking-tighter italic">MODAGESTÃO</span>
          </div>

          <div className="mb-10">
            <h3 className="text-3xl font-bold text-slate-800 mb-2">
              {isRegistering ? 'Crie sua conta' : 'Acesse seu painel'}
            </h3>
            <p className="text-slate-500">
              {isRegistering 
                ? 'Sincronize seus dados em todos os seus dispositivos.' 
                : 'Seus dados serão sincronizados automaticamente via nuvem.'}
            </p>
          </div>

          <form onSubmit={handleAuth} className="space-y-5">
            {isRegistering && (
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Nome da Loja / Gestor</label>
                <input 
                  type="text" 
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600 outline-none transition"
                  placeholder="Ex: Boutique da Maria"
                />
              </div>
            )}
            <div className="space-y-1">
              <label className="text-xs font-bold text-slate-500 uppercase">E-mail de Acesso</label>
              <input 
                type="email" 
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600 outline-none transition"
                placeholder="seu@email.com"
              />
