import { GoogleGenAI, Type } from "@google/genai";
import { Sale, Customer } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Simple cache to avoid redundant calls within the same session
let lastAnalysis: string | null = null;
let lastContextHash: string | null = null;

export const getFinancialInsights = async (
  sales: Sale[],
  customers: Customer[]
) => {
  if (sales.length === 0) return "Adicione algumas vendas para que eu possa analisar seu negócio.";

  const context = {
    totalSales: sales.length,
    totalVolume: sales.reduce((acc, s) => acc + s.totalAmount, 0),
    customersCount: customers.length,
    pendingPayments: sales.flatMap(s => s.installments).filter(i => i.status !== 'PAID').length,
  };

  const contextHash = JSON.stringify(context);
  if (contextHash === lastContextHash && lastAnalysis) {
    return lastAnalysis;
  }

  const model = "gemini-3-flash-preview";
  const prompt = `Analise os seguintes dados financeiros de uma loja de roupas e forneça 3 insights estratégicos curtos sobre vendas a prazo e cobranças. Seja profissional e direto em português brasileiro.
  Dados: ${contextHash}`;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        temperature: 0.7,
        maxOutputTokens: 350, // Reduced to save quota
      }
    });

    const text = response.text;
    lastAnalysis = text;
    lastContextHash = contextHash;
    return text;
  } catch (error: any) {
    console.error("Gemini Error:", error);

    // Specific handling for Rate Limit / Quota error
    if (error?.message?.includes("429") || error?.status === 429) {
      return "⚠️ Limite de consultas atingido. Por favor, aguarde 1 a 2 minutos antes de solicitar novos insights. Seus dados financeiros continuam seguros.";
    }

    return "Não foi possível gerar insights no momento. Verifique sua conexão ou tente novamente mais tarde.";
  }
};

import React, { useState, useEffect } from 'react';
import { Sale, Customer, PaymentStatus } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DashboardProps {
  sales: Sale[];
  customers: Customer[];
}

const Dashboard: React.FC<DashboardProps> = ({ sales, customers }) => {
  const [insights, setInsights] = useState<string>('');
  const [isSyncing, setIsSyncing] = useState(false);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(value);
  };

  const totalReceivable: number = sales.reduce((acc: number, s) => {
    return acc + s.installments.reduce((sum: number, i) => sum + (i.amount - i.paidAmount), 0);
  }, 0);

  const totalReceived: number = sales.reduce((acc: number, s) => {
    return acc + s.installments.reduce((sum: number, i) => sum + i.paidAmount, 0);
  }, 0);

  const overdueSales = sales.filter(s => 
    s.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date())
  );

  const parseMonthYear = (str: string) => {
    const months: Record<string, number> = {
      'janeiro': 0, 'fevereiro': 1, 'março': 2, 'abril': 3, 'maio': 4, 'junho': 5,
      'julho': 6, 'agosto': 7, 'setembro': 8, 'outubro': 9, 'novembro': 10, 'dezembro': 11
    };
    const [month, year] = str.toLowerCase().split(' de ');
    return new Date(parseInt(year), months[month] || 0).getTime();
  };

  const monthlyPendingTotals = sales.flatMap(s => s.installments)
    .filter(i => i.status !== PaymentStatus.PAID)
    .reduce((acc, inst) => {
      const date = new Date(inst.dueDate);
      const key = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
      acc[key] = (acc[key] || 0) + (inst.amount - inst.paidAmount);
      return acc;
    }, {} as Record<string, number>);

  const monthlyReceivedTotals = sales.flatMap(s => s.installments)
    .filter(i => i.paidAmount > 0)
    .reduce((acc, inst) => {
      const date = new Date(inst.dueDate);
      const key = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
      acc[key] = (acc[key] || 0) + inst.paidAmount;
      return acc;
    }, {} as Record<string, number>);

  const sortedPendingMonths = Object.entries(monthlyPendingTotals)
    .sort((a, b) => parseMonthYear(a[0]) - parseMonthYear(b[0]))
    .slice(0, 6);

  const sortedReceivedMonths = Object.entries(monthlyReceivedTotals)
    .sort((a, b) => parseMonthYear(b[0]) - parseMonthYear(a[0]))
    .slice(0, 6);

  const chartData = [
    { name: 'Recebido', value: totalReceived, color: '#10b981' },
    { name: 'A Receber', value: totalReceivable, color: '#6366f1' },
  ];

  const fetchInsights = async (force = false) => {
    if (!force && insights && insights !== 'Carregando insights...') return;
    if (sales.length === 0) {
      setInsights("Registre suas primeiras vendas para ver a análise da IA.");
      return;
    }

    setIsSyncing(true);
    setInsights("Analisando seus dados financeiros...");
    const result = await getFinancialInsights(sales, customers);
    setInsights(result || "Nenhum insight disponível.");
    setIsSyncing(false);
  };

  useEffect(() => {
    // Only auto-fetch if we don't have insights yet
    if (!insights) {
      fetchInsights();
    }
  }, [sales.length]);

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium uppercase tracking-wider text-[10px] mb-1">Total a Receber</p>
          <h3 className="text-2xl font-bold text-indigo-600">R$ {formatCurrency(totalReceivable)}</h3>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium uppercase tracking-wider text-[10px] mb-1">Total Recebido</p>
          <h3 className="text-2xl font-bold text-emerald-600">R$ {formatCurrency(totalReceived)}</h3>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium uppercase tracking-wider text-[10px] mb-1">Vendas em Atraso</p>
          <h3 className="text-2xl font-bold text-rose-500">{overdueSales.length}</h3>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-bold text-slate-800 text-sm uppercase tracking-wider">Recebimentos Realizados p/ Mês</h4>
            <span className="bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Histórico</span>
          </div>
          {sortedReceivedMonths.length > 0 ? (
            <div className="space-y-3">
              {sortedReceivedMonths.map(([month, amount]: [string, number]) => (
