import React, { useState, useEffect } from 'react';
import { User } from '../types';

interface LandingProps {
  onLogin: (user: User) => void;
}

const Landing: React.FC<LandingProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Load merged users from LocalStorage on mount
  const getSavedUsers = (): User[] => {
    return JSON.parse(localStorage.getItem('gestao93_users') || '[]');
  };

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const savedUsers = getSavedUsers();

    if (isRegistering) {
      if (!name || !email || !password) {
        setError('Preencha todos os campos.');
        return;
      }
      if (savedUsers.find((u: User) => u.email === email)) {
        setError('Este e-mail já está cadastrado.');
        return;
      }
      const newUser: User = { 
        id: Math.random().toString(36).substr(2, 9), 
        name, 
        email, 
        password,
        authProvider: 'local'
      };
      const updatedUsers = [...savedUsers, newUser];
      localStorage.setItem('gestao93_users', JSON.stringify(updatedUsers));
      localStorage.setItem('gestao93_current_user', JSON.stringify(newUser));
      onLogin(newUser);
    } else {
      const user = savedUsers.find((u: User) => u.email === email && u.password === password);
      if (user) {
        localStorage.setItem('gestao93_current_user', JSON.stringify(user));
        onLogin(user);
      } else {
        setError('E-mail ou senha incorretos.');
      }
    }
  };

  const handleOneDriveLogin = async () => {
    setIsAuthenticating(true);
    setError('');

    // Simulate Microsoft OAuth Redirect and Return
    setTimeout(() => {
      const msUser: User = {
        id: 'ms_master_account',
        name: 'Administrador Gestão 93',
        email: 'gestao93@cloud.com',
        authProvider: 'onedrive',
        avatarUrl: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=facearea&facepad=2&w=256&h=256&q=80'
      };

      localStorage.setItem('gestao93_current_user', JSON.stringify(msUser));

      // Pull credentials from Cloud Mock if they exist
      const cloudStorage = localStorage.getItem(`gestao93_cloud_master_${msUser.id}`);
      if (cloudStorage) {
         const parsed = JSON.parse(cloudStorage);
         if (parsed.users) {
            const localUsers = getSavedUsers();
            const merged = [...localUsers];
            parsed.users.forEach((cu: User) => {
               if (!merged.find(u => u.email === cu.email)) merged.push(cu);
            });
            localStorage.setItem('gestao93_users', JSON.stringify(merged));
         }
      }

      onLogin(msUser);
      setIsAuthenticating(false);
    }, 1500);
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-white">
      {/* Visual Section */}
      <div className="hidden md:flex md:w-1/2 lg:w-2/3 relative overflow-hidden">
        <div className="absolute inset-0 z-10 bg-gradient-to-t from-indigo-950 via-indigo-900/40 to-transparent"></div>

