    const simulatedEmail = prompt("Para simular o login Microsoft, digite seu e-mail Outlook/Hotmail:", "loja93@outlook.com");

    if (!simulatedEmail) {
      setIsAuthenticating(false);
      return;
    }

    setTimeout(() => {
      // The ID is generated from the email to simulate unique cloud storage buckets per MS account
      const uniqueId = btoa(simulatedEmail).replace(/=/g, '');

      const msUser: User = {
        id: `ms_${uniqueId}`,
        name: simulatedEmail.split('@')[0].toUpperCase(),
        email: simulatedEmail,
        authProvider: 'onedrive',
        avatarUrl: `https://ui-avatars.com/api/?name=${simulatedEmail}&background=4f46e5&color=fff`
      };

      localStorage.setItem('gestao93_current_user', JSON.stringify(msUser));

      // Pull credentials from this specific user's Cloud bucket if they exist
      const cloudStorageKey = `gestao93_cloud_master_${msUser.id}`;
      const cloudStorage = localStorage.getItem(cloudStorageKey);

      if (cloudStorage) {
         const parsed = JSON.parse(cloudStorage);
         if (parsed.users) {
            const localUsers = getSavedUsers();
            const merged = [...localUsers];
            parsed.users.forEach((cu: User) => {
               if (!merged.find(u => u.email === cu.email)) merged.push(cu);
            });
            localStorage.setItem('gestao93_users', JSON.stringify(merged));
         }
      }

      onLogin(msUser);
      setIsAuthenticating(false);
    }, 1200);
  };

  return (
