          <div className="relative overflow-hidden rounded-lg"><img src="https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover" alt="Store" /></div>
          <div className="relative overflow-hidden rounded-lg"><img src="https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover" alt="Fashion" /></div>
          <div className="relative overflow-hidden rounded-lg group">
