import React, { useState, useEffect } from 'react';
import { User } from '../types';

interface LandingProps {
  onLogin: (user: User) => void;
}

const Landing: React.FC<LandingProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Load merged users from LocalStorage on mount
  const getSavedUsers = (): User[] => {
    return JSON.parse(localStorage.getItem('gestao93_users') || '[]');
  };

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const savedUsers = getSavedUsers();

    if (isRegistering) {
      if (!name || !email || !password) {
        setError('Preencha todos os campos.');
        return;
      }
      if (savedUsers.find((u: User) => u.email === email)) {
        setError('Este e-mail já está cadastrado.');
        return;
      }
      const newUser: User = { 
        id: Math.random().toString(36).substr(2, 9), 
        name, 
        email, 
        password,
        authProvider: 'local'
      };
      const updatedUsers = [...savedUsers, newUser];
      localStorage.setItem('gestao93_users', JSON.stringify(updatedUsers));
      localStorage.setItem('gestao93_current_user', JSON.stringify(newUser));
      onLogin(newUser);
    } else {
      const user = savedUsers.find((u: User) => u.email === email && u.password === password);
      if (user) {
        localStorage.setItem('gestao93_current_user', JSON.stringify(user));
        onLogin(user);
      } else {
        setError('E-mail ou senha incorretos.');
      }
    }
  };

  const handleOneDriveLogin = async () => {
    setIsAuthenticating(true);
    setError('');

    const simulatedEmail = prompt("Para simular o login Microsoft, digite seu e-mail Outlook/Hotmail:", "loja93@outlook.com");

    if (!simulatedEmail) {
      setIsAuthenticating(false);
      return;
    }

    setTimeout(() => {
      const uniqueId = btoa(simulatedEmail).replace(/=/g, '');

      const msUser: User = {
        id: `ms_${uniqueId}`,
        name: simulatedEmail.split('@')[0].toUpperCase(),
        email: simulatedEmail,
        authProvider: 'onedrive',
        avatarUrl: `https://ui-avatars.com/api/?name=${simulatedEmail}&background=4f46e5&color=fff`
      };

      localStorage.setItem('gestao93_current_user', JSON.stringify(msUser));

      const cloudStorageKey = `gestao93_cloud_master_${msUser.id}`;
      const cloudStorage = localStorage.getItem(cloudStorageKey);

      if (cloudStorage) {
         const parsed = JSON.parse(cloudStorage);
         if (parsed.users) {
            const localUsers = getSavedUsers();
            const merged = [...localUsers];
            parsed.users.forEach((cu: User) => {
               if (!merged.find(u => u.email === cu.email)) merged.push(cu);
            });
            localStorage.setItem('gestao93_users', JSON.stringify(merged));
         }
      }

      onLogin(msUser);
      setIsAuthenticating(false);
    }, 1200);
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-white">
      {/* Visual Section */}
      <div className="md:w-1/2 lg:w-2/3 relative h-[40vh] md:h-screen overflow-hidden">
        {/* Background Image of Woman Shopping */}
        <img 
          src="https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&q=80&w=1600" 
          className="absolute inset-0 w-full h-full object-cover" 
          alt="Woman Shopping" 
        />

        {/* Overlay for better text readability */}
        <div className="absolute inset-0 z-10 bg-gradient-to-t md:bg-gradient-to-r from-indigo-950/90 via-indigo-950/40 to-transparent"></div>

        {/* Content Overlay */}
        <div className="absolute inset-0 z-20 flex flex-col justify-end md:justify-center p-8 md:p-16 lg:p-24 text-white">
          <div className="animate-in fade-in slide-in-from-left-8 duration-1000">
            <div className="flex items-center gap-4 mb-2 md:mb-6">
              <div className="bg-indigo-600 p-2 md:p-3 rounded-2xl shadow-2xl border border-white/20">
                <svg className="w-8 h-8 md:w-12 md:h-12 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
                </svg>
              </div>
              <h1 className="text-5xl md:text-8xl font-black tracking-tighter italic uppercase drop-shadow-2xl">
                Gestão 93
              </h1>
            </div>

            <p className="text-xl md:text-4xl font-light italic text-indigo-100 mb-8 max-w-xl leading-tight drop-shadow-md">
              “Lute Hoje pelos seus Sonhos”
            </p>

            <div className="hidden md:flex items-center gap-2 bg-white/10 backdrop-blur-md px-4 py-2 rounded-full w-fit border border-white/20">
              <img src="https://upload.wikimedia.org/wikipedia/commons/3/3c/Microsoft_Office_OneDrive_%282019-present%29.svg" className="w-4 h-4" alt="OneDrive" />
              <span className="text-[10px] font-bold uppercase tracking-widest text-indigo-100">Sincronização Nuvem Ativa</span>
            </div>
          </div>
        </div>
      </div>

      {/* Auth Section */}
      <div className="flex-1 flex flex-col justify-center p-8 md:p-12 lg:p-20 bg-slate-50 overflow-y-auto">
        <div className="max-w-md w-full mx-auto">
          <div className="mb-8">
            <h3 className="text-3xl font-bold text-slate-800 mb-2">Acesso Seguro</h3>
            <p className="text-slate-500 text-sm">Gerencie suas vendas a prazo com inteligência e segurança.</p>
          </div>

          <div className="space-y-4">
            <button 
              onClick={handleOneDriveLogin}
              disabled={isAuthenticating}
              className="w-full bg-white border border-slate-200 text-slate-700 font-bold py-4 rounded-2xl hover:bg-slate-50 transition shadow-sm flex items-center justify-center gap-3 active:scale-[0.98] disabled:opacity-50"
            >
              {isAuthenticating ? (
                <div className="w-5 h-5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <img src="https://upload.wikimedia.org/wikipedia/commons/3/3c/Microsoft_Office_OneDrive_%282019-present%29.svg" className="h-6" alt="OneDrive" />
              )}
              {isAuthenticating ? 'Validando Conta...' : 'Entrar com meu OneDrive'}
            </button>

            {/* App Download Recommendation */}
            <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-2xl flex items-start gap-3">
              <div className="bg-white p-2 rounded-lg shadow-sm shrink-0">
                <svg className="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
              </div>
              <div>
                <p className="text-[11px] font-bold text-indigo-900 uppercase tracking-tight">Dica de Sincronização</p>
                <p className="text-[10px] text-indigo-700 leading-tight mt-0.5">
                  Baixe o app <b>OneDrive</b> para salvar seus arquivos em constante modificação com segurança.
                </p>
                <a href="https://www.microsoft.com/pt-br/microsoft-365/onedrive/download" target="_blank" className="text-[9px] font-black text-indigo-600 underline uppercase mt-2 inline-block">Baixar App Agora</a>
              </div>
            </div>

            <div className="relative py-4">
               <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div>
               <div className="relative flex justify-center text-xs uppercase"><span className="bg-slate-50 px-2 text-slate-400 font-bold">Acesso por E-mail</span></div>
            </div>

            <form onSubmit={handleAuth} className="space-y-4">
              {isRegistering && (
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Sua Loja</label>
                  <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600 outline-none transition" placeholder="Nome da Unidade" />
                </div>
              )}
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">E-mail</label>
                <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600 outline-none transition" placeholder="seu@email.com" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Senha</label>
                <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600 outline-none transition" placeholder="••••••••" />
              </div>

              {error && <p className="text-rose-500 text-[10px] font-bold bg-rose-50 p-3 rounded-lg border border-rose-100">{error}</p>}

              <button type="submit" className="w-full bg-indigo-900 text-white font-bold py-4 rounded-xl hover:bg-indigo-950 transition shadow-lg shadow-indigo-100">
                {isRegistering ? 'Criar Acesso' : 'Entrar'}
              </button>
            </form>

            <div className="text-center">
              <button onClick={() => setIsRegistering(!isRegistering)} className="text-xs font-bold text-indigo-600 hover:text-indigo-800 transition">
                {isRegistering ? 'Já tenho acesso? Logar' : 'Novo Vendedor/Usuário'}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

