import React, { useState, useEffect, useCallback } from 'react';
import { View, Customer, Sale, User } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';
import Agenda from './components/Agenda';
import Settings from './components/Settings';
import Landing from './components/Landing';
import Tutorial from './components/Tutorial';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  // Load cloud data (including users) from OneDrive
  const syncWithOneDrive = useCallback(async (action: 'upload' | 'download') => {
    if (!user || user.authProvider !== 'onedrive') return;

    setSyncStatus('syncing');
    try {
      await new Promise(resolve => setTimeout(resolve, 1000));

      const storageKey = `gestao93_cloud_master_${user.id}`;
      if (action === 'download') {
        const cloudData = localStorage.getItem(storageKey);
        if (cloudData) {
          const parsed = JSON.parse(cloudData);
          setCustomers(parsed.customers || []);
          setSales(parsed.sales || []);
          if (parsed.users) {
             const localUsers = JSON.parse(localStorage.getItem('gestao93_users') || '[]');
             const mergedUsers = [...localUsers];
             parsed.users.forEach((cu: User) => {
               if (!mergedUsers.find(u => u.email === cu.email)) mergedUsers.push(cu);
             });
             localStorage.setItem('gestao93_users', JSON.stringify(mergedUsers));
          }
        }
      } else {
        const localUsers = JSON.parse(localStorage.getItem('gestao93_users') || '[]');
        const dataToUpload = JSON.stringify({ 
          customers, 
          sales, 
          users: localUsers,
          lastSync: new Date().toISOString()
        });
        localStorage.setItem(storageKey, dataToUpload);
      }
      setSyncStatus('synced');
    } catch (err) {
      console.error("Sync Error:", err);
      setSyncStatus('error');
    }
  }, [user, customers, sales]);

  useEffect(() => {
    const savedUser = localStorage.getItem('gestao93_current_user');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      checkTutorialStatus(parsedUser.id);

      if (parsedUser.authProvider === 'onedrive') {
        syncWithOneDrive('download');
      } else {
        const localCustomers = localStorage.getItem(`gestao93_customers_${parsedUser.id}`);
        const localSales = localStorage.getItem(`gestao93_sales_${parsedUser.id}`);
        if (localCustomers) setCustomers(JSON.parse(localCustomers));
        if (localSales) setSales(JSON.parse(localSales));
      }
    }
    setLoading(false);
  }, []);

  const checkTutorialStatus = (userId: string) => {
    const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
    if (!tutorialSeen) {
      setShowTutorial(true);
    }
  };

  const handleFinishTutorial = () => {
    if (user) {
      localStorage.setItem(`gestao93_tutorial_seen_${user.id}`, 'true');
    }
    setShowTutorial(false);
  };

  useEffect(() => {
    if (!loading && user) {
      const timer = setTimeout(() => {
        if (user.authProvider === 'onedrive') {
          syncWithOneDrive('upload');
        } else {
          localStorage.setItem(`gestao93_customers_${user.id}`, JSON.stringify(customers));
          localStorage.setItem(`gestao93_sales_${user.id}`, JSON.stringify(sales));
        }
        localStorage.setItem('gestao93_current_user', JSON.stringify(user));
      }, 2000);
      return () => clearTimeout(timer);
    }
  }, [customers, sales, user, loading, syncWithOneDrive]);

  const handleLogin = (userData: User) => {
    setUser(userData);
    checkTutorialStatus(userData.id);
  };

  const handleLogout = () => {
    setUser(null);
    setCustomers([]);
    setSales([]);
    localStorage.removeItem('gestao93_current_user');
    setActiveView('dashboard');
    setShowTutorial(false);
  };

  const addCustomer = (data: Omit<Customer, 'id' | 'createdAt'>) => {
    const newCustomer: Customer = {
      ...data,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now()
    };
    setCustomers(prev => [newCustomer, ...prev]);
  };

  const deleteCustomer = (id: string) => {
    if (window.confirm('Excluir este cliente e todo seu histórico?')) {
      setCustomers(prev => prev.filter(c => c.id !== id));
    }
  };

  const addSale = (saleData: Omit<Sale, 'id'>) => {
    const newSale: Sale = { ...saleData, id: Math.random().toString(36).substr(2, 9) };
    setSales(prev => [newSale, ...prev]);
  };

  const updateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  if (loading) return null;
  if (!user) return <Landing onLogin={handleLogin} />;

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50">
      {showTutorial && <Tutorial onClose={handleFinishTutorial} />}

      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col p-6 sticky top-0 md:h-screen z-10 border-r border-indigo-900 shadow-2xl">
        <div className="flex items-center gap-3 mb-10">
          <div className="bg-indigo-600 p-2 rounded-lg shadow-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <h1 className="text-xl font-bold tracking-tight italic">Gestão 93</h1>
        </div>

        <div className="mb-8 p-3 bg-indigo-50 rounded-xl border border-white/20 shadow-lg group">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-indigo-600 text-white flex items-center justify-center text-xs font-black uppercase shadow-inner overflow-hidden border-2 border-white">
              {user.avatarUrl ? <img src={user.avatarUrl} alt="Avatar" className="w-full h-full object-cover" /> : user.name.substring(0, 2)}
            </div>
            <div className="truncate">
              <p className="text-sm font-black text-slate-900 truncate leading-tight">{user.name}</p>
              <div className="flex items-center gap-1">
                 {user.authProvider === 'onedrive' && (
                    <img src="https://upload.wikimedia.org/wikipedia/commons/3/3c/Microsoft_Office_OneDrive_%282019-present%29.svg" className="w-3 h-3" alt="OneDrive" />
                 )}
                 <p className="text-[9px] text-indigo-600 font-bold uppercase tracking-widest truncate">
                   {user.authProvider === 'onedrive' ? 'Nuvem Ativa' : 'Local'}
                 </p>
              </div>
            </div>
          </div>
        </div>

        <div className="space-y-2 flex-1">
          <button onClick={() => setActiveView('dashboard')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeView === 'dashboard' ? 'bg-indigo-600 text-white shadow-lg' : 'text-indigo-300 hover:bg-white/5'}`}>
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>
            Dashboard
          </button>
          <button onClick={() => setActiveView('agenda')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeView === 'agenda' ? 'bg-indigo-600 text-white shadow-lg' : 'text-indigo-300 hover:bg-white/5'}`}>
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z" /></svg>
            Agenda Mensal
          </button>
          <button onClick={() => setActiveView('sales')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeView === 'sales' ? 'bg-indigo-600 text-white shadow-lg' : 'text-indigo-300 hover:bg-white/5'}`}>
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            Vendas a Prazo
          </button>
          <button onClick={() => setActiveView('customers')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeView === 'customers' ? 'bg-indigo-600 text-white shadow-lg' : 'text-indigo-300 hover:bg-white/5'}`}>
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
            Clientes
          </button>
        </div>

        <div className="mt-auto pt-6 border-t border-white/10 space-y-4">
          <div className="px-4 py-2 bg-white/5 rounded-lg flex items-center justify-between">
            <span className="text-[9px] font-bold uppercase text-indigo-400">Sincronização</span>
            <div className="flex items-center gap-1.5">
               <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-400' : syncStatus === 'error' ? 'bg-rose-500' : 'bg-amber-400 animate-pulse'}`}></div>
               <span className={`text-[9px] font-black uppercase ${syncStatus === 'synced' ? 'text-emerald-400' : syncStatus === 'error' ? 'text-rose-500' : 'text-amber-400'}`}>
                 {syncStatus === 'synced' ? 'OK' : syncStatus === 'error' ? 'Erro' : 'Processando'}
               </span>
            </div>
          </div>

          <div className="space-y-1">
            <button onClick={() => setActiveView('settings')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition ${activeView === 'settings' ? 'bg-white/10 text-white' : 'text-indigo-400 hover:text-white'}`}>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              Configurações
            </button>
            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl transition text-rose-400 hover:bg-rose-500/10">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              Sair
            </button>
          </div>
        </div>
      </nav>

      <main className="flex-1 p-4 md:p-10 max-w-7xl mx-auto w-full overflow-y-auto no-scrollbar">
        {activeView === 'dashboard' && <Dashboard sales={sales} customers={customers} />}
        {activeView === 'agenda' && <Agenda sales={sales} customers={customers} />}
        {activeView === 'customers' && <CustomerList customers={customers} sales={sales} onAdd={addCustomer} onDelete={deleteCustomer} />}
        {activeView === 'sales' && <SalesManager sales={sales} customers={customers} onAddSale={addSale} onUpdateSale={updateSale} />}
        {activeView === 'settings' && <Settings customers={customers} sales={sales} onImport={(d) => {setCustomers(d.customers); setSales(d.sales)}} onClear={() => {setCustomers([]); setSales([]);}} />}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useLayoutEffect } from 'react';

interface TutorialProps {
  onClose: () => void;
  activeView: string;
}

interface Step {
  id: string;
  targetId: string;
  title: string;
  content: string;
  requiredView?: string;
}

const Tutorial: React.FC<TutorialProps> = ({ onClose, activeView }) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [coords, setCoords] = useState<{ top: number, left: number, width: number, height: number } | null>(null);

  const steps: Step[] = [
    {
      id: 'step1',
      targetId: 'nav-customers',
      title: 'Passo 1: Cadastrar Cliente',
      content: 'Comece clicando aqui para abrir sua lista de clientes e registrar quem compra com você.',
    },
    {
      id: 'step2',
      targetId: 'nav-sales',
      title: 'Passo 2: Iniciar uma Venda',
      content: 'Depois de ter clientes, clique aqui para acessar o gerenciador de vendas a prazo.',
    },
    {
      id: 'step3',
      targetId: 'btn-new-sale',
      title: 'Passo 3: Lançar Valor e Itens',
      content: 'Clique em "Nova Venda" para abrir o formulário onde você detalha os produtos e o valor total.',
      requiredView: 'sales'
    },
    {
      id: 'step4',
      targetId: 'sale-form-container',
      title: 'Passo 4: Prazos e Parcelas',
      content: 'Aqui você define o dia do vencimento e em quantas vezes o cliente vai pagar. O sistema calcula tudo sozinho!',
      requiredView: 'sales'
    },
    {
      id: 'step5',
      targetId: 'nav-dashboard',
      title: 'Passo 5: Ver Resultados',
      content: 'Pronto! Agora acompanhe seus lucros e recebimentos futuros aqui no seu Dashboard inteligente.',
    }
  ];

  const updateCoords = () => {
    const step = steps[currentStep];
    const element = document.getElementById(step.targetId);
    if (element) {
      const rect = element.getBoundingClientRect();
      setCoords({
        top: rect.top,
        left: rect.left,
        width: rect.width,
        height: rect.height
      });
    } else {
      setCoords(null);
    }
  };

  useLayoutEffect(() => {
    updateCoords();
    window.addEventListener('resize', updateCoords);
    return () => window.removeEventListener('resize', updateCoords);
  }, [currentStep, activeView]);

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      onClose();
    }
  };

  const currentStepData = steps[currentStep];
  const isTargetVisible = !!coords;

  return (
    <div className="fixed inset-0 z-[9999] pointer-events-none">
      {/* Dark Overlay with Hole */}
      <div 
        className="absolute inset-0 bg-slate-950/70 transition-opacity duration-500 pointer-events-auto"
        style={{
          clipPath: coords 
            ? `polygon(0% 0%, 0% 100%, ${coords.left}px 100%, ${coords.left}px ${coords.top}px, ${coords.left + coords.width}px ${coords.top}px, ${coords.left + coords.width}px ${coords.top + coords.height}px, ${coords.left}px ${coords.top + coords.height}px, ${coords.left}px 100%, 100% 100%, 100% 0%)`
            : 'none'
        }}
      />

      {/* Spotlight Effect (Border/Glow) */}
      {coords && (
        <div 
          className="absolute border-2 border-indigo-400 rounded-lg shadow-[0_0_20px_rgba(129,140,248,0.5)] transition-all duration-300 ease-out animate-pulse"
          style={{
            top: coords.top - 4,
            left: coords.left - 4,
            width: coords.width + 8,
            height: coords.height + 8,
          }}
        />
      )}

      {/* Tooltip Card */}
      <div 
        className="absolute pointer-events-auto transition-all duration-500 ease-out"
        style={{
          top: coords ? (coords.top + coords.height + 20 > window.innerHeight - 200 ? coords.top - 220 : coords.top + coords.height + 20) : '50%',
          left: coords ? Math.min(Math.max(20, coords.left), window.innerWidth - 340) : '50%',
          transform: coords ? 'none' : 'translate(-50%, -50%)',
          width: '320px'
        }}
      >
        <div className="bg-white rounded-2xl shadow-2xl p-6 border border-indigo-100 overflow-hidden relative">
          <div className="absolute top-0 left-0 w-full h-1 bg-indigo-600"></div>

          <div className="flex justify-between items-start mb-4">
            <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest bg-indigo-50 px-2 py-0.5 rounded">
              Passo {currentStep + 1} de {steps.length}
            </span>
            <button onClick={onClose} className="text-slate-400 hover:text-rose-500 transition">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>

          <h4 className="text-lg font-bold text-slate-800 mb-2 leading-tight">
            {currentStepData.title}
          </h4>

          <p className="text-sm text-slate-500 leading-relaxed mb-6">
            {currentStepData.content}
            {!isTargetVisible && currentStepData.requiredView && activeView !== currentStepData.requiredView && (
              <span className="block mt-2 font-bold text-rose-500">
                * Por favor, clique no menu para prosseguir.
              </span>
            )}
          </p>

          <div className="flex items-center justify-between gap-4">
             <button 
                onClick={() => currentStep > 0 && setCurrentStep(currentStep - 1)}
                disabled={currentStep === 0}
                className="text-xs font-bold text-slate-400 uppercase tracking-widest hover:text-slate-600 disabled:opacity-0 transition"
              >
                Anterior
              </button>

              <button 
                onClick={handleNext}
                className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-indigo-700 transition shadow-lg shadow-indigo-200 active:scale-95"
              >
                {currentStep === steps.length - 1 ? 'Finalizar' : 'Entendido'}
              </button>
          </div>
        </div>
      </div>
    </div>
  );
};

