import React, { useState } from 'react';
import { Customer, Sale, PaymentStatus, Installment } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, onAddSale, onUpdateSale }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [description, setDescription] = useState('');
  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [paymentValue, setPaymentValue] = useState<number>(0);

  // State for detailed editing of an installment
  const [editingInstId, setEditingInstId] = useState<string | null>(null);
  const [editFields, setEditFields] = useState({
    amount: 0,
    paidAmount: 0,
    dueDate: ''
  });

  // State for re-parceling (changing installment count)
  const [isReparceling, setIsReparceling] = useState(false);
  const [newTotalInstallments, setNewTotalInstallments] = useState<number>(1);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    if (!customerId || !description || totalAmount <= 0) return;

    const installmentAmount = totalAmount / numInstallments;
    const installments: Installment[] = [];
    const today = new Date();

    for (let i = 1; i <= numInstallments; i++) {
      const dueDate = calculateDueDate(today, i, dueDay);

      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: installmentAmount,
        paidAmount: 0,
        dueDate: dueDate.toISOString().split('T')[0],
        status: PaymentStatus.PENDING
      });
    }

    onAddSale({
      customerId,
      description,
      totalAmount,
      date: today.toISOString().split('T')[0],
      installments,
      status: PaymentStatus.PENDING
    });

    setShowAdd(false);
    resetForm();
  };

  const calculateDueDate = (baseDate: Date, monthsToAdd: number, targetDay: number) => {
    let targetMonth = baseDate.getMonth() + monthsToAdd;
    let targetYear = baseDate.getFullYear();

    while (targetMonth > 11) {
      targetMonth -= 12;
      targetYear += 1;
    }

    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const resetForm = () => {
    setCustomerId('');
    setDescription('');
    setTotalAmount(0);
    setNumInstallments(1);
    setDueDay(new Date().getDate());
  };

  const handleAbatePayment = (sale: Sale, installmentId: string) => {
    if (paymentValue <= 0) return;

    const newInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const remainingToPay = inst.amount - inst.paidAmount;
        const actualPayment = Math.min(paymentValue, remainingToPay);
        const newPaidAmount = inst.paidAmount + actualPayment;

        return {
          ...inst,
          paidAmount: newPaidAmount,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });

    updateSaleState(sale, newInstallments);
    setPaymentValue(0);
  };

  const startEditing = (inst: Installment) => {
    setEditingInstId(inst.id);
    setEditFields({
      amount: inst.amount,
      paidAmount: inst.paidAmount,
      dueDate: inst.dueDate
    });
  };

  const saveEdit = (sale: Sale) => {
    const newInstallments = sale.installments.map(inst => {
      if (inst.id === editingInstId) {
        const status = editFields.paidAmount >= editFields.amount ? PaymentStatus.PAID : 
                       editFields.paidAmount > 0 ? PaymentStatus.PARTIAL : PaymentStatus.PENDING;
        return {
          ...inst,
          amount: editFields.amount,
          paidAmount: editFields.paidAmount,
          dueDate: editFields.dueDate,
          status
        };
      }
      return inst;
    });

    const newTotal = newInstallments.reduce((sum, i) => sum + i.amount, 0);

    onUpdateSale({
      ...sale,
      totalAmount: newTotal,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    });

    setEditingInstId(null);
  };

  const handleReparcel = (sale: Sale) => {
    // 1. Identify "Protected" installments (those already fully or partially paid)
    const protectedInstallments = sale.installments.filter(i => i.paidAmount > 0 || i.status === PaymentStatus.PAID);

    if (newTotalInstallments < protectedInstallments.length) {
      alert(`Não é possível reduzir para ${newTotalInstallments} parcelas pois já existem ${protectedInstallments.length} parcelas com pagamentos registrados.`);
      return;
    }

    const totalPaid = protectedInstallments.reduce((sum, i) => sum + i.paidAmount, 0);
    const balanceRemaining = sale.totalAmount - totalPaid;
    const newInstallmentsNeeded = newTotalInstallments - protectedInstallments.length;

    const newInstallments: Installment[] = [...protectedInstallments];

    if (newInstallmentsNeeded > 0) {
      const amountPerNewInst = balanceRemaining / newInstallmentsNeeded;
      const lastDate = protectedInstallments.length > 0 
        ? new Date(protectedInstallments[protectedInstallments.length - 1].dueDate)
        : new Date(sale.date);

      const targetDay = lastDate.getDate();

      for (let i = 1; i <= newInstallmentsNeeded; i++) {
        const dueDate = calculateDueDate(lastDate, i, targetDay);
        newInstallments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: sale.id,
          amount: amountPerNewInst,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onUpdateSale({
      ...sale,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    });

    setIsReparceling(false);
    // Update local selected sale reference
    setSelectedSale({ ...sale, installments: newInstallments });
  };

  const calculateSaleStatus = (installments: Installment[]) => {
    const allPaid = installments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = installments.some(i => i.status !== PaymentStatus.PENDING);
    return allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING);
  };

  const updateSaleState = (sale: Sale, newInstallments: Installment[]) => {
    onUpdateSale({
      ...sale,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-bold text-slate-800">Vendas a Prazo</h2>
        <button 
          id="btn-new-sale"
          onClick={() => setShowAdd(!showAdd)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-700 transition shadow-sm"
        >
          {showAdd ? 'Cancelar' : 'Nova Venda'}
        </button>
      </div>

      {showAdd && (
        <form 
          id="sale-form-container"
          onSubmit={handleAddSale} 
          className="bg-white p-6 rounded-2xl shadow-sm border border-indigo-100 space-y-4 animate-in fade-in zoom-in duration-200"
        >
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            <div className="md:col-span-1">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Cliente</label>
              <select 
                value={customerId} 
                onChange={e => setCustomerId(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500"
              >
                <option value="">Selecione...</option>
                {customers.map(c => (
                  <option key={c.id} value={c.id}>{c.name}</option>
                ))}
              </select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Descrição Itens</label>
              <input 
                type="text" 
                value={description} 
                onChange={e => setDescription(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500"
                placeholder="Ex: 2 Calças, 1 Blusa"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Valor Total (R$)</label>
              <input 
                type="number" 
                step="0.01"
                value={totalAmount || ''} 
                onChange={e => setTotalAmount(Number(e.target.value))}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500"
              />
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nº Parcelas</label>
                <input 
                  type="number" 
                  min="1"
                  max="24"
                  value={numInstallments} 
                  onChange={e => setNumInstallments(Number(e.target.value))}
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Dia Vencimento</label>
                <input 
                  type="number" 
                  min="1"
                  max="31"
                  value={dueDay} 
                  onChange={e => setDueDay(Number(e.target.value))}
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500"
                />
              </div>
            </div>
          </div>
          <div className="flex justify-end">
            <button type="submit" className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-700 transition">
              Registrar Venda
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {sales.length === 0 && (
          <div className="bg-white p-12 text-center rounded-2xl border border-dashed border-slate-200 text-slate-400">
            Nenhuma venda a prazo registrada.
          </div>
        )}
        {sales.map(sale => {
          const customer = customers.find(c => c.id === sale.customerId);
          const isOverdue = sale.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date());

          return (
            <div key={sale.id} className={`bg-white rounded-2xl shadow-sm border ${isOverdue ? 'border-rose-200' : 'border-slate-100'} overflow-hidden transition-all hover:border-indigo-200`}>
              <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                  <div className="flex items-center gap-2">
                    <h3 className="font-bold text-slate-800">{customer?.name || 'Cliente Excluído'}</h3>
                    {isOverdue && <span className="bg-rose-100 text-rose-600 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Possui Atraso</span>}
                  </div>
                  <p className="text-sm text-slate-500">{sale.description}</p>
                  <p className="text-xs text-slate-400">Venda realizada em: {new Date(sale.date).toLocaleDateString('pt-BR')}</p>
                </div>

                <div className="flex items-center gap-6">
                  <div className="text-right">
                    <p className="text-xs font-bold text-slate-400 uppercase">Total da Venda</p>
                    <p className="font-bold text-slate-800">R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
                  <button 
                    onClick={() => setSelectedSale(selectedSale?.id === sale.id ? null : sale)}
                    className={`px-3 py-2 rounded-lg text-xs font-bold uppercase transition ${
                        selectedSale?.id === sale.id ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-50 text-slate-600 hover:bg-slate-100'
                    }`}
                  >
                    {selectedSale?.id === sale.id ? 'Fechar Detalhes' : 'Ver Parcelas'}
                  </button>
                </div>
              </div>

              {selectedSale?.id === sale.id && (
                <div className="border-t border-slate-50 bg-slate-50/50 p-5 animate-in slide-in-from-top-2 duration-200">
                  <div className="flex justify-between items-center mb-4">
                    <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider">Detalhamento das Parcelas</h4>

                    <div className="flex items-center gap-2">
                      {isReparceling ? (
                        <div className="flex items-center gap-2 bg-indigo-50 p-2 rounded-lg border border-indigo-100 animate-in zoom-in duration-150">
                          <label className="text-[10px] font-bold text-indigo-600 uppercase">Nova Qtd:</label>
                          <input 
                            type="number" 
                            min="1" 
                            max="24"
                            value={newTotalInstallments}
                            onChange={(e) => setNewTotalInstallments(Number(e.target.value))}
                            className="w-12 text-xs border border-indigo-200 rounded px-1 py-0.5 outline-none text-slate-900 focus:ring-1 focus:ring-indigo-500"
                          />
                          <button 
                            onClick={() => handleReparcel(sale)}
                            className="bg-indigo-600 text-white px-2 py-0.5 rounded text-[10px] font-bold uppercase hover:bg-indigo-700 transition"
                          >
                            Aplicar
                          </button>
                          <button 
                            onClick={() => setIsReparceling(false)}
                            className="text-slate-400 hover:text-rose-500 transition px-1"
                          >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                          </button>
                        </div>
                      ) : (
                        <button 
                          onClick={() => {
                            setIsReparceling(true);
                            setNewTotalInstallments(sale.installments.length);
                          }}
                          className="flex items-center gap-1.5 text-indigo-600 hover:text-indigo-800 transition text-[10px] font-bold uppercase border border-indigo-200 bg-indigo-50/50 px-2 py-1 rounded-lg"
                        >
                          <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
                          Alterar Parcelamento
                        </button>
                      )}
                    </div>
                  </div>

                  <div className="space-y-3">
                    {sale.installments.map((inst, idx) => {
                      const isEditing = editingInstId === inst.id;
                      const instOverdue = inst.status !== PaymentStatus.PAID && new Date(inst.dueDate) < new Date();

                      return (
                        <div key={inst.id} className={`bg-white p-3 rounded-xl border ${instOverdue ? 'border-rose-200 bg-rose-50/10' : 'border-slate-200'} flex flex-col gap-3`}>
                          <div className="flex flex-wrap justify-between items-center gap-4">
                            <div className="flex items-center gap-4">
                              <span className={`w-7 h-7 flex items-center justify-center rounded-full text-[10px] font-bold ${inst.status === PaymentStatus.PAID ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                                {idx + 1}
                              </span>

                              {isEditing ? (
                                <div className="flex flex-wrap gap-3 items-end">
                                  <div>
                                    <label className="block text-[9px] font-bold text-slate-400 uppercase">Vencimento</label>
                                    <input 
                                      type="date" 
                                      value={editFields.dueDate}
                                      onChange={(e) => setEditFields({...editFields, dueDate: e.target.value})}
                                      className="text-xs bg-slate-50 border border-slate-300 rounded px-2 py-1 text-slate-900 focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                  </div>
                                  <div>
                                    <label className="block text-[9px] font-bold text-slate-400 uppercase">Valor Parcela</label>
                                    <input 
                                      type="number" 
                                      value={editFields.amount}
                                      onChange={(e) => setEditFields({...editFields, amount: Number(e.target.value)})}
                                      className="w-24 text-xs bg-slate-50 border border-slate-300 rounded px-2 py-1 text-slate-900 focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                  </div>
                                  <div>
                                    <label className="block text-[9px] font-bold text-slate-400 uppercase">Valor Pago</label>
                                    <input 
                                      type="number" 
                                      value={editFields.paidAmount}
                                      onChange={(e) => setEditFields({...editFields, paidAmount: Number(e.target.value)})}
                                      className="w-24 text-xs bg-slate-50 border border-slate-300 rounded px-2 py-1 text-slate-900 focus:ring-1 focus:ring-indigo-500 outline-none"
                                    />
                                  </div>
                                  <div className="flex gap-2">
                                    <button 
                                      onClick={() => saveEdit(sale)}
                                      className="bg-emerald-500 text-white px-3 py-1 rounded text-[10px] font-bold uppercase hover:bg-emerald-600 transition"
                                    >
                                      Salvar
                                    </button>
                                    <button 
                                      onClick={() => setEditingInstId(null)}
                                      className="bg-slate-200 text-slate-600 px-3 py-1 rounded text-[10px] font-bold uppercase hover:bg-slate-300 transition"
                                    >
                                      Cancelar
                                    </button>
                                  </div>
                                </div>
                              ) : (
                                <div>
                                  <div className="flex items-center gap-2">
                                    <p className="text-xs font-semibold text-slate-700">Vencimento: {new Date(inst.dueDate).toLocaleDateString('pt-BR')}</p>
                                    <button 
                                      onClick={() => startEditing(inst)}
                                      className="text-slate-400 hover:text-indigo-600 transition p-1"
                                      title="Editar parcela (valor e data)"
                                    >
                                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                                    </button>
                                  </div>
                                  <p className={`text-[10px] uppercase font-bold ${instOverdue ? 'text-rose-500' : 'text-slate-400'}`}>
                                    {inst.status === PaymentStatus.PAID ? 'Liquidado' : inst.status === PaymentStatus.PARTIAL ? 'Pagamento Parcial' : instOverdue ? 'Vencida (Atraso)' : 'Pendente'}
                                  </p>
                                </div>
                              )}
                            </div>

                            {!isEditing && (
                              <div className="flex items-center gap-4 ml-auto">
                                <div className="text-right">
                                  <p className="text-sm font-bold text-indigo-600">R$ {inst.amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                                  <p className="text-[10px] text-emerald-500 font-medium">Pago: R$ {inst.paidAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                                </div>

                                {inst.status !== PaymentStatus.PAID && (
                                  <div className="flex items-center gap-2">
                                    <input 
                                      type="number" 
                                      placeholder="Valor"
                                      className="w-20 bg-slate-50 border border-slate-200 rounded px-2 py-1 text-xs text-slate-900 outline-none focus:ring-1 focus:ring-emerald-500"
                                      onChange={(e) => setPaymentValue(Number(e.target.value))}
                                    />
                                    <button 
                                      onClick={() => handleAbatePayment(sale, inst.id)}
                                      className="bg-emerald-500 text-white px-3 py-1 rounded text-xs font-bold hover:bg-emerald-600 transition shadow-sm"
                                    >
                                      Abater
                                    </button>
                                  </div>
                                )}
                                {inst.status === PaymentStatus.PAID && (
                                  <div className="text-emerald-500 bg-emerald-50 p-1.5 rounded-full">
                                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                                  </div>
                                )}
                              </div>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default SalesManager;

export interface User {
  id: string;
  name: string;
  email: string;
  password?: string;
  authProvider?: 'local' | 'onedrive';
  avatarUrl?: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  address?: string;
  cpf?: string;
  createdAt: number;
}

export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  PARTIAL = 'PARTIAL'
}

export interface Installment {
  id: string;
  saleId: string;
  amount: number;
  paidAmount: number;
  dueDate: string;
  status: PaymentStatus;
}

export interface Sale {
  id: string;
  customerId: string;
  description: string;
  totalAmount: number;
  date: string;
  installments: Installment[];
  status: PaymentStatus;
  type?: 'cash' | 'credit'; // New field: cash = à vista, credit = a prazo
}

export type View = 'dashboard' | 'customers' | 'sales' | 'agenda' | 'settings';

import React, { useState } from 'react';
import { Customer, Sale, PaymentStatus, Installment } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, onAddSale, onUpdateSale }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [saleType, setSaleType] = useState<'credit' | 'cash'>('credit');
  const [customerId, setCustomerId] = useState('');
  const [description, setDescription] = useState('');
  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [paymentValue, setPaymentValue] = useState<number>(0);

  // State for detailed editing of an installment
  const [editingInstId, setEditingInstId] = useState<string | null>(null);
  const [editFields, setEditFields] = useState({
    amount: 0,
    paidAmount: 0,
    dueDate: ''
  });

  // State for re-parceling
  const [isReparceling, setIsReparceling] = useState(false);
  const [newTotalInstallments, setNewTotalInstallments] = useState<number>(1);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    if (!customerId || !description || totalAmount <= 0) return;

    const installments: Installment[] = [];
    const today = new Date();

    if (saleType === 'cash') {
      // Logic for Cash Sale (À Vista)
      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: totalAmount,
        paidAmount: totalAmount,
        dueDate: today.toISOString().split('T')[0],
        status: PaymentStatus.PAID
      });
    } else {
      // Logic for Credit Sale (A Prazo)
      const installmentAmount = totalAmount / numInstallments;
      for (let i = 1; i <= numInstallments; i++) {
        const dueDate = calculateDueDate(today, i, dueDay);
        installments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: '', 
          amount: installmentAmount,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onAddSale({
      customerId,
      description,
      totalAmount,
      date: today.toISOString().split('T')[0],
      installments,
      status: saleType === 'cash' ? PaymentStatus.PAID : PaymentStatus.PENDING,
      type: saleType
    });

    setShowAdd(false);
    resetForm();
  };

  const calculateDueDate = (baseDate: Date, monthsToAdd: number, targetDay: number) => {
    let targetMonth = baseDate.getMonth() + monthsToAdd;
    let targetYear = baseDate.getFullYear();

    while (targetMonth > 11) {
      targetMonth -= 12;
      targetYear += 1;
    }

    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const resetForm = () => {
    setCustomerId('');
    setDescription('');
    setTotalAmount(0);
    setNumInstallments(1);
    setDueDay(new Date().getDate());
    setSaleType('credit');
  };

  const handleAbatePayment = (sale: Sale, installmentId: string) => {
    if (paymentValue <= 0) return;

    const newInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const remainingToPay = inst.amount - inst.paidAmount;
        const actualPayment = Math.min(paymentValue, remainingToPay);
        const newPaidAmount = inst.paidAmount + actualPayment;

        return {
          ...inst,
          paidAmount: newPaidAmount,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });

    updateSaleState(sale, newInstallments);
    setPaymentValue(0);
  };

  const startEditing = (inst: Installment) => {
    setEditingInstId(inst.id);
    setEditFields({
      amount: inst.amount,
      paidAmount: inst.paidAmount,
      dueDate: inst.dueDate
    });
  };

  const saveEdit = (sale: Sale) => {
    const newInstallments = sale.installments.map(inst => {
      if (inst.id === editingInstId) {
        const status = editFields.paidAmount >= editFields.amount ? PaymentStatus.PAID : 
                       editFields.paidAmount > 0 ? PaymentStatus.PARTIAL : PaymentStatus.PENDING;
        return {
          ...inst,
          amount: editFields.amount,
          paidAmount: editFields.paidAmount,
          dueDate: editFields.dueDate,
          status
        };
      }
      return inst;
    });

    const newTotal = newInstallments.reduce((sum, i) => sum + i.amount, 0);

    onUpdateSale({
      ...sale,
      totalAmount: newTotal,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    });

    setEditingInstId(null);
  };

  const handleReparcel = (sale: Sale) => {
    const protectedInstallments = sale.installments.filter(i => i.paidAmount > 0 || i.status === PaymentStatus.PAID);

    if (newTotalInstallments < protectedInstallments.length) {
      alert(`Não é possível reduzir para ${newTotalInstallments} parcelas pois já existem parcelas com pagamentos.`);
      return;
    }

    const totalPaid = protectedInstallments.reduce((sum, i) => sum + i.paidAmount, 0);
    const balanceRemaining = sale.totalAmount - totalPaid;
    const newInstallmentsNeeded = newTotalInstallments - protectedInstallments.length;

    const newInstallments: Installment[] = [...protectedInstallments];

    if (newInstallmentsNeeded > 0) {
      const amountPerNewInst = balanceRemaining / newInstallmentsNeeded;
      const lastDate = protectedInstallments.length > 0 
        ? new Date(protectedInstallments[protectedInstallments.length - 1].dueDate)
        : new Date(sale.date);

      const targetDay = lastDate.getDate();

      for (let i = 1; i <= newInstallmentsNeeded; i++) {
        const dueDate = calculateDueDate(lastDate, i, targetDay);
        newInstallments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: sale.id,
          amount: amountPerNewInst,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onUpdateSale({
      ...sale,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments),
      type: 'credit' // Reparceling implies a credit sale
    });

    setIsReparceling(false);
    setSelectedSale({ ...sale, installments: newInstallments });
  };

  const calculateSaleStatus = (installments: Installment[]) => {
    const allPaid = installments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = installments.some(i => i.status !== PaymentStatus.PENDING);
    return allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING);
  };

  const updateSaleState = (sale: Sale, newInstallments: Installment[]) => {
    onUpdateSale({
      ...sale,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-bold text-slate-800">Gerenciar Vendas</h2>
        <button 
          id="btn-new-sale"
          onClick={() => setShowAdd(!showAdd)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-700 transition shadow-sm"
        >
          {showAdd ? 'Cancelar' : 'Nova Venda'}
        </button>
      </div>

      {showAdd && (
        <form 
          id="sale-form-container"
          onSubmit={handleAddSale} 
          className="bg-white p-6 rounded-2xl shadow-sm border border-indigo-100 space-y-6 animate-in fade-in zoom-in duration-200"
        >
          {/* Sale Type Selector */}
          <div className="flex bg-slate-100 p-1 rounded-xl w-fit">
            <button 
              type="button"
              onClick={() => setSaleType('credit')}
              className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition ${saleType === 'credit' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              Venda a Prazo
            </button>
            <button 
              type="button"
              onClick={() => setSaleType('cash')}
              className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition ${saleType === 'cash' ? 'bg-emerald-500 text-white shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              Venda À Vista
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            <div className="md:col-span-1">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Cliente</label>
              <select 
                value={customerId} 
                onChange={e => setCustomerId(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500"
              >
                <option value="">Selecione...</option>
                {customers.map(c => (
                  <option key={c.id} value={c.id}>{c.name}</option>
                ))}
              </select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Descrição Itens</label>
              <input 
                type="text" 
                value={description} 
                onChange={e => setDescription(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500"
                placeholder="Ex: 2 Calças, 1 Blusa"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Valor Total (R$)</label>
              <input 
                type="number" 
                step="0.01"
                value={totalAmount || ''} 
                onChange={e => setTotalAmount(Number(e.target.value))}
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500"
              />
            </div>

            {saleType === 'credit' && (
              <div className="grid grid-cols-2 gap-2 animate-in fade-in slide-in-from-left-2">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nº Parcelas</label>
                  <input 
                    type="number" 
                    min="1"
                    max="24"
                    value={numInstallments} 
                    onChange={e => setNumInstallments(Number(e.target.value))}
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Dia Vencimento</label>
                  <input 
                    type="number" 
                    min="1"
                    max="31"
                    value={dueDay} 
                    onChange={e => setDueDay(Number(e.target.value))}
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500"
                  />
                </div>
              </div>
            )}

            {saleType === 'cash' && (
               <div className="flex items-end pb-1 animate-in fade-in slide-in-from-right-2">
                  <div className="bg-emerald-50 text-emerald-700 px-4 py-2 rounded-xl border border-emerald-100 flex items-center gap-2">
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                    <span className="text-xs font-bold uppercase tracking-tight">Pagamento à vista confirmado</span>
                  </div>
               </div>
            )}
          </div>
          <div className="flex justify-end pt-2 border-t border-slate-50">
            <button type="submit" className={`px-8 py-3 rounded-xl text-sm font-bold uppercase tracking-widest transition shadow-lg ${saleType === 'cash' ? 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-emerald-100' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-100'}`}>
              Registrar {saleType === 'cash' ? 'Venda À Vista' : 'Venda a Prazo'}
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {sales.length === 0 && (
          <div className="bg-white p-12 text-center rounded-2xl border border-dashed border-slate-200 text-slate-400">
            Nenhuma venda registrada.
          </div>
        )}
        {sales.map(sale => {
          const customer = customers.find(c => c.id === sale.customerId);
          const isOverdue = sale.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date());
          const isCash = sale.type === 'cash';

          return (
            <div key={sale.id} className={`bg-white rounded-2xl shadow-sm border ${isOverdue ? 'border-rose-200' : isCash ? 'border-emerald-100' : 'border-slate-100'} overflow-hidden transition-all hover:shadow-md`}>
              <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div className="flex items-start gap-3">
                  <div className={`mt-1 p-2 rounded-lg ${isCash ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                    {isCash ? (
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
                    ) : (
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z" /></svg>
                    )}
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <h3 className="font-bold text-slate-800">{customer?.name || 'Cliente Excluído'}</h3>
                      {isOverdue && <span className="bg-rose-100 text-rose-600 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Atraso</span>}
                      {isCash && <span className="bg-emerald-100 text-emerald-600 px-2 py-0.5 rounded text-[10px] font-bold uppercase italic">À Vista</span>}
                    </div>
                    <p className="text-sm text-slate-500">{sale.description}</p>
                    <p className="text-[10px] text-slate-400 uppercase font-bold tracking-tight">Data: {new Date(sale.date).toLocaleDateString('pt-BR')}</p>
                  </div>
                </div>

                <div className="flex items-center gap-6">
                  <div className="text-right">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Valor Total</p>
                    <p className={`font-black text-lg ${isCash ? 'text-emerald-600' : 'text-slate-800'}`}>R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
                  <button 
                    onClick={() => setSelectedSale(selectedSale?.id === sale.id ? null : sale)}
                    className={`px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-widest transition shadow-sm ${
                        selectedSale?.id === sale.id ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-600 hover:bg-slate-100'
                    }`}
                  >
                    {selectedSale?.id === sale.id ? 'Fechar' : 'Detalhes'}
                  </button>
                </div>
              </div>

              {selectedSale?.id === sale.id && (
                <div className="border-t border-slate-50 bg-slate-50/50 p-5 animate-in slide-in-from-top-2 duration-200">
                  <div className="flex justify-between items-center mb-4">
                    <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Informações de Recebimento</h4>

                    {!isCash && (
                      <div className="flex items-center gap-2">
                        {isReparceling ? (
                          <div className="flex items-center gap-2 bg-indigo-50 p-2 rounded-lg border border-indigo-100">
                            <input 
                              type="number" min="1" max="24"
                              value={newTotalInstallments}
                              onChange={(e) => setNewTotalInstallments(Number(e.target.value))}
                              className="w-12 text-xs border border-indigo-200 rounded px-1 py-0.5"
                            />
                            <button onClick={() => handleReparcel(sale)} className="bg-indigo-600 text-white px-2 py-0.5 rounded text-[10px] font-bold uppercase">Aplicar</button>
                            <button onClick={() => setIsReparceling(false)} className="text-slate-400 px-1">✕</button>
                          </div>
                        ) : (
                          <button 
                            onClick={() => { setIsReparceling(true); setNewTotalInstallments(sale.installments.length); }}
                            className="text-indigo-600 hover:text-indigo-800 transition text-[10px] font-bold uppercase border border-indigo-200 bg-white px-2 py-1 rounded-lg"
                          >
                            Alterar Parcelas
                          </button>
                        )}
                      </div>
                    )}
                  </div>

                  <div className="space-y-3">
                    {sale.installments.map((inst, idx) => {
                      const isEditing = editingInstId === inst.id;
                      const instOverdue = inst.status !== PaymentStatus.PAID && new Date(inst.dueDate) < new Date();

                      return (
                        <div key={inst.id} className={`bg-white p-4 rounded-xl border ${instOverdue ? 'border-rose-200 bg-rose-50/10' : 'border-slate-200'} flex flex-col gap-3`}>
                          <div className="flex flex-wrap justify-between items-center gap-4">
                            <div className="flex items-center gap-4">
                              <span className={`w-8 h-8 flex items-center justify-center rounded-lg text-[10px] font-bold ${inst.status === PaymentStatus.PAID ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-100' : 'bg-indigo-50 text-indigo-600 border border-indigo-100'}`}>
                                {isCash ? '✓' : idx + 1}
                              </span>

                              {isEditing ? (
                                <div className="flex flex-wrap gap-3 items-end">
                                  <div>
                                    <label className="block text-[9px] font-bold text-slate-400 uppercase">Vencimento</label>
                                    <input type="date" value={editFields.dueDate} onChange={(e) => setEditFields({...editFields, dueDate: e.target.value})} className="text-xs bg-slate-50 border border-slate-300 rounded px-2 py-1" />
                                  </div>
                                  <div className="flex gap-2">
                                    <button onClick={() => saveEdit(sale)} className="bg-emerald-500 text-white px-3 py-1 rounded text-[10px] font-bold uppercase">Salvar</button>
                                    <button onClick={() => setEditingInstId(null)} className="bg-slate-200 text-slate-600 px-3 py-1 rounded text-[10px] font-bold uppercase">Cancelar</button>
                                  </div>
                                </div>
                              ) : (
                                <div>
                                  <div className="flex items-center gap-2">
                                    <p className="text-xs font-bold text-slate-700">{isCash ? 'Recebido na hora' : `Vencimento: ${new Date(inst.dueDate).toLocaleDateString('pt-BR')}`}</p>
                                    {!isCash && (
                                      <button onClick={() => startEditing(inst)} className="text-slate-300 hover:text-indigo-600 transition p-1"><svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg></button>
                                    )}
                                  </div>
                                  <p className={`text-[10px] uppercase font-black tracking-tighter ${inst.status === PaymentStatus.PAID ? 'text-emerald-500' : instOverdue ? 'text-rose-500' : 'text-amber-500'}`}>
                                    {inst.status === PaymentStatus.PAID ? 'Pago / Liquidado' : instOverdue ? 'Vencida' : 'Pendente'}
                                  </p>
                                </div>
                              )}
                            </div>

                            {!isEditing && (
                              <div className="flex items-center gap-4 ml-auto">
                                <div className="text-right">
                                  <p className="text-sm font-black text-slate-800">R$ {inst.amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                                  {inst.paidAmount > 0 && !isCash && <p className="text-[10px] text-emerald-500 font-bold">Pago: R$ {inst.paidAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>}
                                </div>

                                {inst.status !== PaymentStatus.PAID && (
                                  <div className="flex items-center gap-2">
                                    <input type="number" placeholder="Valor" className="w-20 bg-slate-50 border border-slate-200 rounded px-2 py-1 text-xs" onChange={(e) => setPaymentValue(Number(e.target.value))} />
                                    <button onClick={() => handleAbatePayment(sale, inst.id)} className="bg-emerald-500 text-white px-4 py-1.5 rounded-lg text-xs font-bold hover:bg-emerald-600 transition shadow-sm">Baixar</button>
                                  </div>
                                )}
                              </div>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default SalesManager;

export interface User {
  id: string;
  name: string;
  email: string;
  password?: string;
  authProvider?: 'local' | 'onedrive';
  avatarUrl?: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  address?: string;
  cpf?: string;
  createdAt: number;
}

export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  PARTIAL = 'PARTIAL'
}

export interface Installment {
  id: string;
  saleId: string;
  amount: number;
  paidAmount: number;
  dueDate: string;
  status: PaymentStatus;
}

export interface Sale {
  id: string;
  customerId: string;
  description: string;
  totalAmount: number;
  date: string;
  installments: Installment[];
  status: PaymentStatus;
  type?: 'cash' | 'credit';
}

export type View = 'dashboard' | 'customers' | 'sales-cash' | 'sales-credit' | 'agenda' | 'settings';

import React, { useState, useEffect, useCallback } from 'react';
import { View, Customer, Sale, User } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';
import Agenda from './components/Agenda';
import Settings from './components/Settings';
import Landing from './components/Landing';
import Tutorial from './components/Tutorial';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const syncWithOneDrive = useCallback(async (action: 'upload' | 'download') => {
    if (!user || user.authProvider !== 'onedrive') return;
    setSyncStatus('syncing');
    try {
      await new Promise(resolve => setTimeout(resolve, 1000));
      const storageKey = `gestao93_cloud_master_${user.id}`;
      if (action === 'download') {
        const cloudData = localStorage.getItem(storageKey);
        if (cloudData) {
          const parsed = JSON.parse(cloudData);
          setCustomers(parsed.customers || []);
          setSales(parsed.sales || []);
        }
      } else {
        const localUsers = JSON.parse(localStorage.getItem('gestao93_users') || '[]');
        const dataToUpload = JSON.stringify({ 
          customers, 
          sales, 
          users: localUsers,
          lastSync: new Date().toISOString()
        });
        localStorage.setItem(storageKey, dataToUpload);
      }
      setSyncStatus('synced');
    } catch (err) {
      setSyncStatus('error');
    }
  }, [user, customers, sales]);

  useEffect(() => {
    const savedUser = localStorage.getItem('gestao93_current_user');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      checkTutorialStatus(parsedUser.id);
      if (parsedUser.authProvider === 'onedrive') {
        syncWithOneDrive('download');
      } else {
        const localCustomers = localStorage.getItem(`gestao93_customers_${parsedUser.id}`);
        const localSales = localStorage.getItem(`gestao93_sales_${parsedUser.id}`);
        if (localCustomers) setCustomers(JSON.parse(localCustomers));
        if (localSales) setSales(JSON.parse(localSales));
      }
    }
    setLoading(false);
  }, []);

  const checkTutorialStatus = (userId: string) => {
    const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
    if (!tutorialSeen) setShowTutorial(true);
  };

  const handleFinishTutorial = () => {
    if (user) localStorage.setItem(`gestao93_tutorial_seen_${user.id}`, 'true');
    setShowTutorial(false);
  };

  useEffect(() => {
    if (!loading && user) {
      const timer = setTimeout(() => {
        if (user.authProvider === 'onedrive') {
          syncWithOneDrive('upload');
        } else {
          localStorage.setItem(`gestao93_customers_${user.id}`, JSON.stringify(customers));
          localStorage.setItem(`gestao93_sales_${user.id}`, JSON.stringify(sales));
        }
      }, 2000);
      return () => clearTimeout(timer);
    }
  }, [customers, sales, user, loading, syncWithOneDrive]);

  const handleLogin = (userData: User) => {
    setUser(userData);
    checkTutorialStatus(userData.id);
  };

  const handleLogout = () => {
    setUser(null);
    setCustomers([]);
    setSales([]);
    localStorage.removeItem('gestao93_current_user');
    setActiveView('dashboard');
    setShowTutorial(false);
  };

  const addCustomer = (data: Omit<Customer, 'id' | 'createdAt'>) => {
    const newCustomer: Customer = {
      ...data,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now()
    };
    setCustomers(prev => [newCustomer, ...prev]);
  };

  const deleteCustomer = (id: string) => {
    if (window.confirm('Excluir este cliente e todo seu histórico?')) {
      setCustomers(prev => prev.filter(c => c.id !== id));
    }
  };

  const addSale = (saleData: Omit<Sale, 'id'>) => {
    const newSale: Sale = { ...saleData, id: Math.random().toString(36).substr(2, 9) };
    setSales(prev => [newSale, ...prev]);
  };

  const updateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  if (loading) return null;
  if (!user) return <Landing onLogin={handleLogin} />;

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50">
      {showTutorial && <Tutorial activeView={activeView} onClose={handleFinishTutorial} />}

      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col p-6 sticky top-0 md:h-screen z-[100] border-r border-indigo-900 shadow-2xl">
        <div className="flex items-center gap-3 mb-8">
          <div className="bg-indigo-600 p-2 rounded-lg shadow-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <h1 className="text-xl font-bold tracking-tight italic">Gestão 93</h1>
        </div>

        <div className="mb-6 p-3 bg-white/5 rounded-xl border border-white/10">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-indigo-600 text-white flex items-center justify-center text-[10px] font-black uppercase border border-white/20 overflow-hidden">
              {user.avatarUrl ? <img src={user.avatarUrl} alt="Avatar" className="w-full h-full object-cover" /> : user.name.substring(0, 2)}
            </div>
            <p className="text-xs font-bold text-white truncate">{user.name}</p>
          </div>
        </div>

        <div className="space-y-1.5 flex-1">
          <button id="nav-dashboard" onClick={() => setActiveView('dashboard')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm ${activeView === 'dashboard' ? 'bg-indigo-600 text-white shadow-lg font-bold' : 'text-indigo-300 hover:bg-white/5'}`}>
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>
            Dashboard
          </button>

          <div className="pt-4 pb-2">
            <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest px-4 mb-2">Vendas</p>
            <button id="nav-sales-cash" onClick={() => setActiveView('sales-cash')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm ${activeView === 'sales-cash' ? 'bg-emerald-600 text-white shadow-lg font-bold' : 'text-emerald-400/70 hover:bg-white/5'}`}>
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
              Venda À Vista
            </button>
            <button id="nav-sales-credit" onClick={() => setActiveView('sales-credit')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm ${activeView === 'sales-credit' ? 'bg-indigo-600 text-white shadow-lg font-bold' : 'text-indigo-300 hover:bg-white/5'}`}>
