import React, { useState, useEffect, useLayoutEffect } from 'react';

interface TutorialProps {
  onClose: () => void;
  activeView: string;
}

interface Step {
  id: string;
  targetId: string;
  title: string;
  content: string;
  requiredView?: string;
}

const Tutorial: React.FC<TutorialProps> = ({ onClose, activeView }) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [coords, setCoords] = useState<{ top: number, left: number, width: number, height: number } | null>(null);

  const steps: Step[] = [
    {
      id: 'step1',
      targetId: 'nav-customers',
      title: 'Passo 1: Clientes',
      content: 'Primeiro, cadastre quem compra com você. Sem clientes, não há vendas!',
    },
    {
      id: 'step2',
      targetId: 'nav-sales-cash',
      title: 'Passo 2: Venda À Vista',
      content: 'Quando o cliente pagar na hora, use esta opção para registrar a entrada de dinheiro direto no caixa.',
    },
    {
      id: 'step3',
      targetId: 'nav-sales-credit',
      title: 'Passo 3: Venda a Prazo',
      content: 'Para vendas parceladas ou fiado, use este menu. O sistema cuidará dos vencimentos para você.',
    },
    {
      id: 'step4',
      targetId: 'nav-agenda',
      title: 'Passo 4: Agenda Mensal',
      content: 'Aqui você vê tudo o que tem para receber em cada mês, facilitando a cobrança.',
    },
    {
      id: 'step5',
      targetId: 'nav-dashboard',
      title: 'Passo 5: Dashboard',
      content: 'Acompanhe a saúde financeira da sua loja com gráficos e insights de IA.',
    }
  ];

  const updateCoords = () => {
    const step = steps[currentStep];
    const element = document.getElementById(step.targetId);
    if (element) {
      const rect = element.getBoundingClientRect();
      setCoords({ top: rect.top, left: rect.left, width: rect.width, height: rect.height });
    } else {
      setCoords(null);
    }
  };

  useLayoutEffect(() => {
    updateCoords();
    window.addEventListener('resize', updateCoords);
    return () => window.removeEventListener('resize', updateCoords);
  }, [currentStep, activeView]);

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      onClose();
    }
  };

  const currentStepData = steps[currentStep];
  const isTargetVisible = !!coords;

  return (
    <div className="fixed inset-0 z-[9999] pointer-events-none">
      <div className="absolute inset-0 bg-slate-950/70 pointer-events-auto"
        style={{ clipPath: coords ? `polygon(0% 0%, 0% 100%, ${coords.left}px 100%, ${coords.left}px ${coords.top}px, ${coords.left + coords.width}px ${coords.top}px, ${coords.left + coords.width}px ${coords.top + coords.height}px, ${coords.left}px ${coords.top + coords.height}px, ${coords.left}px 100%, 100% 100%, 100% 0%)` : 'none' }}
      />
      {coords && (
        <div className="absolute border-2 border-indigo-400 rounded-lg shadow-[0_0_20px_rgba(129,140,248,0.5)] animate-pulse"
          style={{ top: coords.top - 4, left: coords.left - 4, width: coords.width + 8, height: coords.height + 8 }}
        />
      )}
      <div className="absolute pointer-events-auto transition-all duration-500 ease-out"
        style={{ top: coords ? (coords.top + coords.height + 20 > window.innerHeight - 200 ? coords.top - 220 : coords.top + coords.height + 20) : '50%', left: coords ? Math.min(Math.max(20, coords.left), window.innerWidth - 340) : '50%', transform: coords ? 'none' : 'translate(-50%, -50%)', width: '320px' }}
      >
        <div className="bg-white rounded-2xl shadow-2xl p-6 border border-indigo-100 relative">
          <div className="absolute top-0 left-0 w-full h-1 bg-indigo-600"></div>
          <div className="flex justify-between items-start mb-4">
            <span className="text-[10px] font-black text-indigo-600 uppercase bg-indigo-50 px-2 py-0.5 rounded">Passo {currentStep + 1} de {steps.length}</span>
            <button onClick={onClose} className="text-slate-400 hover:text-rose-500">✕</button>
          </div>
          <h4 className="text-lg font-bold text-slate-800 mb-2">{currentStepData.title}</h4>
          <p className="text-sm text-slate-500 leading-relaxed mb-6">{currentStepData.content}</p>
          <div className="flex items-center justify-between">
             <button onClick={() => currentStep > 0 && setCurrentStep(currentStep - 1)} disabled={currentStep === 0} className="text-xs font-bold text-slate-400 uppercase tracking-widest disabled:opacity-0 transition">Anterior</button>
             <button onClick={handleNext} className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl text-xs font-bold uppercase hover:bg-indigo-700 shadow-lg shadow-indigo-200">
                {currentStep === steps.length - 1 ? 'Começar' : 'Entendido'}
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

