        <div className="space-y-1.5 flex-1">
          <button id="nav-dashboard" onClick={() => setActiveView('dashboard')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm ${activeView === 'dashboard' ? 'bg-indigo-600 text-white shadow-lg font-bold' : 'text-indigo-300 hover:bg-white/5'}`}>
