import React, { useState } from 'react';
import { Customer, Sale, PaymentStatus, Installment } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
  mode: 'cash' | 'credit';
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, onAddSale, onUpdateSale, mode }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [description, setDescription] = useState('');
  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [paymentValue, setPaymentValue] = useState<number>(0);

  const [editingInstId, setEditingInstId] = useState<string | null>(null);
  const [editFields, setEditFields] = useState({
    amount: 0,
    paidAmount: 0,
    dueDate: ''
  });

  const [isReparceling, setIsReparceling] = useState(false);
  const [newTotalInstallments, setNewTotalInstallments] = useState<number>(1);

  const filteredSales = sales.filter(s => (s.type || 'credit') === mode);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    if (!customerId || !description || totalAmount <= 0) return;

    const installments: Installment[] = [];
    const today = new Date();

    if (mode === 'cash') {
      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: totalAmount,
        paidAmount: totalAmount,
        dueDate: today.toISOString().split('T')[0],
        status: PaymentStatus.PAID
      });
    } else {
      const installmentAmount = totalAmount / numInstallments;
      for (let i = 1; i <= numInstallments; i++) {
        const dueDate = calculateDueDate(today, i, dueDay);
        installments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: '', 
          amount: installmentAmount,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onAddSale({
      customerId,
      description,
      totalAmount,
      date: today.toISOString().split('T')[0],
      installments,
      status: mode === 'cash' ? PaymentStatus.PAID : PaymentStatus.PENDING,
      type: mode
    });

    setShowAdd(false);
    resetForm();
  };

  const calculateDueDate = (baseDate: Date, monthsToAdd: number, targetDay: number) => {
    let targetMonth = baseDate.getMonth() + monthsToAdd;
    let targetYear = baseDate.getFullYear();
    while (targetMonth > 11) { targetMonth -= 12; targetYear += 1; }
    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const resetForm = () => {
    setCustomerId('');
    setDescription('');
    setTotalAmount(0);
    setNumInstallments(1);
    setDueDay(new Date().getDate());
  };

  const handleAbatePayment = (sale: Sale, installmentId: string) => {
    if (paymentValue <= 0) return;
    const newInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const remainingToPay = inst.amount - inst.paidAmount;
        const actualPayment = Math.min(paymentValue, remainingToPay);
        const newPaidAmount = inst.paidAmount + actualPayment;
        return {
          ...inst,
          paidAmount: newPaidAmount,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });
    onUpdateSale({
      ...sale,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    });
    setPaymentValue(0);
  };

  const calculateSaleStatus = (installments: Installment[]) => {
    const allPaid = installments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = installments.some(i => i.status !== PaymentStatus.PENDING);
    return allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING);
  };

  const handleReparcel = (sale: Sale) => {
    const protectedInstallments = sale.installments.filter(i => i.paidAmount > 0 || i.status === PaymentStatus.PAID);
    if (newTotalInstallments < protectedInstallments.length) return;
    const totalPaid = protectedInstallments.reduce((sum, i) => sum + i.paidAmount, 0);
    const balanceRemaining = sale.totalAmount - totalPaid;
    const newInstallmentsNeeded = newTotalInstallments - protectedInstallments.length;
    const newInstallments: Installment[] = [...protectedInstallments];
    if (newInstallmentsNeeded > 0) {
      const amountPerNewInst = balanceRemaining / newInstallmentsNeeded;
      const lastDate = protectedInstallments.length > 0 ? new Date(protectedInstallments[protectedInstallments.length - 1].dueDate) : new Date(sale.date);
      for (let i = 1; i <= newInstallmentsNeeded; i++) {
        const dueDate = calculateDueDate(lastDate, i, lastDate.getDate());
        newInstallments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: sale.id,
          amount: amountPerNewInst,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }
    onUpdateSale({ ...sale, installments: newInstallments, status: calculateSaleStatus(newInstallments) });
    setIsReparceling(false);
  };

  const accentColor = mode === 'cash' ? 'emerald' : 'indigo';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800">{mode === 'cash' ? 'Vendas À Vista' : 'Vendas a Prazo'}</h2>
          <p className="text-xs text-slate-500 uppercase tracking-widest font-bold">Listando apenas lançamentos {mode === 'cash' ? 'em dinheiro' : 'parcelados'}</p>
        </div>
        <button 
          id="btn-new-sale"
          onClick={() => setShowAdd(!showAdd)}
          className={`bg-${accentColor}-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-${accentColor}-700 transition shadow-sm`}
        >
          {showAdd ? 'Cancelar' : 'Novo Lançamento'}
        </button>
      </div>

      {showAdd && (
        <form id="sale-form-container" onSubmit={handleAddSale} className={`bg-white p-6 rounded-2xl shadow-sm border border-${accentColor}-100 space-y-6 animate-in fade-in zoom-in duration-200`}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            <div className="md:col-span-1">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Cliente</label>
              <select 
                value={customerId} 
                onChange={e => setCustomerId(e.target.value)} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none"
              >
                <option value="">Selecione...</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Descrição</label>
              <input 
                type="text" 
                value={description} 
                onChange={e => setDescription(e.target.value)} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
                placeholder="Ex: Vestido Floral" 
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Valor Total (R$)</label>
              <input 
                type="number" 
                step="0.01" 
                value={totalAmount || ''} 
                onChange={e => setTotalAmount(Number(e.target.value))} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
              />
            </div>
            {mode === 'credit' && (
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nº Parcelas</label>
                  <input 
                    type="number" 
                    min="1" 
                    max="24" 
                    value={numInstallments} 
                    onChange={e => setNumInstallments(Number(e.target.value))} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Dia Venc.</label>
                  <input 
                    type="number" 
                    min="1" 
                    max="31" 
                    value={dueDay} 
                    onChange={e => setDueDay(Number(e.target.value))} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
                  />
                </div>
              </div>
            )}
            {mode === 'cash' && (
               <div className="flex items-end pb-1">
                  <div className="bg-emerald-50 text-emerald-700 px-4 py-2 rounded-xl border border-emerald-100 flex items-center gap-2">
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                    <span className="text-xs font-bold uppercase tracking-tight">Recebimento confirmado</span>
                  </div>
               </div>
            )}
          </div>
          <div className="flex justify-end pt-2 border-t border-slate-50">
            <button type="submit" className={`px-8 py-3 rounded-xl text-sm font-bold uppercase tracking-widest transition shadow-lg bg-${accentColor}-600 text-white hover:bg-${accentColor}-700`}>
              Confirmar Venda {mode === 'cash' ? 'À Vista' : 'a Prazo'}
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {filteredSales.length === 0 && (
          <div className="bg-white p-12 text-center rounded-2xl border border-dashed border-slate-200 text-slate-400">
            Nenhuma venda {mode === 'cash' ? 'à vista' : 'a prazo'} registrada.
          </div>
        )}
        {filteredSales.map(sale => {
          const customer = customers.find(c => c.id === sale.customerId);
          const isOverdue = sale.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date());
          return (
            <div key={sale.id} className={`bg-white rounded-2xl shadow-sm border ${isOverdue ? 'border-rose-200' : mode === 'cash' ? 'border-emerald-100' : 'border-slate-100'} overflow-hidden transition-all hover:shadow-md`}>
              <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div className="flex items-start gap-3">
                  <div className={`mt-1 p-2 rounded-lg ${mode === 'cash' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      {mode === 'cash' ? <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /> : <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z" />}
                    </svg>
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-800">{customer?.name || 'Cliente Excluído'}</h3>
                    <p className="text-sm text-slate-500">{sale.description}</p>
                    <p className="text-[10px] text-slate-400 uppercase font-bold">{new Date(sale.date).toLocaleDateString('pt-BR')}</p>
                  </div>
                </div>
                <div className="flex items-center gap-6">
                  <div className="text-right">
                    <p className="text-[10px] font-bold text-slate-400 uppercase">Valor</p>
                    <p className={`font-black text-lg ${mode === 'cash' ? 'text-emerald-600' : 'text-slate-800'}`}>R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
                  <button onClick={() => setSelectedSale(selectedSale?.id === sale.id ? null : sale)} className={`px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-widest transition ${selectedSale?.id === sale.id ? `bg-${accentColor}-600 text-white` : 'bg-slate-50 text-slate-600 hover:bg-slate-100'}`}>
                    {selectedSale?.id === sale.id ? 'Fechar' : 'Detalhes'}
                  </button>
                </div>
              </div>
              {selectedSale?.id === sale.id && (
                <div className="border-t border-slate-50 bg-slate-50/50 p-5 animate-in slide-in-from-top-2 duration-200">
                  <div className="space-y-3">
                    {sale.installments.map((inst, idx) => (
                      <div key={inst.id} className="bg-white p-4 rounded-xl border border-slate-200 flex justify-between items-center">
                        <div className="flex items-center gap-4">
                           <span className={`w-8 h-8 flex items-center justify-center rounded-lg text-[10px] font-bold ${inst.status === PaymentStatus.PAID ? 'bg-emerald-500 text-white' : 'bg-indigo-50 text-indigo-600'}`}>
                             {mode === 'cash' ? '✓' : idx + 1}
                           </span>
                           <div>
                             <p className="text-xs font-bold text-slate-700">{mode === 'cash' ? 'Pagamento Único' : `Vencimento: ${new Date(inst.dueDate).toLocaleDateString('pt-BR')}`}</p>
                             <p className={`text-[10px] uppercase font-black ${inst.status === PaymentStatus.PAID ? 'text-emerald-500' : 'text-amber-500'}`}>{inst.status === PaymentStatus.PAID ? 'Liquidado' : 'Pendente'}</p>
                           </div>
                        </div>
                        <div className="flex items-center gap-4">
                           <p className="text-sm font-black text-slate-800">R$ {inst.amount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                           {inst.status !== PaymentStatus.PAID && (
                             <div className="flex items-center gap-2">
                               <input 
                                 type="number" 
                                 placeholder="Valor" 
                                 className="w-20 bg-slate-50 border border-slate-200 rounded px-2 py-1 text-xs text-slate-900" 
                                 onChange={(e) => setPaymentValue(Number(e.target.value))} 
                               />
                               <button onClick={() => handleAbatePayment(sale, inst.id)} className="bg-emerald-500 text-white px-3 py-1.5 rounded-lg text-xs font-bold">Baixar</button>
                             </div>
                           )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default SalesManager;

import React, { useState } from 'react';
import { Customer, Sale, PaymentStatus, Installment } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
  mode: 'cash' | 'credit';
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, onAddSale, onUpdateSale, mode }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [description, setDescription] = useState('');
  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [paymentValue, setPaymentValue] = useState<number>(0);

  // States for editing existing sale
  const [isEditingSale, setIsEditingSale] = useState(false);
  const [editTotalAmount, setEditTotalAmount] = useState<number>(0);
  const [editNumInstallments, setEditNumInstallments] = useState<number>(0);

  const filteredSales = sales.filter(s => (s.type || 'credit') === mode);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    if (!customerId || !description || totalAmount <= 0) return;

    const installments: Installment[] = [];
    const today = new Date();

    if (mode === 'cash') {
      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: totalAmount,
        paidAmount: totalAmount,
        dueDate: today.toISOString().split('T')[0],
        status: PaymentStatus.PAID
      });
    } else {
      const installmentAmount = totalAmount / numInstallments;
      for (let i = 1; i <= numInstallments; i++) {
        const dueDate = calculateDueDate(today, i, dueDay);
        installments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: '', 
          amount: installmentAmount,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onAddSale({
      customerId,
      description,
      totalAmount,
      date: today.toISOString().split('T')[0],
      installments,
      status: mode === 'cash' ? PaymentStatus.PAID : PaymentStatus.PENDING,
      type: mode
    });

    setShowAdd(false);
    resetForm();
  };

  const calculateDueDate = (baseDate: Date, monthsToAdd: number, targetDay: number) => {
    let targetMonth = baseDate.getMonth() + monthsToAdd;
    let targetYear = baseDate.getFullYear();
    while (targetMonth > 11) { targetMonth -= 12; targetYear += 1; }
    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const resetForm = () => {
    setCustomerId('');
    setDescription('');
    setTotalAmount(0);
    setNumInstallments(1);
    setDueDay(new Date().getDate());
  };

  const handleAbatePayment = (sale: Sale, installmentId: string) => {
    if (paymentValue <= 0) return;
    const newInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const remainingToPay = inst.amount - inst.paidAmount;
        const actualPayment = Math.min(paymentValue, remainingToPay);
        const newPaidAmount = inst.paidAmount + actualPayment;
        return {
          ...inst,
          paidAmount: newPaidAmount,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });
    const updatedSale = {
      ...sale,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    };
    onUpdateSale(updatedSale);
    setSelectedSale(updatedSale);
    setPaymentValue(0);
  };

  const calculateSaleStatus = (installments: Installment[]) => {
    const allPaid = installments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = installments.some(i => i.status !== PaymentStatus.PENDING);
    return allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING);
  };

  const handleApplyEdit = (sale: Sale) => {
    // 1. Get already paid installments (they shouldn't be touched)
    const paidInstallments = sale.installments.filter(i => i.paidAmount > 0 || i.status === PaymentStatus.PAID);
    const totalPaid = paidInstallments.reduce((sum, i) => sum + i.paidAmount, 0);

    if (editNumInstallments < paidInstallments.length) {
      alert(`Não é possível reduzir para menos de ${paidInstallments.length} parcelas, pois já existem pagamentos registrados.`);
      return;
    }

    if (editTotalAmount < totalPaid) {
      alert(`O novo valor total (R$ ${editTotalAmount}) não pode ser menor que o valor já pago (R$ ${totalPaid}).`);
      return;
    }

    const remainingBalance = editTotalAmount - totalPaid;
    const remainingInstallmentsCount = editNumInstallments - paidInstallments.length;

    const newInstallments: Installment[] = [...paidInstallments];

    if (remainingInstallmentsCount > 0) {
      const amountPerNewInst = remainingBalance / remainingInstallmentsCount;
      const lastRefDate = paidInstallments.length > 0 
        ? new Date(paidInstallments[paidInstallments.length - 1].dueDate) 
        : new Date(sale.date);

      const targetDay = lastRefDate.getDate();

      for (let i = 1; i <= remainingInstallmentsCount; i++) {
        const dueDate = calculateDueDate(lastRefDate, i, targetDay);
        newInstallments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: sale.id,
          amount: amountPerNewInst,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    const updatedSale = {
      ...sale,
      totalAmount: editTotalAmount,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    };

    onUpdateSale(updatedSale);
    setSelectedSale(updatedSale);
    setIsEditingSale(false);
  };

  const startEditing = (sale: Sale) => {
    setEditTotalAmount(sale.totalAmount);
    setEditNumInstallments(sale.installments.length);
    setIsEditingSale(true);
  };

  const accentColor = mode === 'cash' ? 'emerald' : 'indigo';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800">{mode === 'cash' ? 'Vendas À Vista' : 'Vendas a Prazo'}</h2>
          <p className="text-xs text-slate-500 uppercase tracking-widest font-bold">Listando apenas lançamentos {mode === 'cash' ? 'em dinheiro' : 'parcelados'}</p>
        </div>
        <button 
          id="btn-new-sale"
          onClick={() => setShowAdd(!showAdd)}
          className={`bg-${accentColor}-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-${accentColor}-700 transition shadow-sm`}
        >
          {showAdd ? 'Cancelar' : 'Novo Lançamento'}
        </button>
      </div>

      {showAdd && (
        <form id="sale-form-container" onSubmit={handleAddSale} className={`bg-white p-6 rounded-2xl shadow-sm border border-${accentColor}-100 space-y-6 animate-in fade-in zoom-in duration-200`}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            <div className="md:col-span-1">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Cliente</label>
              <select 
                value={customerId} 
                onChange={e => setCustomerId(e.target.value)} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none"
              >
                <option value="">Selecione...</option>
                {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Descrição</label>
              <input 
                type="text" 
                value={description} 
                onChange={e => setDescription(e.target.value)} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
                placeholder="Ex: Vestido Floral" 
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Valor Total (R$)</label>
              <input 
                type="number" 
                step="0.01" 
                value={totalAmount || ''} 
                onChange={e => setTotalAmount(Number(e.target.value))} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
              />
            </div>
            {mode === 'credit' && (
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nº Parcelas</label>
                  <input 
                    type="number" 
                    min="1" 
                    max="24" 
                    value={numInstallments} 
                    onChange={e => setNumInstallments(Number(e.target.value))} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Dia Venc.</label>
                  <input 
                    type="number" 
                    min="1" 
                    max="31" 
                    value={dueDay} 
                    onChange={e => setDueDay(Number(e.target.value))} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
                  />
                </div>
              </div>
            )}
            {mode === 'cash' && (
               <div className="flex items-end pb-1">
                  <div className="bg-emerald-50 text-emerald-700 px-4 py-2 rounded-xl border border-emerald-100 flex items-center gap-2">
                    <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                    <span className="text-xs font-bold uppercase tracking-tight">Recebimento confirmado</span>
                  </div>
               </div>
            )}
          </div>
          <div className="flex justify-end pt-2 border-t border-slate-50">
            <button type="submit" className={`px-8 py-3 rounded-xl text-sm font-bold uppercase tracking-widest transition shadow-lg bg-${accentColor}-600 text-white hover:bg-${accentColor}-700`}>
              Confirmar Venda {mode === 'cash' ? 'À Vista' : 'a Prazo'}
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {filteredSales.length === 0 && (
          <div className="bg-white p-12 text-center rounded-2xl border border-dashed border-slate-200 text-slate-400">
            Nenhuma venda {mode === 'cash' ? 'à vista' : 'a prazo'} registrada.
          </div>
        )}
        {filteredSales.map(sale => {
          const customer = customers.find(c => c.id === sale.customerId);
          const isOverdue = sale.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date());
          return (
            <div key={sale.id} className={`bg-white rounded-2xl shadow-sm border ${isOverdue ? 'border-rose-200' : mode === 'cash' ? 'border-emerald-100' : 'border-slate-100'} overflow-hidden transition-all hover:shadow-md`}>
              <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div className="flex items-start gap-3">
                  <div className={`mt-1 p-2 rounded-lg ${mode === 'cash' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      {mode === 'cash' ? <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /> : <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z" />}
                    </svg>
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-800">{customer?.name || 'Cliente Excluído'}</h3>
                    <p className="text-sm text-slate-500">{sale.description}</p>
                    <p className="text-[10px] text-slate-400 uppercase font-bold">{new Date(sale.date).toLocaleDateString('pt-BR')}</p>
                  </div>
                </div>
                <div className="flex items-center gap-6">
                  <div className="text-right">
                    <p className="text-[10px] font-bold text-slate-400 uppercase">Valor</p>
                    <p className={`font-black text-lg ${mode === 'cash' ? 'text-emerald-600' : 'text-slate-800'}`}>R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
                  <button onClick={() => { setSelectedSale(selectedSale?.id === sale.id ? null : sale); setIsEditingSale(false); }} className={`px-4 py-2 rounded-xl text-xs font-bold uppercase tracking-widest transition ${selectedSale?.id === sale.id ? `bg-${accentColor}-600 text-white` : 'bg-slate-50 text-slate-600 hover:bg-slate-100'}`}>
                    {selectedSale?.id === sale.id ? 'Fechar' : 'Detalhes'}
                  </button>
                </div>
              </div>
              {selectedSale?.id === sale.id && (
                <div className="border-t border-slate-50 bg-slate-50/50 p-5 animate-in slide-in-from-top-2 duration-200">

                  {mode === 'credit' && (
                    <div className="mb-6 flex justify-end">
                      {isEditingSale ? (
                        <div className="bg-white p-4 rounded-2xl border border-indigo-200 shadow-xl flex flex-wrap items-end gap-4 animate-in zoom-in duration-200">
                          <div>
                            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Novo Valor Total</label>
                            <input 
                              type="number" 
                              value={editTotalAmount} 
                              onChange={(e) => setEditTotalAmount(Number(e.target.value))} 
                              className="w-32 bg-slate-50 border border-slate-200 rounded-lg px-2 py-1.5 text-sm text-slate-900 font-bold"
                            />
                          </div>
                          <div>
                            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Total de Parcelas</label>
                            <input 
                              type="number" 
                              min="1" 
                              value={editNumInstallments} 
                              onChange={(e) => setEditNumInstallments(Number(e.target.value))} 
                              className="w-24 bg-slate-50 border border-slate-200 rounded-lg px-2 py-1.5 text-sm text-slate-900 font-bold"
                            />
                          </div>
                          <div className="flex gap-2">
                            <button onClick={() => handleApplyEdit(sale)} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold uppercase hover:bg-indigo-700 transition">Aplicar Mudanças</button>
                            <button onClick={() => setIsEditingSale(false)} className="bg-slate-100 text-slate-500 px-4 py-2 rounded-xl text-xs font-bold uppercase hover:bg-slate-200 transition">Cancelar</button>
                          </div>
                        </div>
                      ) : (
                        <button 
                          onClick={() => startEditing(sale)}
                          className="flex items-center gap-2 text-indigo-600 hover:text-indigo-800 transition text-[10px] font-bold uppercase border border-indigo-200 bg-white px-3 py-1.5 rounded-xl shadow-sm"
                        >
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                          Editar Valor ou Parcelas
                        </button>
                      )}
                    </div>
                  )}

                  <div className="space-y-3">
                    {sale.installments.map((inst, idx) => (
                      <div key={inst.id} className="bg-white p-4 rounded-xl border border-slate-200 flex flex-wrap justify-between items-center gap-4">
                        <div className="flex items-center gap-4">
                           <span className={`w-8 h-8 flex items-center justify-center rounded-lg text-[10px] font-bold ${inst.status === PaymentStatus.PAID ? 'bg-emerald-500 text-white' : 'bg-indigo-50 text-indigo-600'}`}>
