import React, { useState, useEffect } from 'react';
import { User } from '../types';

interface LandingProps {
  onLogin: (user: User) => void;
}

const Landing: React.FC<LandingProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [isRecovery, setIsRecovery] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  // Load merged users from LocalStorage on mount
  const getSavedUsers = (): User[] => {
    return JSON.parse(localStorage.getItem('gestao93_users') || '[]');
  };

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setMessage('');

    const savedUsers = getSavedUsers();

    if (isRecovery) {
      const user = savedUsers.find((u: User) => u.email === email);
      if (user) {
        setMessage(`Um link de recuperação foi enviado para ${email}. (Simulação)`);
        setTimeout(() => setIsRecovery(false), 3000);
      } else {
        setError('E-mail não encontrado em nossa base.');
      }
      return;
    }

    if (isRegistering) {
      if (!name || !email || !password) {
        setError('Preencha todos os campos.');
        return;
      }
      if (savedUsers.find((u: User) => u.email === email)) {
        setError('Este e-mail já está cadastrado.');
        return;
      }
      const newUser: User = { 
        id: Math.random().toString(36).substr(2, 9), 
        name, 
        email, 
        password,
        authProvider: 'local'
      };
      const updatedUsers = [...savedUsers, newUser];
      localStorage.setItem('gestao93_users', JSON.stringify(updatedUsers));
      localStorage.setItem('gestao93_current_user', JSON.stringify(newUser));
      onLogin(newUser);
    } else {
      const user = savedUsers.find((u: User) => u.email === email && u.password === password);
      if (user) {
        localStorage.setItem('gestao93_current_user', JSON.stringify(user));
        onLogin(user);
      } else {
        setError('E-mail ou senha incorretos.');
      }
    }
  };

  const handleOneDriveLogin = async () => {
    setIsAuthenticating(true);
    setError('');

    const simulatedEmail = prompt("Para simular o login Microsoft, digite seu e-mail Outlook/Hotmail:", "loja93@outlook.com");

    if (!simulatedEmail) {
      setIsAuthenticating(false);
      return;
    }

    setTimeout(() => {
      const uniqueId = btoa(simulatedEmail).replace(/=/g, '');

      const msUser: User = {
        id: `ms_${uniqueId}`,
        name: simulatedEmail.split('@')[0].toUpperCase(),
        email: simulatedEmail,
        authProvider: 'onedrive',
        avatarUrl: `https://ui-avatars.com/api/?name=${simulatedEmail}&background=4f46e5&color=fff`
      };

      localStorage.setItem('gestao93_current_user', JSON.stringify(msUser));
      onLogin(msUser);
      setIsAuthenticating(false);
    }, 1200);
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-white">
      {/* Visual Section */}
      <div className="md:w-1/2 lg:w-2/3 relative h-[30vh] md:h-screen overflow-hidden">
        <img 
          src="https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&q=80&w=1600" 
          className="absolute inset-0 w-full h-full object-cover" 
          alt="Woman Shopping" 
        />
        <div className="absolute inset-0 z-10 bg-gradient-to-t md:bg-gradient-to-r from-indigo-950/90 via-indigo-950/40 to-transparent"></div>
        <div className="absolute inset-0 z-20 flex flex-col justify-end md:justify-center p-8 md:p-16 lg:p-24 text-white">
          <div className="animate-in fade-in slide-in-from-left-8 duration-1000">
            <div className="flex items-center gap-4 mb-2 md:mb-6">
              <div className="bg-indigo-600 p-2 md:p-3 rounded-2xl shadow-2xl border border-white/20">
                <svg className="w-8 h-8 md:w-12 md:h-12 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
              </div>
              <h1 className="text-4xl md:text-8xl font-black tracking-tighter italic uppercase drop-shadow-2xl">Gestão 93</h1>
            </div>
            <p className="text-lg md:text-4xl font-light italic text-indigo-100 max-w-xl leading-tight drop-shadow-md">“Lute Hoje pelos seus Sonhos”</p>
          </div>
        </div>
      </div>

      {/* Auth Section */}
      <div className="flex-1 flex flex-col justify-center p-8 md:p-12 lg:p-20 bg-slate-50 overflow-y-auto">
        <div className="max-w-md w-full mx-auto">
          <div className="mb-8">
            <h3 className="text-3xl font-bold text-slate-800 mb-2">
              {isRecovery ? 'Recuperar Conta' : isRegistering ? 'Criar Acesso' : 'Bem-vindo de volta'}
            </h3>
            <p className="text-slate-500 text-sm">
              {isRecovery ? 'Insira seu e-mail para receber as instruções.' : 'Gerencie suas vendas a prazo com segurança.'}
            </p>
          </div>

          <div className="space-y-4">
            {!isRecovery && (
              <button 
                onClick={handleOneDriveLogin}
                disabled={isAuthenticating}
                className="w-full bg-white border border-slate-200 text-slate-700 font-bold py-4 rounded-2xl hover:bg-slate-50 transition shadow-sm flex items-center justify-center gap-3 active:scale-[0.98] disabled:opacity-50"
              >
                {isAuthenticating ? (
                  <div className="w-5 h-5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                ) : (
                  <img src="https://upload.wikimedia.org/wikipedia/commons/3/3c/Microsoft_Office_OneDrive_%282019-present%29.svg" className="h-6" alt="OneDrive" />
                )}
                Entrar com OneDrive
              </button>
            )}

            {!isRecovery && (
