                 <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div>
                 <div className="relative flex justify-center text-xs uppercase"><span className="bg-slate-50 px-2 text-slate-400 font-bold">Acesso por E-mail</span></div>
              </div>
            )}

            <form onSubmit={handleAuth} className="space-y-4">
              {isRegistering && !isRecovery && (
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Nome da Loja</label>
                  <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600 outline-none transition" placeholder="Sua Loja" />
                </div>
              )}
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">E-mail</label>
                <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600 outline-none transition" placeholder="seu@email.com" />
              </div>
              {!isRecovery && (
                <div className="space-y-1">
                  <div className="flex justify-between items-center px-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Senha</label>
                    <button type="button" onClick={() => setIsRecovery(true)} className="text-[10px] font-bold text-indigo-600 hover:underline uppercase">Esqueceu?</button>
                  </div>
                  <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600 outline-none transition" placeholder="••••••••" />
