import React, { useState, useEffect, useCallback } from 'react';
import { View, Customer, Sale, User, Expense } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';
import Agenda from './components/Agenda';
import Settings from './components/Settings';
import Landing from './components/Landing';
import Tutorial from './components/Tutorial';
import ExpenseManager from './components/ExpenseManager';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const syncWithOneDrive = useCallback(async (action: 'upload' | 'download') => {
    if (!user || user.authProvider !== 'onedrive') return;
    setSyncStatus('syncing');
    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      const storageKey = `gestao93_cloud_master_${user.id}`;
      if (action === 'download') {
        const cloudData = localStorage.getItem(storageKey);
        if (cloudData) {
          const parsed = JSON.parse(cloudData);
          setCustomers(parsed.customers || []);
          setSales(parsed.sales || []);
          setExpenses(parsed.expenses || []);
        }
      } else {
        const localUsers = JSON.parse(localStorage.getItem('gestao93_users') || '[]');
        const dataToUpload = JSON.stringify({ 
          customers, 
          sales, 
          expenses,
          users: localUsers,
          lastSync: new Date().toISOString()
        });
        localStorage.setItem(storageKey, dataToUpload);
      }
      setSyncStatus('synced');
    } catch (err) {
      setSyncStatus('error');
    }
  }, [user, customers, sales, expenses]);

  useEffect(() => {
    const savedUser = localStorage.getItem('gestao93_current_user');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      checkTutorialStatus(parsedUser.id);
      if (parsedUser.authProvider === 'onedrive') {
        syncWithOneDrive('download');
      } else {
        const localCustomers = localStorage.getItem(`gestao93_customers_${parsedUser.id}`);
        const localSales = localStorage.getItem(`gestao93_sales_${parsedUser.id}`);
        const localExpenses = localStorage.getItem(`gestao93_expenses_${parsedUser.id}`);
        if (localCustomers) setCustomers(JSON.parse(localCustomers));
        if (localSales) setSales(JSON.parse(localSales));
        if (localExpenses) setExpenses(JSON.parse(localExpenses));
      }
    }
    setLoading(false);
  }, []);

  const checkTutorialStatus = (userId: string) => {
    const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
    if (!tutorialSeen) setShowTutorial(true);
  };

  const handleFinishTutorial = () => {
    if (user) localStorage.setItem(`gestao93_tutorial_seen_${user.id}`, 'true');
    setShowTutorial(false);
  };

  useEffect(() => {
    if (!loading && user) {
      setSyncStatus('syncing');
      const timer = setTimeout(() => {
        if (user.authProvider === 'onedrive') {
          syncWithOneDrive('upload');
        } else {
          localStorage.setItem(`gestao93_customers_${user.id}`, JSON.stringify(customers));
          localStorage.setItem(`gestao93_sales_${user.id}`, JSON.stringify(sales));
          localStorage.setItem(`gestao93_expenses_${user.id}`, JSON.stringify(expenses));
          setSyncStatus('synced');
        }
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [customers, sales, expenses, user, loading, syncWithOneDrive]);

  const handleLogin = (userData: User) => {
    setUser(userData);
    checkTutorialStatus(userData.id);
  };

  const handleLogout = () => {
    setUser(null);
    setCustomers([]);
    setSales([]);
    setExpenses([]);
    localStorage.removeItem('gestao93_current_user');
    setActiveView('dashboard');
    setShowTutorial(false);
  };

  const handleUpdateProfile = (updatedUser: User) => {
    setUser(updatedUser);
    localStorage.setItem('gestao93_current_user', JSON.stringify(updatedUser));
    const savedUsers = JSON.parse(localStorage.getItem('gestao93_users') || '[]');
    const updatedUsers = savedUsers.map((u: User) => u.id === updatedUser.id ? updatedUser : u);
    localStorage.setItem('gestao93_users', JSON.stringify(updatedUsers));
  };

  const addCustomer = (data: Omit<Customer, 'id' | 'createdAt'>) => {
    const newCustomer: Customer = {
      ...data,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now()
    };
    setCustomers(prev => [newCustomer, ...prev]);
  };

  const deleteCustomer = (id: string) => {
    if (window.confirm('Excluir este cliente e todo seu histórico?')) {
      setCustomers(prev => prev.filter(c => c.id !== id));
    }
  };

  const addSale = (saleData: Omit<Sale, 'id'>) => {
    const newSale: Sale = { ...saleData, id: Math.random().toString(36).substr(2, 9) };
    setSales(prev => [newSale, ...prev]);
  };

  const updateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  const handleAddExpense = (description: string, amount: number) => {
    const newExpense: Expense = { id: Math.random().toString(36).substr(2, 9), description, amount };
    setExpenses(prev => [...prev, newExpense]);
  };

  const handleDeleteExpense = (id: string) => {
    setExpenses(prev => prev.filter(e => e.id !== id));
  };

  if (loading) return null;
  if (!user) return <Landing onLogin={handleLogin} />;

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50">
      {showTutorial && <Tutorial activeView={activeView} onClose={handleFinishTutorial} />}

      {/* Sync Status Indicator */}
      <div className={`fixed top-0 left-0 right-0 z-[200] h-1.5 transition-all duration-500 ${syncStatus === 'syncing' ? 'bg-amber-400 opacity-100' : 'bg-emerald-500 opacity-100'}`}>
         {syncStatus === 'synced' && (
           <div className="absolute top-2 right-4 bg-emerald-500 text-white text-[10px] font-bold px-2 py-0.5 rounded shadow-lg animate-fade-out pointer-events-none uppercase tracking-tighter">
             Informações Salvas
           </div>
         )}
      </div>

      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col p-6 sticky top-0 md:h-screen z-[100] border-r border-indigo-900 shadow-2xl">
        <div className="flex items-center gap-3 mb-8">
          <div className="w-10 h-10 bg-indigo-600 rounded-lg shadow-lg flex items-center justify-center overflow-hidden border border-white/20">
            {user.avatarUrl ? (
              <img src={user.avatarUrl} alt="Logo" className="w-full h-full object-cover" />
            ) : (
              <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
            )}
          </div>
          <h1 className="text-xl font-bold tracking-tight italic truncate max-w-[120px]">{user.name || 'Gestão 93'}</h1>
        </div>

        <div className="mb-6 p-3 bg-white/5 rounded-xl border border-white/10">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-indigo-600 text-white flex items-center justify-center text-[10px] font-black uppercase border border-white/20 overflow-hidden">
              {user.avatarUrl ? <img src={user.avatarUrl} alt="Avatar" className="w-full h-full object-cover" /> : user.name.substring(0, 2)}
            </div>
            <p className="text-xs font-bold text-white truncate">{user.name}</p>
          </div>
        </div>

        <div className="space-y-1.5 flex-1">
          <button id="nav-dashboard" onClick={() => setActiveView('dashboard')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm ${activeView === 'dashboard' ? 'bg-indigo-600 text-white shadow-lg font-bold' : 'text-indigo-300 hover:bg-white/5'}`}>
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>
            Dashboard
          </button>

          <div className="pt-4 pb-2">
            <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest px-4 mb-2">Vendas</p>
            <button id="nav-sales-cash" onClick={() => setActiveView('sales-cash')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm ${activeView === 'sales-cash' ? 'bg-emerald-400 text-emerald-950 shadow-lg font-bold' : 'text-emerald-400/70 hover:bg-white/5'}`}>
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>
              Venda À Vista
            </button>
            <button id="nav-sales-credit" onClick={() => setActiveView('sales-credit')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm ${activeView === 'sales-credit' ? 'bg-indigo-400 text-indigo-950 shadow-lg font-bold' : 'text-indigo-300 hover:bg-white/5'}`}>
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2-2v12a2 2 0 002 2z" /></svg>
              Venda a Prazo
            </button>
          </div>

          <div className="pt-4 pb-2">
            <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest px-4 mb-2">Controle</p>
            <button id="nav-agenda" onClick={() => setActiveView('agenda')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm ${activeView === 'agenda' ? 'bg-indigo-600 text-white shadow-lg font-bold' : 'text-indigo-300 hover:bg-white/5'}`}>
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
              Agenda Mensal
            </button>
            <button id="nav-expenses" onClick={() => setActiveView('expenses')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm ${activeView === 'expenses' ? 'bg-rose-500 text-white shadow-lg font-bold' : 'text-rose-400/80 hover:bg-white/5'}`}>
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              Despesas Fixas
            </button>
            <button id="nav-customers" onClick={() => setActiveView('customers')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm ${activeView === 'customers' ? 'bg-indigo-600 text-white shadow-lg font-bold' : 'text-indigo-300 hover:bg-white/5'}`}>
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              Lista de Clientes
            </button>
          </div>
        </div>

        <div className="mt-auto pt-6 border-t border-white/10 space-y-1">
          <button onClick={() => setActiveView('settings')} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm ${activeView === 'settings' ? 'bg-white/10 text-white' : 'text-indigo-400 hover:text-white'}`}>
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /></svg>
            Configurações
          </button>
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition text-sm text-rose-400 hover:bg-rose-500/10">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
            Sair do Sistema
          </button>
        </div>
      </nav>

      <main className="flex-1 p-4 md:p-10 max-w-7xl mx-auto w-full overflow-y-auto no-scrollbar relative">
        {activeView === 'dashboard' && <Dashboard sales={sales} customers={customers} expenses={expenses} />}
        {activeView === 'agenda' && <Agenda sales={sales} customers={customers} />}
        {activeView === 'customers' && <CustomerList customers={customers} sales={sales} onAdd={addCustomer} onDelete={deleteCustomer} />}
        {activeView === 'expenses' && <ExpenseManager expenses={expenses} onAdd={handleAddExpense} onDelete={handleDeleteExpense} />}
        {activeView === 'sales-cash' && <SalesManager mode="cash" sales={sales} customers={customers} onAddSale={addSale} onUpdateSale={updateSale} />}
        {activeView === 'sales-credit' && <SalesManager mode="credit" sales={sales} customers={customers} onAddSale={addSale} onUpdateSale={updateSale} />}
        {activeView === 'settings' && <Settings user={user} customers={customers} sales={sales} onUpdateProfile={handleUpdateProfile} onImport={(d) => {setCustomers(d.customers); setSales(d.sales); setExpenses(d.expenses || [])}} onClear={() => {setCustomers([]); setSales([]); setExpenses([])}} />}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Sale, Customer, PaymentStatus, Expense } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DashboardProps {
  sales: Sale[];
  customers: Customer[];
  expenses: Expense[];
}

const Dashboard: React.FC<DashboardProps> = ({ sales, customers, expenses }) => {
  const [insights, setInsights] = useState<string>('');
  const [isSyncing, setIsSyncing] = useState(false);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(value);
  };

  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  // Total Receivable (All time)
  const totalReceivable: number = sales.reduce((acc: number, s) => {
    return acc + s.installments.reduce((sum: number, i) => sum + (i.amount - i.paidAmount), 0);
  }, 0);

  // Total Received (All time)
  const totalReceived: number = sales.reduce((acc: number, s) => {
    return acc + s.installments.reduce((sum: number, i) => sum + i.paidAmount, 0);
  }, 0);

  // Current Month Received
  const currentMonthReceived = sales.reduce((acc, s) => {
    return acc + s.installments.reduce((sum, i) => {
      const payDate = i.paidAmount > 0 ? new Date(i.dueDate) : null; // Approximating received date by due date for this logic
      if (payDate && payDate.getMonth() === currentMonth && payDate.getFullYear() === currentYear) {
        return sum + i.paidAmount;
      }
      return sum;
    }, 0);
  }, 0);

  // Total Fixed Expenses
  const totalFixedExpenses = expenses.reduce((acc, exp) => acc + exp.amount, 0);

  // Profit Calculation (Current month received minus fixed expenses)
  const monthlyProfit = currentMonthReceived - totalFixedExpenses;

  const overdueSales = sales.filter(s => 
    s.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date())
  );

  const parseMonthYear = (str: string) => {
    const months: Record<string, number> = {
      'janeiro': 0, 'fevereiro': 1, 'março': 2, 'abril': 3, 'maio': 4, 'junho': 5,
      'julho': 6, 'agosto': 7, 'setembro': 8, 'outubro': 9, 'novembro': 10, 'dezembro': 11
    };
    const [month, year] = str.toLowerCase().split(' de ');
    return new Date(parseInt(year), months[month] || 0).getTime();
  };

  const monthlyPendingTotals = sales.flatMap(s => s.installments)
    .filter(i => i.status !== PaymentStatus.PAID)
    .reduce((acc, inst) => {
      const date = new Date(inst.dueDate);
      const key = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
      acc[key] = (acc[key] || 0) + (inst.amount - inst.paidAmount);
      return acc;
    }, {} as Record<string, number>);

  const monthlyReceivedTotals = sales.flatMap(s => s.installments)
    .filter(i => i.paidAmount > 0)
    .reduce((acc, inst) => {
      const date = new Date(inst.dueDate);
      const key = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
      acc[key] = (acc[key] || 0) + inst.paidAmount;
      return acc;
    }, {} as Record<string, number>);

  const sortedPendingMonths = Object.entries(monthlyPendingTotals)
    .sort((a, b) => parseMonthYear(a[0]) - parseMonthYear(b[0]))
    .slice(0, 6);

  const sortedReceivedMonths = Object.entries(monthlyReceivedTotals)
    .sort((a, b) => parseMonthYear(b[0]) - parseMonthYear(a[0]))
    .slice(0, 6);

  const chartData = [
    { name: 'Recebido Total', value: totalReceived, color: '#10b981' },
    { name: 'A Receber', value: totalReceivable, color: '#6366f1' },
    { name: 'Gastos Fixos', value: totalFixedExpenses, color: '#f43f5e' },
  ];

  const fetchInsights = async (force = false) => {
    if (!force && insights && insights !== 'Carregando insights...') return;
    if (sales.length === 0) {
      setInsights("Registre suas primeiras vendas para ver a análise da IA.");
      return;
    }

    setIsSyncing(true);
    setInsights("Analisando seus dados financeiros...");
    const result = await getFinancialInsights(sales, customers);
    setInsights(result || "Nenhum insight disponível.");
    setIsSyncing(false);
  };

  useEffect(() => {
    if (!insights) {
      fetchInsights();
    }
  }, [sales.length]);

  return (
    <div className="space-y-6">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium uppercase tracking-wider text-[10px] mb-1">A Receber (Total)</p>
          <h3 className="text-xl font-bold text-indigo-600">R$ {formatCurrency(totalReceivable)}</h3>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium uppercase tracking-wider text-[10px] mb-1">Entrada este Mês</p>
          <h3 className="text-xl font-bold text-emerald-600">R$ {formatCurrency(currentMonthReceived)}</h3>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium uppercase tracking-wider text-[10px] mb-1">Despesas Fixas</p>
          <h3 className="text-xl font-bold text-rose-500">R$ {formatCurrency(totalFixedExpenses)}</h3>
        </div>
        <div className={`p-6 rounded-2xl shadow-md border-2 ${monthlyProfit >= 0 ? 'bg-emerald-50 border-emerald-200' : 'bg-rose-50 border-rose-200'}`}>
          <p className="text-slate-500 text-sm font-bold uppercase tracking-wider text-[10px] mb-1">Lucro Bruto (Mês)</p>
          <h3 className={`text-xl font-black ${monthlyProfit >= 0 ? 'text-emerald-700' : 'text-rose-700'}`}>
            R$ {formatCurrency(monthlyProfit)}
          </h3>
          <p className="text-[9px] text-slate-400 mt-1 uppercase font-bold italic">Base: Entrada - Despesas</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-bold text-slate-800 text-sm uppercase tracking-wider">Entradas Mensais Recentes</h4>
            <span className="bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Dinheiro em Caixa</span>
          </div>
          {sortedReceivedMonths.length > 0 ? (
            <div className="space-y-3">
              {sortedReceivedMonths.map(([month, amount]: [string, number]) => (
                <div key={month} className="flex items-center justify-between p-3 bg-emerald-50/30 rounded-xl border border-emerald-100/50">
                  <p className="text-xs font-bold text-slate-600 capitalize">{month}</p>
                  <p className="text-sm font-bold text-emerald-600">R$ {formatCurrency(amount)}</p>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-slate-400 text-sm text-center py-8">Nenhum valor recebido ainda.</p>
          )}
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-bold text-slate-800 text-sm uppercase tracking-wider">Vendas em Atraso</h4>
            <span className="bg-rose-100 text-rose-700 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Atenção</span>
          </div>
          <div className="text-center py-4">
             <h3 className={`text-5xl font-black ${overdueSales.length > 0 ? 'text-rose-500' : 'text-emerald-500'}`}>{overdueSales.length}</h3>
             <p className="text-xs text-slate-400 mt-2 font-bold uppercase">Parcelas pendentes vencidas</p>
          </div>
          {overdueSales.length > 0 && (
            <div className="mt-4 p-3 bg-rose-50 rounded-xl border border-rose-100">
               <p className="text-[10px] text-rose-800 font-bold leading-tight">Consulte a aba "Agenda Mensal" para identificar os clientes em atraso e realizar a cobrança.</p>
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-80">
          <h4 className="font-semibold text-slate-800 mb-4 uppercase tracking-tighter text-xs">Visão Geral do Capital</h4>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={10} />
              <YAxis axisLine={false} tickLine={false} fontSize={10} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
              <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className={`p-6 rounded-2xl border flex flex-col h-80 overflow-hidden transition-colors ${insights.includes('⚠️') ? 'bg-amber-50 border-amber-200' : 'bg-indigo-50 border-indigo-100'}`}>
          <div className="flex justify-between items-center mb-4">
            <h4 className={`font-bold flex items-center gap-2 ${insights.includes('⚠️') ? 'text-amber-900' : 'text-indigo-900'}`}>
              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 14.95a1 1 0 010-1.414l.707-.707a1 1 0 011.414 1.414l-.707.707a1 1 0 01-1.414 0zM6.464 14.95l.707-.707a1 1 0 011.414 1.414l-.707.707a1 1 0 01-1.414 0l-.707-.707z" /></svg>
              Análise de Saúde Financeira
            </h4>
            <button 
              onClick={() => fetchInsights(true)}
              disabled={isSyncing}
              className={`text-xs font-semibold px-3 py-1 rounded-full border transition ${insights.includes('⚠️') ? 'border-amber-300 text-amber-700 hover:bg-amber-100' : 'border-indigo-200 text-indigo-600 hover:bg-indigo-100'} disabled:opacity-50`}
            >
              {isSyncing ? 'Analisando...' : 'Atualizar'}
            </button>
          </div>
          <div className={`flex-1 overflow-y-auto text-sm leading-relaxed space-y-3 ${insights.includes('⚠️') ? 'text-amber-800' : 'text-indigo-800'}`}>
             {insights.split('\n').map((line, i) => (
               <p key={i} className={line.startsWith('⚠️') ? 'font-bold' : ''}>{line}</p>
             ))}
          </div>
        </div>
      </div>
    </div>
  );
};

