export default ExpenseManager;

export interface User {
  id: string;
  name: string;
  email: string;
  password?: string;
  authProvider?: 'local' | 'onedrive';
  avatarUrl?: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  address?: string;
  cpf?: string;
  createdAt: number;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
}

export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  PARTIAL = 'PARTIAL'
}

export interface Installment {
  id: string;
  saleId: string;
  amount: number;
  paidAmount: number;
  dueDate: string;
  status: PaymentStatus;
}

export interface Sale {
  id: string;
  customerId: string;
  description: string;
  baseAmount: number;      // Preço original
  discount: number;        // Valor do desconto
  totalAmount: number;     // Valor final pago pelo cliente
  cardFeeRate?: number;    // Porcentagem da taxa (ex: 2.5)
  cardFeeAmount?: number;  // Valor absoluto da taxa (R$)
  netAmount: number;       // Valor líquido recebido pela loja
  date: string;
  installments: Installment[];
  status: PaymentStatus;
  type?: 'cash' | 'credit';
}

export type View = 'dashboard' | 'customers' | 'sales-cash' | 'sales-credit' | 'agenda' | 'settings' | 'expenses';

import React, { useState, useEffect } from 'react';
import { Customer, Sale, PaymentStatus, Installment } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
  mode: 'cash' | 'credit';
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, onAddSale, onUpdateSale, mode }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [isBalcao, setIsBalcao] = useState(false);
  const [description, setDescription] = useState('');

  // New financial fields
  const [baseAmount, setBaseAmount] = useState<number>(0);
  const [discount, setDiscount] = useState<number>(0);
  const [cardFeeRate, setCardFeeRate] = useState<number>(0);

  // Calculated fields
  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [netAmount, setNetAmount] = useState<number>(0);

  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [paymentValue, setPaymentValue] = useState<number>(0);

  const [isEditingSale, setIsEditingSale] = useState(false);
  const [editTotalAmount, setEditTotalAmount] = useState<number>(0);
  const [editNumInstallments, setEditNumInstallments] = useState<number>(0);

  // Recalculate totals whenever base, discount or fee changes
  useEffect(() => {
    const calculatedTotal = Math.max(0, baseAmount - discount);
    const feeAmount = (calculatedTotal * cardFeeRate) / 100;
    const calculatedNet = calculatedTotal - feeAmount;

    setTotalAmount(calculatedTotal);
    setNetAmount(calculatedNet);
  }, [baseAmount, discount, cardFeeRate]);

  const filteredSales = sales.filter(s => (s.type || 'credit') === mode);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    const finalCustomerId = isBalcao ? 'BALCAO' : customerId;

    if (!finalCustomerId || !description || totalAmount <= 0) {
      alert("Por favor, preencha todos os campos obrigatórios.");
      return;
    }

    const installments: Installment[] = [];
    const today = new Date();
    const cardFeeAmount = (totalAmount * cardFeeRate) / 100;

    if (mode === 'cash') {
      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: totalAmount,
        paidAmount: totalAmount,
        dueDate: today.toISOString().split('T')[0],
        status: PaymentStatus.PAID
      });
    } else {
      const installmentAmount = totalAmount / numInstallments;
      for (let i = 1; i <= numInstallments; i++) {
        const dueDate = calculateDueDate(today, i, dueDay);
        installments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: '', 
          amount: installmentAmount,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onAddSale({
      customerId: finalCustomerId,
      description,
      baseAmount,
      discount,
      totalAmount,
      cardFeeRate,
      cardFeeAmount,
      netAmount,
      date: today.toISOString().split('T')[0],
      installments,
      status: mode === 'cash' ? PaymentStatus.PAID : PaymentStatus.PENDING,
      type: mode
    });

    setShowAdd(false);
    resetForm();
  };

  const calculateDueDate = (baseDate: Date, monthsToAdd: number, targetDay: number) => {
    let targetMonth = baseDate.getMonth() + monthsToAdd;
    let targetYear = baseDate.getFullYear();
    while (targetMonth > 11) { targetMonth -= 12; targetYear += 1; }
    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const resetForm = () => {
    setCustomerId('');
    setIsBalcao(false);
    setDescription('');
    setBaseAmount(0);
    setDiscount(0);
    setCardFeeRate(0);
    setNumInstallments(1);
    setDueDay(new Date().getDate());
  };

  const handleAbatePayment = (sale: Sale, installmentId: string) => {
    if (paymentValue <= 0) return;
    const newInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const remainingToPay = inst.amount - inst.paidAmount;
        const actualPayment = Math.min(paymentValue, remainingToPay);
        const newPaidAmount = inst.paidAmount + actualPayment;
        return {
          ...inst,
          paidAmount: newPaidAmount,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });
    const updatedSale = {
      ...sale,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    };
    onUpdateSale(updatedSale);
    setSelectedSale(updatedSale);
    setPaymentValue(0);
  };

  const calculateSaleStatus = (installments: Installment[]) => {
    const allPaid = installments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = installments.some(i => i.status !== PaymentStatus.PENDING);
    return allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING);
  };

  const handleApplyEdit = (sale: Sale) => {
    const paidInstallments = sale.installments.filter(i => i.paidAmount > 0 || i.status === PaymentStatus.PAID);
    const totalPaid = paidInstallments.reduce((sum, i) => sum + i.paidAmount, 0);

    if (editNumInstallments < paidInstallments.length) {
      alert(`Não é possível reduzir para menos de ${paidInstallments.length} parcelas, pois já existem pagamentos registrados.`);
      return;
    }

    if (editTotalAmount < totalPaid) {
      alert(`O novo valor total (R$ ${editTotalAmount}) não pode ser menor que o valor já pago (R$ ${totalPaid}).`);
      return;
    }

    const remainingBalance = editTotalAmount - totalPaid;
    const remainingInstallmentsCount = editNumInstallments - paidInstallments.length;
    const newInstallments: Installment[] = [...paidInstallments];

    if (remainingInstallmentsCount > 0) {
      const amountPerNewInst = remainingBalance / remainingInstallmentsCount;
      const lastRefDate = paidInstallments.length > 0 
        ? new Date(paidInstallments[paidInstallments.length - 1].dueDate) 
        : new Date(sale.date);

      const targetDay = lastRefDate.getDate();

      for (let i = 1; i <= remainingInstallmentsCount; i++) {
        const dueDate = calculateDueDate(lastRefDate, i, targetDay);
        newInstallments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: sale.id,
          amount: amountPerNewInst,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    const updatedSale = {
      ...sale,
      totalAmount: editTotalAmount,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    };

    onUpdateSale(updatedSale);
    setSelectedSale(updatedSale);
    setIsEditingSale(false);
  };

  const startEditing = (sale: Sale) => {
    setEditTotalAmount(sale.totalAmount);
    setEditNumInstallments(sale.installments.length);
    setIsEditingSale(true);
  };

  const accentColor = mode === 'cash' ? 'emerald' : 'indigo';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800">{mode === 'cash' ? 'Vendas À Vista' : 'Vendas a Prazo'}</h2>
          <p className="text-xs text-slate-500 uppercase tracking-widest font-bold">Lançamento de {mode === 'cash' ? 'entrada imediata' : 'parcelamentos'}</p>
        </div>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className={`bg-${accentColor}-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-${accentColor}-700 transition shadow-sm`}
        >
          {showAdd ? 'Cancelar' : 'Novo Lançamento'}
        </button>
      </div>

      {showAdd && (
        <form onSubmit={handleAddSale} className={`bg-white p-6 rounded-2xl shadow-sm border border-${accentColor}-100 space-y-6 animate-in fade-in zoom-in duration-200`}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="md:col-span-1">
              <div className="flex justify-between items-center mb-1">
                <label className="block text-[10px] font-bold text-slate-400 uppercase">Cliente</label>
                <button 
                  type="button"
                  onClick={() => setIsBalcao(!isBalcao)}
                  className={`text-[10px] font-bold px-2 py-0.5 rounded transition ${isBalcao ? 'bg-amber-100 text-amber-700 border border-amber-200' : 'bg-slate-100 text-slate-500 border border-slate-200'}`}
                >
                  {isBalcao ? '✓ Venda Balcão' : 'Venda Balcão?'}
                </button>
              </div>

              {isBalcao ? (
                <div className="w-full bg-amber-50 border border-amber-200 rounded-lg px-3 py-2 text-sm text-amber-700 font-bold flex items-center gap-2">
                   <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
                   Balcão (Sem Cadastro)
                </div>
              ) : (
                <select 
                  value={customerId} 
                  onChange={e => setCustomerId(e.target.value)} 
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none"
                >
                  <option value="">Selecione...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              )}
            </div>

            <div className="md:col-span-2">
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Descrição dos Itens</label>
              <input 
                type="text" 
                value={description} 
                onChange={e => setDescription(e.target.value)} 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
                placeholder="Ex: 2 Blusas Crepe, 1 Calça Jeans" 
              />
            </div>

            <div className="space-y-4 md:col-span-3 bg-slate-50/50 p-4 rounded-xl border border-slate-100">
               <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Preço Base (R$)</label>
                    <input 
                      type="number" step="0.01" value={baseAmount || ''} 
                      onChange={e => setBaseAmount(Number(e.target.value))} 
                      className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 font-bold focus:ring-2 focus:ring-indigo-500" 
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Desconto/Promo (R$)</label>
                    <input 
                      type="number" step="0.01" value={discount || ''} 
                      onChange={e => setDiscount(Number(e.target.value))} 
                      className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-rose-600 font-bold focus:ring-2 focus:ring-rose-500" 
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Taxa Cartão (%)</label>
                    <input 
                      type="number" step="0.1" value={cardFeeRate || ''} 
                      onChange={e => setCardFeeRate(Number(e.target.value))} 
                      className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-amber-600 font-bold focus:ring-2 focus:ring-amber-500" 
                      placeholder="0.0"
                    />
                  </div>
                  <div className="flex flex-col justify-end">
                    <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Total Cliente</p>
                    <p className="text-xl font-black text-slate-900">R$ {totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
               </div>

               <div className="flex justify-between items-center pt-3 border-t border-slate-200">
                  <div className="text-[10px] text-slate-400 font-bold uppercase">Resumo Líquido:</div>
                  <div className="text-sm font-bold text-emerald-600">
                    Você recebe: R$ {netAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </div>
               </div>
            </div>

            {mode === 'credit' && (
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Nº Parcelas</label>
                  <input 
                    type="number" min="1" max="24" value={numInstallments} 
                    onChange={e => setNumInstallments(Number(e.target.value))} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Dia Venc.</label>
                  <input 
                    type="number" min="1" max="31" value={dueDay} 
                    onChange={e => setDueDay(Number(e.target.value))} 
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
                  />
                </div>
              </div>
            )}
          </div>
          <div className="flex justify-end pt-2 border-t border-slate-50">
            <button type="submit" className={`px-8 py-3 rounded-xl text-sm font-bold uppercase tracking-widest transition shadow-lg bg-${accentColor}-600 text-white hover:bg-${accentColor}-700`}>
              Confirmar Venda {mode === 'cash' ? 'À Vista' : 'a Prazo'}
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {filteredSales.length === 0 && (
          <div className="bg-white p-12 text-center rounded-2xl border border-dashed border-slate-200 text-slate-400">
            Nenhuma venda {mode === 'cash' ? 'à vista' : 'a prazo'} registrada.
          </div>
        )}
        {filteredSales.map(sale => {
          const isCounterSale = sale.customerId === 'BALCAO';
