import React, { useState, useEffect } from 'react';
import { Sale, Customer, PaymentStatus, Expense } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DashboardProps {
  sales: Sale[];
  customers: Customer[];
  expenses: Expense[];
}

const Dashboard: React.FC<DashboardProps> = ({ sales, customers, expenses }) => {
  const [insights, setInsights] = useState<string>('');
  const [isSyncing, setIsSyncing] = useState(false);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(value);
  };

  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  // Total Receivable (Net amount remaining to be paid)
  // We use the proportion of unpaid installments applied to the netAmount of the sale
  const totalReceivable: number = sales.reduce((acc: number, s) => {
    const totalInst = s.installments.reduce((sum, i) => sum + i.amount, 0);
    const paidInst = s.installments.reduce((sum, i) => sum + i.paidAmount, 0);
    const unpaidRatio = totalInst > 0 ? (totalInst - paidInst) / totalInst : 0;
    return acc + (s.netAmount * unpaidRatio);
  }, 0);

  // Total Received (Net amount actually in pocket)
  const totalReceived: number = sales.reduce((acc: number, s) => {
    const totalInst = s.installments.reduce((sum, i) => sum + i.amount, 0);
    const paidInst = s.installments.reduce((sum, i) => sum + i.paidAmount, 0);
    const paidRatio = totalInst > 0 ? paidInst / totalInst : 0;
    return acc + (s.netAmount * paidRatio);
  }, 0);

  // Current Month Received (Net)
  const currentMonthReceivedNet = sales.reduce((acc, s) => {
    const totalInst = s.installments.reduce((sum, i) => sum + i.amount, 0);
    if (totalInst === 0) return acc;

    const monthPaidAmount = s.installments.reduce((sum, i) => {
      const payDate = i.paidAmount > 0 ? new Date(i.dueDate) : null;
      if (payDate && payDate.getMonth() === currentMonth && payDate.getFullYear() === currentYear) {
        return sum + i.paidAmount;
      }
      return sum;
    }, 0);

    const monthPaidRatio = monthPaidAmount / totalInst;
    return acc + (s.netAmount * monthPaidRatio);
  }, 0);

  // Total Fixed Expenses
  const totalFixedExpenses = expenses.reduce((acc, exp) => acc + exp.amount, 0);

  // Profit Calculation (Current month received net minus fixed expenses)
  const monthlyProfit = currentMonthReceivedNet - totalFixedExpenses;

  const overdueSales = sales.filter(s => 
    s.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date())
  );

  const parseMonthYear = (str: string) => {
    const months: Record<string, number> = {
      'janeiro': 0, 'fevereiro': 1, 'março': 2, 'abril': 3, 'maio': 4, 'junho': 5,
      'julho': 6, 'agosto': 7, 'setembro': 8, 'outubro': 9, 'novembro': 10, 'dezembro': 11
    };
    const [month, year] = str.toLowerCase().split(' de ');
    return new Date(parseInt(year), months[month] || 0).getTime();
  };

  const monthlyReceivedTotals = sales.flatMap(s => {
    const totalInst = s.installments.reduce((sum, i) => sum + i.amount, 0);
    if (totalInst === 0) return [];

    return s.installments
      .filter(i => i.paidAmount > 0)
      .map(i => ({
        amount: (i.paidAmount / totalInst) * s.netAmount,
        date: new Date(i.dueDate)
      }));
  }).reduce((acc, item) => {
    const key = item.date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
    acc[key] = (acc[key] || 0) + item.amount;
    return acc;
  }, {} as Record<string, number>);

  const sortedReceivedMonths = Object.entries(monthlyReceivedTotals)
    .sort((a, b) => parseMonthYear(b[0]) - parseMonthYear(a[0]))
    .slice(0, 6);

  const chartData = [
    { name: 'Recebido Líquido', value: totalReceived, color: '#10b981' },
    { name: 'A Receber Líq.', value: totalReceivable, color: '#6366f1' },
    { name: 'Gastos Fixos', value: totalFixedExpenses, color: '#f43f5e' },
  ];

  const fetchInsights = async (force = false) => {
    if (!force && insights && insights !== 'Carregando insights...') return;
    if (sales.length === 0) {
      setInsights("Registre suas primeiras vendas para ver a análise da IA.");
      return;
    }

    setIsSyncing(true);
    setInsights("Analisando seus dados financeiros...");
    const result = await getFinancialInsights(sales, customers);
    setInsights(result || "Nenhum insight disponível.");
    setIsSyncing(false);
  };

  useEffect(() => {
    if (!insights) {
      fetchInsights();
    }
  }, [sales.length]);

  return (
    <div className="space-y-6">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium uppercase tracking-wider text-[10px] mb-1">A Receber (Líquido)</p>
          <h3 className="text-xl font-bold text-indigo-600">R$ {formatCurrency(totalReceivable)}</h3>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium uppercase tracking-wider text-[10px] mb-1">Entrada Real Mês</p>
          <h3 className="text-xl font-bold text-emerald-600">R$ {formatCurrency(currentMonthReceivedNet)}</h3>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium uppercase tracking-wider text-[10px] mb-1">Despesas Fixas</p>
          <h3 className="text-xl font-bold text-rose-500">R$ {formatCurrency(totalFixedExpenses)}</h3>
        </div>
        <div className={`p-6 rounded-2xl shadow-md border-2 ${monthlyProfit >= 0 ? 'bg-emerald-50 border-emerald-200' : 'bg-rose-50 border-rose-200'}`}>
          <p className="text-slate-500 text-sm font-bold uppercase tracking-wider text-[10px] mb-1">Lucro Real (Mês)</p>
          <h3 className={`text-xl font-black ${monthlyProfit >= 0 ? 'text-emerald-700' : 'text-rose-700'}`}>
            R$ {formatCurrency(monthlyProfit)}
          </h3>
          <p className="text-[9px] text-slate-400 mt-1 uppercase font-bold italic">Base: Líquido - Despesas</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-bold text-slate-800 text-sm uppercase tracking-wider">Entradas Líquidas Recentes</h4>
            <span className="bg-emerald-100 text-emerald-700 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Após Taxas</span>
          </div>
          {sortedReceivedMonths.length > 0 ? (
            <div className="space-y-3">
              {sortedReceivedMonths.map(([month, amount]: [string, number]) => (
                <div key={month} className="flex items-center justify-between p-3 bg-emerald-50/30 rounded-xl border border-emerald-100/50">
                  <p className="text-xs font-bold text-slate-600 capitalize">{month}</p>
                  <p className="text-sm font-bold text-emerald-600">R$ {formatCurrency(amount)}</p>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-slate-400 text-sm text-center py-8">Nenhum valor recebido ainda.</p>
          )}
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-bold text-slate-800 text-sm uppercase tracking-wider">Vendas em Atraso</h4>
            <span className="bg-rose-100 text-rose-700 px-2 py-0.5 rounded text-[10px] font-bold uppercase">Atenção</span>
          </div>
          <div className="text-center py-4">
             <h3 className={`text-5xl font-black ${overdueSales.length > 0 ? 'text-rose-500' : 'text-emerald-500'}`}>{overdueSales.length}</h3>
             <p className="text-xs text-slate-400 mt-2 font-bold uppercase">Parcelas pendentes vencidas</p>
          </div>
          {overdueSales.length > 0 && (
            <div className="mt-4 p-3 bg-rose-50 rounded-xl border border-rose-100">
               <p className="text-[10px] text-rose-800 font-bold leading-tight">Consulte a aba "Agenda Mensal" para identificar os clientes em atraso e realizar a cobrança.</p>
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-80">
          <h4 className="font-semibold text-slate-800 mb-4 uppercase tracking-tighter text-xs">Visão Geral do Capital Líquido</h4>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={10} />
              <YAxis axisLine={false} tickLine={false} fontSize={10} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
              <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className={`p-6 rounded-2xl border flex flex-col h-80 overflow-hidden transition-colors ${insights.includes('⚠️') ? 'bg-amber-50 border-amber-200' : 'bg-indigo-50 border-indigo-100'}`}>
          <div className="flex justify-between items-center mb-4">
            <h4 className={`font-bold flex items-center gap-2 ${insights.includes('⚠️') ? 'text-amber-900' : 'text-indigo-900'}`}>
              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 14.95a1 1 0 010-1.414l.707-.707a1 1 0 011.414 1.414l-.707.707a1 1 0 01-1.414 0zM6.464 14.95l.707-.707a1 1 0 011.414 1.414l-.707.707a1 1 0 01-1.414 0l-.707-.707z" /></svg>
              Análise de Saúde Financeira
            </h4>
            <button 
              onClick={() => fetchInsights(true)}
              disabled={isSyncing}
              className={`text-xs font-semibold px-3 py-1 rounded-full border transition ${insights.includes('⚠️') ? 'border-amber-300 text-amber-700 hover:bg-amber-100' : 'border-indigo-200 text-indigo-600 hover:bg-indigo-100'} disabled:opacity-50`}
            >
              {isSyncing ? 'Analisando...' : 'Atualizar'}
            </button>
          </div>
          <div className={`flex-1 overflow-y-auto text-sm leading-relaxed space-y-3 ${insights.includes('⚠️') ? 'text-amber-800' : 'text-indigo-800'}`}>
             {insights.split('\n').map((line, i) => (
               <p key={i} className={line.startsWith('⚠️') ? 'font-bold' : ''}>{line}</p>
             ))}
          </div>
        </div>
      </div>
    </div>
  );
};

