import React, { useState, useEffect } from 'react';
import { Customer, Sale, PaymentStatus, Installment, Product } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  products: Product[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
  mode: 'cash' | 'credit';
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, products, onAddSale, onUpdateSale, mode }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [isBalcao, setIsBalcao] = useState(false);
  const [productId, setProductId] = useState('');
  const [description, setDescription] = useState('');

  const [baseAmount, setBaseAmount] = useState<number>(0);
  const [discount, setDiscount] = useState<number>(0);
  const [cardFeeRate, setCardFeeRate] = useState<number>(0);
  const [currentProductCost, setCurrentProductCost] = useState<number>(0);

  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [netAmount, setNetAmount] = useState<number>(0);

  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [paymentValue, setPaymentValue] = useState<number>(0);

  // Sync price and cost when product is selected
  useEffect(() => {
    if (productId) {
      const p = products.find(prod => prod.id === productId);
      if (p) {
        setBaseAmount(p.price);
        setDescription(`${p.sku} - ${p.name}`);
        setCurrentProductCost(p.costPrice);
      }
    } else {
      setCurrentProductCost(0);
    }
  }, [productId, products]);

  useEffect(() => {
    const calculatedTotal = Math.max(0, baseAmount - discount);
    const feeAmount = (calculatedTotal * cardFeeRate) / 100;
    const calculatedNet = calculatedTotal - feeAmount;

    setTotalAmount(calculatedTotal);
    setNetAmount(calculatedNet);
  }, [baseAmount, discount, cardFeeRate]);

  const filteredSales = sales.filter(s => (s.type || 'credit') === mode);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    const finalCustomerId = isBalcao ? 'BALCAO' : customerId;

    if (!finalCustomerId || !description || totalAmount <= 0) {
      alert("Por favor, preencha todos os campos obrigatórios.");
      return;
    }

    if (productId) {
      const p = products.find(prod => prod.id === productId);
      if (p && p.stock <= 0) {
        if (!window.confirm("Produto sem estoque! Deseja continuar com a venda mesmo assim?")) return;
      }
    }

    const installments: Installment[] = [];
    const today = new Date();
    const cardFeeAmount = (totalAmount * cardFeeRate) / 100;

    if (mode === 'cash') {
      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: totalAmount,
        paidAmount: totalAmount,
        dueDate: today.toISOString().split('T')[0],
        status: PaymentStatus.PAID
      });
    } else {
      const installmentAmount = totalAmount / numInstallments;
      for (let i = 1; i <= numInstallments; i++) {
        const dueDate = calculateDueDate(today, i, dueDay);
        installments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: '', 
          amount: installmentAmount,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onAddSale({
      customerId: finalCustomerId,
      productId: productId || undefined,
      description,
      baseAmount,
      discount,
      totalAmount,
      cardFeeRate,
      cardFeeAmount,
      netAmount,
      totalCost: currentProductCost, // Salva o custo atual para cálculo de lucro
      date: today.toISOString().split('T')[0],
      installments,
      status: mode === 'cash' ? PaymentStatus.PAID : PaymentStatus.PENDING,
      type: mode
    });

    setShowAdd(false);
    resetForm();
  };

  const calculateDueDate = (baseDate: Date, monthsToAdd: number, targetDay: number) => {
    let targetMonth = baseDate.getMonth() + monthsToAdd;
    let targetYear = baseDate.getFullYear();
    while (targetMonth > 11) { targetMonth -= 12; targetYear += 1; }
    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const resetForm = () => {
    setCustomerId('');
    setIsBalcao(false);
    setProductId('');
    setDescription('');
    setBaseAmount(0);
    setDiscount(0);
    setCardFeeRate(0);
    setCurrentProductCost(0);
    setNumInstallments(1);
    setDueDay(new Date().getDate());
  };

  const handleAbatePayment = (sale: Sale, installmentId: string) => {
    if (paymentValue <= 0) return;
    const newInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const remainingToPay = inst.amount - inst.paidAmount;
        const actualPayment = Math.min(paymentValue, remainingToPay);
        const newPaidAmount = inst.paidAmount + actualPayment;
        return {
          ...inst,
          paidAmount: newPaidAmount,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });
    const updatedSale = {
      ...sale,
      installments: newInstallments,
      status: calculateSaleStatus(newInstallments)
    };
    onUpdateSale(updatedSale);
    setSelectedSale(updatedSale);
    setPaymentValue(0);
  };

  const calculateSaleStatus = (installments: Installment[]) => {
    const allPaid = installments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = installments.some(i => i.status !== PaymentStatus.PENDING);
    return allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING);
  };

  const accentColor = mode === 'cash' ? 'emerald' : 'indigo';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800">{mode === 'cash' ? 'Venda À Vista' : 'Venda a Prazo'}</h2>
          <p className="text-xs text-slate-500 uppercase tracking-widest font-bold">Lançamento de {mode === 'cash' ? 'entrada imediata' : 'parcelamentos'}</p>
        </div>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className={`bg-${accentColor}-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-${accentColor}-700 transition shadow-sm`}
        >
          {showAdd ? 'Cancelar' : 'Nova Venda'}
        </button>
      </div>

      {showAdd && (
        <form onSubmit={handleAddSale} className={`bg-white p-6 rounded-2xl shadow-sm border border-${accentColor}-100 space-y-6 animate-in fade-in zoom-in duration-200`}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="md:col-span-1">
              <div className="flex justify-between items-center mb-1">
                <label className="block text-[10px] font-bold text-slate-400 uppercase">Cliente</label>
                <button type="button" onClick={() => setIsBalcao(!isBalcao)} className={`text-[10px] font-bold px-2 py-0.5 rounded transition ${isBalcao ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-500'}`}>
                  {isBalcao ? '✓ Venda Balcão' : 'Venda Balcão?'}
                </button>
              </div>
              {isBalcao ? (
                <div className="w-full bg-amber-50 border border-amber-200 rounded-lg px-3 py-2 text-sm text-amber-700 font-bold">🛒 Cliente Balcão</div>
              ) : (
                <select value={customerId} onChange={e => setCustomerId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none">
                  <option value="">Selecione o Cliente...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              )}
            </div>

            <div className="md:col-span-1">
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Produto (SKU - Nome)</label>
              <select value={productId} onChange={e => setProductId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none font-medium">
                  <option value="">-- Venda Avulsa / Sem Código --</option>
                  {products.map(p => <option key={p.id} value={p.id}>{p.sku} - {p.name} (Qtd: {p.stock})</option>)}
              </select>
            </div>

            <div className="md:col-span-1">
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Descrição do Item</label>
              <input type="text" value={description} onChange={e => setDescription(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Ex: Camiseta Básica P" />
            </div>

            <div className="space-y-4 md:col-span-3 bg-slate-50/50 p-4 rounded-xl border border-slate-100">
               <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Preço Venda (R$)</label>
                    <input type="number" step="0.01" value={baseAmount || ''} onChange={e => setBaseAmount(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Desconto (R$)</label>
                    <input type="number" step="0.01" value={discount || ''} onChange={e => setDiscount(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-rose-600 font-bold" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Taxa Cartão (%)</label>
                    <input type="number" step="0.1" value={cardFeeRate || ''} onChange={e => setCardFeeRate(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-amber-600 font-bold" />
                  </div>
                  <div className="flex flex-col justify-end">
                    <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Total Cliente</p>
                    <p className="text-xl font-black text-slate-900">R$ {totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-3 border-t border-slate-200">
                  <div className="text-xs text-slate-500 font-medium">
                     Custo Unitário Registrado: <span className="text-rose-600 font-bold">R$ {currentProductCost.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                  </div>
                  <div className="text-right text-emerald-600 font-bold text-sm">
                    Líquido Real: R$ {netAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </div>
               </div>
            </div>

            {mode === 'credit' && (
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Parcelas</label>
                  <input type="number" min="1" max="24" value={numInstallments} onChange={e => setNumInstallments(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Dia Venc.</label>
                  <input type="number" min="1" max="31" value={dueDay} onChange={e => setDueDay(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                </div>
              </div>
            )}
          </div>
          <div className="flex justify-end pt-2 border-t border-slate-50">
            <button type="submit" className={`px-8 py-3 rounded-xl text-sm font-bold uppercase tracking-widest transition shadow-lg bg-${accentColor}-600 text-white hover:bg-${accentColor}-700`}>
              Confirmar Venda {mode === 'cash' ? 'À Vista' : 'a Prazo'}
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {filteredSales.map(sale => {
           const saleProfit = sale.netAmount - sale.totalCost;
           return (
            <div key={sale.id} className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
               <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                  <div className="flex items-start gap-3">
                    <div className={`mt-1 p-2 rounded-lg ${sale.customerId === 'BALCAO' ? 'bg-amber-100 text-amber-600' : mode === 'cash' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
                      </svg>
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-800">{customers.find(c => c.id === sale.customerId)?.name || '🛒 Cliente Balcão'}</h3>
                      <p className="text-sm text-slate-500">{sale.description}</p>
                      <div className="flex gap-3 mt-1">
                        <span className="text-[10px] font-bold uppercase text-slate-400">{new Date(sale.date).toLocaleDateString('pt-BR')}</span>
                        <span className="text-[10px] font-bold uppercase text-emerald-600">Lucro: R$ {saleProfit.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 ml-auto">
                    <div className="text-right">
                      <p className="text-lg font-black text-slate-900">R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                      <span className={`text-[10px] font-bold uppercase px-2 py-0.5 rounded ${sale.status === PaymentStatus.PAID ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>{sale.status}</span>
                    </div>
                    <button onClick={() => setSelectedSale(selectedSale?.id === sale.id ? null : sale)} className="p-2 text-slate-400 hover:text-indigo-600">
                       <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                    </button>
                  </div>
               </div>

               {selectedSale?.id === sale.id && (
                  <div className="px-5 pb-5 pt-2 border-t border-slate-50 bg-slate-50/30 animate-in slide-in-from-top-1 duration-200">
                     <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-center">
                        <div className="bg-white p-2 rounded-lg border border-slate-100">
                           <p className="text-[9px] font-bold text-slate-400 uppercase">Preço Venda</p>
                           <p className="text-xs font-bold">R$ {sale.baseAmount.toFixed(2)}</p>
                        </div>
                        <div className="bg-white p-2 rounded-lg border border-slate-100">
                           <p className="text-[9px] font-bold text-slate-400 uppercase">Líquido (pós taxas)</p>
                           <p className="text-xs font-bold">R$ {sale.netAmount.toFixed(2)}</p>
                        </div>
                        <div className="bg-white p-2 rounded-lg border border-slate-100">
                           <p className="text-[9px] font-bold text-rose-400 uppercase">Custo Produto</p>
                           <p className="text-xs font-bold text-rose-600">R$ {sale.totalCost.toFixed(2)}</p>
                        </div>
                        <div className="bg-emerald-50 p-2 rounded-lg border border-emerald-100">
                           <p className="text-[9px] font-bold text-emerald-600 uppercase">Lucro da Venda</p>
                           <p className="text-xs font-black text-emerald-700">R$ {saleProfit.toFixed(2)}</p>
                        </div>
                     </div>
                  </div>
               )}
            </div>
           );
        })}
      </div>
    </div>
  );
};

export default SalesManager;

import React, { useState, useEffect } from 'react';
import { Sale, Customer, PaymentStatus, Expense } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DashboardProps {
  sales: Sale[];
  customers: Customer[];
  expenses: Expense[];
}

const Dashboard: React.FC<DashboardProps> = ({ sales, customers, expenses }) => {
  const [insights, setInsights] = useState<string>('');
  const [isSyncing, setIsSyncing] = useState(false);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(value);
  };

  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  // Total Fixed Expenses (Applied every month)
  const totalFixedExpenses = expenses.reduce((acc, exp) => acc + exp.amount, 0);

  // Helper to calculate financials for a specific month/year
  const getFinancialsForMonth = (month: number, year: number) => {
    return sales.reduce((acc, s) => {
      const saleDate = new Date(s.date);
      // Faturamento e custo são registrados na data da venda para fins de lucro bruto sobre produtos
      if (saleDate.getMonth() === month && saleDate.getFullYear() === year) {
        acc.netRevenue += s.netAmount;
        acc.totalCostOfGoods += s.totalCost;
      }

      // Entradas efetivas (parcelas pagas no mês)
      const totalInst = s.installments.reduce((sum, i) => sum + i.amount, 0);
      if (totalInst > 0) {
        const monthPaidAmount = s.installments.reduce((sum, i) => {
          const payDate = i.paidAmount > 0 ? new Date(i.dueDate) : null;
          if (payDate && payDate.getMonth() === month && payDate.getFullYear() === year) {
            return sum + i.paidAmount;
          }
          return sum;
        }, 0);

        const monthPaidRatio = monthPaidAmount / totalInst;
        acc.actualCashInflow += (s.netAmount * monthPaidRatio);
      }

      return acc;
    }, { netRevenue: 0, totalCostOfGoods: 0, actualCashInflow: 0 });
  };

  const currentMonthFinancials = getFinancialsForMonth(currentMonth, currentYear);

  // Lucro Bruto sobre Produtos (Faturamento Líquido - Custo dos Produtos)
  const productProfit = currentMonthFinancials.netRevenue - currentMonthFinancials.totalCostOfGoods;

  // Lucro Real Mensal (Lucro sobre Produtos - Despesas Fixas)
  const monthlyRealProfit = productProfit - totalFixedExpenses;

  // History calculation (last 6 months)
  const historyData = Array.from({ length: 6 }).map((_, i) => {
    const d = new Date();
    d.setMonth(d.getMonth() - (5 - i));
    const m = d.getMonth();
    const y = d.getFullYear();
    const financials = getFinancialsForMonth(m, y);
    const profit = (financials.netRevenue - financials.totalCostOfGoods) - totalFixedExpenses;
    return {
      name: d.toLocaleString('pt-BR', { month: 'short' }).toUpperCase(),
      Faturamento: financials.netRevenue,
      Lucro: profit,
      fullName: d.toLocaleString('pt-BR', { month: 'long', year: 'numeric' })
    };
  });

  const totalReceivable: number = sales.reduce((acc: number, s) => {
    const totalInst = s.installments.reduce((sum, i) => sum + i.amount, 0);
    const paidInst = s.installments.reduce((sum, i) => sum + i.paidAmount, 0);
    const unpaidRatio = totalInst > 0 ? (totalInst - paidInst) / totalInst : 0;
    return acc + (s.netAmount * unpaidRatio);
  }, 0);

  const overdueSalesCount = sales.filter(s => 
    s.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date())
  ).length;

  const fetchInsights = async (force = false) => {
    if (!force && insights && insights !== 'Carregando insights...') return;
    if (sales.length === 0) {
      setInsights("Registre suas primeiras vendas para ver a análise da IA.");
      return;
    }

    setIsSyncing(true);
    setInsights("Analisando seus dados financeiros...");
    const result = await getFinancialInsights(sales, customers);
    setInsights(result || "Nenhum insight disponível.");
    setIsSyncing(false);
  };

  useEffect(() => {
    if (!insights) {
      fetchInsights();
    }
  }, [sales.length]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Painel de Lucratividade</h2>
          <p className="text-sm text-slate-500 font-medium">Análise de margem, custos e performance mensal.</p>
        </div>
        <div className="flex gap-2">
           <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 text-[10px] font-bold text-slate-400 uppercase">
             Referência: <span className="text-indigo-600">{new Date().toLocaleString('pt-BR', { month: 'long', year: 'numeric' })}</span>
           </div>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden">
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-wider mb-1">Faturamento Líquido (Mês)</p>
          <h3 className="text-2xl font-black text-slate-800">{formatCurrency(currentMonthFinancials.netRevenue)}</h3>
          <p className="text-[9px] text-slate-400 mt-1 font-bold uppercase italic">Vendas confirmadas no mês</p>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative overflow-hidden">
          <p className="text-rose-400 text-[10px] font-bold uppercase tracking-wider mb-1">Custo + Despesas (Mês)</p>
          <h3 className="text-2xl font-black text-rose-500">{formatCurrency(currentMonthFinancials.totalCostOfGoods + totalFixedExpenses)}</h3>
          <p className="text-[9px] text-slate-400 mt-1 font-bold uppercase italic">Custo Produtos + Gastos Fixos</p>
        </div>

        <div className={`p-6 rounded-2xl shadow-md border-2 relative overflow-hidden ${monthlyRealProfit >= 0 ? 'bg-emerald-50 border-emerald-200' : 'bg-rose-50 border-rose-200'}`}>
          <div className="absolute top-0 right-0 p-2 opacity-10">
            <svg className="w-16 h-16" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M12 7a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0V8.414l-4.293 4.293a1 1 0 01-1.414 0L8 10.414l-4.293 4.293a1 1 0 01-1.414-1.414l5-5a1 1 0 011.414 0L11 10.586 14.586 7H12z" clipRule="evenodd" /></svg>
          </div>
          <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mb-1">Lucro Bruto Real (Mês)</p>
          <h3 className={`text-2xl font-black ${monthlyRealProfit >= 0 ? 'text-emerald-700' : 'text-rose-700'}`}>
            {formatCurrency(monthlyRealProfit)}
          </h3>
          <p className="text-[9px] text-slate-400 mt-1 font-black uppercase italic">Saldo final pós todos os custos</p>
        </div>

        <div className="bg-indigo-900 p-6 rounded-2xl shadow-lg border border-indigo-800 text-white relative overflow-hidden">
          <p className="text-indigo-200 text-[10px] font-bold uppercase tracking-wider mb-1">Capital a Receber</p>
          <h3 className="text-2xl font-black">{formatCurrency(totalReceivable)}</h3>
          <p className="text-[9px] text-indigo-300 mt-1 font-bold uppercase italic">Total em parcelas abertas</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Comparison Chart */}
        <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex justify-between items-center mb-8">
            <h4 className="font-bold text-slate-800 text-xs uppercase tracking-widest">Evolução de Lucratividade</h4>
            <div className="flex gap-4">
               <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-indigo-500"></span><span className="text-[10px] font-bold text-slate-400 uppercase">Faturamento</span></div>
               <div className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-emerald-500"></span><span className="text-[10px] font-bold text-slate-400 uppercase">Lucro</span></div>
            </div>
          </div>
          <div className="h-72">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={historyData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={10} fontWeight="bold" dy={10} />
                <YAxis axisLine={false} tickLine={false} fontSize={10} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}} 
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)', padding: '12px' }}
                  formatter={(value: number) => [formatCurrency(value), '']}
                />
                <Bar dataKey="Faturamento" fill="#6366f1" radius={[6, 6, 0, 0]} barSize={24} />
                <Bar dataKey="Lucro" fill="#10b981" radius={[6, 6, 0, 0]} barSize={24} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Financial Summary & AI */}
        <div className="space-y-6">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
             <h4 className="font-bold text-slate-800 text-xs uppercase tracking-widest mb-4">Resumo da Saúde</h4>
             <div className="space-y-4">
                <div className="flex justify-between items-center pb-2 border-b border-slate-50">
                   <span className="text-[10px] font-bold text-slate-400 uppercase">Margem Bruta (Mês)</span>
                   <span className="text-xs font-black text-slate-800">
                      {currentMonthFinancials.netRevenue > 0 
                        ? ((productProfit / currentMonthFinancials.netRevenue) * 100).toFixed(1) + '%' 
                        : '0%'}
                   </span>
                </div>
                <div className="flex justify-between items-center pb-2 border-b border-slate-50">
                   <span className="text-[10px] font-bold text-slate-400 uppercase">Custo Médio Mercadoria</span>
                   <span className="text-xs font-black text-rose-500">{formatCurrency(currentMonthFinancials.totalCostOfGoods)}</span>
                </div>
                <div className="flex justify-between items-center">
                   <span className="text-[10px] font-bold text-slate-400 uppercase">Clientes em Atraso</span>
                   <span className={`text-xs font-black ${overdueSalesCount > 0 ? 'text-rose-500' : 'text-emerald-500'}`}>{overdueSalesCount}</span>
                </div>
             </div>
          </div>

          <div className={`p-6 rounded-2xl border-2 flex flex-col transition-all shadow-sm ${insights.includes('⚠️') ? 'bg-amber-50 border-amber-100' : 'bg-indigo-50 border-indigo-100'}`}>
            <div className="flex justify-between items-center mb-4">
              <h4 className={`font-black text-[10px] uppercase tracking-[0.2em] flex items-center gap-2 ${insights.includes('⚠️') ? 'text-amber-900' : 'text-indigo-900'}`}>
                IA Insight
              </h4>
              <button onClick={() => fetchInsights(true)} disabled={isSyncing} className="text-[10px] font-black uppercase text-indigo-600">Atualizar</button>
            </div>
            <div className={`text-xs leading-relaxed font-medium italic ${insights.includes('⚠️') ? 'text-amber-800' : 'text-indigo-800'}`}>
               "{insights}"
            </div>
          </div>
        </div>
      </div>

      {/* Historical Detailed List */}
      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
          <div>
            <h4 className="font-black text-slate-800 text-xs uppercase tracking-widest">Histórico de Fechamento</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Comparativo de faturamento real vs lucro bruto</p>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase border-b border-slate-100">
              <tr>
                <th className="px-8 py-5">Período</th>
                <th className="px-8 py-5 text-right">Faturamento Líquido</th>
                <th className="px-8 py-5 text-right">Custo Mercadoria</th>
                <th className="px-8 py-5 text-right">Lucro Bruto (Real)</th>
                <th className="px-8 py-5 text-center">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {[...historyData].reverse().map((month, idx) => (
                <tr key={idx} className={`hover:bg-slate-50 transition-colors ${idx === 0 ? 'bg-indigo-50/20' : ''}`}>
                  <td className="px-8 py-5 font-bold text-slate-800 capitalize text-sm">{month.fullName}</td>
                  <td className="px-8 py-5 text-right text-indigo-600 font-bold text-sm">{formatCurrency(month.Faturamento)}</td>
                  <td className="px-8 py-5 text-right text-rose-500 text-sm font-medium">{formatCurrency(totalFixedExpenses)} (Fixas)</td>
                  <td className={`px-8 py-5 text-right font-black text-sm ${month.Lucro >= 0 ? 'text-emerald-700' : 'text-rose-700'}`}>
                    {formatCurrency(month.Lucro)}
                  </td>
                  <td className="px-8 py-5 text-center">
                    <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-wider ${month.Lucro >= 0 ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                      {month.Lucro >= 0 ? 'Positivo' : 'Negativo'}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Product, Sale, PaymentStatus, Installment } from '../types';

interface InventoryManagerProps {
  products: Product[];
  onAdd: (product: Omit<Product, 'id'>) => void;
  onDelete: (id: string) => void;
  onUpdate: (product: Product) => void;
  // Added optional prop to trigger bulk import from App.tsx
