      </div>
    </div>
  );
};

export default InventoryManager;

import React, { useState, useEffect, useCallback } from 'react';
import { View, Customer, Sale, User, Expense, Product } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';
import Agenda from './components/Agenda';
import Settings from './components/Settings';
import Landing from './components/Landing';
import Tutorial from './components/Tutorial';
import ExpenseManager from './components/ExpenseManager';
import InventoryManager from './components/InventoryManager';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const syncWithOneDrive = useCallback(async (action: 'upload' | 'download') => {
    if (!user || user.authProvider !== 'onedrive') return;
    setSyncStatus('syncing');
    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      const storageKey = `gestao93_cloud_master_${user.id}`;
      if (action === 'download') {
        const cloudData = localStorage.getItem(storageKey);
        if (cloudData) {
          const parsed = JSON.parse(cloudData);
          setCustomers(parsed.customers || []);
          setSales(parsed.sales || []);
          setExpenses(parsed.expenses || []);
          setProducts(parsed.products || []);
        }
      } else {
        const localUsers = JSON.parse(localStorage.getItem('gestao93_users') || '[]');
        const dataToUpload = JSON.stringify({ 
          customers, 
          sales, 
          expenses,
          products,
          users: localUsers,
          lastSync: new Date().toISOString()
        });
        localStorage.setItem(storageKey, dataToUpload);
      }
      setSyncStatus('synced');
    } catch (err) {
      setSyncStatus('error');
    }
  }, [user, customers, sales, expenses, products]);

  useEffect(() => {
    const savedUser = localStorage.getItem('gestao93_current_user');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      checkTutorialStatus(parsedUser.id);
      if (parsedUser.authProvider === 'onedrive') {
        syncWithOneDrive('download');
      } else {
        const localCustomers = localStorage.getItem(`gestao93_customers_${parsedUser.id}`);
        const localSales = localStorage.getItem(`gestao93_sales_${parsedUser.id}`);
        const localExpenses = localStorage.getItem(`gestao93_expenses_${parsedUser.id}`);
        const localProducts = localStorage.getItem(`gestao93_products_${parsedUser.id}`);
        if (localCustomers) setCustomers(JSON.parse(localCustomers));
        if (localSales) setSales(JSON.parse(localSales));
        if (localExpenses) setExpenses(JSON.parse(localExpenses));
        if (localProducts) setProducts(JSON.parse(localProducts));
      }
    }
    setLoading(false);
  }, []);

  const checkTutorialStatus = (userId: string) => {
    const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
    if (!tutorialSeen) setShowTutorial(true);
  };

  const handleFinishTutorial = () => {
    if (user) localStorage.setItem(`gestao93_tutorial_seen_${user.id}`, 'true');
    setShowTutorial(false);
  };

  useEffect(() => {
    if (!loading && user) {
      setSyncStatus('syncing');
      const timer = setTimeout(() => {
        if (user.authProvider === 'onedrive') {
          syncWithOneDrive('upload');
        } else {
          localStorage.setItem(`gestao93_customers_${user.id}`, JSON.stringify(customers));
          localStorage.setItem(`gestao93_sales_${user.id}`, JSON.stringify(sales));
          localStorage.setItem(`gestao93_expenses_${user.id}`, JSON.stringify(expenses));
          localStorage.setItem(`gestao93_products_${user.id}`, JSON.stringify(products));
          setSyncStatus('synced');
        }
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [customers, sales, expenses, products, user, loading, syncWithOneDrive]);

  const handleLogin = (userData: User) => {
    setUser(userData);
    checkTutorialStatus(userData.id);
  };

  const handleLogout = () => {
    setUser(null);
    setCustomers([]);
    setSales([]);
    setExpenses([]);
    setProducts([]);
    localStorage.removeItem('gestao93_current_user');
    setActiveView('dashboard');
    setShowTutorial(false);
  };

  const handleUpdateProfile = (updatedUser: User) => {
    setUser(updatedUser);
    localStorage.setItem('gestao93_current_user', JSON.stringify(updatedUser));
    const savedUsers = JSON.parse(localStorage.getItem('gestao93_users') || '[]');
    const updatedUsers = savedUsers.map((u: User) => u.id === updatedUser.id ? updatedUser : u);
    localStorage.setItem('gestao93_users', JSON.stringify(updatedUsers));
  };

  const addCustomer = (data: Omit<Customer, 'id' | 'createdAt'>) => {
    const newCustomer: Customer = {
      ...data,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now()
    };
    setCustomers(prev => [newCustomer, ...prev]);
  };

  const deleteCustomer = (id: string) => {
    if (window.confirm('Excluir este cliente e todo seu histórico?')) {
      setCustomers(prev => prev.filter(c => c.id !== id));
    }
  };

  const addSale = (saleData: Omit<Sale, 'id'>) => {
    const newSale: Sale = { ...saleData, id: Math.random().toString(36).substr(2, 9) };
    setSales(prev => [newSale, ...prev]);

    // Baixa automática de estoque
    if (saleData.productId) {
      setProducts(prev => prev.map(p => 
        p.id === saleData.productId ? { ...p, stock: Math.max(0, p.stock - 1) } : p
      ));
    }
  };

  const updateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  const handleAddExpense = (description: string, amount: number) => {
    const newExpense: Expense = { id: Math.random().toString(36).substr(2, 9), description, amount };
    setExpenses(prev => [...prev, newExpense]);
  };

  const handleDeleteExpense = (id: string) => {
    setExpenses(prev => prev.filter(e => e.id !== id));
  };

  // Inventário Actions
  const handleAddProduct = (p: Omit<Product, 'id'>) => {
    const newProduct: Product = { ...p, id: Math.random().toString(36).substr(2, 9) };
    setProducts(prev => [...prev, newProduct]);
  };

  const handleDeleteProduct = (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
  };

  const handleUpdateProduct = (p: Product) => {
    setProducts(prev => prev.map(prod => prod.id === p.id ? p : prod));
  };

  const handleBulkImport = (data: { products: Product[], sales: Sale[] }) => {
    setProducts(prev => {
        const existingSkus = new Set(prev.map(p => p.sku));
        const filteredNew = data.products.filter(p => !existingSkus.has(p.sku));
        return [...prev, ...filteredNew];
    });
    setSales(prev => [...prev, ...data.sales]);
  };

  if (loading) return null;
  if (!user) return <Landing onLogin={handleLogin} />;

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50">
      {showTutorial && <Tutorial activeView={activeView} onClose={handleFinishTutorial} />}

      {/* Sync Status Indicator */}
      <div className={`fixed top-0 left-0 right-0 z-[200] h-1.5 transition-all duration-500 ${syncStatus === 'syncing' ? 'bg-amber-400 opacity-100' : 'bg-emerald-500 opacity-100'}`}>
         {syncStatus === 'synced' && (
           <div className="absolute top-2 right-4 bg-emerald-500 text-white text-[10px] font-bold px-2 py-0.5 rounded shadow-lg animate-fade-out pointer-events-none uppercase tracking-tighter">
             Informações Salvas
           </div>
         )}
      </div>

      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col p-6 sticky top-0 md:h-screen z-[100] border-r border-indigo-900 shadow-2xl">
        <div className="flex items-center gap-3 mb-8">
          <div className="w-10 h-10 bg-indigo-600 rounded-lg shadow-lg flex items-center justify-center overflow-hidden border border-white/20">
            {user.avatarUrl ? (
