                return (
                  <tr key={p.id} className="hover:bg-slate-50 transition group">
                    <td className="px-6 py-4">
                      <div className="inline-block bg-slate-100 text-slate-600 text-[10px] font-black px-2 py-0.5 rounded mb-1 uppercase">{p.sku}</div>
                      <div className="font-bold text-slate-800">{p.name}</div>
                      <div className="text-[10px] text-indigo-500 font-medium">{p.category}</div>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <span className="text-xs text-rose-500 font-medium">{formatCurrency(p.costPrice)}</span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <span className="text-sm font-black text-slate-800">{formatCurrency(p.price)}</span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <span className="text-xs font-black text-emerald-600">+{formatCurrency(unitProfit)}</span>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className={`inline-flex items-center justify-center px-3 py-1 rounded-lg ${p.stock <= p.minStock ? 'bg-rose-100 text-rose-700' : 'bg-emerald-100 text-emerald-700'}`}>
                         <span className="text-sm font-black">{p.stock}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex justify-center gap-2">
                         <button onClick={() => {
                            const newQty = prompt("Nova quantidade em estoque:", p.stock.toString());
                            if (newQty !== null) onUpdate({ ...p, stock: Number(newQty) });
                         }} className="p-2 text-indigo-400 hover:text-indigo-600 transition"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg></button>
                         <button onClick={() => { if (window.confirm('Excluir este produto?')) onDelete(p.id); }} className="p-2 text-slate-300 hover:text-rose-600 transition"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {products.length === 0 && (
                <tr><td colSpan={6} className="px-6 py-12 text-center text-slate-400">Nenhum produto cadastrado no estoque.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default InventoryManager;

import React, { useState, useEffect, useLayoutEffect, useCallback } from 'react';

interface TutorialProps {
  onClose: () => void;
  activeView: string;
}

interface Step {
  id: string;
  targetId: string;
  title: string;
  content: string;
}

const Tutorial: React.FC<TutorialProps> = ({ onClose, activeView }) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [coords, setCoords] = useState<{ top: number, left: number, width: number, height: number } | null>(null);

  const steps: Step[] = [
    {
      id: 'step-dashboard',
      targetId: 'nav-dashboard',
      title: 'Bem-vindo ao Gestão 93!',
      content: 'Este é o seu painel principal. Aqui você verá o lucro real das suas vendas, faturamento e insights da nossa Inteligência Artificial.',
    },
    {
      id: 'step-inventory',
      targetId: 'nav-inventory',
      title: 'Passo 1: Seu Estoque',
      content: 'Antes de vender, cadastre seus produtos aqui. É fundamental informar o Preço de Custo e o Preço de Venda para o sistema calcular seu lucro automaticamente.',
    },
    {
      id: 'step-customers',
      targetId: 'nav-customers',
      title: 'Passo 2: Clientes',
      content: 'Cadastre suas clientes para gerenciar quem está devendo e o histórico de compras de cada uma.',
    },
    {
      id: 'step-sales',
      targetId: 'nav-sales-credit',
      title: 'Passo 3: Vendas a Prazo',
      content: 'Vendeu no "fiado" ou parcelado? Lance aqui! O sistema gera as parcelas e te avisa no dia do vencimento.',
    },
    {
      id: 'step-agenda',
      targetId: 'nav-agenda',
      title: 'Passo 4: Agenda de Recebimento',
      content: 'Consulte mês a mês quanto você tem para receber. O dinheiro que está "na rua" fica organizado aqui.',
    },
    {
        id: 'step-expenses',
        targetId: 'nav-expenses',
        title: 'Passo 5: Despesas Fixas',
        content: 'Lance seus custos fixos (Aluguel, MEI, Luz) para que o lucro do Dashboard seja o valor real que sobra no seu bolso.',
    }
  ];

  const updateCoords = useCallback(() => {
    const step = steps[currentStep];
    if (!step) return;

    const element = document.getElementById(step.targetId);
    if (element) {
      const rect = element.getBoundingClientRect();
      // Only set if element has actual dimensions and is visible
      if (rect.width > 0 && rect.height > 0) {
        setCoords({ 
            top: rect.top, 
            left: rect.left, 
            width: rect.width, 
            height: rect.height 
        });
        return;
      }
    }
    setCoords(null);
  }, [currentStep]);

  // Use both effects to ensure we catch the element after render and on step change
  useLayoutEffect(() => {
    // Small delay to ensure DOM is fully ready and reflowed
    const timer = setTimeout(updateCoords, 100);
    window.addEventListener('resize', updateCoords);
    window.addEventListener('scroll', updateCoords, true);

    return () => {
        clearTimeout(timer);
        window.removeEventListener('resize', updateCoords);
        window.removeEventListener('scroll', updateCoords, true);
    };
  }, [currentStep, updateCoords, activeView]);

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      onClose();
    }
  };

  const currentStepData = steps[currentStep];
  if (!currentStepData) return null;

  return (
    <div className="fixed inset-0 z-[9999] pointer-events-none overflow-hidden">
      {/* Overlay with spotlight hole */}
      <div 
        className="absolute inset-0 bg-slate-950/80 pointer-events-auto transition-all duration-300"
        style={{ 
            clipPath: coords 
                ? `polygon(0% 0%, 0% 100%, ${coords.left}px 100%, ${coords.left}px ${coords.top}px, ${coords.left + coords.width}px ${coords.top}px, ${coords.left + coords.width}px ${coords.top + coords.height}px, ${coords.left}px ${coords.top + coords.height}px, ${coords.left}px 100%, 100% 100%, 100% 0%)` 
                : 'none' 
        }}
      />

      {/* Pulsing highlight border */}
      {coords && (
        <div className="absolute border-2 border-indigo-400 rounded-lg shadow-[0_0_30px_rgba(129,140,248,0.6)] animate-pulse"
          style={{ 
              top: coords.top - 4, 
              left: coords.left - 4, 
              width: coords.width + 8, 
              height: coords.height + 8,
              transition: 'all 0.3s ease-out'
          }}
        />
      )}

      {/* Tooltip Box */}
      <div className="absolute pointer-events-auto transition-all duration-500 ease-out z-[10000]"
        style={{ 
            top: coords 
                ? (coords.top + coords.height + 20 > window.innerHeight - 240 ? coords.top - 240 : coords.top + coords.height + 20) 
                : '50%', 
            left: coords 
                ? Math.min(Math.max(20, coords.left), window.innerWidth - 340) 
                : '50%', 
            transform: coords ? 'none' : 'translate(-50%, -50%)', 
            width: '320px' 
        }}
      >
        <div className="bg-white rounded-3xl shadow-2xl p-6 border border-indigo-100 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1.5 bg-indigo-600"></div>

          <div className="flex justify-between items-start mb-4">
            <span className="text-[10px] font-black text-indigo-600 uppercase bg-indigo-50 px-2 py-1 rounded-lg tracking-widest">
                Dica {currentStep + 1} de {steps.length}
            </span>
            <button onClick={onClose} className="text-slate-300 hover:text-rose-500 transition-colors">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>

          <h4 className="text-xl font-black text-slate-800 mb-2 italic uppercase tracking-tight leading-tight">
            {currentStepData.title}
          </h4>

          <p className="text-sm text-slate-500 leading-relaxed mb-8 font-medium">
            {currentStepData.content}
          </p>

          <div className="flex items-center justify-between">
             <button 
                onClick={() => currentStep > 0 && setCurrentStep(currentStep - 1)} 
                disabled={currentStep === 0} 
                className="text-xs font-black text-slate-400 uppercase tracking-widest disabled:opacity-0 transition hover:text-indigo-600"
             >
                Anterior
             </button>
             <button 
                onClick={handleNext} 
                className="bg-indigo-600 text-white px-8 py-3 rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all active:scale-95"
             >
                {currentStep === steps.length - 1 ? 'Finalizar' : 'Entendido'}
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Tutorial;

import React, { useState, useEffect, useCallback } from 'react';
import { View, Customer, Sale, User, Expense, Product } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';
import Agenda from './components/Agenda';
import Settings from './components/Settings';
import Landing from './components/Landing';
import Tutorial from './components/Tutorial';
import ExpenseManager from './components/ExpenseManager';
import InventoryManager from './components/InventoryManager';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const syncWithOneDrive = useCallback(async (action: 'upload' | 'download') => {
    if (!user || user.authProvider !== 'onedrive') return;
    setSyncStatus('syncing');
    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      const storageKey = `gestao93_cloud_master_${user.id}`;
      if (action === 'download') {
        const cloudData = localStorage.getItem(storageKey);
        if (cloudData) {
          const parsed = JSON.parse(cloudData);
          setCustomers(parsed.customers || []);
          setSales(parsed.sales || []);
          setExpenses(parsed.expenses || []);
          setProducts(parsed.products || []);
        }
      } else {
        const localUsers = JSON.parse(localStorage.getItem('gestao93_users') || '[]');
        const dataToUpload = JSON.stringify({ 
          customers, 
          sales, 
          expenses,
          products,
          users: localUsers,
          lastSync: new Date().toISOString()
        });
        localStorage.setItem(storageKey, dataToUpload);
      }
      setSyncStatus('synced');
    } catch (err) {
      setSyncStatus('error');
    }
  }, [user, customers, sales, expenses, products]);

  useEffect(() => {
    const savedUser = localStorage.getItem('gestao93_current_user');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      checkTutorialStatus(parsedUser.id);
      if (parsedUser.authProvider === 'onedrive') {
        syncWithOneDrive('download');
      } else {
        const localCustomers = localStorage.getItem(`gestao93_customers_${parsedUser.id}`);
        const localSales = localStorage.getItem(`gestao93_sales_${parsedUser.id}`);
        const localExpenses = localStorage.getItem(`gestao93_expenses_${parsedUser.id}`);
        const localProducts = localStorage.getItem(`gestao93_products_${parsedUser.id}`);
        if (localCustomers) setCustomers(JSON.parse(localCustomers));
        if (localSales) setSales(JSON.parse(localSales));
        if (localExpenses) setExpenses(JSON.parse(localExpenses));
        if (localProducts) setProducts(JSON.parse(localProducts));
      }
    }
    setLoading(false);
  }, [syncWithOneDrive]);

  const checkTutorialStatus = (userId: string) => {
    const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
    if (!tutorialSeen) setShowTutorial(true);
  };

  const handleFinishTutorial = () => {
    if (user) localStorage.setItem(`gestao93_tutorial_seen_${user.id}`, 'true');
    setShowTutorial(false);
  };

  // Fixed the truncated useEffect to save data and added proper dependencies
  useEffect(() => {
    if (!loading && user) {
      setSyncStatus('syncing');
      const timer = setTimeout(() => {
        if (user.authProvider === 'onedrive') {
          syncWithOneDrive('upload');
        } else {
          localStorage.setItem(`gestao93_customers_${user.id}`, JSON.stringify(customers));
          localStorage.setItem(`gestao93_sales_${user.id}`, JSON.stringify(sales));
          localStorage.setItem(`gestao93_expenses_${user.id}`, JSON.stringify(expenses));
          localStorage.setItem(`gestao93_products_${user.id}`, JSON.stringify(products));
        }
        setSyncStatus('synced');
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [customers, sales, expenses, products, user, loading, syncWithOneDrive]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!user) {
    return <Landing onLogin={setUser} />;
  }

  // View renderer based on activeView state
  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard sales={sales} customers={customers} expenses={expenses} />;
      case 'customers':
        return (
          <CustomerList 
            customers={customers} 
            sales={sales} 
            onAdd={(c) => setCustomers([...customers, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])}
            onDelete={(id) => setCustomers(customers.filter(c => c.id !== id))}
          />
        );
      case 'sales-cash':
        return (
          <SalesManager 
            mode="cash" 
            sales={sales} 
            customers={customers} 
            products={products}
            onAddSale={(s) => setSales([...sales, { ...s, id: Math.random().toString(36).substr(2, 9) }])}
            onUpdateSale={(s) => setSales(sales.map(sale => sale.id === s.id ? s : sale))}
          />
        );
      case 'sales-credit':
        return (
          <SalesManager 
            mode="credit" 
            sales={sales} 
            customers={customers} 
            products={products}
            onAddSale={(s) => setSales([...sales, { ...s, id: Math.random().toString(36).substr(2, 9) }])}
            onUpdateSale={(s) => setSales(sales.map(sale => sale.id === s.id ? s : sale))}
          />
        );
      case 'inventory':
        return (
          <InventoryManager 
            products={products} 
            onAdd={(p) => setProducts([...products, { ...p, id: Math.random().toString(36).substr(2, 9) }])}
            onDelete={(id) => setProducts(products.filter(p => p.id !== id))}
            onUpdate={(p) => setProducts(products.map(prod => prod.id === p.id ? p : prod))}
            onBulkImport={(data) => {
              setProducts(data.products);
              setSales([...sales, ...data.sales]);
            }}
          />
        );
      case 'expenses':
        return (
          <ExpenseManager 
            expenses={expenses} 
            onAdd={(description, amount) => setExpenses([...expenses, { id: Math.random().toString(36).substr(2, 9), description, amount }])}
            onDelete={(id) => setExpenses(expenses.filter(e => e.id !== id))}
          />
        );
      case 'agenda':
        return <Agenda sales={sales} customers={customers} />;
      case 'settings':
        return (
          <Settings 
            user={user}
            customers={customers}
            sales={sales}
            products={products}
            onUpdateProfile={(updatedUser) => {
              setUser(updatedUser);
              localStorage.setItem('gestao93_current_user', JSON.stringify(updatedUser));
            }}
            onImport={(data) => {
              setCustomers(data.customers);
              setSales(data.sales);
              setProducts(data.products || []);
            }}
            onClear={() => {
              setCustomers([]);
              setSales([]);
              setExpenses([]);
              setProducts([]);
            }}
          />
        );
      default:
        return <Dashboard sales={sales} customers={customers} expenses={expenses} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {showTutorial && <Tutorial activeView={activeView} onClose={handleFinishTutorial} />}

      {/* Sidebar Navigation */}
      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col shrink-0">
        <div className="p-6 flex items-center gap-3 border-b border-indigo-900/50">
          <div className="bg-indigo-600 p-2 rounded-xl">
             <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tighter italic uppercase text-white">Gestão 93</h1>
            <div className="flex items-center gap-1">
              <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-400' : syncStatus === 'syncing' ? 'bg-amber-400 animate-pulse' : 'bg-rose-400'}`}></div>
              <span className="text-[8px] font-bold uppercase tracking-widest text-indigo-300">{syncStatus === 'synced' ? 'Sincronizado' : 'Salvando...'}</span>
            </div>
          </div>
        </div>

        <div className="flex-1 py-6 space-y-1 px-3 overflow-y-auto">
          <NavItem id="nav-dashboard" icon="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" label="Início" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem id="nav-inventory" icon="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" label="Estoque" active={activeView === 'inventory'} onClick={() => setActiveView('inventory')} />
          <NavItem id="nav-customers" icon="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 005.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" label="Clientes" active={activeView === 'customers'} onClick={() => setActiveView('customers')} />
          <div className="pt-4 pb-2 px-3 text-[10px] font-black uppercase tracking-widest text-indigo-400">Vendas</div>
          <NavItem id="nav-sales-cash" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" label="À Vista" active={activeView === 'sales-cash'} onClick={() => setActiveView('sales-cash')} />
          <NavItem id="nav-sales-credit" icon="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" label="A Prazo" active={activeView === 'sales-credit'} onClick={() => setActiveView('sales-credit')} />
          <NavItem id="nav-agenda" icon="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" label="Agenda" active={activeView === 'agenda'} onClick={() => setActiveView('agenda')} />
          <div className="pt-4 pb-2 px-3 text-[10px] font-black uppercase tracking-widest text-indigo-400">Financeiro</div>
          <NavItem id="nav-expenses" icon="M15 12H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" label="Despesas" active={activeView === 'expenses'} onClick={() => setActiveView('expenses')} />
          <NavItem id="nav-settings" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" label="Configurações" active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
        </div>

        <div className="p-4 bg-indigo-900/30">
           <div className="flex items-center gap-3 p-3 bg-indigo-950/50 rounded-2xl border border-indigo-900/50">
              <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center font-bold text-lg italic shadow-inner overflow-hidden">
                {user.avatarUrl ? <img src={user.avatarUrl} alt="Avatar" className="w-full h-full object-cover" /> : <span className="text-white">{user.name.charAt(0)}</span>}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-xs font-black truncate text-white">{user.name}</p>
                <p className="text-[10px] text-indigo-400 truncate uppercase font-bold tracking-tighter">Plano Premium</p>
              </div>
              <button onClick={() => { localStorage.removeItem('gestao93_current_user'); window.location.reload(); }} className="text-indigo-400 hover:text-rose-400 transition">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              </button>
           </div>
        </div>
      </nav>

      {/* Main Content Area */}
      <main className="flex-1 p-4 md:p-8 lg:p-12 overflow-y-auto h-screen bg-[#fcfcfd]">
        <div className="max-w-6xl mx-auto">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

interface NavItemProps {
  id: string;
  icon: string;
  label: string;
  active: boolean;
  onClick: () => void;
}

const NavItem: React.FC<NavItemProps> = ({ id, icon, label, active, onClick }) => (
  <button 
    id={id}
    onClick={onClick}
    className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 group ${active ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-indigo-300 hover:bg-indigo-900/50 hover:text-white'}`}
  >
    <svg className={`w-5 h-5 transition-transform group-hover:scale-110 ${active ? 'text-white' : 'text-indigo-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={icon} />
    </svg>
    <span className={`text-sm font-bold tracking-tight ${active ? 'font-black' : ''}`}>{label}</span>
  </button>
);

export default App;

import React, { useState } from 'react';
import { Product, Sale } from '../types';
import { JAN_2026_SPREADSHEET_DATA } from '../services/dataService';

interface InventoryManagerProps {
  products: Product[];
  onAdd: (product: Omit<Product, 'id'>) => void;
  onDelete: (id: string) => void;
  onUpdate: (product: Product) => void;
  onBulkImport?: (data: { products: Product[], sales: Sale[] }) => void;
}

const InventoryManager: React.FC<InventoryManagerProps> = ({ products, onAdd, onDelete, onUpdate, onBulkImport }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [sku, setSku] = useState('');
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [costPrice, setCostPrice] = useState<number>(0);
  const [price, setPrice] = useState<number>(0);
  const [stock, setStock] = useState<number>(0);
  const [minStock, setMinStock] = useState<number>(2);

  const totalCostValue = products.reduce((acc, p) => acc + (p.costPrice * p.stock), 0);
  const totalSaleValue = products.reduce((acc, p) => acc + (p.price * p.stock), 0);
  const expectedProfit = totalSaleValue - totalCostValue;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || price < 0 || stock < 0) return;

    const finalSku = sku.trim().toUpperCase() || Math.random().toString(36).substr(2, 6).toUpperCase();
    const isDuplicate = products.some(p => p.sku.toUpperCase() === finalSku);

    if (isDuplicate) {
      alert(`O código "${finalSku}" já está sendo usado. Escolha outro ou deixe vazio.`);
      return;
    }

    onAdd({ 
      sku: finalSku,
      name, 
      category: category || 'Geral', 
      costPrice,
      price, 
      stock, 
      minStock 
    });

    setSku('');
    setName('');
    setCategory('');
    setCostPrice(0);
    setPrice(0);
    setStock(0);
    setMinStock(2);
    setShowAdd(false);
  };

  const handleJan2026Import = () => {
    if (!onBulkImport) return;
    if (window.confirm("Deseja importar todos os produtos e vendas da planilha de Janeiro/2026 para o seu sistema?")) {
      onBulkImport(JAN_2026_SPREADSHEET_DATA);
      alert("Planilha carregada com sucesso! Verifique seu estoque e dashboard.");
    }
  };

  const formatCurrency = (val: number) => val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-800">Controle de Estoque</h2>
          <p className="text-sm text-slate-500">Gerencie seus produtos e preços de custo.</p>
        </div>
        <div className="flex gap-2">
           <button 
            onClick={handleJan2026Import}
            className="bg-emerald-600 text-white px-4 py-2 rounded-xl text-xs font-black uppercase hover:bg-emerald-700 transition shadow-lg border border-emerald-500 flex items-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
            Carregar Planilha Jan/2026
          </button>
          <button 
            onClick={() => setShowAdd(!showAdd)}
            className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-700 transition shadow-sm"
          >
            {showAdd ? 'Cancelar' : 'Novo Produto'}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm">
           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">Custo Total em Estoque</p>
           <p className="text-xl font-black text-slate-700">{formatCurrency(totalCostValue)}</p>
        </div>
        <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm">
           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-1">Valor Total de Venda</p>
           <p className="text-xl font-black text-indigo-600">{formatCurrency(totalSaleValue)}</p>
        </div>
        <div className="bg-emerald-50 p-5 rounded-2xl border border-emerald-100 shadow-sm">
           <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-wider mb-1">Lucro Bruto Projetado</p>
           <p className="text-xl font-black text-emerald-700">{formatCurrency(expectedProfit)}</p>
        </div>
      </div>

      {showAdd && (
        <form onSubmit={handleSubmit} className="bg-white p-6 rounded-2xl shadow-sm border border-indigo-100 space-y-4 animate-in fade-in zoom-in duration-200">
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              <div>
                <label className="block text-xs font-bold text-indigo-600 uppercase mb-1">Código (SKU)</label>
                <input type="text" value={sku} onChange={e => setSku(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" placeholder="Ex: 101" />
              </div>
              <div className="md:col-span-2">
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nome da Peça *</label>
                <input type="text" value={name} onChange={e => setName(e.target.value)} required className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Categoria</label>
                <input type="text" value={category} onChange={e => setCategory(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Custo (R$)</label>
                <input type="number" step="0.01" value={costPrice || ''} onChange={e => setCostPrice(Number(e.target.value))} required className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Venda (R$)</label>
                <input type="number" step="0.01" value={price || ''} onChange={e => setPrice(Number(e.target.value))} required className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold text-emerald-600" />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Estoque</label>
                <input type="number" value={stock || ''} onChange={e => setStock(Number(e.target.value))} required className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
              </div>
           </div>
           <div className="flex justify-end pt-2">
              <button type="submit" className="bg-indigo-600 text-white px-8 py-3 rounded-xl text-sm font-bold uppercase tracking-widest hover:bg-indigo-700 transition shadow-lg">Cadastrar</button>
           </div>
        </form>
      )}

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Peça</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Custo</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Venda</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Qtd</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {products.map(p => (
                <tr key={p.id} className="hover:bg-slate-50 transition group">
                  <td className="px-6 py-4">
                    <div className="inline-block bg-slate-100 text-slate-600 text-[10px] font-black px-2 py-0.5 rounded mb-1 uppercase">{p.sku}</div>
                    <div className="font-bold text-slate-800">{p.name}</div>
                  </td>
                  <td className="px-6 py-4 text-right text-xs text-rose-500">{formatCurrency(p.costPrice)}</td>
                  <td className="px-6 py-4 text-right text-sm font-black text-slate-800">{formatCurrency(p.price)}</td>
                  <td className="px-6 py-4 text-center">
                    <span className={`px-3 py-1 rounded-lg text-sm font-black ${p.stock <= p.minStock ? 'bg-rose-100 text-rose-700' : 'bg-emerald-100 text-emerald-700'}`}>
                      {p.stock}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <div className="flex justify-center gap-2">
                       <button onClick={() => { if (window.confirm('Excluir este produto?')) onDelete(p.id); }} className="p-2 text-slate-300 hover:text-rose-600 transition">
                         <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                       </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default InventoryManager;

import React, { useState, useEffect, useCallback } from 'react';
import { View, Customer, Sale, User, Expense, Product } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';
import Agenda from './components/Agenda';
import Settings from './components/Settings';
import Landing from './components/Landing';
import Tutorial from './components/Tutorial';
import ExpenseManager from './components/ExpenseManager';
import InventoryManager from './components/InventoryManager';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const syncWithOneDrive = useCallback(async (action: 'upload' | 'download') => {
    if (!user || user.authProvider !== 'onedrive') return;
    setSyncStatus('syncing');
    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      const storageKey = `gestao93_cloud_master_${user.id}`;
      if (action === 'download') {
        const cloudData = localStorage.getItem(storageKey);
        if (cloudData) {
          const parsed = JSON.parse(cloudData);
          setCustomers(parsed.customers || []);
          setSales(parsed.sales || []);
          setExpenses(parsed.expenses || []);
          setProducts(parsed.products || []);
        }
      } else {
        const localUsers = JSON.parse(localStorage.getItem('gestao93_users') || '[]');
        const dataToUpload = JSON.stringify({ 
          customers, 
          sales, 
          expenses,
          products,
          users: localUsers,
          lastSync: new Date().toISOString()
        });
        localStorage.setItem(storageKey, dataToUpload);
      }
      setSyncStatus('synced');
    } catch (err) {
      setSyncStatus('error');
    }
  }, [user, customers, sales, expenses, products]);

  useEffect(() => {
    const savedUser = localStorage.getItem('gestao93_current_user');
    if (savedUser) {
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);
      const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${parsedUser.id}`);
      if (!tutorialSeen) setShowTutorial(true);

      if (parsedUser.authProvider === 'onedrive') {
        syncWithOneDrive('download');
      } else {
        const localCustomers = localStorage.getItem(`gestao93_customers_${parsedUser.id}`);
        const localSales = localStorage.getItem(`gestao93_sales_${parsedUser.id}`);
        const localExpenses = localStorage.getItem(`gestao93_expenses_${parsedUser.id}`);
        const localProducts = localStorage.getItem(`gestao93_products_${parsedUser.id}`);
        if (localCustomers) setCustomers(JSON.parse(localCustomers));
        if (localSales) setSales(JSON.parse(localSales));
        if (localExpenses) setExpenses(JSON.parse(localExpenses));
        if (localProducts) setProducts(JSON.parse(localProducts));
      }
    }
    setLoading(false);
  }, [syncWithOneDrive]);

  useEffect(() => {
    if (!loading && user) {
      setSyncStatus('syncing');
      const timer = setTimeout(() => {
        if (user.authProvider === 'onedrive') {
          syncWithOneDrive('upload');
        } else {
          localStorage.setItem(`gestao93_customers_${user.id}`, JSON.stringify(customers));
          localStorage.setItem(`gestao93_sales_${user.id}`, JSON.stringify(sales));
          localStorage.setItem(`gestao93_expenses_${user.id}`, JSON.stringify(expenses));
          localStorage.setItem(`gestao93_products_${user.id}`, JSON.stringify(products));
        }
        setSyncStatus('synced');
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [customers, sales, expenses, products, user, loading, syncWithOneDrive]);

  const handleFinishTutorial = () => {
    if (user) localStorage.setItem(`gestao93_tutorial_seen_${user.id}`, 'true');
    setShowTutorial(false);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!user) {
    return <Landing onLogin={setUser} />;
  }

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard sales={sales} customers={customers} expenses={expenses} />;
      case 'customers':
        return (
          <CustomerList 
            customers={customers} 
            sales={sales} 
            onAdd={(c) => setCustomers([...customers, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])}
            onDelete={(id) => setCustomers(customers.filter(c => c.id !== id))}
          />
        );
      case 'sales-cash':
        return (
          <SalesManager 
            mode="cash" 
            sales={sales} 
            customers={customers} 
            products={products}
            onAddSale={(s) => setSales([...sales, { ...s, id: Math.random().toString(36).substr(2, 9) }])}
            onUpdateSale={(s) => setSales(sales.map(sale => sale.id === s.id ? s : sale))}
          />
        );
      case 'sales-credit':
        return (
          <SalesManager 
            mode="credit" 
            sales={sales} 
            customers={customers} 
            products={products}
            onAddSale={(s) => setSales([...sales, { ...s, id: Math.random().toString(36).substr(2, 9) }])}
            onUpdateSale={(s) => setSales(sales.map(sale => sale.id === s.id ? s : sale))}
          />
        );
      case 'inventory':
        return (
          <InventoryManager 
            products={products} 
            onAdd={(p) => setProducts([...products, { ...p, id: Math.random().toString(36).substr(2, 9) }])}
            onDelete={(id) => setProducts(products.filter(p => p.id !== id))}
            onUpdate={(p) => setProducts(products.map(prod => prod.id === p.id ? p : prod))}
            onBulkImport={(data) => {
              // Merge products avoiding SKU duplication
              const newProducts = [...products];
              data.products.forEach(p => {
                if (!newProducts.some(existing => existing.sku === p.sku)) {
                  newProducts.push(p);
                }
              });
              setProducts(newProducts);
              // Append sales
              setSales([...sales, ...data.sales]);
            }}
          />
        );
      case 'expenses':
        return (
          <ExpenseManager 
            expenses={expenses} 
            onAdd={(description, amount) => setExpenses([...expenses, { id: Math.random().toString(36).substr(2, 9), description, amount }])}
            onDelete={(id) => setExpenses(expenses.filter(e => e.id !== id))}
          />
        );
      case 'agenda':
        return <Agenda sales={sales} customers={customers} />;
      case 'settings':
        return (
          <Settings 
            user={user}
            customers={customers}
            sales={sales}
            products={products}
            onUpdateProfile={(updatedUser) => {
              setUser(updatedUser);
              localStorage.setItem('gestao93_current_user', JSON.stringify(updatedUser));
            }}
            onImport={(data) => {
              setCustomers(data.customers);
              setSales(data.sales);
              setProducts(data.products || []);
            }}
            onClear={() => {
              setCustomers([]);
              setSales([]);
              setExpenses([]);
              setProducts([]);
            }}
          />
        );
      default:
        return <Dashboard sales={sales} customers={customers} expenses={expenses} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {showTutorial && <Tutorial activeView={activeView} onClose={handleFinishTutorial} />}

      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col shrink-0">
        <div className="p-6 flex items-center gap-3 border-b border-indigo-900/50">
          <div className="bg-indigo-600 p-2 rounded-xl">
             <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tighter italic uppercase text-white">Gestão 93</h1>
            <div className="flex items-center gap-1">
              <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-400' : syncStatus === 'syncing' ? 'bg-amber-400 animate-pulse' : 'bg-rose-400'}`}></div>
              <span className="text-[8px] font-bold uppercase tracking-widest text-indigo-300">{syncStatus === 'synced' ? 'Sincronizado' : 'Salvando...'}</span>
            </div>
          </div>
        </div>

        <div className="flex-1 py-6 space-y-1 px-3 overflow-y-auto">
          <NavItem id="nav-dashboard" icon="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" label="Início" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem id="nav-inventory" icon="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" label="Estoque" active={activeView === 'inventory'} onClick={() => setActiveView('inventory')} />
          <NavItem id="nav-customers" icon="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 005.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" label="Clientes" active={activeView === 'customers'} onClick={() => setActiveView('customers')} />
          <div className="pt-4 pb-2 px-3 text-[10px] font-black uppercase tracking-widest text-indigo-400">Vendas</div>
          <NavItem id="nav-sales-cash" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" label="À Vista" active={activeView === 'sales-cash'} onClick={() => setActiveView('sales-cash')} />
          <NavItem id="nav-sales-credit" icon="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" label="A Prazo" active={activeView === 'sales-credit'} onClick={() => setActiveView('sales-credit')} />
          <NavItem id="nav-agenda" icon="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" label="Agenda" active={activeView === 'agenda'} onClick={() => setActiveView('agenda')} />
          <div className="pt-4 pb-2 px-3 text-[10px] font-black uppercase tracking-widest text-indigo-400">Sistema</div>
          <NavItem id="nav-expenses" icon="M15 12H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" label="Despesas" active={activeView === 'expenses'} onClick={() => setActiveView('expenses')} />
          <NavItem id="nav-settings" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" label="Configurações" active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
        </div>

        <div className="p-4 bg-indigo-900/30">
           <div className="flex items-center gap-3 p-3 bg-indigo-950/50 rounded-2xl border border-indigo-900/50">
              <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center font-bold text-lg italic shadow-inner overflow-hidden">
                {user.avatarUrl ? <img src={user.avatarUrl} alt="Avatar" className="w-full h-full object-cover" /> : <span className="text-white">{user.name.charAt(0)}</span>}
