export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { View, Customer, Sale, User, Expense, Product } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';
import Agenda from './components/Agenda';
import Settings from './components/Settings';
import Landing from './components/Landing';
import Tutorial from './components/Tutorial';
import ExpenseManager from './components/ExpenseManager';
import InventoryManager from './components/InventoryManager';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  // Ref para controlar a montagem inicial e evitar salvamentos indevidos
  const isMounted = useRef(false);

  // 1. Inicialização Robusta
  useEffect(() => {
    const initApp = () => {
      try {
        const savedUser = localStorage.getItem('gestao93_current_user');
        if (savedUser && savedUser !== 'undefined') {
          const parsedUser = JSON.parse(savedUser);
          if (parsedUser && parsedUser.id) {
            setUser(parsedUser);

            // Tentar carregar dados específicos do usuário
            const userId = parsedUser.id;
            const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
            if (!tutorialSeen) setShowTutorial(true);

            // Helper para parse seguro
            const safeParse = (key: string, fallback: any) => {
              try {
                const data = localStorage.getItem(key);
                return data ? JSON.parse(data) : fallback;
              } catch { return fallback; }
            };

            setCustomers(safeParse(`gestao93_customers_${userId}`, []));
            setSales(safeParse(`gestao93_sales_${userId}`, []));
            setExpenses(safeParse(`gestao93_expenses_${userId}`, []));
            setProducts(safeParse(`gestao93_products_${userId}`, []));
          }
        }
      } catch (e) {
        console.error("Erro crítico na inicialização:", e);
        // Em caso de erro grave, limpa o user para permitir login novo
        localStorage.removeItem('gestao93_current_user');
      } finally {
        setLoading(false);
        isMounted.current = true;
      }
    };

    initApp();
  }, []);

  // 2. Persistência Automática (Debounced)
  useEffect(() => {
    // Só salva se o app já carregou e existe um usuário logado
    if (loading || !user || !isMounted.current) return;

    const saveData = () => {
      try {
        setSyncStatus('syncing');
        const userId = user.id;
        localStorage.setItem(`gestao93_customers_${userId}`, JSON.stringify(customers));
        localStorage.setItem(`gestao93_sales_${userId}`, JSON.stringify(sales));
        localStorage.setItem(`gestao93_expenses_${userId}`, JSON.stringify(expenses));
        localStorage.setItem(`gestao93_products_${userId}`, JSON.stringify(products));
        setSyncStatus('synced');
      } catch (err) {
        console.error("Erro ao salvar dados:", err);
        setSyncStatus('error');
      }
    };

    const timer = setTimeout(saveData, 1000);
    return () => clearTimeout(timer);
  }, [customers, sales, expenses, products, user, loading]);

  const handleLogout = () => {
    localStorage.removeItem('gestao93_current_user');
    setUser(null);
    setActiveView('dashboard');
  };

  const handleFinishTutorial = () => {
    if (user) localStorage.setItem(`gestao93_tutorial_seen_${user.id}`, 'true');
    setShowTutorial(false);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-indigo-950">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
          <div className="text-center">
            <h1 className="text-white font-black text-2xl tracking-tighter italic uppercase">Gestão 93</h1>
            <p className="text-indigo-300 text-xs font-bold uppercase tracking-widest mt-2 animate-pulse">Carregando seus dados...</p>
          </div>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Landing onLogin={(u) => { 
      // Ao logar, definimos o usuário e o sistema inicializa os dados via useEffect do user id
      setUser(u);
    }} />;
  }

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard sales={sales} customers={customers} expenses={expenses} />;
      case 'customers':
        return (
          <CustomerList 
            customers={customers} 
            sales={sales} 
            onAdd={(c) => setCustomers([...customers, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])}
            onDelete={(id) => setCustomers(customers.filter(c => c.id !== id))}
          />
        );
      case 'sales-cash':
        return (
          <SalesManager 
            mode="cash" 
            sales={sales} 
            customers={customers} 
            products={products}
            onAddSale={(s) => setSales([...sales, { ...s, id: Math.random().toString(36).substr(2, 9) }])}
            onUpdateSale={(s) => setSales(sales.map(sale => sale.id === s.id ? s : sale))}
          />
        );
      case 'sales-credit':
        return (
          <SalesManager 
            mode="credit" 
            sales={sales} 
            customers={customers} 
            products={products}
            onAddSale={(s) => setSales([...sales, { ...s, id: Math.random().toString(36).substr(2, 9) }])}
            onUpdateSale={(s) => setSales(sales.map(sale => sale.id === s.id ? s : sale))}
          />
        );
      case 'inventory':
        return (
          <InventoryManager 
            products={products} 
            onAdd={(p) => setProducts([...products, { ...p, id: Math.random().toString(36).substr(2, 9) }])}
            onDelete={(id) => setProducts(products.filter(p => p.id !== id))}
            onUpdate={(p) => setProducts(products.map(prod => prod.id === p.id ? p : prod))}
            onBulkImport={(data) => {
              // Mescla produtos evitando duplicatas por SKU
              const existingSkus = new Set(products.map(p => p.sku));
              const filteredNewProducts = data.products.filter(p => !existingSkus.has(p.sku));
              setProducts([...products, ...filteredNewProducts]);
              setSales([...sales, ...data.sales]);
            }}
          />
        );
      case 'expenses':
        return (
          <ExpenseManager 
            expenses={expenses} 
            onAdd={(description, amount) => setExpenses([...expenses, { id: Math.random().toString(36).substr(2, 9), description, amount }])}
            onDelete={(id) => setExpenses(expenses.filter(e => e.id !== id))}
          />
        );
      case 'agenda':
        return <Agenda sales={sales} customers={customers} />;
      case 'settings':
        return (
          <Settings 
            user={user}
            customers={customers}
            sales={sales}
            products={products}
            onUpdateProfile={(updatedUser) => {
              setUser(updatedUser);
              localStorage.setItem('gestao93_current_user', JSON.stringify(updatedUser));
            }}
            onImport={(data) => {
              setCustomers(data.customers);
              setSales(data.sales);
              setProducts(data.products || []);
            }}
            onClear={() => {
              setCustomers([]);
              setSales([]);
              setExpenses([]);
              setProducts([]);
            }}
          />
        );
      default:
        return <Dashboard sales={sales} customers={customers} expenses={expenses} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {showTutorial && <Tutorial activeView={activeView} onClose={handleFinishTutorial} />}

      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col shrink-0 z-50">
