import React, { useState, useEffect } from 'react';
import { User } from '../types';

interface LandingProps {
  onLogin: (user: User) => void;
}

const Landing: React.FC<LandingProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [isRecovery, setIsRecovery] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  const getSavedUsers = (): User[] => {
    try {
      return JSON.parse(localStorage.getItem('gestao93_users') || '[]');
    } catch { return []; }
  };

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setMessage('');

    const savedUsers = getSavedUsers();

    if (isRecovery) {
      const user = savedUsers.find((u: User) => u.email === email);
      if (user) {
        setMessage(`Simulação: Instruções enviadas para ${email}.`);
        setTimeout(() => setIsRecovery(false), 3000);
      } else {
        setError('E-mail não encontrado.');
      }
      return;
    }

    if (isRegistering) {
      if (!name || !email || !password) {
        setError('Preencha todos os campos.');
        return;
      }
      if (savedUsers.find((u: User) => u.email === email)) {
        setError('Este e-mail já existe.');
        return;
      }
      const newUser: User = { 
        id: Math.random().toString(36).substr(2, 9), 
        name, 
        email, 
        password,
        authProvider: 'local'
      };
      const updatedUsers = [...savedUsers, newUser];
      localStorage.setItem('gestao93_users', JSON.stringify(updatedUsers));
      localStorage.setItem('gestao93_current_user', JSON.stringify(newUser));
      onLogin(newUser);
    } else {
      const user = savedUsers.find((u: User) => u.email === email && u.password === password);
      if (user) {
        localStorage.setItem('gestao93_current_user', JSON.stringify(user));
        onLogin(user);
      } else {
        setError('E-mail ou senha incorretos.');
      }
    }
  };

  const handleOneDriveLogin = async () => {
    setIsAuthenticating(true);
    const simulatedEmail = prompt("E-mail Outlook/Hotmail (Simulação):", "loja93@outlook.com");
    if (!simulatedEmail) {
      setIsAuthenticating(false);
      return;
    }
    setTimeout(() => {
      const msUser: User = {
        id: `ms_${btoa(simulatedEmail).substr(0, 10)}`,
        name: simulatedEmail.split('@')[0].toUpperCase(),
        email: simulatedEmail,
        authProvider: 'onedrive',
        avatarUrl: `https://ui-avatars.com/api/?name=${simulatedEmail}&background=4f46e5&color=fff`
      };
      localStorage.setItem('gestao93_current_user', JSON.stringify(msUser));
      onLogin(msUser);
      setIsAuthenticating(false);
    }, 1000);
  };

  const handleEmergencyReset = () => {
    if (confirm("Isso limpará APENAS a sessão atual para destravar o app. Seus dados salvos em contas locais não serão apagados. Deseja continuar?")) {
      localStorage.removeItem('gestao93_current_user');
      window.location.reload();
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-white">
      <div className="md:w-1/2 lg:w-2/3 relative h-[30vh] md:h-screen overflow-hidden">
        <img 
          src="https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&q=80&w=1600" 
          className="absolute inset-0 w-full h-full object-cover" 
          alt="Loja" 
        />
        <div className="absolute inset-0 bg-indigo-950/80"></div>
        <div className="absolute inset-0 flex flex-col justify-center p-8 md:p-24 text-white">
          <div className="flex items-center gap-4 mb-6">
            <div className="bg-indigo-600 p-3 rounded-2xl shadow-2xl">
              <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
            </div>
            <h1 className="text-5xl md:text-7xl font-black tracking-tighter italic uppercase drop-shadow-2xl">Gestão 93</h1>
          </div>
          <p className="text-xl md:text-3xl font-light italic text-indigo-200 max-w-xl leading-tight">“Organize suas vendas e cresça com segurança.”</p>
        </div>
      </div>

      <div className="flex-1 flex flex-col justify-center p-8 md:p-12 lg:p-20 bg-slate-50 relative">
        <div className="max-w-md w-full mx-auto">
          <div className="mb-8">
            <h3 className="text-3xl font-bold text-slate-800 mb-2">
              {isRecovery ? 'Recuperar Acesso' : isRegistering ? 'Nova Conta' : 'Entrar no Sistema'}
            </h3>
            <p className="text-slate-500 text-sm">Controle de Vendas a Prazo e Estoque Inteligente.</p>
          </div>

          <div className="space-y-4">
            {!isRecovery && (
              <button 
                onClick={handleOneDriveLogin}
                disabled={isAuthenticating}
                className="w-full bg-white border border-slate-200 text-slate-700 font-bold py-4 rounded-2xl hover:bg-slate-50 transition shadow-sm flex items-center justify-center gap-3 disabled:opacity-50"
              >
                {isAuthenticating ? <div className="w-5 h-5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div> : <img src="https://upload.wikimedia.org/wikipedia/commons/3/3c/Microsoft_Office_OneDrive_%282019-present%29.svg" className="h-6" alt="OneDrive" />}
                OneDrive Login
              </button>
            )}

            <form onSubmit={handleAuth} className="space-y-4">
              {isRegistering && (
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Nome da Loja</label>
                  <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm" placeholder="Ex: Boutique 93" />
                </div>
              )}
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">E-mail</label>
                <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm" placeholder="seu@email.com" />
              </div>
              {!isRecovery && (
                <div className="space-y-1">
                  <div className="flex justify-between items-center px-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Senha</label>
                    <button type="button" onClick={() => setIsRecovery(true)} className="text-[10px] font-bold text-indigo-600 uppercase">Esqueceu?</button>
                  </div>
                  <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm" placeholder="••••••••" />
                </div>
              )}

              {error && <p className="text-rose-500 text-[10px] font-bold bg-rose-50 p-3 rounded-lg border border-rose-100">{error}</p>}
              {message && <p className="text-emerald-600 text-[10px] font-bold bg-emerald-50 p-3 rounded-lg border border-emerald-100">{message}</p>}

              <button type="submit" className="w-full bg-indigo-900 text-white font-bold py-4 rounded-xl hover:bg-indigo-950 transition shadow-lg">
                {isRecovery ? 'Enviar' : isRegistering ? 'Cadastrar' : 'Entrar'}
              </button>
            </form>

            <div className="text-center pt-4">
              <button onClick={() => { setIsRegistering(!isRegistering); setIsRecovery(false); }} className="text-xs font-bold text-indigo-600 hover:underline">
                {isRegistering ? 'Já tenho conta' : 'Criar nova conta'}
              </button>
            </div>
          </div>
        </div>

        {/* Botão de Emergência */}
        <div className="absolute bottom-4 right-4 opacity-50 hover:opacity-100">
           <button onClick={handleEmergencyReset} className="text-[9px] text-slate-400 uppercase font-bold hover:text-rose-500 underline">Destravar App</button>
        </div>
      </div>
    </div>
  );
};

