              <div className="space-y-1">
                <label className="text-[11px] font-black text-slate-800 uppercase ml-1 tracking-wider">E-mail</label>
                <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required className="w-full bg-white border border-slate-300 rounded-xl px-4 py-3 text-sm text-slate-900 font-medium focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="seu@email.com" />
              </div>
              {!isRecovery && (
                <div className="space-y-1">
                  <div className="flex justify-between items-center px-1">
                    <label className="text-[11px] font-black text-slate-800 uppercase tracking-wider">Senha</label>
                    <button type="button" onClick={() => setIsRecovery(true)} className="text-[11px] font-black text-indigo-700 uppercase hover:underline">Esqueceu?</button>
                  </div>
                  <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required className="w-full bg-white border border-slate-300 rounded-xl px-4 py-3 text-sm text-slate-900 font-medium focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="••••••••" />
                </div>
              )}

              {error && <p className="text-rose-700 text-[11px] font-black bg-rose-50 p-3 rounded-lg border border-rose-200">{error}</p>}
              {message && <p className="text-emerald-800 text-[11px] font-black bg-emerald-50 p-3 rounded-lg border border-emerald-200">{message}</p>}

              <button type="submit" className="w-full bg-indigo-900 text-white font-black py-4 rounded-xl hover:bg-indigo-950 transition shadow-lg uppercase tracking-widest text-sm">
                {isRecovery ? 'Enviar' : isRegistering ? 'Cadastrar' : 'Entrar'}
              </button>
            </form>

            <div className="text-center pt-4">
              <button onClick={() => { setIsRegistering(!isRegistering); setIsRecovery(false); }} className="text-xs font-black text-indigo-800 hover:underline uppercase tracking-wide">
                {isRegistering ? 'Já tenho conta? Entrar' : 'Não tem conta? Criar agora'}
              </button>
            </div>
          </div>
        </div>

        {/* Botão de Emergência */}
        <div className="absolute bottom-4 right-4 opacity-40 hover:opacity-100 transition-opacity">
           <button onClick={handleEmergencyReset} className="text-[10px] text-slate-600 uppercase font-black hover:text-rose-700 underline tracking-tighter">Destravar App (Reset Sessão)</button>
        </div>
      </div>
    </div>
  );
};

