import React, { useState } from 'react';
import { Customer, Sale, User, Product } from '../types';

interface SettingsProps {
  user?: User | null;
  customers: Customer[];
  sales: Sale[];
  products: Product[];
  onUpdateProfile?: (user: User) => void;
  onImport: (data: { customers: Customer[], sales: Sale[], products?: Product[] }) => void;
  onClear: () => void;
}

const Settings: React.FC<SettingsProps> = ({ user, customers, sales, products, onUpdateProfile, onImport, onClear }) => {
  const [activeTab, setActiveTab] = useState<'profile' | 'backup' | 'danger'>('profile');

  const [shopName, setShopName] = useState(user?.name || '');
  const [shopLogo, setShopLogo] = useState(user?.avatarUrl || '');

  const handleUpdateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    if (user && onUpdateProfile) {
      onUpdateProfile({ ...user, name: shopName, avatarUrl: shopLogo });
      alert('Perfil atualizado!');
    }
  };

  const handleExport = () => {
    const data = { customers, sales, products, exportDate: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup_gestao93_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.customers && json.sales) {
          if (confirm('Isso substituirá seus dados atuais. Continuar?')) {
            onImport({ customers: json.customers, sales: json.sales, products: json.products || [] });
          }
        }
      } catch { alert('Erro no arquivo.'); }
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-6">
      <div className="flex border-b border-slate-200 overflow-x-auto no-scrollbar">
        {['profile', 'backup', 'danger'].map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-6 py-3 text-sm font-black uppercase tracking-wider transition-colors whitespace-nowrap ${activeTab === tab ? 'text-indigo-800 border-b-2 border-indigo-800' : 'text-slate-400 hover:text-slate-600'}`}>
            {tab === 'profile' ? 'Perfil' : tab === 'backup' ? 'Backup' : 'Zerar Sistema'}
          </button>
        ))}
      </div>

      <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-100">
        {activeTab === 'profile' && (
           <form onSubmit={handleUpdateProfile} className="max-w-xl space-y-6">
              <div className="space-y-1">
                 <label className="text-[11px] font-black text-slate-800 uppercase tracking-wider">Nome da Loja</label>
                 <input type="text" value={shopName} onChange={(e) => setShopName(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-black text-slate-900" />
              </div>
              <button type="submit" className="bg-indigo-900 text-white px-8 py-3 rounded-xl text-sm font-black uppercase tracking-widest shadow-lg">Salvar Perfil</button>
           </form>
        )}

        {activeTab === 'backup' && (
           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-4">
                 <h3 className="text-sm font-black text-slate-900 uppercase">Exportar Backup</h3>
                 <p className="text-xs text-slate-500">Salve seus dados em um arquivo local por segurança.</p>
                 <button onClick={handleExport} className="w-full bg-indigo-900 text-white px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest">Baixar .JSON</button>
              </div>
              <div className="space-y-4">
                 <h3 className="text-sm font-black text-slate-900 uppercase">Importar Backup</h3>
                 <p className="text-xs text-slate-500">Restaure dados de um arquivo salvo anteriormente.</p>
                 <label className="block w-full cursor-pointer bg-slate-100 text-slate-700 px-6 py-3 rounded-xl text-xs font-black uppercase text-center border border-slate-200 hover:bg-slate-200">
                    Selecionar Arquivo
                    <input type="file" className="hidden" accept=".json" onChange={handleImport} />
                 </label>
              </div>
           </div>
        )}

        {activeTab === 'danger' && (
           <div className="max-w-xl space-y-6">
              <div className="p-4 bg-rose-50 border border-rose-100 rounded-xl">
                 <h3 className="text-sm font-black text-rose-900 uppercase mb-2">Atenção: Ação Irreversível</h3>
                 <p className="text-xs text-rose-700 leading-relaxed font-medium">Esta opção apagará permanentemente todos os seus Clientes, Vendas, Produtos e Despesas registrados neste navegador. Use apenas se desejar recomeçar o sistema do zero ou remover dados de teste/exemplo.</p>
              </div>
              <button 
                onClick={() => { if (confirm('TEM CERTEZA? Todos os dados serão perdidos.')) onClear(); }} 
                className="w-full bg-rose-600 text-white px-8 py-4 rounded-xl text-sm font-black uppercase tracking-widest shadow-lg hover:bg-rose-700"
              >
                Apagar Tudo e Zerar Sistema
              </button>
           </div>
        )}
      </div>
    </div>
  );
};

export default Settings;

import React, { useState } from 'react';
import { Product, Sale } from '../types';
import { JAN_2026_SPREADSHEET_DATA } from '../services/dataService';

interface InventoryManagerProps {
  products: Product[];
  onAdd: (product: Omit<Product, 'id'>) => void;
  onDelete: (id: string) => void;
  onUpdate: (product: Product) => void;
  onBulkImport?: (data: { products: Product[], sales: Sale[] }) => void;
}

const InventoryManager: React.FC<InventoryManagerProps> = ({ products, onAdd, onDelete, onUpdate, onBulkImport }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [sku, setSku] = useState('');
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [costPrice, setCostPrice] = useState<number>(0);
  const [price, setPrice] = useState<number>(0);
  const [stock, setStock] = useState<number>(0);
  const [minStock, setMinStock] = useState<number>(2);

  const totalCostValue = products.reduce((acc, p) => acc + (p.costPrice * p.stock), 0);
  const totalSaleValue = products.reduce((acc, p) => acc + (p.price * p.stock), 0);
  const expectedProfit = totalSaleValue - totalCostValue;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || price < 0 || stock < 0) return;
    const finalSku = sku.trim().toUpperCase() || Math.random().toString(36).substr(2, 6).toUpperCase();
    if (products.some(p => p.sku.toUpperCase() === finalSku)) {
      alert(`Código "${finalSku}" já existe.`);
      return;
    }
    onAdd({ sku: finalSku, name, category: category || 'Geral', costPrice, price, stock, minStock });
    resetForm();
    setShowAdd(false);
  };

  const resetForm = () => { setSku(''); setName(''); setCategory(''); setCostPrice(0); setPrice(0); setStock(0); setMinStock(2); };

  const handleJan2026Import = () => {
    if (!onBulkImport) return;
    if (confirm("Deseja importar os dados de EXEMPLO (Jan/2026)? Isso adicionará produtos e vendas fictícias para demonstração.")) {
      onBulkImport(JAN_2026_SPREADSHEET_DATA);
    }
  };

  const formatCurrency = (val: number) => val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
