          <p className="text-sm text-slate-600 font-bold uppercase tracking-wider">Gestão Inteligente de Estoque e Vendas</p>
        </div>
        <button 
          onClick={() => setShowBreakdown(!showBreakdown)}
          className="bg-white border border-slate-300 text-slate-800 px-4 py-2 rounded-xl text-xs font-black uppercase hover:bg-slate-50 transition shadow-sm"
        >
          {showBreakdown ? 'Fechar Detalhamento' : 'Ver DRE Detalhado'}
        </button>
      </div>

      {/* KPI Cards Principal */}
      <div className="bg-indigo-900 p-8 rounded-3xl shadow-xl border border-indigo-800 text-white overflow-hidden relative">
          <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
            <div>
               <p className="text-indigo-200 text-[10px] font-black uppercase tracking-[0.2em] mb-1">Valor Total em Estoque (Venda)</p>
               <h3 className="text-4xl font-black">{formatCurrency(totalStockValueAtSalesPrice)}</h3>
               <p className="text-[10px] text-indigo-300 mt-2 font-bold uppercase tracking-widest italic">Capital total investido em mercadoria para venda</p>
