import React, { useState } from 'react';
import { Customer, Sale, User, Product } from '../types';

interface SettingsProps {
  user?: User | null;
  customers: Customer[];
  sales: Sale[];
  products: Product[];
  onUpdateProfile?: (user: User) => void;
  onImport: (data: { customers: Customer[], sales: Sale[], products?: Product[] }) => void;
  onClear: () => void;
}

const Settings: React.FC<SettingsProps> = ({ user, customers, sales, products, onUpdateProfile, onImport, onClear }) => {
  const [activeTab, setActiveTab] = useState<'profile' | 'backup' | 'danger'>('profile');

  const [shopName, setShopName] = useState(user?.name || '');
  const [shopLogo, setShopLogo] = useState(user?.avatarUrl || '');

  const handleUpdateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    if (user && onUpdateProfile) {
      onUpdateProfile({ ...user, name: shopName, avatarUrl: shopLogo });
      alert('Perfil atualizado!');
    }
  };

  const handleExport = () => {
    const data = { customers, sales, products, exportDate: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `backup_gestao93_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.customers && json.sales) {
          if (confirm('Isso substituirá seus dados atuais. Continuar?')) {
            onImport({ customers: json.customers, sales: json.sales, products: json.products || [] });
          }
        }
      } catch { alert('Erro no arquivo.'); }
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-6">
      <div className="flex border-b border-slate-200 overflow-x-auto no-scrollbar">
        {['profile', 'backup', 'danger'].map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-6 py-3 text-sm font-black uppercase tracking-wider transition-colors whitespace-nowrap ${activeTab === tab ? 'text-indigo-800 border-b-2 border-indigo-800' : 'text-slate-400 hover:text-slate-600'}`}>
            {tab === 'profile' ? 'Perfil' : tab === 'backup' ? 'Segurança & Backup' : 'Zerar Sistema'}
          </button>
        ))}
      </div>

      <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-100">
        {activeTab === 'profile' && (
           <form onSubmit={handleUpdateProfile} className="max-w-xl space-y-6">
              <div className="space-y-1">
                 <label className="text-[11px] font-black text-slate-800 uppercase tracking-wider">Nome da Loja</label>
                 <input type="text" value={shopName} onChange={(e) => setShopName(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-black text-slate-900" />
              </div>
              <button type="submit" className="bg-indigo-900 text-white px-8 py-3 rounded-xl text-sm font-black uppercase tracking-widest shadow-lg">Salvar Perfil</button>
           </form>
        )}

        {activeTab === 'backup' && (
           <div className="space-y-8">
              <div className="p-5 bg-amber-50 rounded-2xl border border-amber-100 max-w-2xl">
                <p className="text-xs text-amber-900 font-bold leading-relaxed">
                  <span className="font-black uppercase block mb-1">Aviso de Segurança:</span> 
                  Se você não estiver usando o <span className="text-indigo-700">OneDrive</span>, seus dados são salvos localmente neste navegador. 
                  Para garantir que seu trabalho não seja perdido se você limpar o cache ou trocar de aparelho, recomendamos baixar um backup manual regularmente.
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                   <h3 className="text-sm font-black text-slate-900 uppercase">Exportar Backup</h3>
                   <p className="text-xs text-slate-500">Gere um arquivo .JSON com todos os seus dados atuais.</p>
                   <button onClick={handleExport} className="w-full bg-indigo-900 text-white px-6 py-4 rounded-xl text-xs font-black uppercase tracking-widest shadow-lg hover:bg-indigo-950 transition">
                     Baixar Backup Agora
                   </button>
                </div>
                <div className="space-y-4">
                   <h3 className="text-sm font-black text-slate-900 uppercase">Importar Backup</h3>
                   <p className="text-xs text-slate-500">Restaure dados a partir de um arquivo salvo anteriormente.</p>
                   <label className="block w-full cursor-pointer bg-slate-100 text-slate-700 px-6 py-4 rounded-xl text-xs font-black uppercase text-center border border-slate-200 hover:bg-slate-200 transition">
                      Selecionar Arquivo .JSON
                      <input type="file" className="hidden" accept=".json" onChange={handleImport} />
                   </label>
                </div>
              </div>
           </div>
        )}

        {activeTab === 'danger' && (
           <div className="max-w-xl space-y-6">
              <div className="p-4 bg-rose-50 border border-rose-100 rounded-xl">
                 <h3 className="text-sm font-black text-rose-900 uppercase mb-2">Atenção: Ação Irreversível</h3>
                 <p className="text-xs text-rose-700 leading-relaxed font-medium">Esta opção apagará permanentemente todos os seus Clientes, Vendas, Produtos e Despesas registrados neste navegador. Use apenas se desejar recomeçar o sistema do zero ou remover dados de teste/exemplo.</p>
              </div>
              <button 
                onClick={() => { if (confirm('TEM CERTEZA? Todos os dados serão perdidos.')) onClear(); }} 
                className="w-full bg-rose-600 text-white px-8 py-4 rounded-xl text-sm font-black uppercase tracking-widest shadow-lg hover:bg-rose-700"
              >
                Apagar Tudo e Zerar Sistema
              </button>
           </div>
        )}
      </div>
    </div>
  );
};

