  // Inicialização
  useEffect(() => {
    const initApp = () => {
      try {
        const savedUser = localStorage.getItem('gestao93_current_user');
        if (savedUser && savedUser !== 'undefined') {
          const parsedUser = JSON.parse(savedUser);
          if (parsedUser && parsedUser.id) {
            setUser(parsedUser);
            const userId = parsedUser.id;

            const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
            if (!tutorialSeen) setShowTutorial(true);

            const safeParse = (key: string, fallback: any) => {
              try {
                const data = localStorage.getItem(key);
                return data ? JSON.parse(data) : fallback;
              } catch { return fallback; }
            };

            setCustomers(safeParse(`gestao93_customers_${userId}`, []));
            setSales(safeParse(`gestao93_sales_${userId}`, []));
            setExpenses(safeParse(`gestao93_expenses_${userId}`, []));
            setProducts(safeParse(`gestao93_products_${userId}`, []));
          }
        }
      } catch (e) {
        console.error("Erro ao carregar dados:", e);
        localStorage.removeItem('gestao93_current_user');
      } finally {
        setLoading(false);
        isMounted.current = true;
      }
    };
    initApp();
  }, []);

  // Persistência
  useEffect(() => {
    if (loading || !user || !isMounted.current) return;

    const timer = setTimeout(() => {
      try {
        setSyncStatus('syncing');
        const userId = user.id;
        localStorage.setItem(`gestao93_customers_${userId}`, JSON.stringify(customers));
        localStorage.setItem(`gestao93_sales_${userId}`, JSON.stringify(sales));
        localStorage.setItem(`gestao93_expenses_${userId}`, JSON.stringify(expenses));
        localStorage.setItem(`gestao93_products_${userId}`, JSON.stringify(products));
        setSyncStatus('synced');
      } catch (err) {
        setSyncStatus('error');
      }
    }, 1000);

    return () => clearTimeout(timer);
  }, [customers, sales, expenses, products, user, loading]);

  const handleLogout = () => {
    localStorage.removeItem('gestao93_current_user');
    setUser(null);
    setActiveView('dashboard');
  };

  const clearUserData = () => {
    if (!user) return;
    const userId = user.id;
    localStorage.removeItem(`gestao93_customers_${userId}`);
    localStorage.removeItem(`gestao93_sales_${userId}`);
    localStorage.removeItem(`gestao93_expenses_${userId}`);
    localStorage.removeItem(`gestao93_products_${userId}`);
    setCustomers([]);
    setSales([]);
    setExpenses([]);
    setProducts([]);
    alert("Todos os seus dados foram apagados. O sistema está limpo.");
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-indigo-950">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
          <h1 className="text-white font-black text-2xl italic uppercase">Gestão 93</h1>
        </div>
      </div>
    );
  }

  if (!user) return <Landing onLogin={setUser} />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
      case 'customers': return <CustomerList customers={customers} sales={sales} onAdd={(c) => setCustomers([...customers, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])} onDelete={(id) => setCustomers(customers.filter(c => c.id !== id))} />;
      case 'sales-cash': return <SalesManager mode="cash" sales={sales} customers={customers} products={products} onAddSale={(s) => setSales([...sales, { ...s, id: Math.random().toString(36).substr(2, 9) }])} onUpdateSale={(s) => setSales(sales.map(sale => sale.id === s.id ? s : sale))} />;
      case 'sales-credit': return <SalesManager mode="credit" sales={sales} customers={customers} products={products} onAddSale={(s) => setSales([...sales, { ...s, id: Math.random().toString(36).substr(2, 9) }])} onUpdateSale={(s) => setSales(sales.map(sale => sale.id === s.id ? s : sale))} />;
      case 'inventory': return <InventoryManager products={products} onAdd={(p) => setProducts([...products, { ...p, id: Math.random().toString(36).substr(2, 9) }])} onDelete={(id) => setProducts(products.filter(p => p.id !== id))} onUpdate={(p) => setProducts(products.map(prod => prod.id === p.id ? p : prod))} />;
      case 'expenses': return <ExpenseManager expenses={expenses} onAdd={(description, amount) => setExpenses([...expenses, { id: Math.random().toString(36).substr(2, 9), description, amount }])} onDelete={(id) => setExpenses(expenses.filter(e => e.id !== id))} />;
      case 'agenda': return <Agenda sales={sales} customers={customers} />;
      case 'settings': return <Settings user={user} customers={customers} sales={sales} products={products} onUpdateProfile={(u) => { setUser(u); localStorage.setItem('gestao93_current_user', JSON.stringify(u)); }} onImport={(data) => { setCustomers(data.customers); setSales(data.sales); setProducts(data.products || []); }} onClear={clearUserData} />;
      default: return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
    }
  };

  return (
    <div className="min-h-screen bg-white flex flex-col md:flex-row relative">
      {/* Camada de Fundo Temático de Moda - Agora com mais presença e desfoque suave */}
      <div 
        className="fixed inset-0 pointer-events-none z-0 bg-cover bg-center bg-no-repeat"
        style={{ 
          backgroundImage: 'url(https://images.unsplash.com/photo-1441986300917-64674bd600d8?q=80&w=2000)',
          opacity: '0.12',
          filter: 'grayscale(20%)'
        }}
      />

      {showTutorial && <Tutorial activeView={activeView} onClose={() => { localStorage.setItem(`gestao93_tutorial_seen_${user.id}`, 'true'); setShowTutorial(false); }} />}

      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col shrink-0 z-50 shadow-2xl">
        <div className="p-6 flex items-center gap-3 border-b border-indigo-900/50">
          <div className="bg-indigo-600 p-2 rounded-xl shrink-0 shadow-lg">
             <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <div className="min-w-0">
            <h1 className="text-xl font-black tracking-tighter italic uppercase text-white truncate">Gestão 93</h1>
            <div className="flex items-center gap-1">
              <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-400' : 'bg-amber-400 animate-pulse'}`}></div>
              <span className="text-[8px] font-bold uppercase tracking-widest text-indigo-300">{syncStatus === 'synced' ? 'Salvo' : 'Sincronizando'}</span>
            </div>
          </div>
        </div>
        <div className="flex-1 py-4 space-y-1 px-3 overflow-y-auto no-scrollbar">
          <NavItem id="nav-dashboard" icon="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" label="Início" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem id="nav-inventory" icon="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" label="Estoque" active={activeView === 'inventory'} onClick={() => setActiveView('inventory')} />
          <NavItem id="nav-customers" icon="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 005.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" label="Clientes" active={activeView === 'customers'} onClick={() => setActiveView('customers')} />
          <div className="pt-4 pb-1 px-4 text-[9px] font-black uppercase tracking-[0.2em] text-indigo-500">Operacional</div>
          <NavItem id="nav-sales-cash" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" label="À Vista" active={activeView === 'sales-cash'} onClick={() => setActiveView('sales-cash')} />
          <NavItem id="nav-sales-credit" icon="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" label="A Prazo" active={activeView === 'sales-credit'} onClick={() => setActiveView('sales-credit')} />
          <NavItem id="nav-agenda" icon="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" label="Agenda" active={activeView === 'agenda'} onClick={() => setActiveView('agenda')} />
          <NavItem id="nav-expenses" icon="M15 12H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" label="Despesas" active={activeView === 'expenses'} onClick={() => setActiveView('expenses')} />
          <div className="pt-4 pb-1 px-4 text-[9px] font-black uppercase tracking-[0.2em] text-indigo-500">Configurações</div>
          <NavItem id="nav-settings" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" label="Ajustes" active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
        </div>
        <div className="p-4 bg-indigo-900/20">
           <div className="flex items-center gap-3 p-3 bg-indigo-950/40 rounded-2xl border border-indigo-900/30">
              <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center font-bold text-lg italic shrink-0 overflow-hidden shadow-inner">
                {user.avatarUrl ? (
                  <img src={user.avatarUrl} alt="Logo" className="w-full h-full object-cover" />
                ) : (
                  <span className="text-white">{user.name.charAt(0)}</span>
                )}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-[10px] font-black truncate text-white uppercase">{user.name}</p>
                <p className="text-[8px] text-indigo-400 font-bold uppercase tracking-tighter">Premium Account</p>
              </div>
              <button onClick={handleLogout} className="text-indigo-400 hover:text-rose-400 transition transform hover:scale-110">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              </button>
           </div>
        </div>
      </nav>

      <main className="relative flex-1 p-4 md:p-8 overflow-y-auto h-screen z-10">
        <div className="max-w-6xl mx-auto pb-12 relative">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

const NavItem: React.FC<{ id?: string; icon: string; label: string; active: boolean; onClick: () => void; }> = ({ id, icon, label, active, onClick }) => (
  <button id={id} onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 ${active ? 'bg-indigo-600 text-white shadow-xl translate-x-1' : 'text-indigo-300 hover:bg-indigo-900/40 hover:text-white'}`}>
    <svg className="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={icon} /></svg>
    <span className={`text-sm font-bold tracking-tight whitespace-nowrap ${active ? 'font-black' : ''}`}>{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { Sale, Customer, PaymentStatus, Expense, Product } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DashboardProps {
  sales: Sale[];
  customers: Customer[];
  expenses: Expense[];
  products: Product[];
}

const Dashboard: React.FC<DashboardProps> = ({ sales, customers, expenses, products }) => {
  const [insights, setInsights] = useState<string>('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [showBreakdown, setShowBreakdown] = useState(false);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(value);
  };

  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  const totalFixedExpenses = expenses.reduce((acc, exp) => acc + exp.amount, 0);
  const totalStockValueAtSalesPrice = products.reduce((acc, p) => acc + (p.price * p.stock), 0);

  const getFinancialsForMonth = (month: number, year: number) => {
    return sales.reduce((acc, s) => {
      const saleDate = new Date(s.date);
      if (saleDate.getMonth() === month && saleDate.getFullYear() === year) {
        acc.grossRevenue += s.baseAmount;
        acc.discounts += s.discount;
        acc.cardFees += (s.cardFeeAmount || 0);
        acc.netRevenue += s.netAmount;
        acc.totalCostOfGoods += s.totalCost;
      }
      return acc;
    }, { grossRevenue: 0, discounts: 0, cardFees: 0, netRevenue: 0, totalCostOfGoods: 0 });
  };

  const currentMonthFinancials = getFinancialsForMonth(currentMonth, currentYear);
  const productProfit = currentMonthFinancials.netRevenue - currentMonthFinancials.totalCostOfGoods;
  const monthlyRealProfit = productProfit - totalFixedExpenses;

  const historyData = Array.from({ length: 6 }).map((_, i) => {
    const d = new Date();
    d.setMonth(d.getMonth() - (5 - i));
    const financials = getFinancialsForMonth(d.getMonth(), d.getFullYear());
    const profit = (financials.netRevenue - financials.totalCostOfGoods) - totalFixedExpenses;
    return {
      name: d.toLocaleString('pt-BR', { month: 'short' }).toUpperCase(),
      Faturamento: financials.netRevenue,
      Lucro: profit,
      fullName: d.toLocaleString('pt-BR', { month: 'long', year: 'numeric' })
    };
  });

  const totalReceivable = sales.reduce((acc, s) => {
    const totalInst = s.installments.reduce((sum, i) => sum + i.amount, 0);
    const paidInst = s.installments.reduce((sum, i) => sum + i.paidAmount, 0);
    const unpaidRatio = totalInst > 0 ? (totalInst - paidInst) / totalInst : 0;
    return acc + (s.netAmount * unpaidRatio);
  }, 0);

  const overdueSalesCount = sales.filter(s => 
    s.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date())
  ).length;

  const fetchInsights = async (force = false) => {
    if (!force && insights && insights !== 'Carregando insights...') return;
    if (sales.length === 0) {
      setInsights("Registre suas primeiras vendas para ver a análise da IA.");
      return;
    }
    setIsSyncing(true);
    setInsights("Analisando seus dados financeiros...");
    const result = await getFinancialInsights(sales, customers);
    setInsights(result || "Nenhum insight disponível.");
    setIsSyncing(false);
  };

  useEffect(() => {
    if (!insights) fetchInsights();
  }, [sales.length]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div className="backdrop-blur-sm bg-white/30 p-2 rounded-xl">
          <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase italic">Dashboard Financeiro</h2>
          <p className="text-sm text-slate-700 font-bold uppercase tracking-wider">Gestão Inteligente & Moda</p>
        </div>
        <button 
          onClick={() => setShowBreakdown(!showBreakdown)}
          className="bg-indigo-900 text-white px-6 py-3 rounded-xl text-xs font-black uppercase hover:bg-indigo-950 transition shadow-xl"
        >
          {showBreakdown ? 'Fechar Detalhamento' : 'DRE Detalhado'}
        </button>
      </div>

      {/* KPI Card de Estoque - Mais translúcido */}
      <div className="bg-indigo-900/90 backdrop-blur-md p-8 rounded-3xl shadow-2xl border border-indigo-400/20 text-white overflow-hidden relative">
          <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
            <div>
               <p className="text-indigo-200 text-[10px] font-black uppercase tracking-[0.2em] mb-1">Capital em Mercadoria (Venda)</p>
               <h3 className="text-5xl font-black tracking-tighter">{formatCurrency(totalStockValueAtSalesPrice)}</h3>
               <p className="text-[10px] text-indigo-300 mt-2 font-bold uppercase tracking-widest italic opacity-75">Investimento total pronto para retorno</p>
            </div>
            <div className="bg-white/10 p-5 rounded-3xl backdrop-blur-lg border border-white/20 shadow-inner">
               <p className="text-indigo-100 text-[9px] font-black uppercase tracking-widest mb-1">Total a Receber ("Rua")</p>
               <p className="text-2xl font-black text-white">{formatCurrency(totalReceivable)}</p>
            </div>
          </div>
          <div className="absolute -right-20 -top-20 w-64 h-64 bg-white/10 rounded-full blur-3xl pointer-events-none"></div>
      </div>

      {/* Grid de Cards com Transparência de Luxo */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white/70 backdrop-blur-md p-6 rounded-3xl shadow-xl border border-white/40 group hover:bg-white/90 transition-all duration-300">
          <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mb-1">Entradas Líquidas</p>
          <h3 className="text-2xl font-black text-slate-900">{formatCurrency(currentMonthFinancials.netRevenue)}</h3>
          <p className="text-[9px] text-indigo-600 mt-1 font-black uppercase tracking-tighter">Faturamento real do mês</p>
        </div>

        <div className="bg-white/70 backdrop-blur-md p-6 rounded-3xl shadow-xl border border-white/40 group hover:bg-white/90 transition-all duration-300">
          <p className="text-rose-500 text-[10px] font-black uppercase tracking-widest mb-1">Custo Vendido (CMV)</p>
          <h3 className="text-2xl font-black text-rose-600">{formatCurrency(currentMonthFinancials.totalCostOfGoods)}</h3>
          <p className="text-[9px] text-slate-500 mt-1 font-black uppercase tracking-tighter">Investimento nas peças vendidas</p>
        </div>

        <div className={`p-6 rounded-3xl shadow-2xl border-2 backdrop-blur-lg transition-all duration-300 ${monthlyRealProfit >= 0 ? 'bg-emerald-50/80 border-emerald-400/30' : 'bg-rose-50/80 border-rose-400/30'}`}>
          <p className="text-slate-600 text-[10px] font-black uppercase tracking-widest mb-1">Lucro Real Final</p>
          <h3 className={`text-2xl font-black ${monthlyRealProfit >= 0 ? 'text-emerald-700' : 'text-rose-700'}`}>
            {formatCurrency(monthlyRealProfit)}
          </h3>
          <p className="text-[9px] text-slate-500 mt-1 font-black uppercase tracking-tighter italic">Após abater despesas fixas</p>
        </div>
      </div>

      {showBreakdown && (
        <div className="bg-slate-900/95 backdrop-blur-xl text-white p-10 rounded-[3rem] shadow-2xl animate-in fade-in slide-in-from-top-4 duration-500 border border-white/10">
           <h4 className="text-xl font-black uppercase italic tracking-widest mb-8 text-indigo-400 border-b border-white/10 pb-4">Demonstrativo Financeiro (DRE)</h4>
           <div className="space-y-4 font-mono text-sm">
              <div className="flex justify-between border-b border-white/5 pb-2">
                 <span>(+) FATURAMENTO BRUTO</span>
                 <span className="font-bold">{formatCurrency(currentMonthFinancials.grossRevenue)}</span>
              </div>
              <div className="flex justify-between border-b border-white/5 pb-2 text-rose-400">
                 <span>(-) DESCONTOS & TAXAS</span>
                 <span>{formatCurrency(currentMonthFinancials.discounts + currentMonthFinancials.cardFees)}</span>
              </div>
              <div className="flex justify-between pt-2 text-indigo-300 font-black">
                 <span>(=) RECEITA LÍQUIDA</span>
                 <span>{formatCurrency(currentMonthFinancials.netRevenue)}</span>
              </div>
              <div className="flex justify-between border-b border-white/5 pb-2 text-rose-500 mt-6">
                 <span>(-) CUSTO DAS MERCADORIAS (CMV)</span>
                 <span>{formatCurrency(currentMonthFinancials.totalCostOfGoods)}</span>
              </div>
              <div className="flex justify-between border-b border-white/5 pb-2 text-rose-500 mt-2">
                 <span>(-) DESPESAS FIXAS DA LOJA</span>
                 <span>{formatCurrency(totalFixedExpenses)}</span>
              </div>
              <div className="flex justify-between pt-6 mt-6 border-t-4 border-indigo-500/30 text-3xl font-black text-emerald-400">
                 <span>LUCRO FINAL</span>
                 <span>{formatCurrency(monthlyRealProfit)}</span>
              </div>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white/80 backdrop-blur-md p-8 rounded-[2.5rem] shadow-xl border border-white/50">
          <h4 className="font-black text-slate-900 text-[10px] uppercase tracking-[0.3em] mb-8">Fluxo Semestral (Faturamento vs Lucro)</h4>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={historyData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={10} fontWeight="900" dy={10} stroke="#64748b" />
                <YAxis axisLine={false} tickLine={false} fontSize={10} fontWeight="900" stroke="#64748b" />
                <Tooltip 
                  cursor={{fill: 'rgba(255,255,255,0.4)'}} 
                  contentStyle={{ borderRadius: '24px', border: 'none', boxShadow: '0 25px 50px -12px rgba(0,0,0,0.25)', padding: '16px', fontWeight: '900', background: 'rgba(15, 23, 42, 0.9)', color: '#fff' }}
                  formatter={(value: number) => [formatCurrency(value), '']}
                />
                <Bar dataKey="Faturamento" fill="#4338ca" radius={[8, 8, 0, 0]} barSize={28} />
                <Bar dataKey="Lucro" fill="#059669" radius={[8, 8, 0, 0]} barSize={28} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white/80 backdrop-blur-md p-8 rounded-[2.5rem] shadow-xl border border-white/50">
