    localStorage.removeItem('gestao93_current_user');
    setUser(null);
    setActiveView('dashboard');
  };

  const handleAddSale = (s: Omit<Sale, 'id'>) => {
    const newId = Math.random().toString(36).substr(2, 9);
    setSales([...sales, { ...s, id: newId }]);

    // Reduzir estoque se houver produto vinculado
    if (s.productId) {
      setProducts(prev => prev.map(p => 
        p.id === s.productId ? { ...p, stock: Math.max(0, p.stock - 1) } : p
      ));
    }
  };

  const handleDeleteSale = (id: string) => {
    const saleToDelete = sales.find(s => s.id === id);
    if (!saleToDelete) return;

    if (window.confirm('Deseja excluir esta venda? Se houver produto vinculado, ele retornará ao estoque automaticamente.')) {
      // Se a venda tinha um produto do estoque, devolvemos 1 unidade
      if (saleToDelete.productId) {
        setProducts(prev => prev.map(p => 
          p.id === saleToDelete.productId ? { ...p, stock: p.stock + 1 } : p
        ));
      }
      setSales(sales.filter(s => s.id !== id));
    }
  };

  const clearUserData = () => {
    if (!user) return;
    const userId = user.id;
    localStorage.removeItem(`gestao93_customers_${userId}`);
    localStorage.removeItem(`gestao93_sales_${userId}`);
    localStorage.removeItem(`gestao93_expenses_${userId}`);
    localStorage.removeItem(`gestao93_products_${userId}`);
    setCustomers([]);
    setSales([]);
    setExpenses([]);
    setProducts([]);
    alert("Todos os seus dados foram apagados.");
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-indigo-950">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
          <h1 className="text-white font-black text-2xl italic uppercase tracking-tighter">Gestão 93</h1>
        </div>
      </div>
    );
  }

  if (!user) return <Landing onLogin={setUser} />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
      case 'customers': return <CustomerList customers={customers} sales={sales} onAdd={(c) => setCustomers([...customers, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])} onDelete={(id) => setCustomers(customers.filter(c => c.id !== id))} />;
      case 'sales-cash': return <SalesManager mode="cash" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={(s) => setSales(sales.map(sale => sale.id === s.id ? s : sale))} onDeleteSale={handleDeleteSale} />;
      case 'sales-credit': return <SalesManager mode="credit" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={(s) => setSales(sales.map(sale => sale.id === s.id ? s : sale))} onDeleteSale={handleDeleteSale} />;
      case 'inventory': return <InventoryManager products={products} onAdd={(p) => setProducts([...products, { ...p, id: Math.random().toString(36).substr(2, 9) }])} onDelete={(id) => setProducts(products.filter(p => p.id !== id))} onUpdate={(p) => setProducts(products.map(prod => prod.id === p.id ? p : prod))} />;
      case 'expenses': return <ExpenseManager expenses={expenses} onAdd={(description, amount) => setExpenses([...expenses, { id: Math.random().toString(36).substr(2, 9), description, amount }])} onDelete={(id) => setExpenses(expenses.filter(e => e.id !== id))} />;
      case 'agenda': return <Agenda sales={sales} customers={customers} />;
      case 'settings': return <Settings user={user} customers={customers} sales={sales} products={products} onUpdateProfile={(u) => { setUser(u); localStorage.setItem('gestao93_current_user', JSON.stringify(u)); }} onImport={(data) => { setCustomers(data.customers); setSales(data.sales); setProducts(data.products || []); }} onClear={clearUserData} />;
      default: return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div 
        className="fixed inset-0 pointer-events-none z-0 bg-cover bg-center bg-no-repeat"
        style={{ 
          backgroundImage: `url(${FASHION_IMAGE_URL})`,
          opacity: '0.50',
        }}
      />

      {showTutorial && <Tutorial activeView={activeView} onClose={() => { localStorage.setItem(`gestao93_tutorial_seen_${user.id}`, 'true'); setShowTutorial(false); }} />}

      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col shrink-0 z-50 shadow-2xl relative overflow-hidden">
        <div 
          className="absolute inset-0 pointer-events-none opacity-50 mix-blend-soft-light bg-cover bg-center"
          style={{ backgroundImage: `url(${FASHION_IMAGE_URL})` }}
        />

        <div className="relative z-10 p-6 flex items-center gap-3 border-b border-indigo-900/50">
          <div className="bg-indigo-600 p-2 rounded-xl shrink-0 shadow-lg border border-white/20">
             <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <div className="min-w-0">
            <h1 className="text-xl font-black tracking-tighter italic uppercase text-white truncate drop-shadow-md">Gestão 93</h1>
            <div className="flex items-center gap-1">
              <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-400' : 'bg-amber-400 animate-pulse'}`}></div>
              <span className="text-[8px] font-bold uppercase tracking-widest text-indigo-300 drop-shadow-sm">{syncStatus === 'synced' ? 'Salvo' : 'Sincronizando'}</span>
            </div>
          </div>
        </div>

        <div className="relative z-10 flex-1 py-4 space-y-1 px-3 overflow-y-auto no-scrollbar">
          <NavItem id="nav-dashboard" icon="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" label="Início" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem id="nav-inventory" icon="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" label="Estoque" active={activeView === 'inventory'} onClick={() => setActiveView('inventory')} />
          <NavItem id="nav-customers" icon="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 005.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" label="Clientes" active={activeView === 'customers'} onClick={() => setActiveView('customers')} />
          <div className="pt-4 pb-1 px-4 text-[9px] font-black uppercase tracking-[0.2em] text-indigo-400 drop-shadow-sm">Operacional</div>
          <NavItem id="nav-sales-cash" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" label="À Vista" active={activeView === 'sales-cash'} onClick={() => setActiveView('sales-cash')} />
          <NavItem id="nav-sales-credit" icon="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" label="A Prazo" active={activeView === 'sales-credit'} onClick={() => setActiveView('sales-credit')} />
          <NavItem id="nav-agenda" icon="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" label="Agenda" active={activeView === 'agenda'} onClick={() => setActiveView('agenda')} />
          <NavItem id="nav-expenses" icon="M15 12H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" label="Despesas" active={activeView === 'expenses'} onClick={() => setActiveView('expenses')} />
          <div className="pt-4 pb-1 px-4 text-[9px] font-black uppercase tracking-[0.2em] text-indigo-400 drop-shadow-sm">Configurações</div>
          <NavItem id="nav-settings" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" label="Ajustes" active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
        </div>

        <div className="relative z-10 p-4 bg-black/30 border-t border-indigo-900/50">
           <div className="flex items-center gap-3 p-3 bg-black/20 rounded-2xl border border-white/10 shadow-inner backdrop-blur-sm">
              <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center font-bold text-lg italic shrink-0 overflow-hidden shadow-lg border border-white/20">
                {user.avatarUrl ? (
                  <img src={user.avatarUrl} alt="Logo" className="w-full h-full object-cover" />
                ) : (
                  <span className="text-white">{user.name.charAt(0)}</span>
                )}
              </div>
              <div className="flex-1 min-w-0 text-shadow-sm">
                <p className="text-[10px] font-black truncate text-white uppercase">{user.name}</p>
                <p className="text-[8px] text-indigo-300 font-bold uppercase tracking-tighter">Boutique Premium</p>
              </div>
              <button onClick={handleLogout} className="text-indigo-200 hover:text-rose-400 transition transform hover:scale-110">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              </button>
           </div>
        </div>
      </nav>

      <main className="relative flex-1 p-4 md:p-8 overflow-y-auto h-screen z-10">
        <div className="max-w-6xl mx-auto pb-12 relative">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

const NavItem: React.FC<{ id?: string; icon: string; label: string; active: boolean; onClick: () => void; }> = ({ id, icon, label, active, onClick }) => (
  <button id={id} onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 relative group ${active ? 'bg-indigo-600 text-white shadow-xl translate-x-1 border border-white/10' : 'text-indigo-100 hover:bg-white/10 hover:text-white'}`}>
    <svg className="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={icon} /></svg>
    <span className={`text-sm font-bold tracking-tight whitespace-nowrap drop-shadow-sm ${active ? 'font-black' : ''}`}>{label}</span>
    {active && <div className="absolute right-3 w-1.5 h-1.5 bg-white rounded-full shadow-[0_0_8px_white]"></div>}
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { Customer, Sale, PaymentStatus, Installment, Product } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  products: Product[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
  onDeleteSale?: (id: string) => void;
  mode: 'cash' | 'credit';
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, products, onAddSale, onUpdateSale, onDeleteSale, mode }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [isBalcao, setIsBalcao] = useState(false);
  const [productId, setProductId] = useState('');
  const [description, setDescription] = useState('');

  const [baseAmount, setBaseAmount] = useState<number>(0);
  const [discount, setDiscount] = useState<number>(0);
  const [cardFeeRate, setCardFeeRate] = useState<number>(0);
  const [currentProductCost, setCurrentProductCost] = useState<number>(0);

  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [netAmount, setNetAmount] = useState<number>(0);

  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSaleId, setSelectedSaleId] = useState<string | null>(null);

  useEffect(() => {
    if (productId) {
      const p = products.find(prod => prod.id === productId);
      if (p) {
        setBaseAmount(p.price);
        setDescription(`${p.sku} - ${p.name}`);
        setCurrentProductCost(p.costPrice);
      }
    } else {
      setCurrentProductCost(0);
    }
  }, [productId, products]);

  useEffect(() => {
    const calculatedTotal = Math.max(0, baseAmount - discount);
    const feeAmount = (calculatedTotal * cardFeeRate) / 100;
    const calculatedNet = calculatedTotal - feeAmount;

    setTotalAmount(calculatedTotal);
    setNetAmount(calculatedNet);
  }, [baseAmount, discount, cardFeeRate]);

  const filteredSales = sales.filter(s => (s.type || 'credit') === mode);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    const finalCustomerId = isBalcao ? 'BALCAO' : customerId;

    if (!finalCustomerId || !description || totalAmount <= 0) {
      alert("Por favor, preencha todos os campos obrigatórios.");
      return;
    }

    if (productId) {
      const p = products.find(prod => prod.id === productId);
      if (p && p.stock <= 0) {
        if (!window.confirm("Produto sem estoque! Deseja continuar com a venda mesmo assim?")) return;
      }
    }

    const installments: Installment[] = [];
    const today = new Date();
    const cardFeeAmount = (totalAmount * cardFeeRate) / 100;

    if (mode === 'cash') {
      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: totalAmount,
        paidAmount: totalAmount,
        dueDate: today.toISOString().split('T')[0],
        status: PaymentStatus.PAID
      });
    } else {
      const installmentAmount = totalAmount / numInstallments;
      for (let i = 1; i <= numInstallments; i++) {
        const dueDate = calculateDueDate(today, i, dueDay);
        installments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: '', 
          amount: installmentAmount,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onAddSale({
      customerId: finalCustomerId,
      productId: productId || undefined,
      description,
      baseAmount,
      discount,
      totalAmount,
      cardFeeRate,
      cardFeeAmount,
      netAmount,
      totalCost: currentProductCost,
      date: today.toISOString().split('T')[0],
      installments,
      status: mode === 'cash' ? PaymentStatus.PAID : PaymentStatus.PENDING,
      type: mode
    });

    setShowAdd(false);
    resetForm();
  };

  const handleUpdateInstallment = (sale: Sale, installmentId: string, updates: Partial<Installment>) => {
    const updatedInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const newInst = { ...inst, ...updates };
        if (newInst.paidAmount >= newInst.amount) {
          newInst.status = PaymentStatus.PAID;
        } else if (newInst.paidAmount > 0) {
          newInst.status = PaymentStatus.PARTIAL;
        } else {
          newInst.status = PaymentStatus.PENDING;
        }
        return newInst;
      }
      return inst;
    });

    const allPaid = updatedInstallments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = updatedInstallments.some(i => i.status !== PaymentStatus.PENDING);
    const newStatus = allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING);

    onUpdateSale({
      ...sale,
      installments: updatedInstallments,
      status: newStatus
    });
  };

  const handleCancelSale = (id: string) => {
    if (onDeleteSale) {
      onDeleteSale(id);
    }
  };

  const calculateDueDate = (baseDate: Date, monthsToAdd: number, targetDay: number) => {
    let targetMonth = baseDate.getMonth() + monthsToAdd;
    let targetYear = baseDate.getFullYear();
    while (targetMonth > 11) { targetMonth -= 12; targetYear += 1; }
    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const resetForm = () => {
    setCustomerId('');
    setIsBalcao(false);
    setProductId('');
    setDescription('');
    setBaseAmount(0);
    setDiscount(0);
    setCardFeeRate(0);
    setCurrentProductCost(0);
    setNumInstallments(1);
    setDueDay(new Date().getDate());
  };

  const accentColor = mode === 'cash' ? 'emerald' : 'indigo';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800">{mode === 'cash' ? 'Venda À Vista' : 'Venda a Prazo'}</h2>
          <p className="text-xs text-slate-500 uppercase tracking-widest font-bold">Lançamento de {mode === 'cash' ? 'entrada imediata' : 'parcelamentos'}</p>
        </div>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className={`bg-${accentColor}-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-${accentColor}-700 transition shadow-sm`}
        >
          {showAdd ? 'Cancelar' : 'Nova Venda'}
        </button>
      </div>

      {showAdd && (
        <form onSubmit={handleAddSale} className={`bg-white p-6 rounded-2xl shadow-sm border border-${accentColor}-100 space-y-6 animate-in fade-in zoom-in duration-200`}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="md:col-span-1">
              <div className="flex justify-between items-center mb-1">
                <label className="block text-[10px] font-bold text-slate-400 uppercase">Cliente</label>
                <button type="button" onClick={() => setIsBalcao(!isBalcao)} className={`text-[10px] font-bold px-2 py-0.5 rounded transition ${isBalcao ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-500'}`}>
                  {isBalcao ? '✓ Venda Balcão' : 'Venda Balcão?'}
                </button>
              </div>
              {isBalcao ? (
                <div className="w-full bg-amber-50 border border-amber-200 rounded-lg px-3 py-2 text-sm text-amber-700 font-bold">🛒 Cliente Balcão</div>
              ) : (
                <select value={customerId} onChange={e => setCustomerId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none">
                  <option value="">Selecione o Cliente...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              )}
            </div>

            <div className="md:col-span-1">
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Produto (SKU - Nome)</label>
              <select value={productId} onChange={e => setProductId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none font-medium">
                  <option value="">-- Venda Avulsa / Sem Código --</option>
                  {products.map(p => <option key={p.id} value={p.id}>{p.sku} - {p.name} (Qtd: {p.stock})</option>)}
              </select>
            </div>

            <div className="md:col-span-1">
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Descrição do Item</label>
              <input type="text" value={description} onChange={e => setDescription(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Ex: Camiseta Básica P" />
            </div>

            <div className="space-y-4 md:col-span-3 bg-slate-50/50 p-4 rounded-xl border border-slate-100">
               <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Preço Venda (R$)</label>
                    <input type="number" step="0.01" value={baseAmount || ''} onChange={e => setBaseAmount(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Desconto (R$)</label>
                    <input type="number" step="0.01" value={discount || ''} onChange={e => setDiscount(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-rose-600 font-bold" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Taxa Cartão (%)</label>
                    <input type="number" step="0.1" value={cardFeeRate || ''} onChange={e => setCardFeeRate(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-amber-600 font-bold" />
                  </div>
                  <div className="flex flex-col justify-end">
                    <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Total Cliente</p>
                    <p className="text-xl font-black text-slate-900">R$ {totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-3 border-t border-slate-200">
                  <div className="text-xs text-slate-500 font-medium">
                     Custo Unitário Registrado: <span className="text-rose-600 font-bold">R$ {currentProductCost.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                  </div>
                  <div className="text-right text-emerald-600 font-bold text-sm">
                    Líquido Real: R$ {netAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </div>
               </div>
            </div>

            {mode === 'credit' && (
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Parcelas</label>
                  <input type="number" min="1" max="24" value={numInstallments} onChange={e => setNumInstallments(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Dia Venc.</label>
                  <input type="number" min="1" max="31" value={dueDay} onChange={e => setDueDay(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                </div>
              </div>
            )}
          </div>
          <div className="flex justify-end pt-2 border-t border-slate-50">
            <button type="submit" className={`px-8 py-3 rounded-xl text-sm font-bold uppercase tracking-widest transition shadow-lg bg-${accentColor}-600 text-white hover:bg-${accentColor}-700`}>
              Confirmar Venda {mode === 'cash' ? 'À Vista' : 'a Prazo'}
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {filteredSales.map(sale => {
           const saleProfit = sale.netAmount - sale.totalCost;
           const profitMargin = sale.netAmount > 0 ? (saleProfit / sale.netAmount) * 100 : 0;
           const isExpanded = selectedSaleId === sale.id;

           return (
            <div key={sale.id} className={`bg-white rounded-2xl shadow-sm border transition ${isExpanded ? 'border-indigo-400 shadow-md ring-1 ring-indigo-50' : 'border-slate-100 hover:border-indigo-200'}`}>
               <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                  <div className="flex items-start gap-3">
                    <div className={`mt-1 p-2 rounded-lg ${sale.customerId === 'BALCAO' ? 'bg-amber-100 text-amber-600' : mode === 'cash' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
                      </svg>
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-800 leading-tight">{customers.find(c => c.id === sale.customerId)?.name || '🛒 Cliente Balcão'}</h3>
                      <p className="text-xs text-slate-500 mb-1">{sale.description}</p>
                      <div className="flex items-center gap-3">
                        <span className="text-[10px] font-bold uppercase text-slate-400">{new Date(sale.date).toLocaleDateString('pt-BR')}</span>
                        <div className="flex items-center gap-1.5">
                           <span className={`text-[10px] font-black uppercase px-2 py-0.5 rounded ${saleProfit >= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                             Lucro: R$ {saleProfit.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                           </span>
                           <span className="text-[10px] font-bold text-slate-300">({profitMargin.toFixed(0)}%)</span>
                        </div>
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 ml-auto">
                    <div className="text-right">
                      <p className="text-lg font-black text-slate-900 leading-none mb-1">R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                      <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded tracking-tighter ${sale.status === PaymentStatus.PAID ? 'bg-emerald-500 text-white' : 'bg-amber-400 text-amber-950'}`}>
                        {sale.status === PaymentStatus.PAID ? 'Pago' : sale.status === PaymentStatus.PARTIAL ? 'Parcial' : 'Pendente'}
                      </span>
                    </div>
                    <button onClick={() => setSelectedSaleId(isExpanded ? null : sale.id)} className="p-2 text-slate-400 hover:text-indigo-600 transition">
                       <svg className={`w-5 h-5 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                    </button>
                  </div>
               </div>

               {isExpanded && (
                  <div className="px-5 pb-5 pt-4 border-t border-slate-50 bg-slate-50/50 animate-in slide-in-from-top-1 duration-200 space-y-4">
                     <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-slate-400 uppercase mb-1">Faturamento Bruto</p>
                           <p className="text-sm font-bold text-slate-700">R$ {sale.baseAmount.toFixed(2)}</p>
                        </div>
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-indigo-400 uppercase mb-1">Líquido (Pós Taxas)</p>
                           <p className="text-sm font-bold text-indigo-600">R$ {sale.netAmount.toFixed(2)}</p>
                        </div>
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-rose-400 uppercase mb-1">Custo do Produto</p>
                           <p className="text-sm font-bold text-rose-500">R$ {sale.totalCost.toFixed(2)}</p>
                        </div>
                        <div className="bg-emerald-600 p-3 rounded-xl shadow-md">
                           <p className="text-[9px] font-bold text-emerald-100 uppercase mb-1">Ganho Real (Lucro)</p>
                           <p className="text-sm font-black text-white">R$ {saleProfit.toFixed(2)}</p>
                        </div>
                     </div>

                     <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
                        <div className="p-3 bg-slate-100 border-b border-slate-200 flex justify-between items-center">
                           <h4 className="text-[10px] font-black uppercase text-slate-600 tracking-widest">Controle de Parcelas / Recebimentos</h4>
                           <button 
                            onClick={() => handleCancelSale(sale.id)}
                            className="flex items-center gap-1.5 text-[9px] font-black uppercase text-rose-500 hover:text-rose-700 transition"
                           >
                            <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                            Cancelar Venda & Estornar
                           </button>
                        </div>
                        <div className="overflow-x-auto">
                           <table className="w-full text-left text-xs">
                              <thead>
                                 <tr className="bg-slate-50 text-slate-400 font-bold uppercase text-[9px]">
                                    <th className="px-4 py-2">Parc.</th>
                                    <th className="px-4 py-2">Vencimento</th>
                                    <th className="px-4 py-2">Valor Parcela (R$)</th>
                                    <th className="px-4 py-2">Valor Pago (R$)</th>
                                    <th className="px-4 py-2">Status</th>
                                 </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-100">
                                 {sale.installments.map((inst, idx) => (
                                    <tr key={inst.id} className="hover:bg-indigo-50/30 transition">
                                       <td className="px-4 py-2 font-black text-slate-400">{idx + 1}ª</td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="date" 
                                             value={inst.dueDate} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { dueDate: e.target.value })}
                                             className="bg-transparent border-none p-0 text-xs font-bold text-slate-700 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="number" 
                                             step="0.01"
                                             value={inst.amount} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { amount: Number(e.target.value) })}
                                             className="bg-transparent border-none p-0 text-xs font-black text-slate-900 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="number" 
                                             step="0.01"
                                             value={inst.paidAmount} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { paidAmount: Number(e.target.value) })}
                                             className={`bg-transparent border-none p-0 text-xs font-black focus:ring-0 w-full ${inst.paidAmount >= inst.amount ? 'text-emerald-600' : inst.paidAmount > 0 ? 'text-amber-600' : 'text-slate-400'}`}
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <span className={`text-[8px] font-black uppercase px-1.5 py-0.5 rounded ${
                                             inst.status === PaymentStatus.PAID ? 'bg-emerald-100 text-emerald-700' :
                                             inst.status === PaymentStatus.PARTIAL ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-400'
                                          }`}>
                                             {inst.status === PaymentStatus.PAID ? 'Pago' : inst.status === PaymentStatus.PARTIAL ? 'Parcial' : 'Aberto'}
                                          </span>
                                       </td>
                                    </tr>
                                 ))}
                              </tbody>
                           </table>
                        </div>
                     </div>
                  </div>
               )}
            </div>
           );
        })}
        {filteredSales.length === 0 && (
          <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-slate-200 text-slate-400 text-sm">
             Nenhuma venda registrada nesta modalidade.
          </div>
        )}
      </div>
    </div>
  );
};

export default SalesManager;

export interface User {
  id: string;
  name: string;
  email: string;
  password?: string;
  authProvider?: 'local' | 'onedrive';
  avatarUrl?: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  address?: string;
  cpf?: string;
  createdAt: number;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
}

export interface Product {
  id: string;
  sku: string;        // Código do produto
  name: string;
  category: string;
  costPrice: number;  // Preço de custo
  price: number;      // Preço de venda
  stock: number;
  minStock: number;
}

export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  PARTIAL = 'PARTIAL',
  CANCELED = 'CANCELED'
}

export interface Installment {
  id: string;
  saleId: string;
  amount: number;
  paidAmount: number;
  dueDate: string;
  paymentDate?: string; // Data em que o pagamento foi realizado
  status: PaymentStatus;
}

export interface Sale {
  id: string;
  customerId: string;
  description: string;
  baseAmount: number;
  discount: number;
  totalAmount: number;
  cardFeeRate?: number;
  cardFeeAmount?: number;
  netAmount: number;
  totalCost: number;   // Custo total dos produtos nesta venda para cálculo de lucro
  date: string;
  installments: Installment[];
  status: PaymentStatus;
  type?: 'cash' | 'credit';
  productId?: string;
}

export type View = 'dashboard' | 'customers' | 'sales-cash' | 'sales-credit' | 'agenda' | 'settings' | 'expenses' | 'inventory';

import React, { useState, useEffect } from 'react';
import { Customer, Sale, PaymentStatus, Installment, Product } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  products: Product[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
  onDeleteSale?: (id: string) => void;
  mode: 'cash' | 'credit';
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, products, onAddSale, onUpdateSale, onDeleteSale, mode }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [isBalcao, setIsBalcao] = useState(false);
  const [productId, setProductId] = useState('');
  const [description, setDescription] = useState('');

  const [baseAmount, setBaseAmount] = useState<number>(0);
  const [discount, setDiscount] = useState<number>(0);
  const [cardFeeRate, setCardFeeRate] = useState<number>(0);
  const [currentProductCost, setCurrentProductCost] = useState<number>(0);

  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [netAmount, setNetAmount] = useState<number>(0);

  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSaleId, setSelectedSaleId] = useState<string | null>(null);

  useEffect(() => {
    if (productId) {
      const p = products.find(prod => prod.id === productId);
      if (p) {
        setBaseAmount(p.price);
        setDescription(`${p.sku} - ${p.name}`);
        setCurrentProductCost(p.costPrice);
      }
    } else {
      setCurrentProductCost(0);
    }
  }, [productId, products]);

  useEffect(() => {
    const calculatedTotal = Math.max(0, baseAmount - discount);
    const feeAmount = (calculatedTotal * cardFeeRate) / 100;
    const calculatedNet = calculatedTotal - feeAmount;

    setTotalAmount(calculatedTotal);
    setNetAmount(calculatedNet);
  }, [baseAmount, discount, cardFeeRate]);

  const filteredSales = sales.filter(s => (s.type || 'credit') === mode);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    const finalCustomerId = isBalcao ? 'BALCAO' : customerId;

    if (!finalCustomerId || !description || totalAmount <= 0) {
      alert("Por favor, preencha todos os campos obrigatórios.");
      return;
    }

    if (productId) {
      const p = products.find(prod => prod.id === productId);
      if (p && p.stock <= 0) {
        if (!window.confirm("Produto sem estoque! Deseja continuar com a venda mesmo assim?")) return;
      }
    }

    const installments: Installment[] = [];
    const today = new Date();
    const todayStr = today.toISOString().split('T')[0];

    if (mode === 'cash') {
      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: totalAmount,
        paidAmount: totalAmount,
        dueDate: todayStr,
        paymentDate: todayStr,
        status: PaymentStatus.PAID
      });
    } else {
      const installmentAmount = totalAmount / numInstallments;
      for (let i = 1; i <= numInstallments; i++) {
        const dueDate = calculateDueDate(today, i, dueDay);
        installments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: '', 
          amount: installmentAmount,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onAddSale({
      customerId: finalCustomerId,
      productId: productId || undefined,
      description,
      baseAmount,
      discount,
      totalAmount,
      cardFeeRate,
      cardFeeAmount: (totalAmount * cardFeeRate) / 100,
      netAmount,
      totalCost: currentProductCost,
      date: todayStr,
      installments,
      status: mode === 'cash' ? PaymentStatus.PAID : PaymentStatus.PENDING,
      type: mode
    });

    setShowAdd(false);
    resetForm();
  };

  const handleUpdateInstallment = (sale: Sale, installmentId: string, updates: Partial<Installment>) => {
    const updatedInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const newInst = { ...inst, ...updates };

        // Se o valor pago for igual ou maior que o valor da parcela, status é PAGO
        if (newInst.paidAmount >= newInst.amount) {
          newInst.status = PaymentStatus.PAID;
          // Se não tiver data de pagamento mas está pago, coloca hoje
          if (!newInst.paymentDate) {
            newInst.paymentDate = new Date().toISOString().split('T')[0];
          }
        } else if (newInst.paidAmount > 0) {
          newInst.status = PaymentStatus.PARTIAL;
        } else {
          newInst.status = PaymentStatus.PENDING;
          newInst.paymentDate = undefined;
        }
        return newInst;
      }
      return inst;
    });

    const allPaid = updatedInstallments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = updatedInstallments.some(i => i.status !== PaymentStatus.PENDING);
    const newStatus = allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING);

    onUpdateSale({
      ...sale,
      installments: updatedInstallments,
      status: newStatus
    });
  };

  const handleQuickSettle = (sale: Sale, inst: Installment) => {
    handleUpdateInstallment(sale, inst.id, { 
      paidAmount: inst.amount, 
      paymentDate: new Date().toISOString().split('T')[0] 
    });
  };

  const handleCancelSale = (id: string) => {
    if (onDeleteSale) {
      onDeleteSale(id);
    }
  };

  const calculateDueDate = (baseDate: Date, monthsToAdd: number, targetDay: number) => {
    let targetMonth = baseDate.getMonth() + monthsToAdd;
    let targetYear = baseDate.getFullYear();
    while (targetMonth > 11) { targetMonth -= 12; targetYear += 1; }
    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const resetForm = () => {
    setCustomerId('');
    setIsBalcao(false);
    setProductId('');
    setDescription('');
    setBaseAmount(0);
    setDiscount(0);
    setCardFeeRate(0);
    setCurrentProductCost(0);
    setNumInstallments(1);
    setDueDay(new Date().getDate());
  };

  const accentColor = mode === 'cash' ? 'emerald' : 'indigo';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800">{mode === 'cash' ? 'Venda À Vista' : 'Venda a Prazo'}</h2>
          <p className="text-xs text-slate-500 uppercase tracking-widest font-bold">Lançamento de {mode === 'cash' ? 'entrada imediata' : 'parcelamentos'}</p>
        </div>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className={`bg-${accentColor}-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-${accentColor}-700 transition shadow-sm`}
        >
          {showAdd ? 'Cancelar' : 'Nova Venda'}
        </button>
      </div>

      {showAdd && (
        <form onSubmit={handleAddSale} className={`bg-white p-6 rounded-2xl shadow-sm border border-${accentColor}-100 space-y-6 animate-in fade-in zoom-in duration-200`}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="md:col-span-1">
              <div className="flex justify-between items-center mb-1">
                <label className="block text-[10px] font-bold text-slate-400 uppercase">Cliente</label>
                <button type="button" onClick={() => setIsBalcao(!isBalcao)} className={`text-[10px] font-bold px-2 py-0.5 rounded transition ${isBalcao ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-500'}`}>
                  {isBalcao ? '✓ Venda Balcão' : 'Venda Balcão?'}
                </button>
              </div>
              {isBalcao ? (
                <div className="w-full bg-amber-50 border border-amber-200 rounded-lg px-3 py-2 text-sm text-amber-700 font-bold">🛒 Cliente Balcão</div>
              ) : (
                <select value={customerId} onChange={e => setCustomerId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none">
                  <option value="">Selecione o Cliente...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              )}
            </div>

            <div className="md:col-span-1">
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Produto (SKU - Nome)</label>
              <select value={productId} onChange={e => setProductId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none font-medium">
                  <option value="">-- Venda Avulsa / Sem Código --</option>
                  {products.map(p => <option key={p.id} value={p.id}>{p.sku} - {p.name} (Qtd: {p.stock})</option>)}
              </select>
            </div>

            <div className="md:col-span-1">
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Descrição do Item</label>
              <input type="text" value={description} onChange={e => setDescription(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Ex: Camiseta Básica P" />
            </div>

            <div className="space-y-4 md:col-span-3 bg-slate-50/50 p-4 rounded-xl border border-slate-100">
               <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Preço Venda (R$)</label>
                    <input type="number" step="0.01" value={baseAmount || ''} onChange={e => setBaseAmount(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Desconto (R$)</label>
                    <input type="number" step="0.01" value={discount || ''} onChange={e => setDiscount(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-rose-600 font-bold" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Taxa Cartão (%)</label>
                    <input type="number" step="0.1" value={cardFeeRate || ''} onChange={e => setCardFeeRate(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-amber-600 font-bold" />
                  </div>
                  <div className="flex flex-col justify-end">
                    <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Total Cliente</p>
                    <p className="text-xl font-black text-slate-900">R$ {totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-3 border-t border-slate-200">
                  <div className="text-xs text-slate-500 font-medium">
                     Custo Unitário Registrado: <span className="text-rose-600 font-bold">R$ {currentProductCost.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                  </div>
                  <div className="text-right text-emerald-600 font-bold text-sm">
                    Líquido Real: R$ {netAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </div>
               </div>
            </div>

            {mode === 'credit' && (
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Parcelas</label>
                  <input type="number" min="1" max="24" value={numInstallments} onChange={e => setNumInstallments(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Dia Venc.</label>
                  <input type="number" min="1" max="31" value={dueDay} onChange={e => setDueDay(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                </div>
              </div>
            )}
          </div>
          <div className="flex justify-end pt-2 border-t border-slate-50">
            <button type="submit" className={`px-8 py-3 rounded-xl text-sm font-bold uppercase tracking-widest transition shadow-lg bg-${accentColor}-600 text-white hover:bg-${accentColor}-700`}>
              Confirmar Venda {mode === 'cash' ? 'À Vista' : 'a Prazo'}
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {filteredSales.map(sale => {
           const saleProfit = sale.netAmount - sale.totalCost;
           const profitMargin = sale.netAmount > 0 ? (saleProfit / sale.netAmount) * 100 : 0;
           const isExpanded = selectedSaleId === sale.id;

           return (
            <div key={sale.id} className={`bg-white rounded-2xl shadow-sm border transition ${isExpanded ? 'border-indigo-400 shadow-md ring-1 ring-indigo-50' : 'border-slate-100 hover:border-indigo-200'}`}>
               <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                  <div className="flex items-start gap-3">
                    <div className={`mt-1 p-2 rounded-lg ${sale.customerId === 'BALCAO' ? 'bg-amber-100 text-amber-600' : mode === 'cash' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
                      </svg>
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-800 leading-tight">{customers.find(c => c.id === sale.customerId)?.name || '🛒 Cliente Balcão'}</h3>
                      <p className="text-xs text-slate-500 mb-1">{sale.description}</p>
                      <div className="flex items-center gap-3">
                        <span className="text-[10px] font-bold uppercase text-slate-400">{new Date(sale.date).toLocaleDateString('pt-BR')}</span>
                        <div className="flex items-center gap-1.5">
                           <span className={`text-[10px] font-black uppercase px-2 py-0.5 rounded ${saleProfit >= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                             Lucro: R$ {saleProfit.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                           </span>
                           <span className="text-[10px] font-bold text-slate-300">({profitMargin.toFixed(0)}%)</span>
                        </div>
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 ml-auto">
                    <div className="text-right">
                      <p className="text-lg font-black text-slate-900 leading-none mb-1">R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                      <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded tracking-tighter ${sale.status === PaymentStatus.PAID ? 'bg-emerald-500 text-white' : 'bg-amber-400 text-amber-950'}`}>
                        {sale.status === PaymentStatus.PAID ? 'Pago' : sale.status === PaymentStatus.PARTIAL ? 'Parcial' : 'Pendente'}
                      </span>
                    </div>
                    <button onClick={() => setSelectedSaleId(isExpanded ? null : sale.id)} className="p-2 text-slate-400 hover:text-indigo-600 transition">
                       <svg className={`w-5 h-5 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                    </button>
                  </div>
               </div>

               {isExpanded && (
                  <div className="px-5 pb-5 pt-4 border-t border-slate-50 bg-slate-50/50 animate-in slide-in-from-top-1 duration-200 space-y-4">
                     <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-slate-400 uppercase mb-1">Faturamento Bruto</p>
                           <p className="text-sm font-bold text-slate-700">R$ {sale.baseAmount.toFixed(2)}</p>
                        </div>
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-indigo-400 uppercase mb-1">Líquido (Pós Taxas)</p>
                           <p className="text-sm font-bold text-indigo-600">R$ {sale.netAmount.toFixed(2)}</p>
                        </div>
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-rose-400 uppercase mb-1">Custo do Produto</p>
                           <p className="text-sm font-bold text-rose-500">R$ {sale.totalCost.toFixed(2)}</p>
                        </div>
                        <div className="bg-emerald-600 p-3 rounded-xl shadow-md">
                           <p className="text-[9px] font-bold text-emerald-100 uppercase mb-1">Ganho Real (Lucro)</p>
                           <p className="text-sm font-black text-white">R$ {saleProfit.toFixed(2)}</p>
                        </div>
                     </div>

                     <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
                        <div className="p-3 bg-slate-100 border-b border-slate-200 flex justify-between items-center">
                           <h4 className="text-[10px] font-black uppercase text-slate-600 tracking-widest">Controle de Recebimentos (Modificar Datas e Valores)</h4>
                           <button 
                            onClick={() => handleCancelSale(sale.id)}
                            className="flex items-center gap-1.5 text-[9px] font-black uppercase text-rose-500 hover:text-rose-700 transition"
                           >
                            <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                            Cancelar Venda & Estornar
                           </button>
                        </div>
                        <div className="overflow-x-auto">
                           <table className="w-full text-left text-xs">
                              <thead>
                                 <tr className="bg-slate-50 text-slate-400 font-bold uppercase text-[9px]">
                                    <th className="px-4 py-2">Parc.</th>
                                    <th className="px-4 py-2">Vencimento</th>
                                    <th className="px-4 py-2">Valor Parcela</th>
                                    <th className="px-4 py-2">Valor Pago</th>
                                    <th className="px-4 py-2">Data Recebimento</th>
                                    <th className="px-4 py-2 text-center">Ações</th>
                                 </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-100">
                                 {sale.installments.map((inst, idx) => (
                                    <tr key={inst.id} className="hover:bg-indigo-50/30 transition">
                                       <td className="px-4 py-2 font-black text-slate-400">{idx + 1}ª</td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="date" 
                                             value={inst.dueDate} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { dueDate: e.target.value })}
                                             className="bg-transparent border-none p-0 text-xs font-bold text-slate-700 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="number" 
                                             step="0.01"
                                             value={inst.amount} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { amount: Number(e.target.value) })}
                                             className="bg-transparent border-none p-0 text-xs font-black text-slate-900 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="number" 
                                             step="0.01"
                                             value={inst.paidAmount} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { paidAmount: Number(e.target.value) })}
                                             className={`bg-transparent border-none p-0 text-xs font-black focus:ring-0 w-full ${inst.paidAmount >= inst.amount ? 'text-emerald-600' : inst.paidAmount > 0 ? 'text-amber-600' : 'text-slate-400'}`}
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="date" 
                                             value={inst.paymentDate || ''} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { paymentDate: e.target.value })}
                                             className="bg-transparent border-none p-0 text-[10px] font-bold text-emerald-600 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2 text-center">
                                          {inst.status !== PaymentStatus.PAID ? (
                                             <button 
                                                onClick={() => handleQuickSettle(sale, inst)}
                                                className="bg-emerald-500 hover:bg-emerald-600 text-white text-[9px] font-black uppercase px-2 py-1 rounded transition shadow-sm"
                                             >
                                                Quitar
                                             </button>
                                          ) : (
                                             <span className="text-emerald-500">
                                                <svg className="w-4 h-4 mx-auto" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                                             </span>
                                          )}
                                       </td>
                                    </tr>
                                 ))}
                              </tbody>
                           </table>
                        </div>
                     </div>
                  </div>
               )}
            </div>
           );
        })}
        {filteredSales.length === 0 && (
          <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-slate-200 text-slate-400 text-sm">
             Nenhuma venda registrada nesta modalidade.
          </div>
        )}
      </div>
    </div>
  );
};

export default SalesManager;

import React, { useState, useEffect } from 'react';
import { Customer, Sale, PaymentStatus, Installment, Product } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  products: Product[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
  onDeleteSale?: (id: string) => void;
  mode: 'cash' | 'credit';
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, products, onAddSale, onUpdateSale, onDeleteSale, mode }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [isBalcao, setIsBalcao] = useState(false);
  const [productId, setProductId] = useState('');
  const [description, setDescription] = useState('');

  const [baseAmount, setBaseAmount] = useState<number>(0);
  const [discount, setDiscount] = useState<number>(0);
  const [cardFeeRate, setCardFeeRate] = useState<number>(0);
  const [currentProductCost, setCurrentProductCost] = useState<number>(0);

  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [netAmount, setNetAmount] = useState<number>(0);

  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSaleId, setSelectedSaleId] = useState<string | null>(null);
  const [newInstallmentCount, setNewInstallmentCount] = useState<number>(1);

  useEffect(() => {
    if (productId) {
      const p = products.find(prod => prod.id === productId);
      if (p) {
        setBaseAmount(p.price);
        setDescription(`${p.sku} - ${p.name}`);
        setCurrentProductCost(p.costPrice);
      }
    } else {
      setCurrentProductCost(0);
    }
  }, [productId, products]);

  useEffect(() => {
    const calculatedTotal = Math.max(0, baseAmount - discount);
    const feeAmount = (calculatedTotal * cardFeeRate) / 100;
    const calculatedNet = calculatedTotal - feeAmount;

    setTotalAmount(calculatedTotal);
    setNetAmount(calculatedNet);
  }, [baseAmount, discount, cardFeeRate]);

  const filteredSales = sales.filter(s => (s.type || 'credit') === mode);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    const finalCustomerId = isBalcao ? 'BALCAO' : customerId;

    if (!finalCustomerId || !description || totalAmount <= 0) {
      alert("Por favor, preencha todos os campos obrigatórios.");
      return;
    }

    if (productId) {
      const p = products.find(prod => prod.id === productId);
      if (p && p.stock <= 0) {
        if (!window.confirm("Produto sem estoque! Deseja continuar com a venda mesmo assim?")) return;
      }
    }

    const installments: Installment[] = [];
    const today = new Date();
    const todayStr = today.toISOString().split('T')[0];

    if (mode === 'cash') {
      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: totalAmount,
        paidAmount: totalAmount,
        dueDate: todayStr,
        paymentDate: todayStr,
        status: PaymentStatus.PAID
      });
    } else {
      const installmentAmount = totalAmount / numInstallments;
      for (let i = 1; i <= numInstallments; i++) {
        const dueDate = calculateDueDate(today, i, dueDay);
        installments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: '', 
          amount: installmentAmount,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onAddSale({
      customerId: finalCustomerId,
      productId: productId || undefined,
      description,
      baseAmount,
      discount,
      totalAmount,
      cardFeeRate,
      cardFeeAmount: (totalAmount * cardFeeRate) / 100,
      netAmount,
      totalCost: currentProductCost,
      date: todayStr,
      installments,
      status: mode === 'cash' ? PaymentStatus.PAID : PaymentStatus.PENDING,
      type: mode
    });

    setShowAdd(false);
    resetForm();
  };

  const handleUpdateInstallment = (sale: Sale, installmentId: string, updates: Partial<Installment>) => {
    const updatedInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const newInst = { ...inst, ...updates };
        if (newInst.paidAmount >= newInst.amount) {
          newInst.status = PaymentStatus.PAID;
          if (!newInst.paymentDate) {
            newInst.paymentDate = new Date().toISOString().split('T')[0];
          }
        } else if (newInst.paidAmount > 0) {
          newInst.status = PaymentStatus.PARTIAL;
        } else {
          newInst.status = PaymentStatus.PENDING;
          newInst.paymentDate = undefined;
        }
        return newInst;
      }
      return inst;
    });

    const allPaid = updatedInstallments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = updatedInstallments.some(i => i.status !== PaymentStatus.PENDING);
    const newStatus = allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING);

    onUpdateSale({
      ...sale,
      installments: updatedInstallments,
      status: newStatus
    });
  };

  const handleRescheduleInstallments = (sale: Sale) => {
    if (newInstallmentCount < 1) return;
    if (!window.confirm(`Isso irá apagar as parcelas atuais e criar ${newInstallmentCount} novas parcelas de R$ ${(sale.totalAmount / newInstallmentCount).toFixed(2)}. Deseja continuar?`)) return;

    const newInstallments: Installment[] = [];
    const baseDate = new Date(sale.date);
    const targetDay = baseDate.getDate();
    const installmentAmount = sale.totalAmount / newInstallmentCount;

    for (let i = 1; i <= newInstallmentCount; i++) {
      const dueDate = calculateDueDate(baseDate, i, targetDay);
      newInstallments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: sale.id,
        amount: installmentAmount,
        paidAmount: 0,
        dueDate: dueDate.toISOString().split('T')[0],
        status: PaymentStatus.PENDING
      });
    }

    onUpdateSale({
      ...sale,
      installments: newInstallments,
      status: PaymentStatus.PENDING
    });
  };

  const handleQuickSettle = (sale: Sale, inst: Installment) => {
    handleUpdateInstallment(sale, inst.id, { 
      paidAmount: inst.amount, 
      paymentDate: new Date().toISOString().split('T')[0] 
    });
  };

  const handleCancelSale = (id: string) => {
    if (onDeleteSale) {
      onDeleteSale(id);
    }
  };

  const calculateDueDate = (baseDate: Date, monthsToAdd: number, targetDay: number) => {
    let targetMonth = baseDate.getMonth() + monthsToAdd;
    let targetYear = baseDate.getFullYear();
    while (targetMonth > 11) { targetMonth -= 12; targetYear += 1; }
    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const resetForm = () => {
    setCustomerId('');
    setIsBalcao(false);
    setProductId('');
    setDescription('');
    setBaseAmount(0);
    setDiscount(0);
    setCardFeeRate(0);
    setCurrentProductCost(0);
    setNumInstallments(1);
    setDueDay(new Date().getDate());
  };

  const accentColor = mode === 'cash' ? 'emerald' : 'indigo';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800">{mode === 'cash' ? 'Venda À Vista' : 'Venda a Prazo'}</h2>
          <p className="text-xs text-slate-500 uppercase tracking-widest font-bold">Lançamento de {mode === 'cash' ? 'entrada imediata' : 'parcelamentos'}</p>
        </div>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className={`bg-${accentColor}-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-${accentColor}-700 transition shadow-sm`}
        >
          {showAdd ? 'Cancelar' : 'Nova Venda'}
        </button>
      </div>

      {showAdd && (
        <form onSubmit={handleAddSale} className={`bg-white p-6 rounded-2xl shadow-sm border border-${accentColor}-100 space-y-6 animate-in fade-in zoom-in duration-200`}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="md:col-span-1">
              <div className="flex justify-between items-center mb-1">
                <label className="block text-[10px] font-bold text-slate-400 uppercase">Cliente</label>
                <button type="button" onClick={() => setIsBalcao(!isBalcao)} className={`text-[10px] font-bold px-2 py-0.5 rounded transition ${isBalcao ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-500'}`}>
                  {isBalcao ? '✓ Venda Balcão' : 'Venda Balcão?'}
                </button>
              </div>
              {isBalcao ? (
                <div className="w-full bg-amber-50 border border-amber-200 rounded-lg px-3 py-2 text-sm text-amber-700 font-bold">🛒 Cliente Balcão</div>
              ) : (
                <select value={customerId} onChange={e => setCustomerId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none">
                  <option value="">Selecione o Cliente...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              )}
            </div>

            <div className="md:col-span-1">
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Produto (SKU - Nome)</label>
              <select value={productId} onChange={e => setProductId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none font-medium">
                  <option value="">-- Venda Avulsa / Sem Código --</option>
                  {products.map(p => <option key={p.id} value={p.id}>{p.sku} - {p.name} (Qtd: {p.stock})</option>)}
              </select>
            </div>

            <div className="md:col-span-1">
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Descrição do Item</label>
              <input type="text" value={description} onChange={e => setDescription(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Ex: Camiseta Básica P" />
            </div>

            <div className="space-y-4 md:col-span-3 bg-slate-50/50 p-4 rounded-xl border border-slate-100">
               <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Preço Venda (R$)</label>
                    <input type="number" step="0.01" value={baseAmount || ''} onChange={e => setBaseAmount(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Desconto (R$)</label>
                    <input type="number" step="0.01" value={discount || ''} onChange={e => setDiscount(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-rose-600 font-bold" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Taxa Cartão (%)</label>
                    <input type="number" step="0.1" value={cardFeeRate || ''} onChange={e => setCardFeeRate(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-amber-600 font-bold" />
                  </div>
                  <div className="flex flex-col justify-end">
                    <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Total Cliente</p>
                    <p className="text-xl font-black text-slate-900">R$ {totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-3 border-t border-slate-200">
                  <div className="text-xs text-slate-500 font-medium">
                     Custo Unitário Registrado: <span className="text-rose-600 font-bold">R$ {currentProductCost.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                  </div>
                  <div className="text-right text-emerald-600 font-bold text-sm">
                    Líquido Real: R$ {netAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </div>
               </div>
            </div>

            {mode === 'credit' && (
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Parcelas</label>
                  <input type="number" min="1" max="24" value={numInstallments} onChange={e => setNumInstallments(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Dia Venc.</label>
                  <input type="number" min="1" max="31" value={dueDay} onChange={e => setDueDay(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                </div>
              </div>
            )}
          </div>
          <div className="flex justify-end pt-2 border-t border-slate-50">
            <button type="submit" className={`px-8 py-3 rounded-xl text-sm font-bold uppercase tracking-widest transition shadow-lg bg-${accentColor}-600 text-white hover:bg-${accentColor}-700`}>
              Confirmar Venda {mode === 'cash' ? 'À Vista' : 'a Prazo'}
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {filteredSales.map(sale => {
           const saleProfit = sale.netAmount - sale.totalCost;
           const profitMargin = sale.netAmount > 0 ? (saleProfit / sale.netAmount) * 100 : 0;
           const isExpanded = selectedSaleId === sale.id;

           return (
            <div key={sale.id} className={`bg-white rounded-2xl shadow-sm border transition ${isExpanded ? 'border-indigo-400 shadow-md ring-1 ring-indigo-50' : 'border-slate-100 hover:border-indigo-200'}`}>
               <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                  <div className="flex items-start gap-3">
                    <div className={`mt-1 p-2 rounded-lg ${sale.customerId === 'BALCAO' ? 'bg-amber-100 text-amber-600' : mode === 'cash' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
                      </svg>
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-800 leading-tight">{customers.find(c => c.id === sale.customerId)?.name || '🛒 Cliente Balcão'}</h3>
                      <p className="text-xs text-slate-500 mb-1">{sale.description}</p>
                      <div className="flex items-center gap-3">
                        <span className="text-[10px] font-bold uppercase text-slate-400">{new Date(sale.date).toLocaleDateString('pt-BR')}</span>
                        <div className="flex items-center gap-1.5">
                           <span className={`text-[10px] font-black uppercase px-2 py-0.5 rounded ${saleProfit >= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                             Lucro: R$ {saleProfit.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                           </span>
                           <span className="text-[10px] font-bold text-slate-300">({profitMargin.toFixed(0)}%)</span>
                        </div>
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 ml-auto">
                    <div className="text-right">
                      <p className="text-lg font-black text-slate-900 leading-none mb-1">R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                      <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded tracking-tighter ${sale.status === PaymentStatus.PAID ? 'bg-emerald-500 text-white' : 'bg-amber-400 text-amber-950'}`}>
                        {sale.status === PaymentStatus.PAID ? 'Pago' : sale.status === PaymentStatus.PARTIAL ? 'Parcial' : 'Pendente'}
                      </span>
                    </div>
                    <button onClick={() => {
                      if (isExpanded) {
                        setSelectedSaleId(null);
                      } else {
                        setSelectedSaleId(sale.id);
                        setNewInstallmentCount(sale.installments.length);
                      }
                    }} className="p-2 text-slate-400 hover:text-indigo-600 transition">
                       <svg className={`w-5 h-5 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                    </button>
                  </div>
               </div>

               {isExpanded && (
                  <div className="px-5 pb-5 pt-4 border-t border-slate-50 bg-slate-50/50 animate-in slide-in-from-top-1 duration-200 space-y-4">
                     <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-slate-400 uppercase mb-1">Faturamento Bruto</p>
                           <p className="text-sm font-bold text-slate-700">R$ {sale.baseAmount.toFixed(2)}</p>
                        </div>
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-indigo-400 uppercase mb-1">Líquido (Pós Taxas)</p>
                           <p className="text-sm font-bold text-indigo-600">R$ {sale.netAmount.toFixed(2)}</p>
                        </div>
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-rose-400 uppercase mb-1">Custo do Produto</p>
                           <p className="text-sm font-bold text-rose-500">R$ {sale.totalCost.toFixed(2)}</p>
                        </div>
                        <div className="bg-emerald-600 p-3 rounded-xl shadow-md">
                           <p className="text-[9px] font-bold text-emerald-100 uppercase mb-1">Ganho Real (Lucro)</p>
                           <p className="text-sm font-black text-white">R$ {saleProfit.toFixed(2)}</p>
                        </div>
                     </div>

                     <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
                        <div className="p-3 bg-slate-100 border-b border-slate-200 flex flex-col md:flex-row justify-between items-center gap-4">
                           <h4 className="text-[10px] font-black uppercase text-slate-600 tracking-widest">Controle de Recebimentos</h4>

                           <div className="flex items-center gap-4">
                              {mode === 'credit' && (
                                <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-xl border border-indigo-100 shadow-inner">
                                   <label className="text-[9px] font-black text-indigo-400 uppercase">Qtd Parcelas:</label>
                                   <input 
                                    type="number" 
                                    min="1" 
                                    max="24" 
                                    value={newInstallmentCount} 
                                    onChange={(e) => setNewInstallmentCount(Number(e.target.value))}
                                    className="w-10 bg-transparent border-none p-0 text-xs font-black text-indigo-700 focus:ring-0 text-center"
                                   />
                                   <button 
                                    onClick={() => handleRescheduleInstallments(sale)}
                                    className="bg-indigo-600 text-white text-[9px] font-black uppercase px-2 py-1 rounded-lg hover:bg-indigo-700 transition"
                                   >
                                    Redistribuir
                                   </button>
                                </div>
                              )}

                              <button 
                                onClick={() => handleCancelSale(sale.id)}
                                className="flex items-center gap-1.5 text-[9px] font-black uppercase text-rose-500 hover:text-rose-700 transition"
                              >
                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                                Cancelar Venda
                              </button>
                           </div>
                        </div>
                        <div className="overflow-x-auto">
                           <table className="w-full text-left text-xs">
                              <thead>
                                 <tr className="bg-slate-50 text-slate-400 font-bold uppercase text-[9px]">
                                    <th className="px-4 py-2">Parc.</th>
                                    <th className="px-4 py-2">Vencimento</th>
                                    <th className="px-4 py-2">Valor Parcela</th>
                                    <th className="px-4 py-2">Valor Pago</th>
                                    <th className="px-4 py-2">Data Recebimento</th>
                                    <th className="px-4 py-2 text-center">Ações</th>
                                 </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-100">
                                 {sale.installments.map((inst, idx) => (
                                    <tr key={inst.id} className="hover:bg-indigo-50/30 transition">
                                       <td className="px-4 py-2 font-black text-slate-400">{idx + 1}ª</td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="date" 
                                             value={inst.dueDate} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { dueDate: e.target.value })}
                                             className="bg-transparent border-none p-0 text-xs font-bold text-slate-700 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="number" 
                                             step="0.01"
                                             value={inst.amount} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { amount: Number(e.target.value) })}
                                             className="bg-transparent border-none p-0 text-xs font-black text-slate-900 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="number" 
                                             step="0.01"
                                             value={inst.paidAmount} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { paidAmount: Number(e.target.value) })}
                                             className={`bg-transparent border-none p-0 text-xs font-black focus:ring-0 w-full ${inst.paidAmount >= inst.amount ? 'text-emerald-600' : inst.paidAmount > 0 ? 'text-amber-600' : 'text-slate-400'}`}
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="date" 
                                             value={inst.paymentDate || ''} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { paymentDate: e.target.value })}
                                             className="bg-transparent border-none p-0 text-[10px] font-bold text-emerald-600 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2 text-center">
                                          {inst.status !== PaymentStatus.PAID ? (
                                             <button 
                                                onClick={() => handleQuickSettle(sale, inst)}
                                                className="bg-emerald-500 hover:bg-emerald-600 text-white text-[9px] font-black uppercase px-2 py-1 rounded transition shadow-sm"
                                             >
                                                Quitar
                                             </button>
                                          ) : (
                                             <span className="text-emerald-500">
                                                <svg className="w-4 h-4 mx-auto" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                                             </span>
                                          )}
                                       </td>
                                    </tr>
                                 ))}
                              </tbody>
                           </table>
                        </div>
                     </div>
                  </div>
               )}
            </div>
           );
        })}
        {filteredSales.length === 0 && (
          <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-slate-200 text-slate-400 text-sm">
             Nenhuma venda registrada nesta modalidade.
          </div>
        )}
      </div>
    </div>
  );
};

export default SalesManager;

import React, { useState, useEffect } from 'react';
import { Sale, Customer, PaymentStatus, Expense, Product } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DashboardProps {
  sales: Sale[];
  customers: Customer[];
  expenses: Expense[];
  products: Product[];
}

const Dashboard: React.FC<DashboardProps> = ({ sales, customers, expenses, products }) => {
  const [insights, setInsights] = useState<string>('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [showBreakdown, setShowBreakdown] = useState(false);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(value);
  };

  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  const totalFixedExpenses = expenses.reduce((acc, exp) => acc + exp.amount, 0);
  const totalStockValueAtSalesPrice = products.reduce((acc, p) => acc + (p.price * p.stock), 0);

  const getFinancialsForMonth = (month: number, year: number) => {
    const stats = sales.reduce((acc, s) => {
      const saleDate = new Date(s.date);
      if (saleDate.getMonth() === month && saleDate.getFullYear() === year) {
        acc.grossRevenue += s.baseAmount;
        acc.discounts += s.discount;
        acc.cardFees += (s.cardFeeAmount || 0);
        acc.netRevenue += s.netAmount;
        acc.totalCostOfGoods += s.totalCost;
      }
      return acc;
    }, { grossRevenue: 0, discounts: 0, cardFees: 0, netRevenue: 0, totalCostOfGoods: 0 });

    // Cálculo do Recebido Real (Fluxo de Caixa)
    // Soma todos os paidAmount de parcelas cuja paymentDate é no mês selecionado
    const realReceived = sales.reduce((total, sale) => {
      const receivedInSale = sale.installments.reduce((sum, inst) => {
        if (inst.paymentDate) {
          const pDate = new Date(inst.paymentDate);
          if (pDate.getMonth() === month && pDate.getFullYear() === year) {
            return sum + inst.paidAmount;
          }
        }
        return sum;
      }, 0);
      return total + receivedInSale;
    }, 0);

    return { ...stats, realReceived };
  };

  const currentMonthFinancials = getFinancialsForMonth(currentMonth, currentYear);
  const productProfit = currentMonthFinancials.netRevenue - currentMonthFinancials.totalCostOfGoods;
  const monthlyRealProfit = productProfit - totalFixedExpenses;

  const historyData = Array.from({ length: 6 }).map((_, i) => {
    const d = new Date();
    d.setMonth(d.getMonth() - (5 - i));
    const financials = getFinancialsForMonth(d.getMonth(), d.getFullYear());
    const profit = (financials.netRevenue - financials.totalCostOfGoods) - totalFixedExpenses;
    return {
      name: d.toLocaleString('pt-BR', { month: 'short' }).toUpperCase(),
      Faturamento: financials.netRevenue,
      Recebido: financials.realReceived,
      fullName: d.toLocaleString('pt-BR', { month: 'long', year: 'numeric' })
    };
  });

  const totalReceivable = sales.reduce((acc, s) => {
    const totalInst = s.installments.reduce((sum, i) => sum + i.amount, 0);
    const paidInst = s.installments.reduce((sum, i) => sum + i.paidAmount, 0);
    const unpaidRatio = totalInst > 0 ? (totalInst - paidInst) / totalInst : 0;
    return acc + (s.netAmount * unpaidRatio);
  }, 0);

  const overdueSalesCount = sales.filter(s => 
    s.installments.some(i => i.status !== PaymentStatus.PAID && new Date(i.dueDate) < new Date())
  ).length;

  const fetchInsights = async (force = false) => {
    if (!force && insights && insights !== 'Carregando insights...') return;
    if (sales.length === 0) {
      setInsights("Registre suas primeiras vendas para ver a análise da IA.");
      return;
    }
    setIsSyncing(true);
    setInsights("Analisando seus dados financeiros...");
    const result = await getFinancialInsights(sales, customers);
    setInsights(result || "Nenhum insight disponível.");
    setIsSyncing(false);
  };

  useEffect(() => {
    if (!insights) fetchInsights();
  }, [sales.length]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div className="backdrop-blur-sm bg-white/30 p-2 rounded-xl">
          <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase italic">Dashboard Financeiro</h2>
          <p className="text-sm text-slate-700 font-bold uppercase tracking-wider">Gestão Inteligente & Moda</p>
        </div>
        <button 
          onClick={() => setShowBreakdown(!showBreakdown)}
          className="bg-indigo-900 text-white px-6 py-3 rounded-xl text-xs font-black uppercase hover:bg-indigo-950 transition shadow-xl"
        >
          {showBreakdown ? 'Fechar Detalhamento' : 'DRE Detalhado'}
        </button>
      </div>

      {/* KPI Card Principal - Estoque & Rua */}
      <div className="bg-indigo-900/90 backdrop-blur-md p-8 rounded-3xl shadow-2xl border border-indigo-400/20 text-white overflow-hidden relative">
          <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
            <div>
               <p className="text-indigo-200 text-[10px] font-black uppercase tracking-[0.2em] mb-1">Capital em Mercadoria (Venda)</p>
               <h3 className="text-5xl font-black tracking-tighter">{formatCurrency(totalStockValueAtSalesPrice)}</h3>
               <p className="text-[10px] text-indigo-300 mt-2 font-bold uppercase tracking-widest italic opacity-75">Investimento total pronto para retorno</p>
            </div>
            <div className="flex flex-col md:flex-row gap-4">
                <div className="bg-white/10 p-5 rounded-3xl backdrop-blur-lg border border-white/20 shadow-inner">
                   <p className="text-indigo-100 text-[9px] font-black uppercase tracking-widest mb-1">Total a Receber ("Rua")</p>
                   <p className="text-2xl font-black text-white">{formatCurrency(totalReceivable)}</p>
                </div>
            </div>
          </div>
          <div className="absolute -right-20 -top-20 w-64 h-64 bg-white/10 rounded-full blur-3xl pointer-events-none"></div>
      </div>

      {/* Grid de Cards KPIs Mensais */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white/70 backdrop-blur-md p-6 rounded-3xl shadow-xl border border-white/40 group hover:bg-white/90 transition-all duration-300">
          <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mb-1">Faturamento (Vendas)</p>
          <h3 className="text-xl font-black text-slate-900">{formatCurrency(currentMonthFinancials.netRevenue)}</h3>
          <p className="text-[9px] text-indigo-600 mt-1 font-black uppercase tracking-tighter">Total vendido no mês</p>
        </div>

        <div className="bg-emerald-600 p-6 rounded-3xl shadow-xl group transition-all duration-300 relative overflow-hidden">
          <p className="text-emerald-100 text-[10px] font-black uppercase tracking-widest mb-1 relative z-10">Total Recebido (Caixa)</p>
          <h3 className="text-xl font-black text-white relative z-10">{formatCurrency(currentMonthFinancials.realReceived)}</h3>
          <p className="text-[9px] text-emerald-200 mt-1 font-black uppercase tracking-tighter relative z-10">Dinheiro real que entrou</p>
          <div className="absolute -right-4 -bottom-4 opacity-20 text-white">
            <svg className="w-16 h-16" fill="currentColor" viewBox="0 0 20 20"><path d="M4 4a2 2 0 00-2 2v1h16V6a2 2 0 00-2-2H4z" /><path fillRule="evenodd" d="M18 9H2v5a2 2 0 002 2h12a2 2 0 002-2V9zM4 13a1 1 0 011-1h1a1 1 0 110 2H5a1 1 0 01-1-1zm5-1a1 1 0 100 2h1a1 1 0 100-2H9z" clipRule="evenodd" /></svg>
          </div>
        </div>

        <div className="bg-white/70 backdrop-blur-md p-6 rounded-3xl shadow-xl border border-white/40 group hover:bg-white/90 transition-all duration-300">
          <p className="text-rose-500 text-[10px] font-black uppercase tracking-widest mb-1">Custo Vendido (CMV)</p>
          <h3 className="text-xl font-black text-rose-600">{formatCurrency(currentMonthFinancials.totalCostOfGoods)}</h3>
          <p className="text-[9px] text-slate-500 mt-1 font-black uppercase tracking-tighter">Investimento nas peças</p>
        </div>

        <div className={`p-6 rounded-3xl shadow-2xl border-2 backdrop-blur-lg transition-all duration-300 ${monthlyRealProfit >= 0 ? 'bg-indigo-50/80 border-indigo-400/30' : 'bg-rose-50/80 border-rose-400/30'}`}>
          <p className="text-slate-600 text-[10px] font-black uppercase tracking-widest mb-1">Lucro Real Final</p>
          <h3 className={`text-xl font-black ${monthlyRealProfit >= 0 ? 'text-indigo-700' : 'text-rose-700'}`}>
            {formatCurrency(monthlyRealProfit)}
          </h3>
          <p className="text-[9px] text-slate-500 mt-1 font-black uppercase tracking-tighter italic">Após despesas fixas</p>
        </div>
      </div>

      {showBreakdown && (
        <div className="bg-slate-900/95 backdrop-blur-xl text-white p-10 rounded-[3rem] shadow-2xl animate-in fade-in slide-in-from-top-4 duration-500 border border-white/10">
           <h4 className="text-xl font-black uppercase italic tracking-widest mb-8 text-indigo-400 border-b border-white/10 pb-4">Demonstrativo Financeiro (DRE)</h4>
           <div className="space-y-4 font-mono text-sm">
              <div className="flex justify-between border-b border-white/5 pb-2">
                 <span>(+) FATURAMENTO BRUTO (Vendas do Mês)</span>
                 <span className="font-bold">{formatCurrency(currentMonthFinancials.grossRevenue)}</span>
              </div>
              <div className="flex justify-between border-b border-white/5 pb-2 text-rose-400">
                 <span>(-) DESCONTOS & TAXAS</span>
                 <span>{formatCurrency(currentMonthFinancials.discounts + currentMonthFinancials.cardFees)}</span>
              </div>
              <div className="flex justify-between pt-2 text-indigo-300 font-black">
                 <span>(=) RECEITA LÍQUIDA</span>
                 <span>{formatCurrency(currentMonthFinancials.netRevenue)}</span>
              </div>
              <div className="flex justify-between border-b border-white/5 pb-2 text-emerald-400 mt-4">
                 <span>(INFO) TOTAL RECEBIDO EM CAIXA (Parcelas Pagas)</span>
                 <span className="font-black">{formatCurrency(currentMonthFinancials.realReceived)}</span>
              </div>
              <div className="flex justify-between border-b border-white/5 pb-2 text-rose-500 mt-6">
                 <span>(-) CUSTO DAS MERCADORIAS (CMV)</span>
                 <span>{formatCurrency(currentMonthFinancials.totalCostOfGoods)}</span>
              </div>
              <div className="flex justify-between border-b border-white/5 pb-2 text-rose-500 mt-2">
                 <span>(-) DESPESAS FIXAS DA LOJA</span>
                 <span>{formatCurrency(totalFixedExpenses)}</span>
              </div>
              <div className="flex justify-between pt-6 mt-6 border-t-4 border-indigo-500/30 text-3xl font-black text-emerald-400">
                 <span>LUCRO FINAL</span>
                 <span>{formatCurrency(monthlyRealProfit)}</span>
              </div>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white/80 backdrop-blur-md p-8 rounded-[2.5rem] shadow-xl border border-white/50">
          <h4 className="font-black text-slate-900 text-[10px] uppercase tracking-[0.3em] mb-8">Faturamento vs Recebimento (Histórico)</h4>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={historyData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={10} fontWeight="900" dy={10} stroke="#64748b" />
                <YAxis axisLine={false} tickLine={false} fontSize={10} fontWeight="900" stroke="#64748b" />
                <Tooltip 
                  cursor={{fill: 'rgba(255,255,255,0.4)'}} 
                  contentStyle={{ borderRadius: '24px', border: 'none', boxShadow: '0 25px 50px -12px rgba(0,0,0,0.25)', padding: '16px', fontWeight: '900', background: 'rgba(15, 23, 42, 0.9)', color: '#fff' }}
                  formatter={(value: number) => [formatCurrency(value), '']}
                />
                <Bar dataKey="Faturamento" fill="#4338ca" radius={[8, 8, 0, 0]} barSize={28} />
                <Bar dataKey="Recebido" fill="#10b981" radius={[8, 8, 0, 0]} barSize={28} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white/80 backdrop-blur-md p-8 rounded-[2.5rem] shadow-xl border border-white/50">
             <h4 className="font-black text-slate-900 text-[10px] uppercase tracking-[0.3em] mb-6">Saúde Financeira</h4>
             <div className="space-y-5">
                <div className="flex justify-between items-center pb-3 border-b border-slate-100">
                   <span className="text-[10px] font-black text-slate-400 uppercase">Eficiência de Cobrança</span>
                   <span className="text-sm font-black text-slate-900">
                      {currentMonthFinancials.netRevenue > 0 
                        ? ((currentMonthFinancials.realReceived / currentMonthFinancials.netRevenue) * 100).toFixed(0) + '%' 
                        : '100%'}
                   </span>
                </div>
                <div className="flex justify-between items-center">
                   <span className="text-[10px] font-black text-slate-400 uppercase">Pendências de Hoje</span>
                   <span className={`text-sm font-black ${overdueSalesCount > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                     {overdueSalesCount} Cliente(s)
                   </span>
                </div>
             </div>
          </div>

          <div className={`p-8 rounded-[2.5rem] border-2 flex flex-col transition-all shadow-xl backdrop-blur-lg ${insights.includes('⚠️') ? 'bg-amber-50/90 border-amber-200' : 'bg-indigo-50/90 border-indigo-200'}`}>
            <div className="flex justify-between items-center mb-6">
              <h4 className={`font-black text-[9px] uppercase tracking-[0.3em] flex items-center gap-2 ${insights.includes('⚠️') ? 'text-amber-900' : 'text-indigo-900'}`}>
                IA Insight Fashion
              </h4>
              <button onClick={() => fetchInsights(true)} disabled={isSyncing} className="text-[9px] font-black uppercase text-indigo-700 underline tracking-tighter">Recalcular</button>
            </div>
            <div className={`text-xs leading-relaxed font-black italic ${insights.includes('⚠️') ? 'text-amber-900' : 'text-indigo-900'}`}>
               "{insights}"
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Customer, Sale, PaymentStatus, Installment, Product } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  products: Product[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
  onDeleteSale?: (id: string) => void;
  mode: 'cash' | 'credit';
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, products, onAddSale, onUpdateSale, onDeleteSale, mode }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [isBalcao, setIsBalcao] = useState(false);
  const [productId, setProductId] = useState('');
  const [description, setDescription] = useState('');

  const [baseAmount, setBaseAmount] = useState<number>(0);
  const [discount, setDiscount] = useState<number>(0);
  const [cardFeeRate, setCardFeeRate] = useState<number>(0);
  const [currentProductCost, setCurrentProductCost] = useState<number>(0);

  const [totalAmount, setTotalAmount] = useState<number>(0);
  const [netAmount, setNetAmount] = useState<number>(0);

  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSaleId, setSelectedSaleId] = useState<string | null>(null);
  const [newInstallmentCount, setNewInstallmentCount] = useState<number>(1);

  useEffect(() => {
    if (productId) {
      const p = products.find(prod => prod.id === productId);
      if (p) {
        setBaseAmount(p.price);
        setDescription(`${p.sku} - ${p.name}`);
        setCurrentProductCost(p.costPrice);
      }
    } else {
      setCurrentProductCost(0);
    }
  }, [productId, products]);

  useEffect(() => {
    const calculatedTotal = Math.max(0, baseAmount - discount);
    const feeAmount = (calculatedTotal * cardFeeRate) / 100;
    const calculatedNet = calculatedTotal - feeAmount;

    setTotalAmount(calculatedTotal);
    setNetAmount(calculatedNet);
  }, [baseAmount, discount, cardFeeRate]);

  const filteredSales = sales.filter(s => (s.type || 'credit') === mode);

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    const finalCustomerId = isBalcao ? 'BALCAO' : customerId;

    if (!finalCustomerId || !description || totalAmount <= 0) {
      alert("Por favor, preencha todos os campos obrigatórios.");
      return;
    }

    if (productId) {
      const p = products.find(prod => prod.id === productId);
      if (p && p.stock <= 0) {
        if (!window.confirm("Produto sem estoque! Deseja continuar com a venda mesmo assim?")) return;
      }
    }

    const installments: Installment[] = [];
    const today = new Date();
    const todayStr = today.toISOString().split('T')[0];

    if (mode === 'cash') {
      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: totalAmount,
        paidAmount: totalAmount,
        dueDate: todayStr,
        paymentDate: todayStr,
        status: PaymentStatus.PAID
      });
    } else {
      const installmentAmount = totalAmount / numInstallments;
      for (let i = 1; i <= numInstallments; i++) {
        const dueDate = calculateDueDate(today, i, dueDay);
        installments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: '', 
          amount: installmentAmount,
          paidAmount: 0,
          dueDate: dueDate.toISOString().split('T')[0],
          status: PaymentStatus.PENDING
        });
      }
    }

    onAddSale({
      customerId: finalCustomerId,
      productId: productId || undefined,
      description,
      baseAmount,
      discount,
      totalAmount,
      cardFeeRate,
      cardFeeAmount: (totalAmount * cardFeeRate) / 100,
      netAmount,
      totalCost: currentProductCost,
      date: todayStr,
      installments,
      status: mode === 'cash' ? PaymentStatus.PAID : PaymentStatus.PENDING,
      type: mode
    });

    setShowAdd(false);
    resetForm();
  };

  const handleUpdateInstallment = (sale: Sale, installmentId: string, updates: Partial<Installment>) => {
    const updatedInstallments = sale.installments.map(inst => {
      if (inst.id === installmentId) {
        const newInst = { ...inst, ...updates };
        if (newInst.paidAmount >= newInst.amount) {
          newInst.status = PaymentStatus.PAID;
          if (!newInst.paymentDate) {
            newInst.paymentDate = new Date().toISOString().split('T')[0];
          }
        } else if (newInst.paidAmount > 0) {
          newInst.status = PaymentStatus.PARTIAL;
        } else {
          newInst.status = PaymentStatus.PENDING;
          newInst.paymentDate = undefined;
        }
        return newInst;
      }
      return inst;
    });

    const allPaid = updatedInstallments.every(i => i.status === PaymentStatus.PAID);
    const somePaid = updatedInstallments.some(i => i.status !== PaymentStatus.PENDING);
    const newStatus = allPaid ? PaymentStatus.PAID : (somePaid ? PaymentStatus.PARTIAL : PaymentStatus.PENDING);

    onUpdateSale({
      ...sale,
      installments: updatedInstallments,
      status: newStatus
    });
  };

  const handleRescheduleInstallments = (sale: Sale) => {
    if (newInstallmentCount < 1) return;
    if (!window.confirm(`Isso irá apagar as parcelas atuais e criar ${newInstallmentCount} novas parcelas de R$ ${(sale.totalAmount / newInstallmentCount).toFixed(2)}. Deseja continuar?`)) return;

    const newInstallments: Installment[] = [];
    const baseDate = new Date(sale.date);
    const targetDay = baseDate.getDate();
    const installmentAmount = sale.totalAmount / newInstallmentCount;

    for (let i = 1; i <= newInstallmentCount; i++) {
      const dueDate = calculateDueDate(baseDate, i, targetDay);
      newInstallments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: sale.id,
        amount: installmentAmount,
        paidAmount: 0,
        dueDate: dueDate.toISOString().split('T')[0],
        status: PaymentStatus.PENDING
      });
    }

    onUpdateSale({
      ...sale,
      installments: newInstallments,
      status: PaymentStatus.PENDING
    });
  };

  const handleQuickSettle = (sale: Sale, inst: Installment) => {
    handleUpdateInstallment(sale, inst.id, { 
      paidAmount: inst.amount, 
      paymentDate: new Date().toISOString().split('T')[0] 
    });
  };

  const handleCancelSale = (e: React.MouseEvent, id: string) => {
    e.stopPropagation(); // Evita expandir o card ao clicar em deletar
    if (onDeleteSale) {
      onDeleteSale(id);
    }
  };

  const calculateDueDate = (baseDate: Date, monthsToAdd: number, targetDay: number) => {
    let targetMonth = baseDate.getMonth() + monthsToAdd;
    let targetYear = baseDate.getFullYear();
    while (targetMonth > 11) { targetMonth -= 12; targetYear += 1; }
    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const resetForm = () => {
    setCustomerId('');
    setIsBalcao(false);
    setProductId('');
    setDescription('');
    setBaseAmount(0);
    setDiscount(0);
    setCardFeeRate(0);
    setCurrentProductCost(0);
    setNumInstallments(1);
    setDueDay(new Date().getDate());
  };

  const accentColor = mode === 'cash' ? 'emerald' : 'indigo';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800">{mode === 'cash' ? 'Venda À Vista' : 'Venda a Prazo'}</h2>
          <p className="text-xs text-slate-500 uppercase tracking-widest font-bold">Lançamento de {mode === 'cash' ? 'entrada imediata' : 'parcelamentos'}</p>
        </div>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className={`bg-${accentColor}-600 text-white px-4 py-2 rounded-xl text-sm font-semibold hover:bg-${accentColor}-700 transition shadow-sm`}
        >
          {showAdd ? 'Cancelar' : 'Nova Venda'}
        </button>
      </div>

      {showAdd && (
        <form onSubmit={handleAddSale} className={`bg-white p-6 rounded-2xl shadow-sm border border-${accentColor}-100 space-y-6 animate-in fade-in zoom-in duration-200`}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="md:col-span-1">
              <div className="flex justify-between items-center mb-1">
                <label className="block text-[10px] font-bold text-slate-400 uppercase">Cliente</label>
                <button type="button" onClick={() => setIsBalcao(!isBalcao)} className={`text-[10px] font-bold px-2 py-0.5 rounded transition ${isBalcao ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-500'}`}>
                  {isBalcao ? '✓ Venda Balcão' : 'Venda Balcão?'}
                </button>
              </div>
              {isBalcao ? (
                <div className="w-full bg-amber-50 border border-amber-200 rounded-lg px-3 py-2 text-sm text-amber-700 font-bold">🛒 Cliente Balcão</div>
              ) : (
                <select value={customerId} onChange={e => setCustomerId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none">
                  <option value="">Selecione o Cliente...</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              )}
            </div>

            <div className="md:col-span-1">
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Produto (SKU - Nome)</label>
              <select value={productId} onChange={e => setProductId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none font-medium">
                  <option value="">-- Venda Avulsa / Sem Código --</option>
                  {products.map(p => <option key={p.id} value={p.id}>{p.sku} - {p.name} (Qtd: {p.stock})</option>)}
              </select>
            </div>

            <div className="md:col-span-1">
              <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Descrição do Item</label>
              <input type="text" value={description} onChange={e => setDescription(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Ex: Camiseta Básica P" />
            </div>

            <div className="space-y-4 md:col-span-3 bg-slate-50/50 p-4 rounded-xl border border-slate-100">
               <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Preço Venda (R$)</label>
                    <input type="number" step="0.01" value={baseAmount || ''} onChange={e => setBaseAmount(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Desconto (R$)</label>
                    <input type="number" step="0.01" value={discount || ''} onChange={e => setDiscount(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-rose-600 font-bold" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Taxa Cartão (%)</label>
                    <input type="number" step="0.1" value={cardFeeRate || ''} onChange={e => setCardFeeRate(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-lg px-3 py-2 text-sm text-amber-600 font-bold" />
                  </div>
                  <div className="flex flex-col justify-end">
                    <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Total Cliente</p>
                    <p className="text-xl font-black text-slate-900">R$ {totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-3 border-t border-slate-200">
                  <div className="text-xs text-slate-500 font-medium">
                     Custo Unitário Registrado: <span className="text-rose-600 font-bold">R$ {currentProductCost.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                  </div>
                  <div className="text-right text-emerald-600 font-bold text-sm">
                    Líquido Real: R$ {netAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                  </div>
               </div>
            </div>

            {mode === 'credit' && (
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Parcelas</label>
                  <input type="number" min="1" max="24" value={numInstallments} onChange={e => setNumInstallments(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Dia Venc.</label>
                  <input type="number" min="1" max="31" value={dueDay} onChange={e => setDueDay(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm" />
                </div>
              </div>
            )}
          </div>
          <div className="flex justify-end pt-2 border-t border-slate-50">
            <button type="submit" className={`px-8 py-3 rounded-xl text-sm font-bold uppercase tracking-widest transition shadow-lg bg-${accentColor}-600 text-white hover:bg-${accentColor}-700`}>
              Confirmar Venda {mode === 'cash' ? 'À Vista' : 'a Prazo'}
            </button>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-4">
        {filteredSales.map(sale => {
           const saleProfit = sale.netAmount - sale.totalCost;
           const profitMargin = sale.netAmount > 0 ? (saleProfit / sale.netAmount) * 100 : 0;
           const isExpanded = selectedSaleId === sale.id;

           return (
            <div key={sale.id} className={`bg-white rounded-2xl shadow-sm border transition ${isExpanded ? 'border-indigo-400 shadow-md ring-1 ring-indigo-50' : 'border-slate-100 hover:border-indigo-200'}`}>
               <div className="p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                  <div className="flex items-start gap-3">
                    <div className={`mt-1 p-2 rounded-lg ${sale.customerId === 'BALCAO' ? 'bg-amber-100 text-amber-600' : mode === 'cash' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600'}`}>
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
                      </svg>
                    </div>
                    <div>
                      <h3 className="font-bold text-slate-800 leading-tight">{customers.find(c => c.id === sale.customerId)?.name || '🛒 Cliente Balcão'}</h3>
                      <p className="text-xs text-slate-500 mb-1">{sale.description}</p>
                      <div className="flex items-center gap-3">
                        <span className="text-[10px] font-bold uppercase text-slate-400">{new Date(sale.date).toLocaleDateString('pt-BR')}</span>
                        <div className="flex items-center gap-1.5">
                           <span className={`text-[10px] font-black uppercase px-2 py-0.5 rounded ${saleProfit >= 0 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                             Lucro: R$ {saleProfit.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                           </span>
                           <span className="text-[10px] font-bold text-slate-300">({profitMargin.toFixed(0)}%)</span>
                        </div>
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 ml-auto">
                    <div className="text-right flex items-center gap-4">
                      <div>
                        <p className="text-lg font-black text-slate-900 leading-none mb-1">R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                        <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded tracking-tighter ${sale.status === PaymentStatus.PAID ? 'bg-emerald-500 text-white' : 'bg-amber-400 text-amber-950'}`}>
                          {sale.status === PaymentStatus.PAID ? 'Pago' : sale.status === PaymentStatus.PARTIAL ? 'Parcial' : 'Pendente'}
                        </span>
                      </div>

                      {/* Botão de Excluir Rápido */}
                      <button 
                        onClick={(e) => handleCancelSale(e, sale.id)}
                        className="p-2 text-slate-300 hover:text-rose-500 transition-colors bg-slate-50 rounded-xl"
                        title="Excluir/Estornar Venda"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                      </button>

                      <button onClick={() => {
                        if (isExpanded) {
                          setSelectedSaleId(null);
                        } else {
                          setSelectedSaleId(sale.id);
                          setNewInstallmentCount(sale.installments.length);
                        }
                      }} className="p-2 text-slate-400 hover:text-indigo-600 transition">
                         <svg className={`w-5 h-5 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                      </button>
                    </div>
                  </div>
               </div>

               {isExpanded && (
                  <div className="px-5 pb-5 pt-4 border-t border-slate-50 bg-slate-50/50 animate-in slide-in-from-top-1 duration-200 space-y-4">
                     <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-slate-400 uppercase mb-1">Faturamento Bruto</p>
                           <p className="text-sm font-bold text-slate-700">R$ {sale.baseAmount.toFixed(2)}</p>
                        </div>
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-indigo-400 uppercase mb-1">Líquido (Pós Taxas)</p>
                           <p className="text-sm font-bold text-indigo-600">R$ {sale.netAmount.toFixed(2)}</p>
                        </div>
                        <div className="bg-white p-3 rounded-xl border border-slate-100 shadow-sm">
                           <p className="text-[9px] font-bold text-rose-400 uppercase mb-1">Custo do Produto</p>
                           <p className="text-sm font-bold text-rose-500">R$ {sale.totalCost.toFixed(2)}</p>
                        </div>
                        <div className="bg-emerald-600 p-3 rounded-xl shadow-md">
                           <p className="text-[9px] font-bold text-emerald-100 uppercase mb-1">Ganho Real (Lucro)</p>
                           <p className="text-sm font-black text-white">R$ {saleProfit.toFixed(2)}</p>
                        </div>
                     </div>

                     <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
                        <div className="p-3 bg-slate-100 border-b border-slate-200 flex flex-col md:flex-row justify-between items-center gap-4">
                           <h4 className="text-[10px] font-black uppercase text-slate-600 tracking-widest">Controle de Recebimentos</h4>

                           <div className="flex items-center gap-4">
                              {mode === 'credit' && (
                                <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-xl border border-indigo-100 shadow-inner">
                                   <label className="text-[9px] font-black text-indigo-400 uppercase">Qtd Parcelas:</label>
                                   <input 
                                    type="number" 
                                    min="1" 
                                    max="24" 
                                    value={newInstallmentCount} 
                                    onChange={(e) => setNewInstallmentCount(Number(e.target.value))}
                                    className="w-10 bg-transparent border-none p-0 text-xs font-black text-indigo-700 focus:ring-0 text-center"
                                   />
                                   <button 
                                    onClick={() => handleRescheduleInstallments(sale)}
                                    className="bg-indigo-600 text-white text-[9px] font-black uppercase px-2 py-1 rounded-lg hover:bg-indigo-700 transition"
                                   >
                                    Redistribuir
                                   </button>
                                </div>
                              )}
                           </div>
                        </div>
                        <div className="overflow-x-auto">
                           <table className="w-full text-left text-xs">
                              <thead>
                                 <tr className="bg-slate-50 text-slate-400 font-bold uppercase text-[9px]">
                                    <th className="px-4 py-2">Parc.</th>
                                    <th className="px-4 py-2">Vencimento</th>
                                    <th className="px-4 py-2">Valor Parcela</th>
                                    <th className="px-4 py-2">Valor Pago</th>
                                    <th className="px-4 py-2">Data Recebimento</th>
                                    <th className="px-4 py-2 text-center">Ações</th>
                                 </tr>
                              </thead>
                              <tbody className="divide-y divide-slate-100">
                                 {sale.installments.map((inst, idx) => (
                                    <tr key={inst.id} className="hover:bg-indigo-50/30 transition">
                                       <td className="px-4 py-2 font-black text-slate-400">{idx + 1}ª</td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="date" 
                                             value={inst.dueDate} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { dueDate: e.target.value })}
                                             className="bg-transparent border-none p-0 text-xs font-bold text-slate-700 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="number" 
                                             step="0.01"
                                             value={inst.amount} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { amount: Number(e.target.value) })}
                                             className="bg-transparent border-none p-0 text-xs font-black text-slate-900 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="number" 
                                             step="0.01"
                                             value={inst.paidAmount} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { paidAmount: Number(e.target.value) })}
                                             className={`bg-transparent border-none p-0 text-xs font-black focus:ring-0 w-full ${inst.paidAmount >= inst.amount ? 'text-emerald-600' : inst.paidAmount > 0 ? 'text-amber-600' : 'text-slate-400'}`}
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="date" 
                                             value={inst.paymentDate || ''} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { paymentDate: e.target.value })}
                                             className="bg-transparent border-none p-0 text-[10px] font-bold text-emerald-600 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2 text-center">
                                          {inst.status !== PaymentStatus.PAID ? (
                                             <button 
                                                onClick={() => handleQuickSettle(sale, inst)}
                                                className="bg-emerald-500 hover:bg-emerald-600 text-white text-[9px] font-black uppercase px-2 py-1 rounded transition shadow-sm"
                                             >
                                                Quitar
                                             </button>
                                          ) : (
                                             <span className="text-emerald-500">
                                                <svg className="w-4 h-4 mx-auto" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                                             </span>
                                          )}
                                       </td>
                                    </tr>
                                 ))}
                              </tbody>
                           </table>
                        </div>
                     </div>
                  </div>
               )}
            </div>
           );
        })}
        {filteredSales.length === 0 && (
          <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-slate-200 text-slate-400 text-sm">
             Nenhuma venda registrada nesta modalidade.
          </div>
        )}
      </div>
    </div>
  );
};

export default SalesManager;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { View, Customer, Sale, User, Expense, Product } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';
import Agenda from './components/Agenda';
import Settings from './components/Settings';
import Landing from './components/Landing';
import Tutorial from './components/Tutorial';
import ExpenseManager from './components/ExpenseManager';
import InventoryManager from './components/InventoryManager';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const isMounted = useRef(false);

  const FASHION_IMAGE_URL = 'https://images.unsplash.com/photo-1445205170230-053b83016050?q=80&w=2000';

  useEffect(() => {
    const initApp = () => {
      try {
        const savedUser = localStorage.getItem('gestao93_current_user');
        if (savedUser && savedUser !== 'undefined') {
          const parsedUser = JSON.parse(savedUser);
          if (parsedUser && parsedUser.id) {
            setUser(parsedUser);
            const userId = parsedUser.id;

            const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
            if (!tutorialSeen) setShowTutorial(true);

            const safeParse = (key: string, fallback: any) => {
              try {
                const data = localStorage.getItem(key);
                return data ? JSON.parse(data) : fallback;
              } catch { return fallback; }
            };

            setCustomers(safeParse(`gestao93_customers_${userId}`, []));
            setSales(safeParse(`gestao93_sales_${userId}`, []));
            setExpenses(safeParse(`gestao93_expenses_${userId}`, []));
            setProducts(safeParse(`gestao93_products_${userId}`, []));
          }
        }
      } catch (e) {
        console.error("Erro ao carregar dados:", e);
        localStorage.removeItem('gestao93_current_user');
      } finally {
        setLoading(false);
        isMounted.current = true;
      }
    };
    initApp();
  }, []);

  useEffect(() => {
    if (loading || !user || !isMounted.current) return;

    const timer = setTimeout(() => {
      try {
        setSyncStatus('syncing');
        const userId = user.id;
        localStorage.setItem(`gestao93_customers_${userId}`, JSON.stringify(customers));
        localStorage.setItem(`gestao93_sales_${userId}`, JSON.stringify(sales));
        localStorage.setItem(`gestao93_expenses_${userId}`, JSON.stringify(expenses));
        localStorage.setItem(`gestao93_products_${userId}`, JSON.stringify(products));
        setSyncStatus('synced');
      } catch (err) {
        setSyncStatus('error');
      }
    }, 1000);

    return () => clearTimeout(timer);
  }, [customers, sales, expenses, products, user, loading]);

  const handleLogout = () => {
    localStorage.removeItem('gestao93_current_user');
    setUser(null);
    setActiveView('dashboard');
  };

  const handleAddSale = (s: Omit<Sale, 'id'>) => {
    const newId = Math.random().toString(36).substr(2, 9);
    setSales(prev => [...prev, { ...s, id: newId }]);

    // Reduzir estoque se houver produto vinculado
    if (s.productId) {
      setProducts(prev => prev.map(p => 
        p.id === s.productId ? { ...p, stock: Math.max(0, p.stock - 1) } : p
      ));
    }
  };

  const handleDeleteSale = useCallback((id: string) => {
    if (window.confirm('Deseja excluir esta venda? Se houver produto vinculado, ele retornará ao estoque automaticamente.')) {
      setSales(prevSales => {
        const saleToDelete = prevSales.find(s => s.id === id);
        if (!saleToDelete) return prevSales;

        // Se a venda tinha um produto do estoque, devolvemos 1 unidade
        if (saleToDelete.productId) {
          setProducts(prevProducts => prevProducts.map(p => 
            p.id === saleToDelete.productId ? { ...p, stock: p.stock + 1 } : p
          ));
        }
        return prevSales.filter(s => s.id !== id);
      });
    }
  }, []);

  const clearUserData = () => {
    if (!user) return;
    const userId = user.id;
    localStorage.removeItem(`gestao93_customers_${userId}`);
    localStorage.removeItem(`gestao93_sales_${userId}`);
    localStorage.removeItem(`gestao93_expenses_${userId}`);
    localStorage.removeItem(`gestao93_products_${userId}`);
    setCustomers([]);
    setSales([]);
    setExpenses([]);
    setProducts([]);
    alert("Todos os seus dados foram apagados.");
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-indigo-950">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
          <h1 className="text-white font-black text-2xl italic uppercase tracking-tighter">Gestão 93</h1>
        </div>
      </div>
    );
  }

  if (!user) return <Landing onLogin={setUser} />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
      case 'customers': return <CustomerList customers={customers} sales={sales} onAdd={(c) => setCustomers(prev => [...prev, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])} onDelete={(id) => setCustomers(prev => prev.filter(c => c.id !== id))} />;
      case 'sales-cash': return <SalesManager mode="cash" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={(s) => setSales(prev => prev.map(sale => sale.id === s.id ? s : sale))} onDeleteSale={handleDeleteSale} />;
      case 'sales-credit': return <SalesManager mode="credit" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={(s) => setSales(prev => prev.map(sale => sale.id === s.id ? s : sale))} onDeleteSale={handleDeleteSale} />;
      case 'inventory': return <InventoryManager products={products} onAdd={(p) => setProducts(prev => [...prev, { ...p, id: Math.random().toString(36).substr(2, 9) }])} onDelete={(id) => setProducts(prev => prev.filter(p => p.id !== id))} onUpdate={(p) => setProducts(prev => prev.map(prod => prod.id === p.id ? p : prod))} />;
      case 'expenses': return <ExpenseManager expenses={expenses} onAdd={(description, amount) => setExpenses(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), description, amount }])} onDelete={(id) => setExpenses(prev => prev.filter(e => e.id !== id))} />;
      case 'agenda': return <Agenda sales={sales} customers={customers} />;
      case 'settings': return <Settings user={user} customers={customers} sales={sales} products={products} onUpdateProfile={(u) => { setUser(u); localStorage.setItem('gestao93_current_user', JSON.stringify(u)); }} onImport={(data) => { setCustomers(data.customers); setSales(data.sales); setProducts(data.products || []); }} onClear={clearUserData} />;
      default: return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div 
        className="fixed inset-0 pointer-events-none z-0 bg-cover bg-center bg-no-repeat"
        style={{ 
          backgroundImage: `url(${FASHION_IMAGE_URL})`,
          opacity: '0.50',
        }}
      />

      {showTutorial && <Tutorial activeView={activeView} onClose={() => { localStorage.setItem(`gestao93_tutorial_seen_${user.id}`, 'true'); setShowTutorial(false); }} />}

      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col shrink-0 z-50 shadow-2xl relative overflow-hidden">
        <div 
          className="absolute inset-0 pointer-events-none opacity-50 mix-blend-soft-light bg-cover bg-center"
          style={{ backgroundImage: `url(${FASHION_IMAGE_URL})` }}
        />

        <div className="relative z-10 p-6 flex items-center gap-3 border-b border-indigo-900/50">
          <div className="bg-indigo-600 p-2 rounded-xl shrink-0 shadow-lg border border-white/20">
             <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <div className="min-w-0">
            <h1 className="text-xl font-black tracking-tighter italic uppercase text-white truncate drop-shadow-md">Gestão 93</h1>
            <div className="flex items-center gap-1">
              <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-400' : 'bg-amber-400 animate-pulse'}`}></div>
              <span className="text-[8px] font-bold uppercase tracking-widest text-indigo-300 drop-shadow-sm">{syncStatus === 'synced' ? 'Salvo' : 'Sincronizando'}</span>
            </div>
          </div>
        </div>

        <div className="relative z-10 flex-1 py-4 space-y-1 px-3 overflow-y-auto no-scrollbar">
          <NavItem id="nav-dashboard" icon="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" label="Início" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem id="nav-inventory" icon="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" label="Estoque" active={activeView === 'inventory'} onClick={() => setActiveView('inventory')} />
          <NavItem id="nav-customers" icon="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 005.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" label="Clientes" active={activeView === 'customers'} onClick={() => setActiveView('customers')} />
          <div className="pt-4 pb-1 px-4 text-[9px] font-black uppercase tracking-[0.2em] text-indigo-400 drop-shadow-sm">Operacional</div>
          <NavItem id="nav-sales-cash" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" label="À Vista" active={activeView === 'sales-cash'} onClick={() => setActiveView('sales-cash')} />
          <NavItem id="nav-sales-credit" icon="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" label="A Prazo" active={activeView === 'sales-credit'} onClick={() => setActiveView('sales-credit')} />
          <NavItem id="nav-agenda" icon="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" label="Agenda" active={activeView === 'agenda'} onClick={() => setActiveView('agenda')} />
          <NavItem id="nav-expenses" icon="M15 12H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" label="Despesas" active={activeView === 'expenses'} onClick={() => setActiveView('expenses')} />
          <div className="pt-4 pb-1 px-4 text-[9px] font-black uppercase tracking-[0.2em] text-indigo-400 drop-shadow-sm">Configurações</div>
          <NavItem id="nav-settings" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" label="Ajustes" active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
        </div>

        <div className="relative z-10 p-4 bg-black/30 border-t border-indigo-900/50">
           <div className="flex items-center gap-3 p-3 bg-black/20 rounded-2xl border border-white/10 shadow-inner backdrop-blur-sm">
              <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center font-bold text-lg italic shrink-0 overflow-hidden shadow-lg border border-white/20">
                {user.avatarUrl ? (
                  <img src={user.avatarUrl} alt="Logo" className="w-full h-full object-cover" />
                ) : (
                  <span className="text-white">{user.name.charAt(0)}</span>
                )}
              </div>
              <div className="flex-1 min-w-0 text-shadow-sm">
                <p className="text-[10px] font-black truncate text-white uppercase">{user.name}</p>
                <p className="text-[8px] text-indigo-300 font-bold uppercase tracking-tighter">Boutique Premium</p>
              </div>
              <button onClick={handleLogout} className="text-indigo-200 hover:text-rose-400 transition transform hover:scale-110">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              </button>
           </div>
        </div>
      </nav>

      <main className="relative flex-1 p-4 md:p-8 overflow-y-auto h-screen z-10">
        <div className="max-w-6xl mx-auto pb-12 relative">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

const NavItem: React.FC<{ id?: string; icon: string; label: string; active: boolean; onClick: () => void; }> = ({ id, icon, label, active, onClick }) => (
  <button id={id} onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 relative group ${active ? 'bg-indigo-600 text-white shadow-xl translate-x-1 border border-white/10' : 'text-indigo-100 hover:bg-white/10 hover:text-white'}`}>
    <svg className="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={icon} /></svg>
    <span className={`text-sm font-bold tracking-tight whitespace-nowrap drop-shadow-sm ${active ? 'font-black' : ''}`}>{label}</span>
    {active && <div className="absolute right-3 w-1.5 h-1.5 bg-white rounded-full shadow-[0_0_8px_white]"></div>}
  </button>
);

export default App;

export interface User {
  id: string;
  name: string;
  email: string;
  password?: string;
  authProvider?: 'local' | 'onedrive';
  avatarUrl?: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  address?: string;
  cpf?: string;
  createdAt: number;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
}

export interface Product {
  id: string;
  sku: string;        // Código do produto
  name: string;
  category: string;
  costPrice: number;  // Preço de custo
  price: number;      // Preço de venda
  stock: number;
  minStock: number;
}

export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  PARTIAL = 'PARTIAL',
  CANCELED = 'CANCELED'
}

export interface Installment {
  id: string;
  saleId: string;
  amount: number;
  paidAmount: number;
  dueDate: string;
  paymentDate?: string; // Data em que o pagamento foi realizado
  status: PaymentStatus;
}

export interface Sale {
  id: string;
  customerId: string;
  description: string;
  baseAmount: number;
  discount: number;
  totalAmount: number;
  cardFeeRate?: number;
  cardFeeAmount?: number;
  netAmount: number;
  totalCost: number;   // Custo total dos produtos nesta venda para cálculo de lucro
  date: string;
  installments: Installment[];
  status: PaymentStatus;
  type?: 'cash' | 'credit';
  productId?: string;
}

export interface TrashItem {
  id: string;
  sale: Sale;
  deletedAt: number; // Timestamp da exclusão
}

export type View = 'dashboard' | 'customers' | 'sales-cash' | 'sales-credit' | 'agenda' | 'settings' | 'expenses' | 'inventory' | 'trash';

import React from 'react';
import { TrashItem, Sale, Customer } from '../types';

interface TrashManagerProps {
  trashItems: TrashItem[];
  customers: Customer[];
  onRestore: (id: string) => void;
  onDeletePermanent: (id: string) => void;
}

const TrashManager: React.FC<TrashManagerProps> = ({ trashItems, customers, onRestore, onDeletePermanent }) => {
  const getDaysRemaining = (deletedAt: number) => {
    const thirtyDaysInMs = 30 * 24 * 60 * 60 * 1000;
    const expirationDate = deletedAt + thirtyDaysInMs;
    const remainingMs = expirationDate - Date.now();
    return Math.max(0, Math.ceil(remainingMs / (1000 * 60 * 60 * 24)));
  };

  const formatCurrency = (val: number) => val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-xl font-black text-slate-900 uppercase italic">Lixeira de Vendas</h2>
        <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Itens aqui serão apagados permanentemente após 30 dias.</p>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {trashItems.map((item) => {
          const daysLeft = getDaysRemaining(item.deletedAt);
          const customer = customers.find(c => c.id === item.sale.customerId);

          return (
            <div key={item.id} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4 group">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-[10px] font-black bg-rose-100 text-rose-600 px-2 py-0.5 rounded uppercase">Excluído</span>
                  <span className="text-[10px] font-bold text-slate-400 uppercase italic">Expira em {daysLeft} dias</span>
                </div>
                <h3 className="font-black text-slate-800 uppercase">{customer?.name || '🛒 Venda Balcão'}</h3>
                <p className="text-xs text-slate-500">{item.sale.description} • {formatCurrency(item.sale.totalAmount)}</p>
                <p className="text-[9px] text-slate-400 mt-1 uppercase font-bold">Vendido em: {new Date(item.sale.date).toLocaleDateString('pt-BR')}</p>
              </div>

              <div className="flex items-center gap-2">
                <button 
                  onClick={() => onRestore(item.id)}
                  className="bg-indigo-50 text-indigo-600 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-100 transition"
                >
                  Restaurar
                </button>
                <button 
                  onClick={() => { if(confirm('Apagar permanentemente agora?')) onDeletePermanent(item.id); }}
                  className="p-2 text-slate-300 hover:text-rose-600 transition"
                  title="Excluir Permanentemente"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                  </svg>
                </button>
              </div>
            </div>
          );
        })}

        {trashItems.length === 0 && (
          <div className="text-center py-20 bg-white rounded-3xl border-2 border-dashed border-slate-200">
            <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg className="w-8 h-8 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </div>
            <p className="text-slate-400 font-bold uppercase text-xs tracking-widest">Sua lixeira está vazia</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default TrashManager;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { View, Customer, Sale, User, Expense, Product, TrashItem } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';
import Agenda from './components/Agenda';
import Settings from './components/Settings';
import Landing from './components/Landing';
import Tutorial from './components/Tutorial';
import ExpenseManager from './components/ExpenseManager';
import InventoryManager from './components/InventoryManager';
import TrashManager from './components/TrashManager';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [trashSales, setTrashSales] = useState<TrashItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const isMounted = useRef(false);

  const FASHION_IMAGE_URL = 'https://images.unsplash.com/photo-1445205170230-053b83016050?q=80&w=2000';

  useEffect(() => {
    const initApp = () => {
      try {
        const savedUser = localStorage.getItem('gestao93_current_user');
        if (savedUser && savedUser !== 'undefined') {
          const parsedUser = JSON.parse(savedUser);
          if (parsedUser && parsedUser.id) {
            setUser(parsedUser);
            const userId = parsedUser.id;

            const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
            if (!tutorialSeen) setShowTutorial(true);

            const safeParse = (key: string, fallback: any) => {
              try {
                const data = localStorage.getItem(key);
                return data ? JSON.parse(data) : fallback;
              } catch { return fallback; }
            };

            setCustomers(safeParse(`gestao93_customers_${userId}`, []));
            setSales(safeParse(`gestao93_sales_${userId}`, []));
            setExpenses(safeParse(`gestao93_expenses_${userId}`, []));
            setProducts(safeParse(`gestao93_products_${userId}`, []));

            // Carregar lixeira e realizar limpeza de 30 dias
            const loadedTrash = safeParse(`gestao93_trash_${userId}`, []);
            const thirtyDaysInMs = 30 * 24 * 60 * 60 * 1000;
            const validTrash = loadedTrash.filter((item: TrashItem) => (Date.now() - item.deletedAt) < thirtyDaysInMs);
            setTrashSales(validTrash);
          }
        }
      } catch (e) {
        console.error("Erro ao carregar dados:", e);
        localStorage.removeItem('gestao93_current_user');
      } finally {
        setLoading(false);
        isMounted.current = true;
      }
    };
    initApp();
  }, []);

  useEffect(() => {
    if (loading || !user || !isMounted.current) return;

    const timer = setTimeout(() => {
      try {
        setSyncStatus('syncing');
        const userId = user.id;
        localStorage.setItem(`gestao93_customers_${userId}`, JSON.stringify(customers));
        localStorage.setItem(`gestao93_sales_${userId}`, JSON.stringify(sales));
        localStorage.setItem(`gestao93_expenses_${userId}`, JSON.stringify(expenses));
        localStorage.setItem(`gestao93_products_${userId}`, JSON.stringify(products));
        localStorage.setItem(`gestao93_trash_${userId}`, JSON.stringify(trashSales));
        setSyncStatus('synced');
      } catch (err) {
        setSyncStatus('error');
      }
    }, 1000);

    return () => clearTimeout(timer);
  }, [customers, sales, expenses, products, trashSales, user, loading]);

  const handleLogout = () => {
    localStorage.removeItem('gestao93_current_user');
    setUser(null);
    setActiveView('dashboard');
  };

  const handleAddSale = (s: Omit<Sale, 'id'>) => {
    const newId = Math.random().toString(36).substr(2, 9);
    setSales(prev => [...prev, { ...s, id: newId }]);

    if (s.productId) {
      setProducts(prev => prev.map(p => 
        p.id === s.productId ? { ...p, stock: Math.max(0, p.stock - 1) } : p
      ));
    }
  };

  const handleDeleteSale = useCallback((id: string) => {
    if (window.confirm('Mover venda para a lixeira? Os itens retornarão ao estoque e a venda será apagada definitivamente em 30 dias.')) {
      setSales(prevSales => {
        const saleToDelete = prevSales.find(s => s.id === id);
        if (!saleToDelete) return prevSales;

        // Mover para lixeira
        setTrashSales(prevTrash => [
          ...prevTrash, 
          { id: Math.random().toString(36).substr(2, 9), sale: saleToDelete, deletedAt: Date.now() }
        ]);

        // Devolver estoque
        if (saleToDelete.productId) {
          setProducts(prevProducts => prevProducts.map(p => 
            p.id === saleToDelete.productId ? { ...p, stock: p.stock + 1 } : p
          ));
        }
        return prevSales.filter(s => s.id !== id);
      });
    }
  }, []);

  const handleRestoreSale = (trashId: string) => {
    const item = trashSales.find(i => i.id === trashId);
    if (!item) return;

    // Verificar se o produto ainda existe e tem estoque (para subtrair de novo)
    if (item.sale.productId) {
      const p = products.find(prod => prod.id === item.sale.productId);
      if (p && p.stock <= 0) {
        if (!confirm('Produto sem estoque. Restaurar venda mesmo assim?')) return;
      }
      setProducts(prev => prev.map(prod => 
        prod.id === item.sale.productId ? { ...prod, stock: Math.max(0, prod.stock - 1) } : prod
      ));
    }

    setSales(prev => [...prev, item.sale]);
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
    alert('Venda restaurada com sucesso!');
  };

  const handlePermanentDelete = (trashId: string) => {
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
  };

  const clearUserData = () => {
    if (!user) return;
    const userId = user.id;
    localStorage.removeItem(`gestao93_customers_${userId}`);
    localStorage.removeItem(`gestao93_sales_${userId}`);
    localStorage.removeItem(`gestao93_expenses_${userId}`);
    localStorage.removeItem(`gestao93_products_${userId}`);
    localStorage.removeItem(`gestao93_trash_${userId}`);
    setCustomers([]);
    setSales([]);
    setExpenses([]);
    setProducts([]);
    setTrashSales([]);
