                              <tbody className="divide-y divide-slate-100">
                                 {sale.installments.map((inst, idx) => (
                                    <tr key={inst.id} className="hover:bg-indigo-50/30 transition">
                                       <td className="px-4 py-2 font-black text-slate-400">{idx + 1}ª</td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="date" 
                                             value={inst.dueDate} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { dueDate: e.target.value })}
                                             className="bg-transparent border-none p-0 text-xs font-bold text-slate-700 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="number" 
                                             step="0.01"
                                             value={inst.amount} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { amount: Number(e.target.value) })}
                                             className="bg-transparent border-none p-0 text-xs font-black text-slate-900 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="number" 
                                             step="0.01"
                                             value={inst.paidAmount} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { paidAmount: Number(e.target.value) })}
                                             className={`bg-transparent border-none p-0 text-xs font-black focus:ring-0 w-full ${inst.paidAmount >= inst.amount ? 'text-emerald-600' : inst.paidAmount > 0 ? 'text-amber-600' : 'text-slate-400'}`}
                                          />
                                       </td>
                                       <td className="px-4 py-2">
                                          <input 
                                             type="date" 
                                             value={inst.paymentDate || ''} 
                                             onChange={(e) => handleUpdateInstallment(sale, inst.id, { paymentDate: e.target.value })}
                                             className="bg-transparent border-none p-0 text-[10px] font-bold text-emerald-600 focus:ring-0 w-full"
                                          />
                                       </td>
                                       <td className="px-4 py-2 text-center">
                                          {inst.status !== PaymentStatus.PAID ? (
                                             <button 
                                                onClick={() => handleQuickSettle(sale, inst)}
                                                className="bg-emerald-500 hover:bg-emerald-600 text-white text-[9px] font-black uppercase px-2 py-1 rounded transition shadow-sm"
                                             >
                                                Quitar
                                             </button>
                                          ) : (
                                             <span className="text-emerald-500">
                                                <svg className="w-4 h-4 mx-auto" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                                             </span>
                                          )}
                                       </td>
                                    </tr>
                                 ))}
                              </tbody>
                           </table>
                        </div>
                     </div>
                  </div>
               )}
            </div>
           );
        })}
        {filteredSales.length === 0 && (
          <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-slate-200 text-slate-400 text-sm">
             Nenhuma venda registrada nesta modalidade.
          </div>
        )}
      </div>
    </div>
  );
};

