import React, { useState } from 'react';
import { Sale, Customer, PaymentStatus } from '../types';

interface RefundManagerProps {
  sales: Sale[];
  customers: Customer[];
  onRefund: (id: string) => void;
}

const RefundManager: React.FC<RefundManagerProps> = ({ sales, customers, onRefund }) => {
  const [searchTerm, setSearchTerm] = useState('');

  const filteredSales = sales.filter(sale => {
    const customer = customers.find(c => c.id === sale.customerId);
    const searchStr = `${customer?.name || ''} ${sale.description} ${sale.totalAmount}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  const handleRefundClick = (sale: Sale) => {
    const formattedVal = sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 });
    const userInput = prompt(`⚠️ CONFIRMAÇÃO DE ESTORNO (DEVOLUÇÃO)\n\nEsta ação devolverá o produto ao estoque e gerará uma SAÍDA DE CAIXA caso existam valores já pagos.\n\nPara confirmar o estorno de R$ ${formattedVal}, digite o valor exato da venda abaixo:`);

    if (userInput === null) return;
    const cleanInput = userInput.replace(',', '.').trim();
    const inputNumber = parseFloat(cleanInput);

    if (!isNaN(inputNumber) && Math.abs(inputNumber - sale.totalAmount) < 0.01) {
      onRefund(sale.id);
    } else {
      alert(`❌ Valor incorreto! O estorno não foi realizado.`);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-xl font-black text-slate-900 uppercase italic">Central de Estornos</h2>
          <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Devolução de mercadoria e saída de dinheiro do caixa.</p>
        </div>
        <div className="w-full md:w-64 relative">
          <input 
            type="text" 
            placeholder="Buscar venda ou cliente..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm focus:ring-2 focus:ring-rose-500 outline-none pl-10"
          />
          <svg className="w-4 h-4 absolute left-3 top-2.5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredSales.map(sale => {
          const customer = customers.find(c => c.id === sale.customerId);
          const totalPaid = sale.installments.reduce((acc, inst) => acc + inst.paidAmount, 0);

          return (
            <div key={sale.id} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm hover:border-rose-300 transition-all flex flex-col justify-between">
              <div>
                <div className="flex justify-between items-start mb-2">
                  <span className={`text-[9px] font-black px-2 py-0.5 rounded uppercase ${sale.type === 'cash' ? 'bg-emerald-100 text-emerald-700' : 'bg-indigo-100 text-indigo-700'}`}>
                    {sale.type === 'cash' ? 'À Vista' : 'A Prazo'}
                  </span>
                  <span className="text-[10px] font-bold text-slate-400">{new Date(sale.date).toLocaleDateString('pt-BR')}</span>
                </div>
                <h3 className="font-black text-slate-800 uppercase leading-tight">{customer?.name || '🛒 Cliente Balcão'}</h3>
                <p className="text-xs text-slate-500 mb-4">{sale.description}</p>

                <div className="space-y-2 mb-6">
                  <div className="flex justify-between text-xs">
                    <span className="text-slate-400 font-bold uppercase">Valor Venda</span>
                    <span className="font-black text-slate-900">R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                  </div>
                  <div className="flex justify-between text-xs">
                    <span className="text-slate-400 font-bold uppercase">Já Recebido</span>
                    <span className="font-black text-emerald-600">R$ {totalPaid.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                  </div>
                </div>
              </div>

              <button 
                onClick={() => handleRefundClick(sale)}
                className="w-full bg-rose-50 text-rose-600 border border-rose-100 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-600 hover:text-white transition shadow-sm"
              >
                Realizar Estorno
              </button>
            </div>
          );
        })}
        {filteredSales.length === 0 && (
          <div className="col-span-full py-20 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 font-bold uppercase text-xs tracking-widest">
            Nenhuma venda encontrada para estorno.
          </div>
        )}
      </div>
    </div>
  );
};

