  const [manualAmount, setManualAmount] = useState<number>(0);

  const filteredSales = sales.filter(sale => {
    const customer = customers.find(c => c.id === sale.customerId);
    const searchStr = `${customer?.name || ''} ${sale.description} ${sale.totalAmount}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  const handleRefundClick = (sale: Sale) => {
    const formattedVal = sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 });
    const isAvulsa = !sale.productId;

    const msg = isAvulsa 
      ? `⚠️ CONFIRMAR ESTORNO (ITEM AVULSO)\n\nValor: R$ ${formattedVal}\n\nEsta venda não está ligada ao estoque. O dinheiro pago será registrado como saída de caixa, mas nada voltará para o inventário.`
      : `⚠️ CONFIRMAR ESTORNO (COM ESTOQUE)\n\nValor: R$ ${formattedVal}\n\nO item voltará para o estoque e o dinheiro pago será registrado como saída de caixa.`;

    if (window.confirm(`${msg}\n\nDeseja prosseguir?`)) {
      onRefund(sale.id);
    }
  };

  const handleManualSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!manualDesc || manualAmount <= 0) return;

    if (window.confirm(`⚠️ REGISTRAR ESTORNO MANUAL\n\nDescrição: ${manualDesc}\nValor: R$ ${manualAmount.toFixed(2)}\n\nIsso gerará uma saída de caixa imediata. Confirmar?`)) {
      onManualRefund(manualDesc, manualAmount);
      setManualDesc('');
      setManualAmount(0);
      setShowManualForm(false);
