            />
          </div>
          <button type="submit" className="w-full bg-amber-600 text-white py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-amber-700 transition">
            Confirmar Saída de Caixa (Estorno Manual)
          </button>
