import React, { useState, useEffect, useCallback, useRef } from 'react';
import { View, Customer, Sale, User, Expense, Product, TrashItem } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';
import Agenda from './components/Agenda';
import Settings from './components/Settings';
import Landing from './components/Landing';
import Tutorial from './components/Tutorial';
import ExpenseManager from './components/ExpenseManager';
import InventoryManager from './components/InventoryManager';
import TrashManager from './components/TrashManager';
import RefundManager from './components/RefundManager';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [trashSales, setTrashSales] = useState<TrashItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const isMounted = useRef(false);

  const FASHION_IMAGE_URL = 'https://images.unsplash.com/photo-1445205170230-053b83016050?q=80&w=2000';

  useEffect(() => {
    const initApp = () => {
      try {
        const savedUser = localStorage.getItem('gestao93_current_user');
        if (savedUser && savedUser !== 'undefined') {
          const parsedUser = JSON.parse(savedUser);
          if (parsedUser && parsedUser.id) {
            setUser(parsedUser);
            const userId = parsedUser.id;

            const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
            if (!tutorialSeen) setShowTutorial(true);

            const safeParse = (key: string, fallback: any) => {
              try {
                const data = localStorage.getItem(key);
                return data ? JSON.parse(data) : fallback;
              } catch { return fallback; }
            };

            setCustomers(safeParse(`gestao93_customers_${userId}`, []));
            setSales(safeParse(`gestao93_sales_${userId}`, []));
            setExpenses(safeParse(`gestao93_expenses_${userId}`, []));
            setProducts(safeParse(`gestao93_products_${userId}`, []));

            const loadedTrash = safeParse(`gestao93_trash_${userId}`, []);
            const thirtyDaysInMs = 30 * 24 * 60 * 60 * 1000;
            const validTrash = loadedTrash.filter((item: TrashItem) => (Date.now() - item.deletedAt) < thirtyDaysInMs);
            setTrashSales(validTrash);
          }
        }
      } catch (e) {
        console.error("Erro ao carregar dados:", e);
        localStorage.removeItem('gestao93_current_user');
      } finally {
        setLoading(false);
        isMounted.current = true;
      }
    };
    initApp();
  }, []);

  useEffect(() => {
    if (loading || !user || !isMounted.current) return;

    const timer = setTimeout(() => {
      try {
        setSyncStatus('syncing');
        const userId = user.id;
        localStorage.setItem(`gestao93_customers_${userId}`, JSON.stringify(customers));
        localStorage.setItem(`gestao93_sales_${userId}`, JSON.stringify(sales));
        localStorage.setItem(`gestao93_expenses_${userId}`, JSON.stringify(expenses));
        localStorage.setItem(`gestao93_products_${userId}`, JSON.stringify(products));
        localStorage.setItem(`gestao93_trash_${userId}`, JSON.stringify(trashSales));
        setSyncStatus('synced');
      } catch (err) {
        setSyncStatus('error');
      }
    }, 1000);

    return () => clearTimeout(timer);
  }, [customers, sales, expenses, products, trashSales, user, loading]);

  const handleLogout = () => {
    localStorage.removeItem('gestao93_current_user');
    setUser(null);
    setActiveView('dashboard');
  };

  const handleAddSale = (s: Omit<Sale, 'id'>) => {
    const newId = Math.random().toString(36).substr(2, 9);
    setSales(prev => [...prev, { ...s, id: newId }]);

    if (s.productId) {
      setProducts(prev => prev.map(p => 
        p.id === s.productId ? { ...p, stock: Math.max(0, p.stock - 1) } : p
      ));
    }
  };

  const handleDeleteSale = useCallback((id: string, isRefund: boolean = false) => {
    setSales(prevSales => {
      const saleToDelete = prevSales.find(s => s.id === id);
      if (!saleToDelete) return prevSales;

      if (isRefund) {
        const totalAlreadyPaid = saleToDelete.installments.reduce((acc, inst) => acc + inst.paidAmount, 0);

        if (totalAlreadyPaid > 0) {
          const customer = customers.find(c => c.id === saleToDelete.customerId);
          const customerName = customer ? customer.name : (saleToDelete.customerId === 'BALCAO' ? 'Cliente Balcão' : 'Desconhecido');

          const refundExpense: Expense = {
            id: Math.random().toString(36).substr(2, 9),
            description: `ESTORNO (DEVOLUÇÃO): ${customerName} (${saleToDelete.description})`,
            amount: totalAlreadyPaid
          };

          setExpenses(prev => [...prev, refundExpense]);
          alert(`ℹ️ Estorno Financeiro Realizado!\n\nUma SAÍDA DE CAIXA de R$ ${totalAlreadyPaid.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} foi registrada em suas Despesas.`);
        }
      }

      setTrashSales(prevTrash => [
        ...prevTrash, 
        { id: Math.random().toString(36).substr(2, 9), sale: saleToDelete, deletedAt: Date.now() }
      ]);

      if (saleToDelete.productId) {
        setProducts(prevProducts => prevProducts.map(p => 
          p.id === saleToDelete.productId ? { ...p, stock: p.stock + 1 } : p
        ));
      }

      if (!isRefund) {
        alert('ℹ️ Registro de venda excluído com sucesso (Estoque recomposto).');
      }

      return prevSales.filter(s => s.id !== id);
    });
  }, [customers]);

  const handleRestoreSale = (trashId: string) => {
    const item = trashSales.find(i => i.id === trashId);
    if (!item) return;

    if (item.sale.productId) {
      const p = products.find(prod => prod.id === item.sale.productId);
      if (p && p.stock <= 0) {
        if (!confirm('Produto sem estoque. Restaurar venda mesmo assim?')) return;
      }
      setProducts(prev => prev.map(prod => 
        prod.id === item.sale.productId ? { ...prod, stock: Math.max(0, prod.stock - 1) } : prod
      ));
    }

    setSales(prev => [...prev, item.sale]);
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
    alert('Venda restaurada com sucesso!');
  };

  const handlePermanentDelete = (trashId: string) => {
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
  };

  const clearUserData = () => {
    if (!user) return;
    const userId = user.id;
    localStorage.removeItem(`gestao93_customers_${userId}`);
    localStorage.removeItem(`gestao93_sales_${userId}`);
    localStorage.removeItem(`gestao93_expenses_${userId}`);
    localStorage.removeItem(`gestao93_products_${userId}`);
    localStorage.removeItem(`gestao93_trash_${userId}`);
    setCustomers([]);
    setSales([]);
    setExpenses([]);
    setProducts([]);
    setTrashSales([]);
    alert("Todos os seus dados foram apagados.");
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-indigo-950">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
          <h1 className="text-white font-black text-2xl italic uppercase tracking-tighter">Gestão 93</h1>
        </div>
      </div>
    );
  }

  if (!user) return <Landing onLogin={setUser} />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
      case 'customers': return <CustomerList customers={customers} sales={sales} onAdd={(c) => setCustomers(prev => [...prev, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])} onDelete={(id) => setCustomers(prev => prev.filter(c => c.id !== id))} />;
      case 'sales-cash': return <SalesManager mode="cash" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={(s) => setSales(prev => prev.map(sale => sale.id === s.id ? s : sale))} onDeleteSale={handleDeleteSale} />;
      case 'sales-credit': return <SalesManager mode="credit" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={(s) => setSales(prev => prev.map(sale => sale.id === s.id ? s : sale))} onDeleteSale={handleDeleteSale} />;
      case 'refunds': return (
        <RefundManager 
          sales={sales} 
          customers={customers} 
          onRefund={(id) => handleDeleteSale(id, true)}
          onManualRefund={(desc, amount) => {
            const manualExpense: Expense = {
              id: Math.random().toString(36).substr(2, 9),
              description: `ESTORNO MANUAL: ${desc}`,
              amount: amount
            };
            setExpenses(prev => [...prev, manualExpense]);
            alert(`✅ Estorno manual de R$ ${amount.toFixed(2)} registrado nas Despesas.`);
          }}
        />
      );
      case 'inventory': return <InventoryManager products={products} onAdd={(p) => setProducts(prev => [...prev, { ...p, id: Math.random().toString(36).substr(2, 9) }])} onDelete={(id) => setProducts(prev => prev.filter(p => p.id !== id))} onUpdate={(p) => setProducts(prev => prev.map(prod => prod.id === p.id ? p : prod))} />;
      case 'expenses': return <ExpenseManager expenses={expenses} onAdd={(description, amount) => setExpenses(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), description, amount }])} onDelete={(id) => setExpenses(prev => prev.filter(e => e.id !== id))} />;
      case 'agenda': return <Agenda sales={sales} customers={customers} />;
      case 'trash': return <TrashManager trashItems={trashSales} customers={customers} onRestore={handleRestoreSale} onDeletePermanent={handlePermanentDelete} />;
      case 'settings': return <Settings user={user} customers={customers} sales={sales} products={products} onUpdateProfile={(u) => { setUser(u); localStorage.setItem('gestao93_current_user', JSON.stringify(u)); }} onImport={(data) => { setCustomers(data.customers); setSales(data.sales); setProducts(data.products || []); }} onClear={clearUserData} />;
      default: return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div 
        className="fixed inset-0 pointer-events-none z-0 bg-cover bg-center bg-no-repeat"
        style={{ 
          backgroundImage: `url(${FASHION_IMAGE_URL})`,
          opacity: '0.50',
        }}
      />

      {showTutorial && <Tutorial activeView={activeView} onClose={() => { localStorage.setItem(`gestao93_tutorial_seen_${user.id}`, 'true'); setShowTutorial(false); }} />}

      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col shrink-0 z-50 shadow-2xl relative overflow-hidden">
        <div 
          className="absolute inset-0 pointer-events-none opacity-50 mix-blend-soft-light bg-cover bg-center"
          style={{ backgroundImage: `url(${FASHION_IMAGE_URL})` }}
        />

        <div className="relative z-10 p-6 flex items-center gap-3 border-b border-indigo-900/50">
          <div className="bg-indigo-600 p-2 rounded-xl shrink-0 shadow-lg border border-white/20">
             <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <div className="min-w-0">
            <h1 className="text-xl font-black tracking-tighter italic uppercase text-white truncate drop-shadow-md">Gestão 93</h1>
            <div className="flex items-center gap-1">
              <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-400' : 'bg-amber-400 animate-pulse'}`}></div>
              <span className="text-[8px] font-bold uppercase tracking-widest text-indigo-300 drop-shadow-sm">{syncStatus === 'synced' ? 'Salvo' : 'Sincronizando'}</span>
            </div>
          </div>
        </div>

        <div className="relative z-10 flex-1 py-4 space-y-1 px-3 overflow-y-auto no-scrollbar">
          <NavItem id="nav-dashboard" icon="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" label="Início" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem id="nav-inventory" icon="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" label="Estoque" active={activeView === 'inventory'} onClick={() => setActiveView('inventory')} />
          <NavItem id="nav-customers" icon="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 005.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" label="Clientes" active={activeView === 'customers'} onClick={() => setActiveView('customers')} />
          <div className="pt-4 pb-1 px-4 text-[9px] font-black uppercase tracking-[0.2em] text-indigo-400 drop-shadow-sm">Operacional</div>
          <NavItem id="nav-sales-cash" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" label="À Vista" active={activeView === 'sales-cash'} onClick={() => setActiveView('sales-cash')} />
          <NavItem id="nav-sales-credit" icon="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" label="A Prazo" active={activeView === 'sales-credit'} onClick={() => setActiveView('sales-credit')} />
          <NavItem id="nav-refunds" icon="M16 15v-1a4 4 0 00-4-4H8m0 0l3 3m-3-3l3-3m9 14V5a2 2 0 00-2-2H6a2 2 0 00-2 2v14a2 2 0 002 2h12a2 2 0 002-2z" label="Estornos" active={activeView === 'refunds'} onClick={() => setActiveView('refunds')} />
          <NavItem id="nav-agenda" icon="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" label="Agenda" active={activeView === 'agenda'} onClick={() => setActiveView('agenda')} />
          <NavItem id="nav-expenses" icon="M15 12H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" label="Despesas" active={activeView === 'expenses'} onClick={() => setActiveView('expenses')} />
          <div className="pt-4 pb-1 px-4 text-[9px] font-black uppercase tracking-[0.2em] text-indigo-400 drop-shadow-sm">Sistema</div>
          <NavItem id="nav-trash" icon="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" label="Lixeira" active={activeView === 'trash'} onClick={() => setActiveView('trash')} />
          <NavItem id="nav-settings" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" label="Ajustes" active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
        </div>

        <div className="relative z-10 p-4 bg-black/30 border-t border-indigo-900/50">
           <div className="flex items-center gap-3 p-3 bg-black/20 rounded-2xl border border-white/10 shadow-inner backdrop-blur-sm">
              <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center font-bold text-lg italic shrink-0 overflow-hidden shadow-lg border border-white/20">
                {user.avatarUrl ? (
                  <img src={user.avatarUrl} alt="Logo" className="w-full h-full object-cover" />
                ) : (
                  <span className="text-white">{user.name.charAt(0)}</span>
                )}
              </div>
              <div className="flex-1 min-w-0 text-shadow-sm">
                <p className="text-[10px] font-black truncate text-white uppercase">{user.name}</p>
                <p className="text-[8px] text-indigo-300 font-bold uppercase tracking-tighter">Boutique Premium</p>
              </div>
              <button onClick={handleLogout} className="text-indigo-200 hover:text-rose-400 transition transform hover:scale-110">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              </button>
           </div>
        </div>
      </nav>

      <main className="relative flex-1 p-4 md:p-8 overflow-y-auto h-screen z-10">
        <div className="max-w-6xl mx-auto pb-12 relative">
          {renderView()}
        </div>
      </main>
    </div>
  );
};

const NavItem: React.FC<{ id?: string; icon: string; label: string; active: boolean; onClick: () => void; }> = ({ id, icon, label, active, onClick }) => (
  <button id={id} onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 relative group ${active ? 'bg-indigo-600 text-white shadow-xl translate-x-1 border border-white/10' : 'text-indigo-100 hover:bg-white/10 hover:text-white'}`}>
    <svg className="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={icon} /></svg>
    <span className={`text-sm font-bold tracking-tight whitespace-nowrap drop-shadow-sm ${active ? 'font-black' : ''}`}>{label}</span>
    {active && <div className="absolute right-3 w-1.5 h-1.5 bg-white rounded-full shadow-[0_0_8px_white]"></div>}
  </button>
);

export default App;

export interface User {
  id: string;
  name: string;
  email: string;
  password?: string;
  authProvider?: 'local' | 'onedrive';
  avatarUrl?: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  address?: string;
  cpf?: string;
  createdAt: number;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
}

export interface Product {
  id: string;
  sku: string;
  name: string;
  category: string;
  costPrice: number;
  price: number;
  stock: number;
  minStock: number;
}

export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  PARTIAL = 'PARTIAL',
  CANCELED = 'CANCELED'
}

export interface Installment {
  id: string;
  saleId: string;
  amount: number;
  paidAmount: number;
  dueDate: string;
  paymentDate?: string;
  status: PaymentStatus;
}

export interface SaleItem {
  id: string;
  productId?: string;
  description: string;
  price: number;
  costPrice: number;
  quantity: number;
}

export interface Sale {
  id: string;
  customerId: string;
  description: string;
  items: SaleItem[];
  baseAmount: number;
  discount: number;
  totalAmount: number;
  cardFeeRate?: number;
  cardFeeAmount?: number;
  netAmount: number;
  totalCost: number;
  date: string;
  installments: Installment[];
  status: PaymentStatus;
  type?: 'cash' | 'credit';
}

export interface TrashItem {
  id: string;
  sale: Sale;
  deletedAt: number;
}

export type View = 'dashboard' | 'customers' | 'sales-cash' | 'sales-credit' | 'agenda' | 'settings' | 'expenses' | 'inventory' | 'trash' | 'refunds';

import React, { useState, useEffect, useMemo } from 'react';
import { Customer, Sale, PaymentStatus, Installment, Product, SaleItem } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  customers: Customer[];
  products: Product[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
  onUpdateSale: (sale: Sale) => void;
  onDeleteSale?: (id: string, isRefund: boolean) => void;
  mode: 'cash' | 'credit';
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, customers, products, onAddSale, onUpdateSale, onDeleteSale, mode }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [customerId, setCustomerId] = useState('');
  const [isBalcao, setIsBalcao] = useState(false);

  // Carrinho de Itens
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [selectedProductId, setSelectedProductId] = useState('');
  const [manualDescription, setManualDescription] = useState('');
  const [manualPrice, setManualPrice] = useState<number>(0);

  const [discount, setDiscount] = useState<number>(0);
  const [cardFeeRate, setCardFeeRate] = useState<number>(0);

  const [numInstallments, setNumInstallments] = useState<number>(1);
  const [dueDay, setDueDay] = useState<number>(new Date().getDate());

  const [selectedSaleId, setSelectedSaleId] = useState<string | null>(null);
  const [newInstallmentCount, setNewInstallmentCount] = useState<number>(1);

  // Estados para adicionar item a venda existente
  const [editingSaleAddProduct, setEditingSaleAddProduct] = useState('');

  // Cálculos Automáticos do Formulário
  const baseAmount = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);
  const totalCost = useMemo(() => cart.reduce((acc, item) => acc + (item.costPrice * item.quantity), 0), [cart]);
  const totalAmount = Math.max(0, baseAmount - discount);
  const cardFeeAmount = (totalAmount * cardFeeRate) / 100;
  const netAmount = totalAmount - cardFeeAmount;

  // Preview de Parcelas
  const installmentPreview = useMemo(() => {
    if (numInstallments <= 0) return 0;
    return totalAmount / numInstallments;
  }, [totalAmount, numInstallments]);

  const addToCart = () => {
    if (selectedProductId) {
      const p = products.find(prod => prod.id === selectedProductId);
      if (p) {
        const newItem: SaleItem = {
          id: Math.random().toString(36).substr(2, 5),
          productId: p.id,
          description: `${p.sku} - ${p.name}`,
          price: p.price,
          costPrice: p.costPrice,
          quantity: 1
        };
        setCart([...cart, newItem]);
        setSelectedProductId('');
      }
    } else if (manualDescription && manualPrice > 0) {
      const newItem: SaleItem = {
        id: Math.random().toString(36).substr(2, 5),
        description: manualDescription,
        price: manualPrice,
        costPrice: 0,
        quantity: 1
      };
      setCart([...cart, newItem]);
      setManualDescription('');
      setManualPrice(0);
    }
  };

  const removeFromCart = (id: string) => setCart(cart.filter(i => i.id !== id));

  const formatLocalDate = (date: Date) => {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  };

  const handleAddSale = (e: React.FormEvent) => {
    e.preventDefault();
    const finalCustomerId = isBalcao ? 'BALCAO' : customerId;

    if (!finalCustomerId || cart.length === 0 || totalAmount <= 0) {
      alert("Adicione itens ao carrinho e selecione um cliente.");
      return;
    }

    const installments: Installment[] = [];
    const today = new Date();
    const todayStr = formatLocalDate(today);

    if (mode === 'cash') {
      installments.push({
        id: Math.random().toString(36).substr(2, 9),
        saleId: '', 
        amount: totalAmount,
        paidAmount: totalAmount,
        dueDate: todayStr,
        paymentDate: todayStr,
        status: PaymentStatus.PAID
      });
    } else {
      const baseValue = Math.floor((totalAmount / numInstallments) * 100) / 100;
      const lastValue = Number((totalAmount - (baseValue * (numInstallments - 1))).toFixed(2));

      for (let i = 1; i <= numInstallments; i++) {
        const dueDate = calculateDueDateFromComponents(today.getFullYear(), today.getMonth(), dueDay, i);
        installments.push({
          id: Math.random().toString(36).substr(2, 9),
          saleId: '', 
          amount: i === numInstallments ? lastValue : baseValue,
          paidAmount: 0,
          dueDate: formatLocalDate(dueDate),
          status: PaymentStatus.PENDING
        });
      }
    }

    onAddSale({
      customerId: finalCustomerId,
      items: cart,
      description: cart.map(i => i.description).join(', ').substring(0, 100),
      baseAmount,
      discount,
      totalAmount,
      cardFeeRate,
      cardFeeAmount,
      netAmount,
      totalCost,
      date: todayStr,
      installments,
      status: mode === 'cash' ? PaymentStatus.PAID : PaymentStatus.PENDING,
      type: mode
    });

    setShowAdd(false);
    resetForm();
  };

  const resetForm = () => {
    setCustomerId(''); setIsBalcao(false); setCart([]);
    setDiscount(0); setCardFeeRate(0); setNumInstallments(1);
    setDueDay(new Date().getDate());
  };

  const calculateDueDateFromComponents = (year: number, month: number, targetDay: number, monthsToAdd: number) => {
    let targetMonth = month + monthsToAdd;
    let targetYear = year;
    while (targetMonth > 11) { targetMonth -= 12; targetYear += 1; }
    const lastDayOfMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    const actualDay = Math.min(targetDay, lastDayOfMonth);
    return new Date(targetYear, targetMonth, actualDay);
  };

  const handleAddItemToExistingSale = (sale: Sale, prodId: string) => {
    const p = products.find(prod => prod.id === prodId);
    if (!p) return;

    const newItem: SaleItem = {
      id: Math.random().toString(36).substr(2, 5),
      productId: p.id,
      description: `${p.sku} - ${p.name}`,
      price: p.price,
      costPrice: p.costPrice,
      quantity: 1
    };

    const updatedItems = [...sale.items, newItem];
    const newBaseAmount = updatedItems.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const newTotalCost = updatedItems.reduce((acc, item) => acc + (item.costPrice * item.quantity), 0);
    const newTotalAmount = Math.max(0, newBaseAmount - sale.discount);
    const newCardFeeAmount = (newTotalAmount * (sale.cardFeeRate || 0)) / 100;
    const newNetAmount = newTotalAmount - newCardFeeAmount;

    onUpdateSale({
      ...sale,
      items: updatedItems,
      baseAmount: newBaseAmount,
      totalAmount: newTotalAmount,
      totalCost: newTotalCost,
      cardFeeAmount: newCardFeeAmount,
      netAmount: newNetAmount,
      description: updatedItems.map(i => i.description).join(', ').substring(0, 100),
      status: PaymentStatus.PARTIAL
    });

    setEditingSaleAddProduct('');
    alert('Item adicionado à venda. Não esqueça de ajustar as parcelas se necessário.');
  };

  const handleUpdateInstallment = (sale: Sale, installmentId: string, updates: Partial<Installment>) => {
    const updatedInstallments = sale.installments.map(inst => inst.id === installmentId ? { ...inst, ...updates } : inst);
    const allPaid = updatedInstallments.every(i => i.paidAmount >= i.amount);
    onUpdateSale({
      ...sale,
      installments: updatedInstallments,
      status: allPaid ? PaymentStatus.PAID : PaymentStatus.PARTIAL
    });
  };

  const accentColor = mode === 'cash' ? 'emerald' : 'indigo';

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-black text-slate-800 uppercase italic tracking-tighter">
            {mode === 'cash' ? 'Vendas À Vista' : 'Vendas A Prazo'}
          </h2>
          <p className="text-[10px] text-slate-500 uppercase tracking-widest font-black">
            Gestão de {mode === 'cash' ? 'entrada imediata' : 'fluxo de parcelamento'}
          </p>
        </div>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className={`bg-${accentColor}-600 text-white px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-${accentColor}-700 transition shadow-lg active:scale-95`}
        >
          {showAdd ? 'Cancelar' : 'Nova Venda'}
        </button>
      </div>

      {showAdd && (
        <form onSubmit={handleAddSale} className="bg-white p-6 rounded-3xl shadow-2xl border border-slate-100 space-y-6 animate-in fade-in slide-in-from-top-4 duration-300">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Esquerda: Cliente e Itens */}
            <div className="space-y-4">
              <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                <div className="flex justify-between items-center mb-3">
                  <label className="text-[10px] font-black text-slate-400 uppercase">Cliente</label>
                  <button type="button" onClick={() => setIsBalcao(!isBalcao)} className={`text-[10px] font-black px-3 py-1 rounded-full transition ${isBalcao ? 'bg-amber-500 text-white' : 'bg-slate-200 text-slate-600'}`}>
                    {isBalcao ? '✓ Balcão' : 'Venda Balcão?'}
                  </button>
                </div>
                {!isBalcao && (
                  <select value={customerId} onChange={e => setCustomerId(e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-bold focus:ring-2 focus:ring-indigo-500 outline-none">
                    <option value="">Selecionar Cliente...</option>
                    {customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                )}
              </div>

              <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                <label className="block text-[10px] font-black text-slate-400 uppercase mb-3">Adicionar ao Carrinho</label>
                <div className="flex gap-2 mb-4">
                  <select value={selectedProductId} onChange={e => setSelectedProductId(e.target.value)} className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none">
                    <option value="">Buscar no Estoque...</option>
                    {products.map(p => <option key={p.id} value={p.id}>{p.sku} - {p.name} (R$ {p.price.toFixed(2)})</option>)}
                  </select>
                  <button type="button" onClick={addToCart} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 transition">+</button>
                </div>

                {/* Lista do Carrinho */}
                <div className="space-y-2 max-h-40 overflow-y-auto pr-2 no-scrollbar">
                  {cart.map(item => (
                    <div key={item.id} className="flex justify-between items-center bg-white p-3 rounded-xl border border-slate-200 group">
                      <div className="min-w-0">
                        <p className="text-[10px] font-black text-slate-800 uppercase truncate">{item.description}</p>
                        <p className="text-[9px] font-bold text-indigo-600">R$ {item.price.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                      </div>
                      <button type="button" onClick={() => removeFromCart(item.id)} className="text-slate-300 hover:text-rose-500 p-1 opacity-0 group-hover:opacity-100 transition">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                      </button>
                    </div>
                  ))}
                  {cart.length === 0 && <p className="text-center py-4 text-[10px] font-bold text-slate-400 uppercase italic">Carrinho Vazio</p>}
                </div>
              </div>
            </div>

            {/* Direita: Pagamento */}
            <div className="space-y-4">
              <div className="bg-indigo-900 text-white p-6 rounded-3xl shadow-xl relative overflow-hidden">
                <p className="text-indigo-300 text-[10px] font-black uppercase tracking-[0.2em] mb-1">Total da Venda</p>
                <h3 className="text-4xl font-black tracking-tighter">R$ {totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</h3>

                <div className="grid grid-cols-2 gap-4 mt-6">
                  <div>
                    <label className="text-[9px] font-black uppercase text-indigo-300">Desconto (R$)</label>
                    <input type="number" step="0.01" value={discount || ''} onChange={e => setDiscount(Number(e.target.value))} className="w-full bg-white/10 border border-white/20 rounded-xl px-3 py-1.5 text-sm font-black text-white focus:bg-white/20 outline-none" />
                  </div>
                  <div>
                    <label className="text-[9px] font-black uppercase text-indigo-300">Taxa Cartão (%)</label>
                    <input type="number" step="0.1" value={cardFeeRate || ''} onChange={e => setCardFeeRate(Number(e.target.value))} className="w-full bg-white/10 border border-white/20 rounded-xl px-3 py-1.5 text-sm font-black text-white focus:bg-white/20 outline-none" />
                  </div>
                </div>
              </div>

              {mode === 'credit' && (
                <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100 space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Qtd Parcelas</label>
                      <input type="number" min="1" max="24" value={numInstallments} onChange={e => setNumInstallments(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-black focus:ring-2 focus:ring-indigo-500 outline-none" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Dia Vencimento</label>
                      <input type="number" min="1" max="31" value={dueDay} onChange={e => setDueDay(Number(e.target.value))} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-black focus:ring-2 focus:ring-indigo-500 outline-none" />
                    </div>
                  </div>

                  {/* Real-time Recalculate Feedback */}
                  <div className="bg-indigo-100 p-3 rounded-xl border border-indigo-200 text-center">
                    <p className="text-[9px] font-black text-indigo-400 uppercase tracking-widest mb-1">Preview de Parcelamento</p>
                    <p className="text-lg font-black text-indigo-900">{numInstallments}x de R$ {installmentPreview.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
                </div>
              )}
            </div>
          </div>

          <div className="flex justify-end pt-4">
            <button type="submit" className={`w-full md:w-auto px-12 py-4 rounded-2xl bg-${accentColor}-600 text-white text-xs font-black uppercase tracking-widest shadow-xl hover:bg-${accentColor}-700 transition active:scale-95`}>
              Finalizar Venda de R$ {totalAmount.toFixed(2)}
            </button>
          </div>
        </form>
      )}

      {/* Lista de Vendas */}
      <div className="space-y-4">
        {sales.filter(s => s.type === mode).map(sale => {
          const isExpanded = selectedSaleId === sale.id;
          const totalPaid = sale.installments.reduce((acc, inst) => acc + inst.paidAmount, 0);
          const remaining = sale.totalAmount - totalPaid;

          return (
            <div key={sale.id} className={`bg-white rounded-3xl shadow-sm border transition-all duration-300 ${isExpanded ? 'border-indigo-400 ring-4 ring-indigo-50 scale-[1.01]' : 'border-slate-100 hover:border-slate-200'}`}>
              <div className="p-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div className="flex items-center gap-4">
                  <div className={`p-3 rounded-2xl ${sale.status === PaymentStatus.PAID ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
                  </div>
                  <div>
                    <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">{customers.find(c => c.id === sale.customerId)?.name || '🛒 Cliente Balcão'}</h3>
                    <p className="text-[10px] text-slate-500 font-bold uppercase">{sale.description}</p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[9px] font-black text-slate-300 uppercase">{new Date(sale.date).toLocaleDateString('pt-BR')}</span>
                      <span className={`text-[8px] font-black px-2 py-0.5 rounded-full uppercase ${sale.status === PaymentStatus.PAID ? 'bg-emerald-500 text-white' : 'bg-amber-400 text-white'}`}>
                        {sale.status === PaymentStatus.PAID ? 'Pago' : 'Pendente'}
                      </span>
                    </div>
                  </div>
                </div>

                <div className="flex items-center gap-6 ml-auto">
                  <div className="text-right">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total</p>
                    <p className="text-xl font-black text-slate-900 leading-none">R$ {sale.totalAmount.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                  </div>
                  <button onClick={() => setSelectedSaleId(isExpanded ? null : sale.id)} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-indigo-600 transition">
                    <svg className={`w-6 h-6 transition-transform ${isExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" /></svg>
                  </button>
                </div>
              </div>

              {isExpanded && (
                <div className="px-6 pb-6 pt-2 border-t border-slate-50 animate-in slide-in-from-top-2 duration-300 space-y-6">
                  {/* Adicionar novos produtos na mesma venda */}
                  <div className="bg-indigo-50 p-4 rounded-2xl border border-indigo-100">
                    <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-3">Adicionar mais produtos a esta venda</h4>
                    <div className="flex gap-2">
                      <select value={editingSaleAddProduct} onChange={e => setEditingSaleAddProduct(e.target.value)} className="flex-1 bg-white border border-indigo-200 rounded-xl px-4 py-2 text-[10px] font-bold outline-none">
                        <option value="">Escolher Produto do Estoque...</option>
                        {products.filter(p => p.stock > 0).map(p => <option key={p.id} value={p.id}>{p.sku} - {p.name} (R$ {p.price.toFixed(2)})</option>)}
                      </select>
                      <button 
                        onClick={() => handleAddItemToExistingSale(sale, editingSaleAddProduct)}
                        className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase shadow-lg shadow-indigo-200 active:scale-95 transition"
                      >
                        Incluir Item
                      </button>
                    </div>
                  </div>

                  {/* Detalhes do Pagamento / Parcelas */}
                  <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
                    <div className="bg-slate-50 px-4 py-3 border-b border-slate-200 flex justify-between items-center">
                       <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest italic">Controle de Pagamentos</h4>
                       <p className="text-[10px] font-black text-rose-600 uppercase">Restante: R$ {remaining.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                    </div>
                    <div className="overflow-x-auto">
                      <table className="w-full text-left text-[10px]">
                        <thead className="bg-slate-50/50 text-slate-400 font-black uppercase">
                          <tr>
                            <th className="px-4 py-3">Parc.</th>
                            <th className="px-4 py-3">Vencimento</th>
                            <th className="px-4 py-3">Valor</th>
                            <th className="px-4 py-3">Valor Pago</th>
                            <th className="px-4 py-3">Data Pgto</th>
                            <th className="px-4 py-3 text-center">Ação</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                          {sale.installments.map((inst, idx) => (
                            <tr key={inst.id} className="hover:bg-slate-50/80 transition">
                              <td className="px-4 py-3 font-black text-slate-400">{idx + 1}ª</td>
                              <td className="px-4 py-3 font-bold text-slate-700">{new Date(inst.dueDate).toLocaleDateString('pt-BR')}</td>
                              <td className="px-4 py-3">
                                <input 
                                  type="number" 
                                  step="0.01" 
                                  value={inst.amount} 
                                  onChange={e => handleUpdateInstallment(sale, inst.id, { amount: Number(e.target.value) })}
                                  className="w-16 bg-transparent border-none p-0 font-black text-slate-900 focus:ring-0"
                                />
                              </td>
                              <td className="px-4 py-3">
                                <input 
                                  type="number" 
                                  step="0.01" 
                                  value={inst.paidAmount} 
                                  onChange={e => handleUpdateInstallment(sale, inst.id, { paidAmount: Number(e.target.value) })}
                                  className={`w-16 bg-transparent border-none p-0 font-black focus:ring-0 ${inst.paidAmount >= inst.amount ? 'text-emerald-600' : 'text-amber-600'}`}
                                />
                              </td>
                              <td className="px-4 py-3">
                                <input 
                                  type="date" 
                                  value={inst.paymentDate || ''} 
                                  onChange={e => handleUpdateInstallment(sale, inst.id, { paymentDate: e.target.value })}
                                  className="bg-transparent border-none p-0 text-[9px] font-bold text-slate-400 focus:ring-0"
                                />
                              </td>
                              <td className="px-4 py-3 text-center">
                                {inst.paidAmount < inst.amount ? (
                                  <button onClick={() => handleUpdateInstallment(sale, inst.id, { paidAmount: inst.amount, paymentDate: formatLocalDate(new Date()) })} className="bg-emerald-500 text-white px-2 py-1 rounded text-[8px] font-black uppercase shadow-md shadow-emerald-100">Quitar</button>
                                ) : (
                                  <span className="text-emerald-500">✓</span>
                                )}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>

                  <button onClick={() => onDeleteSale && onDeleteSale(sale.id, false)} className="w-full py-3 bg-rose-50 text-rose-600 rounded-xl text-[9px] font-black uppercase tracking-widest border border-rose-100 hover:bg-rose-600 hover:text-white transition">Excluir Registro de Venda</button>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default SalesManager;

export interface User {
  id: string;
  name: string;
  email: string;
  password?: string;
  authProvider?: 'local' | 'onedrive';
  avatarUrl?: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email?: string;
  address?: string;
  cpf?: string;
  createdAt: number;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
}

export interface Product {
  id: string;
  sku: string;
  name: string;
  category: string;
  costPrice: number;
  price: number;
  stock: number;
  minStock: number;
}

export enum PaymentStatus {
  PENDING = 'PENDING',
  PAID = 'PAID',
  PARTIAL = 'PARTIAL',
  CANCELED = 'CANCELED'
}

export interface Installment {
  id: string;
  saleId: string;
  amount: number;
  paidAmount: number;
  dueDate: string;
  paymentDate?: string;
  status: PaymentStatus;
}

export interface SaleItem {
  id: string;
  productId?: string;
  description: string;
  price: number;
  costPrice: number;
  quantity: number;
}

export interface Sale {
  id: string;
  customerId: string;
  description: string;
  items: SaleItem[];
  baseAmount: number;
  discount: number;
  totalAmount: number;
  cardFeeRate?: number;
  cardFeeAmount?: number;
  netAmount: number;
  totalCost: number;
  date: string;
  installments: Installment[];
  status: PaymentStatus;
  type?: 'cash' | 'credit';
  // Add productId for legacy support and compatibility with single-item logic
  productId?: string;
}

export interface TrashItem {
  id: string;
  sale: Sale;
  deletedAt: number;
}

export type View = 'dashboard' | 'customers' | 'sales-cash' | 'sales-credit' | 'agenda' | 'settings' | 'expenses' | 'inventory' | 'trash' | 'refunds';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { View, Customer, Sale, User, Expense, Product, TrashItem } from './types';
import Dashboard from './components/Dashboard';
import CustomerList from './components/CustomerList';
import SalesManager from './components/SalesManager';
import Agenda from './components/Agenda';
import Settings from './components/Settings';
import Landing from './components/Landing';
import Tutorial from './components/Tutorial';
import ExpenseManager from './components/ExpenseManager';
import InventoryManager from './components/InventoryManager';
import TrashManager from './components/TrashManager';
import RefundManager from './components/RefundManager';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [trashSales, setTrashSales] = useState<TrashItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const isMounted = useRef(false);

  const FASHION_IMAGE_URL = 'https://images.unsplash.com/photo-1445205170230-053b83016050?q=80&w=2000';

  useEffect(() => {
    const initApp = () => {
      try {
        const savedUser = localStorage.getItem('gestao93_current_user');
        if (savedUser && savedUser !== 'undefined') {
          const parsedUser = JSON.parse(savedUser);
          if (parsedUser && parsedUser.id) {
            setUser(parsedUser);
            const userId = parsedUser.id;

            const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
            if (!tutorialSeen) setShowTutorial(true);

            const safeParse = (key: string, fallback: any) => {
              try {
                const data = localStorage.getItem(key);
                return data ? JSON.parse(data) : fallback;
              } catch { return fallback; }
            };

            setCustomers(safeParse(`gestao93_customers_${userId}`, []));
            setSales(safeParse(`gestao93_sales_${userId}`, []));
            setExpenses(safeParse(`gestao93_expenses_${userId}`, []));
            setProducts(safeParse(`gestao93_products_${userId}`, []));

            const loadedTrash = safeParse(`gestao93_trash_${userId}`, []);
            const thirtyDaysInMs = 30 * 24 * 60 * 60 * 1000;
            const validTrash = loadedTrash.filter((item: TrashItem) => (Date.now() - item.deletedAt) < thirtyDaysInMs);
            setTrashSales(validTrash);
          }
        }
      } catch (e) {
        console.error("Erro ao carregar dados:", e);
        localStorage.removeItem('gestao93_current_user');
      } finally {
        setLoading(false);
        isMounted.current = true;
      }
    };
    initApp();
  }, []);

  useEffect(() => {
    if (loading || !user || !isMounted.current) return;

    const timer = setTimeout(() => {
      try {
        setSyncStatus('syncing');
        const userId = user.id;
        localStorage.setItem(`gestao93_customers_${userId}`, JSON.stringify(customers));
        localStorage.setItem(`gestao93_sales_${userId}`, JSON.stringify(sales));
        localStorage.setItem(`gestao93_expenses_${userId}`, JSON.stringify(expenses));
        localStorage.setItem(`gestao93_products_${userId}`, JSON.stringify(products));
        localStorage.setItem(`gestao93_trash_${userId}`, JSON.stringify(trashSales));
        setSyncStatus('synced');
      } catch (err) {
        setSyncStatus('error');
      }
    }, 1000);

    return () => clearTimeout(timer);
  }, [customers, sales, expenses, products, trashSales, user, loading]);

  const handleLogout = () => {
    localStorage.removeItem('gestao93_current_user');
    setUser(null);
    setActiveView('dashboard');
  };

  const handleAddSale = (s: Omit<Sale, 'id'>) => {
    const newId = Math.random().toString(36).substr(2, 9);
    setSales(prev => [...prev, { ...s, id: newId }]);

    // Fix: Handle stock decrement for all items in the sale
    if (s.items && s.items.length > 0) {
      s.items.forEach(item => {
        if (item.productId) {
          setProducts(prev => prev.map(p => 
            p.id === item.productId ? { ...p, stock: Math.max(0, p.stock - item.quantity) } : p
          ));
        }
      });
    }

    // Fix: Handle legacy single productId stock decrement
    if (s.productId) {
      setProducts(prev => prev.map(p => 
        p.id === s.productId ? { ...p, stock: Math.max(0, p.stock - 1) } : p
      ));
    }
  };

  const handleDeleteSale = useCallback((id: string, isRefund: boolean = false) => {
    setSales(prevSales => {
      const saleToDelete = prevSales.find(s => s.id === id);
      if (!saleToDelete) return prevSales;

      if (isRefund) {
        const totalAlreadyPaid = saleToDelete.installments.reduce((acc, inst) => acc + inst.paidAmount, 0);

        if (totalAlreadyPaid > 0) {
          const customer = customers.find(c => c.id === saleToDelete.customerId);
          const customerName = customer ? customer.name : (saleToDelete.customerId === 'BALCAO' ? 'Cliente Balcão' : 'Desconhecido');

          const refundExpense: Expense = {
            id: Math.random().toString(36).substr(2, 9),
            description: `ESTORNO (DEVOLUÇÃO): ${customerName} (${saleToDelete.description})`,
            amount: totalAlreadyPaid
          };

          setExpenses(prev => [...prev, refundExpense]);
          alert(`ℹ️ Estorno Financeiro Realizado!\n\nUma SAÍDA DE CAIXA de R$ ${totalAlreadyPaid.toLocaleString('pt-BR', { minimumFractionDigits: 2 })} foi registrada em suas Despesas.`);
        }
      }

      setTrashSales(prevTrash => [
        ...prevTrash, 
        { id: Math.random().toString(36).substr(2, 9), sale: saleToDelete, deletedAt: Date.now() }
      ]);

      // Fix: Handle legacy single productId stock restoration
      if (saleToDelete.productId) {
        setProducts(prevProducts => prevProducts.map(p => 
          p.id === saleToDelete.productId ? { ...p, stock: p.stock + 1 } : p
        ));
      }

      // Fix: Handle multi-item stock restoration
      if (saleToDelete.items && saleToDelete.items.length > 0) {
        setProducts(prevProducts => {
          let updated = [...prevProducts];
          saleToDelete.items.forEach(item => {
            if (item.productId) {
              updated = updated.map(p => p.id === item.productId ? { ...p, stock: p.stock + item.quantity } : p);
            }
          });
          return updated;
        });
      }

      if (!isRefund) {
        alert('ℹ️ Registro de venda excluído com sucesso (Estoque recomposto).');
      }

      return prevSales.filter(s => s.id !== id);
    });
  }, [customers]);

  const handleRestoreSale = (trashId: string) => {
    const item = trashSales.find(i => i.id === trashId);
    if (!item) return;

    // Fix: Handle legacy single productId stock check and update
    if (item.sale.productId) {
      const p = products.find(prod => prod.id === item.sale.productId);
      if (p && p.stock <= 0) {
        if (!confirm('Produto sem estoque. Restaurar venda mesmo assim?')) return;
      }
      setProducts(prev => prev.map(prod => 
        prod.id === item.sale.productId ? { ...prod, stock: Math.max(0, prod.stock - 1) } : prod
      ));
    }

    // Fix: Handle multi-item stock restoration decrement
    if (item.sale.items && item.sale.items.length > 0) {
      setProducts(prevProducts => {
        let updated = [...prevProducts];
        item.sale.items.forEach(saleItem => {
          if (saleItem.productId) {
            updated = updated.map(p => p.id === saleItem.productId ? { ...p, stock: Math.max(0, p.stock - saleItem.quantity) } : p);
          }
        });
        return updated;
      });
    }

    setSales(prev => [...prev, item.sale]);
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
    alert('Venda restaurada com sucesso!');
  };

  const handlePermanentDelete = (trashId: string) => {
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
  };

  const clearUserData = () => {
    if (!user) return;
    const userId = user.id;
    localStorage.removeItem(`gestao93_customers_${userId}`);
    localStorage.removeItem(`gestao93_sales_${userId}`);
    localStorage.removeItem(`gestao93_expenses_${userId}`);
    localStorage.removeItem(`gestao93_products_${userId}`);
    localStorage.removeItem(`gestao93_trash_${userId}`);
    setCustomers([]);
    setSales([]);
    setExpenses([]);
    setProducts([]);
    setTrashSales([]);
    alert("Todos os seus dados foram apagados.");
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-indigo-950">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
          <h1 className="text-white font-black text-2xl italic uppercase tracking-tighter">Gestão 93</h1>
        </div>
      </div>
    );
  }

  if (!user) return <Landing onLogin={setUser} />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
      case 'customers': return <CustomerList customers={customers} sales={sales} onAdd={(c) => setCustomers(prev => [...prev, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])} onDelete={(id) => setCustomers(prev => prev.filter(c => c.id !== id))} />;
      case 'sales-cash': return <SalesManager mode="cash" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={(s) => setSales(prev => prev.map(sale => sale.id === s.id ? s : sale))} onDeleteSale={handleDeleteSale} />;
      case 'sales-credit': return <SalesManager mode="credit" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={(s) => setSales(prev => prev.map(sale => sale.id === s.id ? s : sale))} onDeleteSale={handleDeleteSale} />;
      case 'refunds': return (
        <RefundManager 
          sales={sales} 
          customers={customers} 
          onRefund={(id) => handleDeleteSale(id, true)}
          onManualRefund={(desc, amount) => {
            const manualExpense: Expense = {
              id: Math.random().toString(36).substr(2, 9),
              description: `ESTORNO MANUAL: ${desc}`,
              amount: amount
            };
            setExpenses(prev => [...prev, manualExpense]);
            alert(`✅ Estorno manual de R$ ${amount.toFixed(2)} registrado nas Despesas.`);
          }}
        />
      );
      case 'inventory': return <InventoryManager products={products} onAdd={(p) => setProducts(prev => [...prev, { ...p, id: Math.random().toString(36).substr(2, 9) }])} onDelete={(id) => setProducts(prev => prev.filter(p => p.id !== id))} onUpdate={(p) => setProducts(prev => prev.map(prod => prod.id === p.id ? p : prod))} />;
      case 'expenses': return <ExpenseManager expenses={expenses} onAdd={(description, amount) => setExpenses(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), description, amount }])} onDelete={(id) => setExpenses(prev => prev.filter(e => e.id !== id))} />;
      case 'agenda': return <Agenda sales={sales} customers={customers} />;
      case 'trash': return <TrashManager trashItems={trashSales} customers={customers} onRestore={handleRestoreSale} onDeletePermanent={handlePermanentDelete} />;
      case 'settings': return <Settings user={user} customers={customers} sales={sales} products={products} onUpdateProfile={(u) => { setUser(u); localStorage.setItem('gestao93_current_user', JSON.stringify(u)); }} onImport={(data) => { setCustomers(data.customers); setSales(data.sales); setProducts(data.products || []); }} onClear={clearUserData} />;
      default: return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div 
        className="fixed inset-0 pointer-events-none z-0 bg-cover bg-center bg-no-repeat"
        style={{ 
