                  <div className="flex gap-1">
                    <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${sale.type === 'cash' ? 'bg-emerald-100 text-emerald-700' : 'bg-indigo-100 text-indigo-700'}`}>
