  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [trashSales, setTrashSales] = useState<TrashItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error' | 'cloud-syncing'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const isMounted = useRef(false);

  const FASHION_IMAGE_URL = 'https://images.unsplash.com/photo-1445205170230-053b83016050?q=80&w=2000';

  useEffect(() => {
    const initApp = async () => {
      try {
        const msal = await getMsalInstance();
        const accounts = msal.getAllAccounts();

        let currentUser: User | null = null;

        // Verifica se há login OneDrive ativo
        if (accounts.length > 0) {
          currentUser = {
            id: accounts[0].homeAccountId,
            name: accounts[0].name || accounts[0].username,
            email: accounts[0].username,
            authProvider: 'onedrive',
            avatarUrl: `https://ui-avatars.com/api/?name=${accounts[0].name}&background=4f46e5&color=fff`
          };
        } else {
          const savedUser = localStorage.getItem('gestao93_current_user');
          if (savedUser) currentUser = JSON.parse(savedUser);
        }

        if (currentUser) {
          setUser(currentUser);
          const userId = currentUser.id;

          const tutorialSeen = localStorage.getItem(`gestao93_tutorial_seen_${userId}`);
          if (!tutorialSeen) setShowTutorial(true);

          // Tenta carregar da nuvem primeiro se for OneDrive
          if (currentUser.authProvider === 'onedrive') {
            setSyncStatus('cloud-syncing');
            const cloudData = await loadFromOneDrive();
            if (cloudData) {
              setCustomers(cloudData.customers || []);
              setSales(cloudData.sales || []);
              setExpenses(cloudData.expenses || []);
              setProducts(cloudData.products || []);
              setTrashSales(cloudData.trashSales || []);
              setSyncStatus('synced');
              setLoading(false);
              isMounted.current = true;
              return;
            }
          }

          // Fallback para LocalStorage
          const safeParse = (key: string, fallback: any) => {
            try {
              const data = localStorage.getItem(key);
              return data ? JSON.parse(data) : fallback;
            } catch { return fallback; }
          };

          setCustomers(safeParse(`gestao93_customers_${userId}`, []));
          setSales(safeParse(`gestao93_sales_${userId}`, []));
          setExpenses(safeParse(`gestao93_expenses_${userId}`, []));
          setProducts(safeParse(`gestao93_products_${userId}`, []));
          setTrashSales(safeParse(`gestao93_trash_${userId}`, []));
        }
      } catch (e) {
        console.error("Erro ao carregar dados:", e);
      } finally {
        setLoading(false);
        isMounted.current = true;
      }
    };
    initApp();
  }, []);

  useEffect(() => {
    if (loading || !user || !isMounted.current) return;

    const timer = setTimeout(async () => {
      try {
        setSyncStatus('syncing');
        const userId = user.id;
        const dataToSave = { customers, sales, expenses, products, trashSales };

        // Salva Local
        localStorage.setItem(`gestao93_customers_${userId}`, JSON.stringify(customers));
        localStorage.setItem(`gestao93_sales_${userId}`, JSON.stringify(sales));
        localStorage.setItem(`gestao93_expenses_${userId}`, JSON.stringify(expenses));
        localStorage.setItem(`gestao93_products_${userId}`, JSON.stringify(products));
        localStorage.setItem(`gestao93_trash_${userId}`, JSON.stringify(trashSales));

        // Salva Nuvem se OneDrive
        if (user.authProvider === 'onedrive') {
          setSyncStatus('cloud-syncing');
          await saveToOneDrive(dataToSave);
        }

        setSyncStatus('synced');
      } catch (err) {
        setSyncStatus('error');
      }
    }, 2000);

    return () => clearTimeout(timer);
  }, [customers, sales, expenses, products, trashSales, user, loading]);

  const handleLogout = () => {
    localStorage.removeItem('gestao93_current_user');
    setUser(null);
    setActiveView('dashboard');
  };

  const handleAddSale = (s: Omit<Sale, 'id'>) => {
    const newId = Math.random().toString(36).substr(2, 9);
    setSales(prev => [...prev, { ...s, id: newId }]);

    if (s.items && s.items.length > 0) {
      s.items.forEach(item => {
        if (item.productId) {
          setProducts(prev => prev.map(p => 
            p.id === item.productId ? { ...p, stock: Math.max(0, p.stock - item.quantity) } : p
          ));
        }
      });
    }
  };

  const handleDeleteSale = useCallback((id: string, isRefund: boolean = false) => {
    setSales(prevSales => {
      const saleToDelete = prevSales.find(s => s.id === id);
      if (!saleToDelete) return prevSales;

      if (isRefund) {
        const totalAlreadyPaid = saleToDelete.installments.reduce((acc, inst) => acc + inst.paidAmount, 0);
        if (totalAlreadyPaid > 0) {
          const refundExpense: Expense = {
            id: Math.random().toString(36).substr(2, 9),
            description: `ESTORNO: ${saleToDelete.customerId}`,
            amount: totalAlreadyPaid,
            category: 'refund',
            date: new Date().toISOString().split('T')[0]
          };
          setExpenses(prev => [...prev, refundExpense]);
        }
      }

      setTrashSales(prevTrash => [...prevTrash, { id: Math.random().toString(36).substr(2, 9), sale: saleToDelete, deletedAt: Date.now() }]);
      return prevSales.filter(s => s.id !== id);
    });
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-indigo-950">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
          <h1 className="text-white font-black text-2xl italic uppercase tracking-tighter">Gestão 93</h1>
        </div>
      </div>
    );
  }

  if (!user) return <Landing onLogin={setUser} />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
      case 'customers': return <CustomerList customers={customers} sales={sales} onAdd={(c) => setCustomers(prev => [...prev, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])} onDelete={(id) => setCustomers(prev => prev.filter(c => c.id !== id))} />;
      case 'sales-cash': return <SalesManager mode="cash" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={(s) => setSales(prev => prev.map(sale => sale.id === s.id ? s : sale))} onDeleteSale={handleDeleteSale} />;
      case 'sales-credit': return <SalesManager mode="credit" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={(s) => setSales(prev => prev.map(sale => sale.id === s.id ? s : sale))} onDeleteSale={handleDeleteSale} />;
      case 'refunds': return <RefundManager sales={sales} customers={customers} expenses={expenses} onRefund={(id) => handleDeleteSale(id, true)} onManualRefund={(desc, amount) => setExpenses(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), description: desc, amount, category: 'refund', date: new Date().toISOString().split('T')[0] }])} />;
      case 'inventory': return <InventoryManager products={products} onAdd={(p) => setProducts(prev => [...prev, { ...p, id: Math.random().toString(36).substr(2, 9) }])} onDelete={(id) => setProducts(prev => prev.filter(p => p.id !== id))} onUpdate={(p) => setProducts(prev => prev.map(prod => prod.id === p.id ? p : prod))} />;
      case 'expenses': return <ExpenseManager expenses={expenses} onAdd={(description, amount) => setExpenses(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), description, amount, category: 'fixed', date: new Date().toISOString().split('T')[0] }])} onDelete={(id) => setExpenses(prev => prev.filter(e => e.id !== id))} />;
      case 'agenda': return <Agenda sales={sales} customers={customers} />;
      case 'trash': return <TrashManager trashItems={trashSales} customers={customers} onRestore={(tid) => { const item = trashSales.find(i => i.id === tid); if(item) { setSales(p => [...p, item.sale]); setTrashSales(p => p.filter(i => i.id !== tid)); } }} onDeletePermanent={(tid) => setTrashSales(p => p.filter(i => i.id !== tid))} />;
      case 'settings': return <Settings user={user} customers={customers} sales={sales} products={products} onUpdateProfile={(u) => setUser(u)} onImport={(data) => { setCustomers(data.customers); setSales(data.sales); }} onClear={() => { setCustomers([]); setSales([]); }} />;
      default: return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div className="fixed inset-0 pointer-events-none z-0 bg-cover bg-center bg-no-repeat" style={{ backgroundImage: `url(${FASHION_IMAGE_URL})`, opacity: '0.50' }} />
      {showTutorial && <Tutorial activeView={activeView} onClose={() => setShowTutorial(false)} />}

      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col shrink-0 z-50 shadow-2xl relative overflow-hidden">
        <div className="relative z-10 p-6 flex items-center gap-3 border-b border-indigo-900/50">
          <div className="bg-indigo-600 p-2 rounded-xl shrink-0 shadow-lg border border-white/20">
             <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <div className="min-w-0">
            <h1 className="text-xl font-black tracking-tighter italic uppercase text-white truncate">Gestão 93</h1>
            <div className="flex items-center gap-1">
              <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-400' : syncStatus === 'cloud-syncing' ? 'bg-blue-400 animate-pulse' : 'bg-amber-400'}`}></div>
              <span className="text-[8px] font-bold uppercase tracking-widest text-indigo-300">
                {syncStatus === 'synced' ? 'Nuvem OK' : syncStatus === 'cloud-syncing' ? 'Sincronizando...' : 'Local'}
              </span>
            </div>
          </div>
        </div>

        <div className="relative z-10 flex-1 py-4 space-y-1 px-3 overflow-y-auto no-scrollbar">
          <NavItem icon="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" label="Início" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem icon="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" label="Estoque" active={activeView === 'inventory'} onClick={() => setActiveView('inventory')} />
          <NavItem icon="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 005.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z" label="Clientes" active={activeView === 'customers'} onClick={() => setActiveView('customers')} />
          <NavItem icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" label="À Vista" active={activeView === 'sales-cash'} onClick={() => setActiveView('sales-cash')} />
          <NavItem icon="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" label="A Prazo" active={activeView === 'sales-credit'} onClick={() => setActiveView('sales-credit')} />
          <NavItem icon="M16 15v-1a4 4 0 00-4-4H8m0 0l3 3m-3-3l3-3m9 14V5a2 2 0 00-2-2H6a2 2 0 00-2 2v14a2 2 0 002 2h12a2 2 0 002-2z" label="Estornos" active={activeView === 'refunds'} onClick={() => setActiveView('refunds')} />
          <NavItem icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" label="Ajustes" active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
        </div>

        <div className="relative z-10 p-4 bg-black/30 border-t border-indigo-900/50">
           <div className="flex items-center gap-3 p-3 bg-black/20 rounded-2xl border border-white/10 shadow-inner backdrop-blur-sm">
              <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center font-bold text-lg italic shrink-0 overflow-hidden shadow-lg border border-white/20">
                {user.avatarUrl ? <img src={user.avatarUrl} alt="Logo" className="w-full h-full object-cover" /> : <span className="text-white">{user.name.charAt(0)}</span>}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-[10px] font-black truncate text-white uppercase">{user.name}</p>
                <p className="text-[8px] text-indigo-300 font-bold uppercase tracking-tighter">Boutique Premium</p>
              </div>
              <button onClick={handleLogout} className="text-indigo-200 hover:text-rose-400 transition transform hover:scale-110">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              </button>
           </div>
        </div>
      </nav>

      <main className="relative flex-1 p-4 md:p-8 overflow-y-auto h-screen z-10">
        <div className="max-w-6xl mx-auto pb-12 relative">{renderView()}</div>
      </main>
    </div>
  );
};

const NavItem: React.FC<{ icon: string; label: string; active: boolean; onClick: () => void; }> = ({ icon, label, active, onClick }) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 relative group ${active ? 'bg-indigo-600 text-white shadow-xl translate-x-1 border border-white/10' : 'text-indigo-100 hover:bg-white/10 hover:text-white'}`}>
    <svg className="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={icon} /></svg>
    <span className={`text-sm font-bold tracking-tight whitespace-nowrap ${active ? 'font-black' : ''}`}>{label}</span>
    {active && <div className="absolute right-3 w-1.5 h-1.5 bg-white rounded-full shadow-[0_0_8px_white]"></div>}
  </button>
);

export default App;

import React, { useState } from 'react';
import { User } from '../types';
