interface LandingProps {
  onLogin: (user: User) => void;
}

const Landing: React.FC<LandingProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [isRecovery, setIsRecovery] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [isAuthenticating, setIsAuthenticating] = useState(false);

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Fallback: Login Local
    const savedUsers = JSON.parse(localStorage.getItem('gestao93_users') || '[]');
    const user = savedUsers.find((u: any) => u.email === email && u.password === password);

    if (user) {
      localStorage.setItem('gestao93_current_user', JSON.stringify(user));
      onLogin(user);
    } else {
      setError('E-mail ou senha incorretos.');
    }
  };

  const handleMicrosoftLogin = async () => {
    setIsAuthenticating(true);
    try {
      const account = await loginOneDrive();
      const msUser: User = {
        id: account.homeAccountId,
        name: account.name || account.username,
        email: account.username,
        authProvider: 'onedrive',
        avatarUrl: `https://ui-avatars.com/api/?name=${account.name}&background=4f46e5&color=fff`
      };
      localStorage.setItem('gestao93_current_user', JSON.stringify(msUser));
      onLogin(msUser);
