        <div className="absolute inset-0 bg-indigo-950/30"></div>
        <div className="absolute inset-0 flex flex-col justify-end p-8 md:p-24 text-white">
          <div className="flex items-center gap-3 mb-4">
            <div className="bg-indigo-600 p-2 rounded-xl shadow-2xl">
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
            </div>
            <h1 className="text-3xl md:text-5xl font-black italic uppercase">Gestão 93</h1>
          </div>
          <p className="text-lg md:text-2xl font-bold italic drop-shadow-lg">“Lute Pelos seus Sonhos hoje !”</p>
        </div>
      </div>

      <div className="flex-1 flex flex-col justify-center p-8 md:p-12 bg-slate-50">
        <div className="max-w-md w-full mx-auto space-y-8">
          <div>
            <h3 className="text-2xl font-black text-slate-900 uppercase">Acesse sua Loja</h3>
            <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Controle de Vendas Profissional</p>
          </div>

          <button 
            onClick={handleMicrosoftLogin}
            disabled={isAuthenticating}
            className="w-full bg-white border-2 border-indigo-100 text-indigo-900 font-black py-4 rounded-2xl hover:bg-indigo-50 transition shadow-sm flex items-center justify-center gap-3 disabled:opacity-50"
          >
            {isAuthenticating ? (
              <div className="w-5 h-5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
            ) : (
              <>
                <img src="https://upload.wikimedia.org/wikipedia/commons/3/3c/Microsoft_Office_OneDrive_%282019-present%29.svg" className="h-6" alt="OneDrive" />
                Entrar com Conta Microsoft
              </>
            )}
          </button>

          <p className="text-[10px] text-indigo-600 font-black text-center uppercase tracking-tighter">
            Salvamento automático na nuvem garantido pela Microsoft.
          </p>

          <div className="relative py-4">
            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div>
            <div className="relative flex justify-center text-xs uppercase"><span className="bg-slate-50 px-4 text-slate-400 font-black">Ou Login Local</span></div>
          </div>

          <form onSubmit={handleAuth} className="space-y-4">
            <input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="E-mail" required className="w-full bg-white border border-slate-300 rounded-xl px-4 py-3 text-sm font-black outline-none" />
            <input type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="Senha" required className="w-full bg-white border border-slate-300 rounded-xl px-4 py-3 text-sm font-black outline-none" />
            {error && <p className="text-rose-600 text-[10px] font-black">{error}</p>}
            <button type="submit" className="w-full bg-indigo-900 text-white font-black py-4 rounded-xl uppercase tracking-widest text-sm">Entrar Local</button>
          </form>
        </div>
      </div>
    </div>
  );
};

