import React, { useState, useEffect, useMemo } from 'react';
import { Sale, Customer, PaymentStatus, Expense, Product } from '../types';
import { getFinancialInsights } from '../services/geminiService';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface DashboardProps {
  sales: Sale[];
  customers: Customer[];
  expenses: Expense[];
  products: Product[];
}

const Dashboard: React.FC<DashboardProps> = ({ sales, customers, expenses, products }) => {
  const [insights, setInsights] = useState<string>('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [showBreakdown, setShowBreakdown] = useState(false);

  // Estado para seleção de mês e ano
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth());
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(value);
  };

  const months = [
    'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
    'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
  ];

  const years = useMemo(() => {
    const currentYear = new Date().getFullYear();
    const startYear = 2024;
    const list = [];
    for (let y = currentYear; y >= startYear; y--) list.push(y);
    return list;
  }, []);

  // Filtragem e Cálculos baseados no mês selecionado
  const getFinancialsForMonth = (month: number, year: number) => {
    const monthSales = sales.filter(s => {
      const saleDate = new Date(s.date);
      return saleDate.getMonth() === month && saleDate.getFullYear() === year;
    });

    const monthExpenses = expenses.filter(e => {
      if (!e.date) return true; 
      const expDate = new Date(e.date);
      return expDate.getMonth() === month && expDate.getFullYear() === year;
    });

    const stats = monthSales.reduce((acc, s) => {
      acc.grossRevenue += s.baseAmount;
      acc.discounts += s.discount;
      acc.cardFees += (s.cardFeeAmount || 0);
      acc.totalCostOfGoods += s.totalCost;
      return acc;
    }, { grossRevenue: 0, discounts: 0, cardFees: 0, totalCostOfGoods: 0 });

    const totalRefunds = monthExpenses
      .filter(e => e.category === 'refund')
      .reduce((sum, e) => sum + e.amount, 0);

    const totalFixedExpenses = monthExpenses
      .filter(e => e.category === 'fixed' || !e.category)
      .reduce((sum, e) => sum + e.amount, 0);

    const netRevenueBeforeRefund = monthSales.reduce((sum, s) => sum + s.netAmount, 0);
    const realRevenue = netRevenueBeforeRefund - totalRefunds;

    const realReceived = sales.reduce((total, sale) => {
      return total + sale.installments.reduce((sum, inst) => {
        if (inst.paymentDate) {
          const pDate = new Date(inst.paymentDate);
          if (pDate.getMonth() === month && pDate.getFullYear() === year) {
            return sum + inst.paidAmount;
          }
        }
        return sum;
      }, 0);
    }, 0);

    return { 
      ...stats, 
      realRevenue, 
      realReceived, 
      totalRefunds, 
      totalFixedExpenses,
      profit: realRevenue - stats.totalCostOfGoods - totalFixedExpenses
    };
  };

  const cur = getFinancialsForMonth(selectedMonth, selectedYear);
  const totalStockValueAtSalesPrice = products.reduce((acc, p) => acc + (p.price * p.stock), 0);

  const historyData = Array.from({ length: 6 }).map((_, i) => {
    const d = new Date();
    d.setMonth(d.getMonth() - (5 - i));
    const financials = getFinancialsForMonth(d.getMonth(), d.getFullYear());
    return {
      name: d.toLocaleString('pt-BR', { month: 'short' }).toUpperCase(),
      Faturamento: financials.grossRevenue, // Mudado para Bruto no gráfico também
      Recebido: financials.realReceived,
    };
  });

  const fetchInsights = async (force = false) => {
    if (!force && insights && insights !== 'Carregando insights...') return;
    if (sales.length === 0) {
      setInsights("Registre suas primeiras vendas para ver a análise da IA.");
      return;
    }
    setIsSyncing(true);
    setInsights("Analisando seus dados financeiros...");
    const result = await getFinancialInsights(sales, customers);
    setInsights(result || "Nenhum insight disponível.");
    setIsSyncing(false);
  };

  useEffect(() => {
    if (!insights) fetchInsights();
  }, [sales.length]);

  return (
    <div className="space-y-6">
      {/* Cabeçalho com Seletor de Mês */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div className="backdrop-blur-sm bg-white/30 p-2 rounded-xl">
          <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase italic">Gestão de Vendas Brutas</h2>
          <p className="text-sm text-slate-700 font-bold uppercase tracking-wider">Divisão por período e performance</p>
        </div>

        <div className="flex items-center gap-2 bg-white/80 p-1.5 rounded-2xl shadow-sm border border-slate-200">
          <select 
            value={selectedMonth} 
            onChange={(e) => setSelectedMonth(Number(e.target.value))}
            className="bg-transparent text-xs font-black uppercase text-indigo-900 px-3 py-1.5 outline-none cursor-pointer"
          >
            {months.map((m, i) => <option key={m} value={i}>{m}</option>)}
          </select>
          <select 
            value={selectedYear} 
            onChange={(e) => setSelectedYear(Number(e.target.value))}
            className="bg-transparent text-xs font-black uppercase text-indigo-900 px-3 py-1.5 outline-none cursor-pointer border-l border-slate-200"
          >
            {years.map(y => <option key={y} value={y}>{y}</option>)}
          </select>
        </div>
      </div>

      {/* KPI Principal: Faturamento Bruto */}
      <div className="bg-indigo-900/95 backdrop-blur-md p-8 rounded-3xl shadow-2xl border border-indigo-400/20 text-white relative overflow-hidden">
          <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
            <div>
               <p className="text-indigo-200 text-[10px] font-black uppercase tracking-[0.2em] mb-1">Faturamento Bruto ({months[selectedMonth]})</p>
               <h3 className="text-5xl font-black tracking-tighter">{formatCurrency(cur.grossRevenue)}</h3>
               <p className="text-[10px] text-indigo-300 mt-2 font-bold uppercase tracking-widest italic opacity-75">
                 Valor total vendido sem descontos ou estornos.
               </p>
            </div>
            <div className="flex flex-col md:flex-row gap-4">
                <div className="bg-white/10 p-5 rounded-3xl backdrop-blur-lg border border-white/20 shadow-inner">
                   <p className="text-indigo-100 text-[9px] font-black uppercase tracking-widest mb-1">Líquido Estimado</p>
                   <p className="text-2xl font-black text-white">{formatCurrency(cur.realRevenue)}</p>
                </div>
            </div>
          </div>
          <div className="absolute -right-20 -top-20 w-64 h-64 bg-indigo-500/20 rounded-full blur-3xl pointer-events-none"></div>
      </div>

      {/* Cards de Métricas */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white/70 backdrop-blur-md p-6 rounded-3xl shadow-xl border border-white/40 group">
          <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mb-1">Descontos & Estornos</p>
          <h3 className="text-xl font-black text-rose-600">{formatCurrency(cur.discounts + cur.totalRefunds)}</h3>
          <p className="text-[9px] text-slate-400 mt-1 font-black uppercase tracking-tighter">Impacto no faturamento bruto</p>
        </div>

        <div className="bg-emerald-600 p-6 rounded-3xl shadow-xl relative overflow-hidden">
          <p className="text-emerald-100 text-[10px] font-black uppercase tracking-widest mb-1 relative z-10">Entrada de Caixa (Real)</p>
          <h3 className="text-xl font-black text-white relative z-10">{formatCurrency(cur.realReceived)}</h3>
          <p className="text-[9px] text-emerald-200 mt-1 font-black uppercase tracking-tighter relative z-10">Recebimento efetivo no mês</p>
        </div>

        <div className="bg-white/70 backdrop-blur-md p-6 rounded-3xl shadow-xl border border-white/40 group">
          <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mb-1">Custo de Aquisição (CMV)</p>
          <h3 className="text-xl font-black text-slate-800">{formatCurrency(cur.totalCostOfGoods)}</h3>
          <p className="text-[9px] text-slate-400 mt-1 font-black uppercase tracking-tighter">Custo das peças vendidas</p>
        </div>

        <div className={`p-6 rounded-3xl shadow-2xl border-2 backdrop-blur-lg ${cur.profit >= 0 ? 'bg-indigo-50 border-indigo-200' : 'bg-rose-50 border-rose-200'}`}>
          <p className="text-slate-600 text-[10px] font-black uppercase tracking-widest mb-1">Lucro Operacional</p>
          <h3 className={`text-xl font-black ${cur.profit >= 0 ? 'text-indigo-700' : 'text-rose-700'}`}>
            {formatCurrency(cur.profit)}
          </h3>
          <p className="text-[9px] text-slate-500 mt-1 font-black uppercase tracking-tighter italic">Após todas as deduções</p>
        </div>
      </div>

      <div className="flex justify-end">
        <button 
          onClick={() => setShowBreakdown(!showBreakdown)}
          className="bg-slate-900 text-white px-6 py-3 rounded-xl text-xs font-black uppercase hover:bg-black transition shadow-xl"
        >
          {showBreakdown ? 'Ocultar DRE' : 'Ver DRE Completo'}
        </button>
      </div>

      {showBreakdown && (
        <div className="bg-slate-900/95 backdrop-blur-xl text-white p-10 rounded-[3rem] shadow-2xl animate-in fade-in slide-in-from-top-4 duration-500 border border-white/10">
           <h4 className="text-xl font-black uppercase italic tracking-widest mb-8 text-indigo-400 border-b border-white/10 pb-4">Demonstrativo ({months[selectedMonth]} {selectedYear})</h4>
           <div className="space-y-4 font-mono text-sm">
              <div className="flex justify-between border-b border-white/5 pb-2 text-indigo-300 font-black">
