import React, { useState, useEffect, useMemo } from 'react';
import { Sale, Customer, PaymentStatus, Expense, Product } from '../types.ts';
import { getFinancialInsights } from '../services/geminiService.ts';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface DashboardProps {
  sales: Sale[];
  customers: Customer[];
  expenses: Expense[];
  products: Product[];
}

const Dashboard: React.FC<DashboardProps> = ({ sales, customers, expenses, products }) => {
  const [insights, setInsights] = useState<string>('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [showBreakdown, setShowBreakdown] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth());
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const months = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

  const years = useMemo(() => {
    const list = [];
    for (let y = new Date().getFullYear(); y >= 2024; y--) list.push(y);
    return list;
  }, []);

  const getFinancialsForMonth = (month: number, year: number) => {
    const monthSales = sales.filter(s => {
      const saleDate = new Date(s.date);
      return saleDate.getMonth() === month && saleDate.getFullYear() === year;
    });

    const monthExpenses = expenses.filter(e => {
      if (!e.date) return true; 
      const expDate = new Date(e.date);
      return expDate.getMonth() === month && expDate.getFullYear() === year;
    });

    const stats = monthSales.reduce((acc, s) => {
      acc.grossRevenue += s.baseAmount;
      acc.discounts += s.discount;
      acc.totalCostOfGoods += s.totalCost;
      return acc;
    }, { grossRevenue: 0, discounts: 0, totalCostOfGoods: 0 });

    const totalRefunds = monthExpenses.filter(e => e.category === 'refund').reduce((sum, e) => sum + e.amount, 0);
    const totalFixedExpenses = monthExpenses.filter(e => e.category === 'fixed' || !e.category).reduce((sum, e) => sum + e.amount, 0);
    const realRevenue = monthSales.reduce((sum, s) => sum + s.netAmount, 0) - totalRefunds;

    const realReceived = sales.reduce((total, sale) => {
      return total + sale.installments.reduce((sum, inst) => {
        if (inst.paymentDate) {
          const pDate = new Date(inst.paymentDate);
          if (pDate.getMonth() === month && pDate.getFullYear() === year) return sum + inst.paidAmount;
        }
        return sum;
      }, 0);
    }, 0);

    return { ...stats, realRevenue, realReceived, totalRefunds, totalFixedExpenses, profit: realRevenue - stats.totalCostOfGoods - totalFixedExpenses };
  };

  const cur = getFinancialsForMonth(selectedMonth, selectedYear);

  const fetchInsights = async (force = false) => {
    if (!force && insights) return;
    if (sales.length === 0) { setInsights("Adicione vendas para análise."); return; }
    setIsSyncing(true);
    const result = await getFinancialInsights(sales, customers);
    setInsights(result || "Nenhum insight disponível.");
    setIsSyncing(false);
  };

  useEffect(() => { fetchInsights(); }, [sales.length]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div className="backdrop-blur-sm bg-white/30 p-2 rounded-xl">
          <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase italic">Gestão de Vendas Brutas</h2>
        </div>
        <div className="flex items-center gap-2 bg-white/80 p-1.5 rounded-2xl shadow-sm border border-slate-200">
          <select value={selectedMonth} onChange={(e) => setSelectedMonth(Number(e.target.value))} className="bg-transparent text-xs font-black uppercase text-indigo-900 px-3 py-1.5 outline-none">{months.map((m, i) => <option key={m} value={i}>{m}</option>)}</select>
          <select value={selectedYear} onChange={(e) => setSelectedYear(Number(e.target.value))} className="bg-transparent text-xs font-black uppercase text-indigo-900 px-3 py-1.5 outline-none border-l border-slate-200">{years.map(y => <option key={y} value={y}>{y}</option>)}</select>
        </div>
      </div>

      <div className="bg-indigo-900/95 backdrop-blur-md p-8 rounded-3xl shadow-2xl text-white relative overflow-hidden">
          <p className="text-indigo-200 text-[10px] font-black uppercase tracking-[0.2em] mb-1">Faturamento Bruto ({months[selectedMonth]})</p>
          <h3 className="text-5xl font-black tracking-tighter">{formatCurrency(cur.grossRevenue)}</h3>
          <div className="absolute -right-20 -top-20 w-64 h-64 bg-indigo-500/20 rounded-full blur-3xl pointer-events-none"></div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard label="Descontos & Estornos" value={formatCurrency(cur.discounts + cur.totalRefunds)} color="rose-600" />
        <StatCard label="Entrada Real (Caixa)" value={formatCurrency(cur.realReceived)} color="emerald-600" />
        <StatCard label="Custo CMV" value={formatCurrency(cur.totalCostOfGoods)} color="slate-800" />
        <StatCard label="Lucro Operacional" value={formatCurrency(cur.profit)} color={cur.profit >= 0 ? "indigo-700" : "rose-700"} />
      </div>

      <div className={`p-8 rounded-[2.5rem] border-2 bg-indigo-50 border-indigo-200 shadow-xl backdrop-blur-lg`}>
        <h4 className="font-black text-[9px] uppercase tracking-[0.3em] text-indigo-900 mb-4">Insights (IA)</h4>
        <div className="text-xs leading-relaxed font-black italic text-indigo-900">"{insights}"</div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ label: string; value: string; color: string }> = ({ label, value, color }) => (
  <div className="bg-white/70 backdrop-blur-md p-6 rounded-3xl shadow-xl border border-white/40">
    <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest mb-1">{label}</p>
    <h3 className={`text-xl font-black text-${color}`}>{value}</h3>
  </div>
);

export default Dashboard;

import { GoogleGenAI } from "@google/genai";
import { Sale, Customer } from "../types.ts";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const COOLDOWN_TIME = 60000;
let cooldownUntil = 0;

export const getFinancialInsights = async (sales: Sale[], customers: Customer[]) => {
  const now = Date.now();
  if (now < cooldownUntil) return "⚠️ IA em repouso. Tente em instantes.";
  if (sales.length === 0) return "Adicione vendas para análise.";

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analise brevemente: Loja com ${sales.length} vendas (R$ ${sales.reduce((acc, s) => acc + s.totalAmount, 0)}). Foco em saúde do caixa.`,
      config: { temperature: 0.5, maxOutputTokens: 200 }
    });
    return response.text || "Sem insights.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Falha na IA.";
  }
};

