                                        onClick={() => handlePaymentAction(saleId, installment.id, instRemaining)}
                                        className="bg-emerald-500 text-white px-4 py-2 rounded-xl text-[9px] font-black uppercase shadow-md shadow-emerald-100 hover:bg-emerald-600 transition"
                                      >
                                        Quitar
                                      </button>
                                    </div>
                                  )}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
};

