import React, { useState } from 'react';
import { Sale, Customer, PaymentStatus, Installment } from '../types.ts';

interface AgendaProps {
  sales: Sale[];
  customers: Customer[];
  onUpdateSale: (sale: Sale) => void;
}

interface InstallmentItem {
  saleId: string;
  installment: Installment;
  customerName: string;
  saleDescription: string;
  monthYear: string;
}

const Agenda: React.FC<AgendaProps> = ({ sales, customers, onUpdateSale }) => {
  const [abatimentoValues, setAbatimentoValues] = useState<Record<string, string>>({});

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const getSortedInstallments = (): InstallmentItem[] => {
    const allItems: InstallmentItem[] = [];

    sales.forEach(sale => {
      sale.installments.forEach(inst => {
        const date = new Date(inst.dueDate);
        const monthYear = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });

        const customer = sale.customerId === 'BALCAO' 
          ? { name: '🛒 Venda Balcão' } 
          : customers.find(c => c.id === sale.customerId);

        allItems.push({
          saleId: sale.id,
          installment: inst,
          customerName: customer?.name || 'Cliente Excluído',
          saleDescription: sale.description,
          monthYear
        });
      });
    });

    // Ordena por data de vencimento
    return allItems.sort((a, b) => 
      new Date(a.installment.dueDate).getTime() - new Date(b.installment.dueDate).getTime()
    );
  };

  const handlePaymentAction = (saleId: string, instId: string, amountStr: string) => {
    const amount = parseFloat(amountStr.replace(',', '.'));
    if (isNaN(amount) || amount <= 0) return;

    const sale = sales.find(s => s.id === saleId);
    if (!sale) return;

    const todayStr = new Date().toISOString().split('T')[0];
    const updatedInstallments = sale.installments.map(inst => {
      if (inst.id === instId) {
        const newPaidAmount = Math.min(inst.amount, inst.paidAmount + amount);
        return {
          ...inst,
          paidAmount: newPaidAmount,
          paymentDate: newPaidAmount >= inst.amount ? todayStr : inst.paymentDate,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });

    const allPaid = updatedInstallments.every(i => i.paidAmount >= i.amount);
    onUpdateSale({
      ...sale,
      installments: updatedInstallments,
      status: allPaid ? PaymentStatus.PAID : PaymentStatus.PARTIAL
    });

    setAbatimentoValues(prev => ({ ...prev, [instId]: '' }));
  };

  const handleFullPayment = (saleId: string, instId: string) => {
    const sale = sales.find(s => s.id === saleId);
    const inst = sale?.installments.find(i => i.id === instId);
    if (sale && inst) {
      handlePaymentAction(saleId, instId, (inst.amount - inst.paidAmount).toString());
    }
  };

  const allInstallments = getSortedInstallments();

  const groupedByMonth = allInstallments.reduce((acc, item) => {
    if (!acc[item.monthYear]) acc[item.monthYear] = [];
    acc[item.monthYear].push(item);
    return acc;
  }, {} as Record<string, InstallmentItem[]>);

  const sortedMonthKeys = Object.keys(groupedByMonth).sort((a, b) => {
    const parseMonth = (str: string) => {
      const parts = str.split(' de ');
      const months = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
      return new Date(parseInt(parts[1]), months.indexOf(parts[0].toLowerCase())).getTime();
    };
    return parseMonth(a) - parseMonth(b);
  });

  return (
    <div className="space-y-8 pb-10">
      <div className="flex flex-col gap-1">
        <h2 className="text-xl font-black text-slate-800 uppercase italic">Agenda de Recebimentos</h2>
        <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Controle individual de parcelas e vencimentos</p>
      </div>

      {sortedMonthKeys.length === 0 && (
        <div className="bg-white/50 backdrop-blur-sm p-12 text-center rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 font-bold uppercase text-xs tracking-widest">
          Nenhuma parcela encontrada.
        </div>
      )}

      {sortedMonthKeys.map(month => (
        <div key={month} className="space-y-4">
          <div className="sticky top-0 z-10 bg-slate-50/80 backdrop-blur-sm py-2 border-b border-slate-200">
            <h3 className="text-sm font-black text-indigo-900 capitalize italic tracking-wide">{month}</h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
            {groupedByMonth[month].map(({ saleId, installment, customerName, saleDescription }) => {
              const remaining = installment.amount - installment.paidAmount;
              const isPaid = remaining <= 0;
              const isOverdue = !isPaid && new Date(installment.dueDate) < new Date(new Date().setHours(0,0,0,0));

              return (
                <div 
                  key={installment.id} 
                  className={`relative bg-white rounded-2xl border transition-all shadow-sm flex flex-col justify-between ${
                    isPaid ? 'border-emerald-100 opacity-75' : 
                    isOverdue ? 'border-rose-200 ring-1 ring-rose-50' : 'border-slate-200 hover:border-indigo-300'
                  }`}
                >
                  <div className="p-4">
                    <div className="flex justify-between items-start mb-2">
                      <span className={`text-[9px] font-black px-2 py-0.5 rounded-full uppercase tracking-tighter ${
                        isPaid ? 'bg-emerald-500 text-white' : 
                        isOverdue ? 'bg-rose-500 text-white animate-pulse' : 'bg-indigo-100 text-indigo-700'
                      }`}>
                        Venc: {new Date(installment.dueDate).toLocaleDateString('pt-BR')}
                      </span>
                      {isPaid && <span className="text-emerald-500 font-black text-[10px]">PAGO</span>}
                    </div>

                    <h4 className={`text-xs font-black uppercase truncate ${customerName.includes('🛒') ? 'text-amber-600' : 'text-slate-800'}`}>
                      {customerName}
                    </h4>
                    <p className="text-[9px] text-slate-400 font-bold uppercase truncate mb-3">{saleDescription}</p>

                    <div className="flex justify-between items-end bg-slate-50 p-2 rounded-xl border border-slate-100">
                      <div className="text-left">
                        <p className="text-[8px] font-black text-slate-400 uppercase leading-none">Total Parc.</p>
                        <p className="text-xs font-black text-slate-600">{formatCurrency(installment.amount)}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-[8px] font-black text-slate-400 uppercase leading-none">Aberto</p>
                        <p className={`text-sm font-black ${isPaid ? 'text-emerald-600' : 'text-rose-600'}`}>
                          {formatCurrency(remaining)}
                        </p>
                      </div>
                    </div>
                  </div>

                  {!isPaid && (
                    <div className="p-3 bg-slate-50/50 border-t border-slate-100 rounded-b-2xl flex flex-col gap-2">
                      <div className="flex gap-1">
                        <div className="flex-1 flex items-center bg-white border border-slate-200 rounded-lg overflow-hidden h-8">
                          <span className="pl-2 text-[9px] font-black text-slate-400">R$</span>
                          <input 
                            type="text" 
                            inputMode="decimal"
                            placeholder="Valor"
                            value={abatimentoValues[installment.id] || ''}
                            onChange={e => setAbatimentoValues(prev => ({ ...prev, [installment.id]: e.target.value }))}
                            className="w-full h-full px-1 text-[10px] font-black text-indigo-600 outline-none"
                          />
                          <button 
                            onClick={() => handlePaymentAction(saleId, installment.id, abatimentoValues[installment.id] || '0')}
                            className="bg-indigo-600 text-white px-2 h-full text-[8px] font-black uppercase hover:bg-indigo-700 transition active:scale-95"
                          >
                            Abater
                          </button>
                        </div>
                        <button 
                          onClick={() => handleFullPayment(saleId, installment.id)}
                          className="bg-emerald-500 text-white px-3 h-8 rounded-lg text-[8px] font-black uppercase shadow-sm hover:bg-emerald-600 transition active:scale-95"
                        >
                          Quitar
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
};

