import React, { useState } from 'react';
import { Sale, Customer, PaymentStatus, Installment } from '../types.ts';

interface AgendaProps {
  sales: Sale[];
  customers: Customer[];
  onUpdateSale: (sale: Sale) => void;
}

interface InstallmentItem {
  saleId: string;
  installment: Installment;
  saleDescription: string;
}

interface CustomerGroup {
  customerId: string;
  customerName: string;
  totalAmount: number;
  totalRemaining: number;
  installments: InstallmentItem[];
  isOverdue: boolean;
}

const Agenda: React.FC<AgendaProps> = ({ sales, customers, onUpdateSale }) => {
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({});
  const [abatimentoValues, setAbatimentoValues] = useState<Record<string, string>>({});

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const toggleGroup = (groupId: string) => {
    setExpandedGroups(prev => ({ ...prev, [groupId]: !prev[groupId] }));
  };

  const getGroupedData = () => {
    const months: Record<string, Record<string, CustomerGroup>> = {};

    sales.forEach(sale => {
      sale.installments.forEach(inst => {
        const date = new Date(inst.dueDate);
        const monthYear = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
        const customerId = sale.customerId;

        if (!months[monthYear]) months[monthYear] = {};

        if (!months[monthYear][customerId]) {
          const customer = customerId === 'BALCAO' 
            ? { name: '🛒 Venda Balcão' } 
            : customers.find(c => c.id === customerId);

          months[monthYear][customerId] = {
            customerId,
            customerName: customer?.name || 'Cliente Excluído',
            totalAmount: 0,
            totalRemaining: 0,
            installments: [],
            isOverdue: false
          };
        }

        const group = months[monthYear][customerId];
        const remaining = inst.amount - inst.paidAmount;
        const isInstOverdue = remaining > 0 && new Date(inst.dueDate) < new Date(new Date().setHours(0,0,0,0));

        group.totalAmount += inst.amount;
        group.totalRemaining += remaining;
        if (isInstOverdue) group.isOverdue = true;

        group.installments.push({
          saleId: sale.id,
          installment: inst,
          saleDescription: sale.description
        });
      });
    });

    // Ordenar parcelas dentro de cada grupo por data
    Object.values(months).forEach(customersInMonth => {
      Object.values(customersInMonth).forEach(group => {
        group.installments.sort((a, b) => 
          new Date(a.installment.dueDate).getTime() - new Date(b.installment.dueDate).getTime()
        );
      });
    });

    return months;
  };

  const handlePaymentAction = (saleId: string, instId: string, amountStr: string) => {
    const amount = parseFloat(amountStr.replace(',', '.'));
    if (isNaN(amount) || amount <= 0) return;

    const sale = sales.find(s => s.id === saleId);
    if (!sale) return;

    const todayStr = new Date().toISOString().split('T')[0];
    const updatedInstallments = sale.installments.map(inst => {
      if (inst.id === instId) {
        const newPaidAmount = Math.min(inst.amount, inst.paidAmount + amount);
        return {
          ...inst,
          paidAmount: newPaidAmount,
          paymentDate: newPaidAmount >= inst.amount ? todayStr : inst.paymentDate,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });

    const allPaid = updatedInstallments.every(i => i.paidAmount >= i.amount);
    onUpdateSale({
      ...sale,
      installments: updatedInstallments,
      status: allPaid ? PaymentStatus.PAID : PaymentStatus.PARTIAL
    });

    setAbatimentoValues(prev => ({ ...prev, [instId]: '' }));
  };

  const handleFullPayment = (saleId: string, instId: string) => {
    const sale = sales.find(s => s.id === saleId);
    const inst = sale?.installments.find(i => i.id === instId);
    if (sale && inst) {
      handlePaymentAction(saleId, instId, (inst.amount - inst.paidAmount).toString());
    }
  };

  const groupedData = getGroupedData();
  const sortedMonthKeys = Object.keys(groupedData).sort((a, b) => {
    const parseMonth = (str: string) => {
      const parts = str.split(' de ');
      const months = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
      return new Date(parseInt(parts[1]), months.indexOf(parts[0].toLowerCase())).getTime();
    };
    return parseMonth(a) - parseMonth(b);
  });

  return (
    <div className="space-y-8 pb-10">
      <div className="flex flex-col gap-1">
        <h2 className="text-xl font-black text-slate-800 uppercase italic">Agenda de Recebimentos</h2>
        <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Valores somados por cliente no mês</p>
      </div>

      {sortedMonthKeys.length === 0 && (
        <div className="bg-white/50 backdrop-blur-sm p-12 text-center rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 font-bold uppercase text-xs tracking-widest">
          Nenhuma parcela encontrada.
        </div>
      )}

      {sortedMonthKeys.map(month => {
        const customersInMonth = Object.values(groupedData[month]);

        return (
          <div key={month} className="space-y-4">
            <div className="sticky top-0 z-10 bg-slate-50/80 backdrop-blur-sm py-2 border-b border-slate-200 flex justify-between items-center">
              <h3 className="text-sm font-black text-indigo-900 capitalize italic tracking-wide">{month}</h3>
              <span className="text-[10px] font-black text-slate-400 uppercase">
                {customersInMonth.length} {customersInMonth.length === 1 ? 'Cliente' : 'Clientes'}
              </span>
            </div>

            <div className="space-y-3">
              {customersInMonth.map(group => {
                const groupId = `${month}-${group.customerId}`;
                const isExpanded = !!expandedGroups[groupId];
                const isPaid = group.totalRemaining <= 0;

                return (
                  <div key={groupId} className={`bg-white rounded-3xl border transition-all ${isExpanded ? 'ring-2 ring-indigo-500 border-transparent shadow-xl' : 'border-slate-100 hover:border-indigo-200 shadow-sm'}`}>
                    {/* Resumo do Cliente */}
                    <div 
                      onClick={() => toggleGroup(groupId)}
                      className="p-5 cursor-pointer flex justify-between items-center"
                    >
                      <div className="flex items-center gap-4">
                        <div className={`w-10 h-10 rounded-2xl flex items-center justify-center font-black text-lg shadow-sm border ${
                          isPaid ? 'bg-emerald-100 text-emerald-600 border-emerald-200' : 
                          group.isOverdue ? 'bg-rose-100 text-rose-600 border-rose-200' : 
                          'bg-indigo-100 text-indigo-600 border-indigo-200'
                        }`}>
                          {group.customerName.charAt(0)}
                        </div>
                        <div>
                          <h4 className={`text-sm font-black uppercase tracking-tight ${group.customerName.includes('🛒') ? 'text-amber-600' : 'text-slate-800'}`}>
                            {group.customerName}
                          </h4>
                          <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest leading-none">
                            {group.installments.length} {group.installments.length === 1 ? 'Título' : 'Títulos'} no mês
                          </p>
                        </div>
                      </div>

                      <div className="flex items-center gap-4">
                        <div className="text-right">
                          <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">Total Devedor</p>
                          <p className={`text-base font-black ${isPaid ? 'text-emerald-600' : 'text-rose-600'}`}>
                            {formatCurrency(group.totalRemaining)}
                          </p>
                        </div>
                        <svg className={`w-5 h-5 text-slate-300 transition-transform ${isExpanded ? 'rotate-180 text-indigo-600' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
                        </svg>
                      </div>
                    </div>

                    {/* Detalhamento Individual (Cards Menores) */}
                    {isExpanded && (
                      <div className="px-5 pb-5 pt-2 border-t border-slate-50 space-y-3 bg-slate-50/30 rounded-b-3xl animate-in fade-in slide-in-from-top-2 duration-300">
                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2 italic">Parcelas individuais:</p>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                          {group.installments.map(({ saleId, installment, saleDescription }) => {
                            const instRemaining = installment.amount - installment.paidAmount;
                            const instIsPaid = instRemaining <= 0;
                            const instIsOverdue = !instIsPaid && new Date(installment.dueDate) < new Date(new Date().setHours(0,0,0,0));

                            return (
                              <div 
                                key={installment.id} 
                                className={`bg-white rounded-2xl border p-3 transition-all flex flex-col justify-between ${
                                  instIsPaid ? 'border-emerald-100 opacity-75' : 
                                  instIsOverdue ? 'border-rose-200 bg-rose-50/10' : 'border-slate-200'
