                              >
                                <div className="mb-3">
                                  <div className="flex justify-between items-start mb-2">
                                    <span className={`text-[8px] font-black px-1.5 py-0.5 rounded-full uppercase tracking-tighter ${
                                      instIsPaid ? 'bg-emerald-500 text-white' : 
                                      instIsOverdue ? 'bg-rose-500 text-white' : 'bg-slate-200 text-slate-600'
                                    }`}>
                                      Venc: {new Date(installment.dueDate).toLocaleDateString('pt-BR')}
                                    </span>
                                    {instIsPaid && <span className="text-emerald-500 font-black text-[9px]">QUITADA</span>}
                                  </div>
                                  <p className="text-[10px] font-black text-slate-700 uppercase truncate mb-1">{saleDescription}</p>
                                  <div className="flex justify-between items-center text-[10px]">
                                    <span className="text-slate-400 font-bold uppercase">Aberto:</span>
                                    <span className={`font-black ${instIsPaid ? 'text-emerald-600' : 'text-rose-600'}`}>{formatCurrency(instRemaining)}</span>
                                  </div>
                                </div>

                                {!instIsPaid && (
                                  <div className="flex gap-1 pt-2 border-t border-slate-50">
                                    <div className="flex-1 flex items-center bg-white border border-slate-200 rounded-lg overflow-hidden h-7">
                                      <span className="pl-2 text-[8px] font-black text-slate-400">R$</span>
                                      <input 
                                        type="text" 
                                        inputMode="decimal"
                                        placeholder="Valor"
                                        value={abatimentoValues[installment.id] || ''}
                                        onChange={e => setAbatimentoValues(prev => ({ ...prev, [installment.id]: e.target.value }))}
                                        className="w-full h-full px-1 text-[9px] font-black text-indigo-600 outline-none"
                                      />
                                      <button 
                                        onClick={() => handlePaymentAction(saleId, installment.id, abatimentoValues[installment.id] || '0')}
                                        className="bg-indigo-600 text-white px-2 h-full text-[8px] font-black uppercase hover:bg-indigo-700 transition"
                                      >
                                        Abater
                                      </button>
