import React, { useState } from 'react';
import { Sale, Customer, PaymentStatus, Installment } from '../types.ts';

interface AgendaProps {
  sales: Sale[];
  customers: Customer[];
  onUpdateSale: (sale: Sale) => void;
}

interface InstallmentItem {
  saleId: string;
  installment: Installment;
  saleDescription: string;
}

interface CustomerGroup {
  customerId: string;
  customerName: string;
  totalAmount: number;
  totalRemaining: number;
  installments: InstallmentItem[];
  isOverdue: boolean;
}

const Agenda: React.FC<AgendaProps> = ({ sales, customers, onUpdateSale }) => {
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({});
  const [abatimentoValues, setAbatimentoValues] = useState<Record<string, string>>({});

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const toggleGroup = (groupId: string) => {
    setExpandedGroups(prev => ({ ...prev, [groupId]: !prev[groupId] }));
  };

  const getGroupedData = () => {
    const months: Record<string, Record<string, CustomerGroup>> = {};

    sales.forEach(sale => {
      sale.installments.forEach(inst => {
        const date = new Date(inst.dueDate);
        const monthYear = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
        const customerId = sale.customerId;

        if (!months[monthYear]) months[monthYear] = {};

        if (!months[monthYear][customerId]) {
          const customer = customerId === 'BALCAO' 
            ? { name: '🛒 Venda Balcão' } 
            : customers.find(c => c.id === customerId);

          months[monthYear][customerId] = {
            customerId,
            customerName: customer?.name || 'Cliente Excluído',
            totalAmount: 0,
            totalRemaining: 0,
            installments: [],
            isOverdue: false
          };
        }

        const group = months[monthYear][customerId];
        const remaining = inst.amount - inst.paidAmount;
        const isInstOverdue = remaining > 0 && new Date(inst.dueDate) < new Date(new Date().setHours(0,0,0,0));

        group.totalAmount += inst.amount;
        group.totalRemaining += remaining;
        if (isInstOverdue) group.isOverdue = true;

        group.installments.push({
          saleId: sale.id,
          installment: inst,
          saleDescription: sale.description
        });
      });
    });

    // Ordenar parcelas dentro de cada grupo por data
    Object.values(months).forEach(customersInMonth => {
      Object.values(customersInMonth).forEach(group => {
        group.installments.sort((a, b) => 
          new Date(a.installment.dueDate).getTime() - new Date(b.installment.dueDate).getTime()
        );
      });
    });

    return months;
  };

  const handlePaymentAction = (saleId: string, instId: string, amountStr: string) => {
    const amount = parseFloat(amountStr.replace(',', '.'));
    if (isNaN(amount) || amount <= 0) return;

    const sale = sales.find(s => s.id === saleId);
    if (!sale) return;

    const todayStr = new Date().toISOString().split('T')[0];
    const updatedInstallments = sale.installments.map(inst => {
      if (inst.id === instId) {
        const newPaidAmount = Math.min(inst.amount, inst.paidAmount + amount);
        return {
          ...inst,
          paidAmount: newPaidAmount,
          paymentDate: newPaidAmount >= inst.amount ? todayStr : inst.paymentDate,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });

    const allPaid = updatedInstallments.every(i => i.paidAmount >= i.amount);
    onUpdateSale({
      ...sale,
      installments: updatedInstallments,
      status: allPaid ? PaymentStatus.PAID : PaymentStatus.PARTIAL
    });

    setAbatimentoValues(prev => ({ ...prev, [instId]: '' }));
  };

  const handleFullPayment = (saleId: string, instId: string) => {
    const sale = sales.find(s => s.id === saleId);
    const inst = sale?.installments.find(i => i.id === instId);
    if (sale && inst) {
      handlePaymentAction(saleId, instId, (inst.amount - inst.paidAmount).toString());
    }
  };

  const groupedData = getGroupedData();
  const sortedMonthKeys = Object.keys(groupedData).sort((a, b) => {
    const parseMonth = (str: string) => {
      const parts = str.split(' de ');
      const months = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
      return new Date(parseInt(parts[1]), months.indexOf(parts[0].toLowerCase())).getTime();
    };
    return parseMonth(a) - parseMonth(b);
  });

  return (
    <div className="space-y-6 pb-12">
      <div className="flex flex-col gap-1 px-1">
        <h2 className="text-2xl font-black text-indigo-950 uppercase italic tracking-tight">Agenda Mensal</h2>
        <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em]">Recebimentos agrupados por cliente</p>
      </div>

      {sortedMonthKeys.length === 0 && (
        <div className="bg-white/40 backdrop-blur-sm p-16 text-center rounded-[2.5rem] border-2 border-dashed border-slate-200 text-slate-400 font-black uppercase text-[10px] tracking-widest">
          Nenhum débito agendado.
        </div>
      )}

      {sortedMonthKeys.map(month => {
        const customersInMonth = Object.values(groupedData[month]).sort((a, b) => b.totalRemaining - a.totalRemaining);

        return (
          <div key={month} className="space-y-3">
            <div className="flex items-center gap-3 px-2">
              <div className="h-px flex-1 bg-slate-200"></div>
              <h3 className="text-[11px] font-black text-indigo-900 capitalize italic tracking-widest bg-slate-50 px-3 py-1 rounded-full border border-slate-200 shadow-sm">{month}</h3>
              <div className="h-px flex-1 bg-slate-200"></div>
            </div>

            <div className="grid grid-cols-1 gap-3">
              {customersInMonth.map(group => {
                const groupId = `${month}-${group.customerId}`;
                const isExpanded = !!expandedGroups[groupId];
                const isPaid = group.totalRemaining <= 0;

                return (
                  <div key={groupId} className={`group bg-white rounded-[2rem] border-2 transition-all duration-300 ${isExpanded ? 'border-indigo-500 shadow-2xl ring-4 ring-indigo-50' : 'border-slate-100 hover:border-indigo-200 shadow-sm'}`}>
                    {/* Cabeçalho Compacto do Cliente */}
                    <div 
                      onClick={() => toggleGroup(groupId)}
                      className="p-4 cursor-pointer flex justify-between items-center"
                    >
                      <div className="flex items-center gap-3">
                        <div className={`w-10 h-10 rounded-2xl flex items-center justify-center font-black text-sm shadow-inner transition-colors border ${
                          isPaid ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 
                          group.isOverdue ? 'bg-rose-50 text-rose-600 border-rose-100 animate-pulse' : 
                          'bg-indigo-50 text-indigo-600 border-indigo-100'
                        }`}>
                          {group.customerName.charAt(0)}
                        </div>
                        <div>
                          <h4 className={`text-xs font-black uppercase tracking-tight ${group.customerName.includes('🛒') ? 'text-amber-600' : 'text-slate-900'}`}>
                            {group.customerName}
                          </h4>
                          <div className="flex items-center gap-2">
                            <span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">
                              {group.installments.length} {group.installments.length === 1 ? 'Título' : 'Títulos'}
                            </span>
                            {group.isOverdue && !isPaid && (
                                <span className="text-[7px] font-black text-rose-500 bg-rose-50 px-1 rounded uppercase tracking-tighter">Vencido!</span>
                            )}
                          </div>
                        </div>
                      </div>

                      <div className="flex items-center gap-4">
                        <div className="text-right">
                          <p className={`text-sm font-black tracking-tighter ${isPaid ? 'text-emerald-600' : 'text-rose-600'}`}>
                            {formatCurrency(group.totalRemaining)}
                          </p>
                        </div>
                        <div className={`p-1 rounded-full transition-colors ${isExpanded ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-50 text-slate-300'}`}>
                          <svg className={`w-4 h-4 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" />
                          </svg>
                        </div>
                      </div>
                    </div>

                    {/* Detalhamento em Mini-Cards */}
                    {isExpanded && (
                      <div className="px-4 pb-5 pt-1 space-y-2 animate-in fade-in slide-in-from-top-1 duration-300">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2">
                          {group.installments.map(({ saleId, installment, saleDescription }) => {
                            const instRemaining = installment.amount - installment.paidAmount;
                            const instIsPaid = instRemaining <= 0;
                            const instIsOverdue = !instIsPaid && new Date(installment.dueDate) < new Date(new Date().setHours(0,0,0,0));

                            return (
                              <div 
                                key={installment.id} 
                                className={`bg-slate-50/50 rounded-2xl border p-3 flex flex-col justify-between transition-all ${
                                  instIsPaid ? 'border-emerald-100 bg-emerald-50/20' : 
                                  instIsOverdue ? 'border-rose-200 bg-rose-50/30' : 'border-slate-100 hover:border-indigo-200'
                                }`}
                              >
                                <div className="mb-2">
                                  <div className="flex justify-between items-start mb-1.5">
                                    <span className={`text-[8px] font-black px-1.5 py-0.5 rounded-lg uppercase ${
                                      instIsPaid ? 'bg-emerald-500 text-white' : 
                                      instIsOverdue ? 'bg-rose-500 text-white' : 'bg-indigo-900 text-white'
                                    }`}>
                                      {new Date(installment.dueDate).toLocaleDateString('pt-BR', {day: '2-digit', month: '2-digit'})}
                                    </span>
                                    {instIsPaid && <span className="text-emerald-500 font-black text-[8px] tracking-widest">OK</span>}
                                  </div>
                                  <p className="text-[10px] font-black text-slate-700 uppercase truncate leading-tight">{saleDescription}</p>
                                  <div className="flex justify-between items-center text-[9px] mt-1">
                                    <span className="text-slate-400 font-bold uppercase">Restante:</span>
                                    <span className={`font-black ${instIsPaid ? 'text-emerald-600' : 'text-rose-600'}`}>{formatCurrency(instRemaining)}</span>
                                  </div>
                                </div>

                                {!instIsPaid && (
                                  <div className="flex gap-1 pt-2 border-t border-slate-100">
                                    <div className="flex-1 flex items-center bg-white border border-slate-200 rounded-xl overflow-hidden h-7 shadow-sm">
                                      <span className="pl-2 text-[8px] font-black text-slate-300">R$</span>
                                      <input 
                                        type="text" 
                                        inputMode="decimal"
                                        placeholder="Valor"
                                        value={abatimentoValues[installment.id] || ''}
                                        onChange={e => setAbatimentoValues(prev => ({ ...prev, [installment.id]: e.target.value }))}
                                        className="w-full h-full px-1 text-[9px] font-black text-indigo-600 outline-none"
                                      />
                                      <button 
                                        onClick={() => handlePaymentAction(saleId, installment.id, abatimentoValues[installment.id] || '0')}
                                        className="bg-indigo-600 text-white px-2 h-full text-[8px] font-black uppercase hover:bg-indigo-700 transition active:scale-95"
                                      >
                                        <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
                                      </button>
                                    </div>
                                    <button 
                                      onClick={() => handleFullPayment(saleId, installment.id)}
                                      className="bg-emerald-500 text-white px-3 h-7 rounded-xl text-[8px] font-black uppercase shadow-sm hover:bg-emerald-600 transition active:scale-95"
                                    >
                                      Quitar
                                    </button>
                                  </div>
                                )}
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
};

