  customerId: string;
  customerName: string;
  totalAmount: number;
  totalRemaining: number;
  installments: InstallmentItem[];
  isOverdue: boolean;
}

const Agenda: React.FC<AgendaProps> = ({ sales, customers, onUpdateSale }) => {
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({});
  const [abatimentoValues, setAbatimentoValues] = useState<Record<string, string>>({});

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  const toggleGroup = (groupId: string) => {
    setExpandedGroups(prev => ({ ...prev, [groupId]: !prev[groupId] }));
  };

  const getGroupedData = () => {
    const months: Record<string, Record<string, CustomerGroup>> = {};
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    sales.forEach(sale => {
      sale.installments.forEach(inst => {
        const date = new Date(inst.dueDate);
        const monthYear = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
        const customerId = sale.customerId;

        if (!months[monthYear]) months[monthYear] = {};

        if (!months[monthYear][customerId]) {
          const customer = customerId === 'BALCAO' 
            ? { name: '🛒 Venda Balcão' } 
            : customers.find(c => c.id === customerId);

          months[monthYear][customerId] = {
            customerId,
            customerName: customer?.name || 'Cliente Excluído',
            totalAmount: 0,
            totalRemaining: 0,
            installments: [],
            isOverdue: false
          };
        }

        const group = months[monthYear][customerId];
        const remaining = inst.amount - inst.paidAmount;
        const isInstOverdue = remaining > 0 && new Date(inst.dueDate) < today;

        group.totalAmount += inst.amount;
        group.totalRemaining += remaining;
        if (isInstOverdue) group.isOverdue = true;

        group.installments.push({
          saleId: sale.id,
          installment: inst,
          saleDescription: sale.description
        });
      });
    });

    Object.values(months).forEach(customersInMonth => {
      Object.values(customersInMonth).forEach(group => {
        group.installments.sort((a, b) => 
          new Date(a.installment.dueDate).getTime() - new Date(b.installment.dueDate).getTime()
        );
      });
    });

    return months;
  };

  const handlePaymentAction = (saleId: string, instId: string, amountStr: string) => {
    const amount = parseFloat(amountStr.replace(',', '.'));
    if (isNaN(amount) || amount <= 0) return;

    const sale = sales.find(s => s.id === saleId);
    if (!sale) return;

    const todayStr = new Date().toISOString().split('T')[0];
    const updatedInstallments = sale.installments.map(inst => {
      if (inst.id === instId) {
        const newPaidAmount = Math.min(inst.amount, inst.paidAmount + amount);
        return {
          ...inst,
          paidAmount: newPaidAmount,
          paymentDate: newPaidAmount >= inst.amount ? todayStr : inst.paymentDate,
          status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
        };
      }
      return inst;
    });

    const allPaid = updatedInstallments.every(i => i.paidAmount >= i.amount);
    onUpdateSale({
      ...sale,
      installments: updatedInstallments,
      status: allPaid ? PaymentStatus.PAID : PaymentStatus.PARTIAL
    });

    setAbatimentoValues(prev => ({ ...prev, [instId]: '' }));
  };

  const handleFullPayment = (saleId: string, instId: string) => {
    const sale = sales.find(s => s.id === saleId);
    const inst = sale?.installments.find(i => i.id === instId);
    if (sale && inst) {
      handlePaymentAction(saleId, instId, (inst.amount - inst.paidAmount).toString());
    }
  };

  const groupedData = getGroupedData();
  const sortedMonthKeys = Object.keys(groupedData).sort((a, b) => {
    const parseMonth = (str: string) => {
      const parts = str.split(' de ');
      const months = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
      return new Date(parseInt(parts[1]), months.indexOf(parts[0].toLowerCase())).getTime();
    };
    return parseMonth(a) - parseMonth(b);
  });

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col gap-1 px-1">
        <h2 className="text-xl font-black text-slate-800 uppercase italic tracking-tighter">Agenda de Recebimentos</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Controle de débitos por vencimento</p>
      </div>

      {sortedMonthKeys.map(month => {
        const customersInMonth = Object.values(groupedData[month]);

        return (
          <div key={month} className="space-y-2">
            <div className="flex items-center gap-2 px-1">
              <span className="text-[9px] font-black text-indigo-400 uppercase tracking-widest bg-indigo-50 px-3 py-0.5 rounded-full border border-indigo-100">{month}</span>
              <div className="h-px flex-1 bg-slate-100"></div>
            </div>

            <div className="space-y-1.5">
              {customersInMonth.map(group => {
                const groupId = `${month}-${group.customerId}`;
                const isExpanded = !!expandedGroups[groupId];
                const isPaid = group.totalRemaining <= 0;

                return (
                  <div key={groupId} className={`transition-all duration-300 overflow-hidden ${isExpanded ? 'bg-white rounded-3xl shadow-xl ring-1 ring-slate-100 mb-4' : 'bg-white rounded-2xl shadow-sm border border-slate-100 hover:border-slate-200'}`}>
                    {/* Header do Cliente (Super Slim) */}
                    <div 
                      onClick={() => toggleGroup(groupId)}
                      className="p-3 cursor-pointer flex justify-between items-center"
                    >
                      <div className="flex items-center gap-3">
                        <div className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-[10px] shadow-sm ${
                          isPaid ? 'bg-emerald-500 text-white' : 
                          group.isOverdue ? 'bg-rose-500 text-white' : 
                          'bg-amber-400 text-white'
                        }`}>
                          {group.customerName.charAt(0)}
                        </div>
                        <div>
                          <h4 className={`text-[10px] font-black uppercase tracking-tight ${group.customerName.includes('🛒') ? 'text-amber-600' : 'text-slate-800'}`}>
                            {group.customerName}
                          </h4>
                          <p className="text-[8px] font-bold text-slate-400 uppercase leading-none">{group.installments.length} títulos</p>
                        </div>
                      </div>

                      <div className="flex items-center gap-4">
                        <p className={`text-[11px] font-black tracking-tighter ${isPaid ? 'text-emerald-600' : 'text-slate-900'}`}>
                          {formatCurrency(group.totalRemaining)}
                        </p>
                        <svg className={`w-3 h-3 text-slate-300 transition-transform ${isExpanded ? 'rotate-180 text-indigo-500' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" />
                        </svg>
                      </div>
                    </div>

                    {/* Detalhes (Mini-Cards Ultra-Menores) */}
                    {isExpanded && (
                      <div className="px-3 pb-3 pt-1 space-y-1 bg-slate-50/50">
                        {group.installments.map(({ saleId, installment, saleDescription }) => {
                          const instRemaining = installment.amount - installment.paidAmount;
                          const instIsPaid = instRemaining <= 0;
                          const dueDate = new Date(installment.dueDate);
                          const today = new Date();
                          today.setHours(0,0,0,0);
                          const instIsOverdue = !instIsPaid && dueDate < today;

                          // Status Color Logic
                          const statusColor = instIsPaid ? 'bg-emerald-500' : (instIsOverdue ? 'bg-rose-500' : 'bg-amber-400');

                          return (
                            <div key={installment.id} className="bg-white rounded-xl border border-slate-100 flex items-center gap-3 p-1.5 shadow-sm">
                              {/* Badge de Data Prioritária */}
                              <div className={`w-10 h-10 shrink-0 flex flex-col items-center justify-center rounded-lg text-white ${statusColor}`}>
                                <span className="text-[12px] font-black leading-none">{dueDate.getDate()}</span>
                                <span className="text-[7px] font-black uppercase">{dueDate.toLocaleString('pt-BR', { month: 'short' }).replace('.', '')}</span>
                              </div>

                              <div className="flex-1 min-w-0 flex flex-col md:flex-row md:items-center justify-between gap-2">
                                <div className="min-w-0">
                                  <p className="text-[9px] font-black text-slate-800 uppercase truncate leading-none">{saleDescription}</p>
                                  <div className="flex items-center gap-2 mt-1">
                                    <span className={`text-[9px] font-black ${instIsPaid ? 'text-emerald-600' : 'text-slate-900'}`}>
                                      {formatCurrency(instRemaining)}
                                    </span>
                                    {instIsPaid && <span className="text-[7px] font-black text-emerald-500 bg-emerald-50 px-1 rounded uppercase tracking-widest">Pago</span>}
                                  </div>
                                </div>

                                {!instIsPaid && (
                                  <div className="flex items-center gap-1 shrink-0">
                                    <div className="flex items-center bg-slate-50 border border-slate-200 rounded-lg overflow-hidden h-6 w-24">
                                      <input 
                                        type="text" 
                                        inputMode="decimal"
                                        placeholder="Valor"
                                        value={abatimentoValues[installment.id] || ''}
                                        onChange={e => setAbatimentoValues(prev => ({ ...prev, [installment.id]: e.target.value }))}
                                        className="w-full h-full px-1 text-[8px] font-black text-indigo-600 bg-transparent outline-none placeholder:text-slate-300"
                                      />
                                      <button 
                                        onClick={() => handlePaymentAction(saleId, installment.id, abatimentoValues[installment.id] || '0')}
                                        className="bg-indigo-600 text-white px-1.5 h-full hover:bg-indigo-700"
                                      >
                                        <svg className="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M12 4v16m8-8H4" /></svg>
                                      </button>
                                    </div>
                                    <button 
                                      onClick={() => handleFullPayment(saleId, installment.id)}
                                      className="bg-emerald-500 text-white h-6 px-2 rounded-lg text-[8px] font-black uppercase hover:bg-emerald-600 transition"
                                    >
                                      Quitar
                                    </button>
                                  </div>
                                )}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
};

