                    {/* Grade de Cards Ultra-Compactos (Até 5 por linha) */}
                    {isExpanded && (
                      <div className="p-3 grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-2 animate-in fade-in slide-in-from-top-2 duration-200">
                        {group.installments.map(({ saleId, installment, saleDescription }) => {
                          const instRemaining = installment.amount - installment.paidAmount;
                          const instIsPaid = instRemaining <= 0;
                          const dueDate = new Date(installment.dueDate);
                          const today = new Date();
                          today.setHours(0,0,0,0);
                          const instIsOverdue = !instIsPaid && dueDate < today;

                          // Semáforo de Status
                          const statusBg = instIsPaid ? 'bg-emerald-500' : (instIsOverdue ? 'bg-rose-500' : 'bg-amber-400');
                          const cardBorder = instIsPaid ? 'border-emerald-100' : (instIsOverdue ? 'border-rose-100' : 'border-amber-100');

                          return (
                            <div key={installment.id} className={`flex flex-col bg-slate-50 border rounded-2xl p-2 transition-all shadow-sm ${cardBorder} ${instIsPaid ? 'opacity-50' : 'hover:scale-[1.02] hover:bg-white'}`}>
                              {/* Data e Nome Imediatos */}
                              <div className="flex justify-between items-start mb-1.5">
                                <span className={`text-[9px] font-black px-1.5 py-0.5 rounded-lg text-white shadow-sm ${statusBg}`}>
                                  {dueDate.getDate()}/{dueDate.getMonth() + 1}
                                </span>
                                {instIsPaid && <svg className="w-3.5 h-3.5 text-emerald-500" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>}
                              </div>

                              <div className="min-w-0 flex-1 flex flex-col justify-center mb-2">
                                <h5 className="text-[8px] font-black text-slate-500 uppercase truncate mb-0.5" title={saleDescription}>{saleDescription}</h5>
                                <p className={`text-[11px] font-black tracking-tighter leading-none ${instIsPaid ? 'text-emerald-600' : 'text-slate-900'}`}>
                                  {formatCurrency(instRemaining)}
                                </p>
                              </div>

                              {/* Ações Rápidas Ultra-Slim */}
                              {!instIsPaid && (
                                <div className="space-y-1 mt-auto">
                                  <div className="flex items-center bg-white border border-slate-200 rounded-lg overflow-hidden h-6">
                                    <input 
                                      type="text" 
                                      inputMode="decimal"
                                      placeholder="R$"
                                      value={abatimentoValues[installment.id] || ''}
                                      onChange={e => setAbatimentoValues(prev => ({ ...prev, [installment.id]: e.target.value }))}
                                      className="w-full h-full px-1.5 text-[9px] font-black text-indigo-600 bg-transparent outline-none placeholder:text-slate-300"
                                    />
                                    <button 
                                      onClick={() => handlePaymentAction(saleId, installment.id, abatimentoValues[installment.id] || '0')}
                                      className="bg-indigo-600 text-white px-1.5 h-full hover:bg-indigo-700 active:scale-95 transition-all"
                                    >
                                      <svg className="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M12 4v16m8-8H4" /></svg>
                                    </button>
