                                  <button 
                                    onClick={() => handleFullPayment(saleId, installment.id)}
                                    className="w-full bg-emerald-500 text-white h-5 rounded-lg text-[8px] font-black uppercase hover:bg-emerald-600 transition active:scale-95 shadow-sm"
                                  >
                                    Quitar
