import React, { useState } from 'react';
import { Sale, Customer, PaymentStatus, Installment } from '../types.ts';

interface AgendaProps {
  sales: Sale[];
  customers: Customer[];
  onUpdateSale: (sale: Sale) => void;
}

interface ConsolidateInstallment {
  dueDate: string;
  totalAmount: number;
  paidAmount: number;
  remainingAmount: number;
  isOverdue: boolean;
  salesIds: string[]; // IDs das vendas originais para processar pagamentos
  descriptions: string[];
}

interface CustomerGroup {
  customerId: string;
  customerName: string;
  totalRemaining: number;
  consolidated: ConsolidateInstallment[];
  isOverdue: boolean;
}

const Agenda: React.FC<AgendaProps> = ({ sales, customers, onUpdateSale }) => {
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({});
  const [abatimentoValues, setAbatimentoValues] = useState<Record<string, string>>({});

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 });

  const toggleGroup = (groupId: string) => {
    setExpandedGroups(prev => ({ ...prev, [groupId]: !prev[groupId] }));
  };

  const getGroupedData = () => {
    const months: Record<string, Record<string, CustomerGroup>> = {};
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    sales.forEach(sale => {
      sale.installments.forEach(inst => {
        const date = new Date(inst.dueDate);
        const monthYear = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
        const customerId = sale.customerId;

        if (!months[monthYear]) months[monthYear] = {};

        if (!months[monthYear][customerId]) {
          const customer = customerId === 'BALCAO' 
            ? { name: 'Venda Balcão' } 
            : customers.find(c => c.id === customerId);

          months[monthYear][customerId] = {
            customerId,
            customerName: customer?.name || 'Cliente Excluído',
            totalRemaining: 0,
            consolidated: [],
            isOverdue: false
          };
        }

        const group = months[monthYear][customerId];
        const remaining = inst.amount - inst.paidAmount;

        // Lógica de Consolidação por Data Única para o cliente
        let existingConsolidated = group.consolidated.find(c => c.dueDate === inst.dueDate);

        if (!existingConsolidated) {
          existingConsolidated = {
            dueDate: inst.dueDate,
            totalAmount: 0,
            paidAmount: 0,
            remainingAmount: 0,
            isOverdue: false,
            salesIds: [],
            descriptions: []
          };
          group.consolidated.push(existingConsolidated);
        }

        existingConsolidated.totalAmount += inst.amount;
        existingConsolidated.paidAmount += inst.paidAmount;
        existingConsolidated.remainingAmount += remaining;

        if (remaining > 0 && new Date(inst.dueDate) < today) {
          existingConsolidated.isOverdue = true;
          group.isOverdue = true;
        }

        if (!existingConsolidated.salesIds.includes(sale.id)) {
          existingConsolidated.salesIds.push(sale.id);
        }

        const shortDesc = sale.description.split(',')[0].substring(0, 20);
        if (!existingConsolidated.descriptions.includes(shortDesc)) {
          existingConsolidated.descriptions.push(shortDesc);
        }

        group.totalRemaining += remaining;
      });
    });

    Object.values(months).forEach(customersInMonth => {
      Object.values(customersInMonth).forEach(group => {
        group.consolidated.sort((a, b) => 
          new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime()
        );
      });
    });

    return months;
  };

  const handlePaymentAction = (consolidated: ConsolidateInstallment, amountStr: string, customerId: string) => {
    let amountToPay = parseFloat(amountStr.replace(',', '.'));
    if (isNaN(amountToPay) || amountToPay <= 0) return;

    const todayStr = new Date().toISOString().split('T')[0];

    // Processa o pagamento distribuindo nas parcelas originais das vendas desse cliente naquela data
    consolidated.salesIds.forEach(saleId => {
      const sale = sales.find(s => s.id === saleId);
      if (!sale) return;

      const updatedInstallments = sale.installments.map(inst => {
        if (inst.dueDate === consolidated.dueDate && amountToPay > 0) {
          const debt = inst.amount - inst.paidAmount;
          const payment = Math.min(debt, amountToPay);
          const newPaidAmount = inst.paidAmount + payment;
          amountToPay -= payment;

          return {
            ...inst,
            paidAmount: newPaidAmount,
            paymentDate: newPaidAmount >= inst.amount ? todayStr : inst.paymentDate,
            status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
          };
        }
        return inst;
      });

      const allPaid = updatedInstallments.every(i => i.paidAmount >= i.amount);
      onUpdateSale({
        ...sale,
        installments: updatedInstallments,
        status: allPaid ? PaymentStatus.PAID : PaymentStatus.PARTIAL
      });
    });

    setAbatimentoValues(prev => ({ ...prev, [`${customerId}-${consolidated.dueDate}`]: '' }));
  };

  const groupedData = getGroupedData();
  const sortedMonthKeys = Object.keys(groupedData).sort((a, b) => {
    const parseMonth = (str: string) => {
      const parts = str.split(' de ');
      const months = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
      return new Date(parseInt(parts[1]), months.indexOf(parts[0].toLowerCase())).getTime();
    };
    return parseMonth(a) - parseMonth(b);
  });

  return (
    <div className="space-y-6 pb-24">
      <div className="flex flex-col gap-1 px-1">
        <h2 className="text-xl font-black text-slate-800 uppercase italic tracking-tighter">Painel da Agenda</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Grade consolidada por vencimento e cliente</p>
      </div>

      {sortedMonthKeys.map(month => {
        const customersInMonth = Object.values(groupedData[month]);

        return (
          <div key={month} className="space-y-3">
            <div className="flex items-center gap-3 px-1">
              <span className="text-[10px] font-black text-indigo-500 bg-indigo-50/50 px-3 py-1 rounded-lg border border-indigo-100 uppercase tracking-tighter">{month}</span>
              <div className="h-px flex-1 bg-slate-100"></div>
            </div>

            <div className="space-y-2">
              {customersInMonth.map(group => {
                const groupId = `${month}-${group.customerId}`;
                const isExpanded = !!expandedGroups[groupId];
                const isPaid = group.totalRemaining <= 0;

                return (
                  <div key={groupId} className={`transition-all duration-300 overflow-hidden ${isExpanded ? 'bg-white rounded-[2rem] shadow-xl ring-1 ring-slate-100 mb-4' : 'bg-white rounded-3xl border border-slate-100 hover:border-slate-200 shadow-sm'}`}>
                    {/* Header do Cliente Consolidado */}
                    <div 
                      onClick={() => toggleGroup(groupId)}
                      className={`p-3 cursor-pointer flex justify-between items-center ${isExpanded ? 'bg-slate-50/50 border-b border-slate-100' : ''}`}
                    >
                      <div className="flex items-center gap-2">
                        <div className={`w-8 h-8 rounded-xl flex items-center justify-center font-black text-[10px] shadow-sm ${
                          isPaid ? 'bg-emerald-500 text-white' : 
                          group.isOverdue ? 'bg-rose-500 text-white' : 
                          'bg-amber-400 text-white'
                        }`}>
                          {group.customerName.charAt(0)}
                        </div>
                        <div className="min-w-0">
                          <h4 className={`text-[11px] font-black uppercase text-slate-800 truncate tracking-tight ${group.customerName.includes('Venda Balcão') ? 'text-amber-600' : ''}`}>
                            {group.customerName}
                          </h4>
                          <p className="text-[9px] font-bold text-slate-400 uppercase leading-none">Total Consolidado</p>
                        </div>
                      </div>

                      <div className="flex items-center gap-3">
                        <p className={`text-[12px] font-black tracking-tighter ${isPaid ? 'text-emerald-600' : 'text-slate-900'}`}>
                          {formatCurrency(group.totalRemaining)}
                        </p>
                        <svg className={`w-3 h-3 text-slate-300 transition-transform ${isExpanded ? 'rotate-180 text-indigo-500' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" />
                        </svg>
                      </div>
                    </div>

                    {/* Grade de Cards de Vencimento (Máx 5 por linha) */}
                    {isExpanded && (
                      <div className="p-3 grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 animate-in fade-in slide-in-from-top-2 duration-200">
                        {group.consolidated.map((c) => {
                          const instIsPaid = c.remainingAmount <= 0;
                          const dueDate = new Date(c.dueDate);
                          const inputKey = `${group.customerId}-${c.dueDate}`;

                          // Estilos de Status
                          const statusBg = instIsPaid ? 'bg-emerald-500' : (c.isOverdue ? 'bg-rose-500' : 'bg-amber-400');
                          const cardBorder = instIsPaid ? 'border-emerald-100' : (c.isOverdue ? 'border-rose-100' : 'border-amber-100');

                          return (
                            <div key={c.dueDate} className={`flex flex-col bg-slate-50 border rounded-2xl p-2.5 transition-all shadow-sm ${cardBorder} ${instIsPaid ? 'opacity-50' : 'hover:scale-[1.03] hover:bg-white hover:shadow-md'}`}>
                              {/* Data e Status Explícitos */}
                              <div className="flex justify-between items-center mb-2">
                                <span className={`text-[10px] font-black px-2 py-0.5 rounded-lg text-white shadow-sm ${statusBg}`}>
                                  {dueDate.getDate()}/{dueDate.getMonth() + 1}
                                </span>
                                {instIsPaid && <svg className="w-4 h-4 text-emerald-500" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>}
                              </div>

                              {/* Conteúdo do Card */}
                              <div className="min-w-0 flex-1 flex flex-col mb-3">
                                <h5 className="text-[8px] font-black text-slate-500 uppercase truncate mb-1 leading-tight" title={c.descriptions.join(' + ')}>
                                  {group.customerName.split(' ')[0]}
                                </h5>
                                <p className={`text-[12px] font-black tracking-tighter leading-none ${instIsPaid ? 'text-emerald-600' : 'text-slate-900'}`}>
                                  {formatCurrency(c.remainingAmount)}
                                </p>
                              </div>

                              {/* Ações de Abatimento */}
                              {!instIsPaid && (
                                <div className="space-y-1.5 mt-auto">
                                  <div className="flex items-center bg-white border border-slate-200 rounded-lg overflow-hidden h-7 shadow-sm">
                                    <input 
                                      type="text" 
                                      inputMode="decimal"
                                      placeholder="R$"
                                      value={abatimentoValues[inputKey] || ''}
                                      onChange={e => setAbatimentoValues(prev => ({ ...prev, [inputKey]: e.target.value }))}
                                      className="w-full h-full px-2 text-[10px] font-black text-indigo-600 bg-transparent outline-none placeholder:text-slate-300"
                                    />
                                    <button 
                                      onClick={() => handlePaymentAction(c, abatimentoValues[inputKey] || '0', group.customerId)}
                                      className="bg-indigo-600 text-white px-2 h-full hover:bg-indigo-700 active:scale-95 transition-all"
                                    >
                                      <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M12 4v16m8-8H4" /></svg>
                                    </button>
                                  </div>
                                  <button 
                                    onClick={() => handlePaymentAction(c, c.remainingAmount.toString(), group.customerId)}
                                    className="w-full bg-emerald-500 text-white h-6 rounded-lg text-[9px] font-black uppercase hover:bg-emerald-600 transition active:scale-95 shadow-sm"
                                  >
                                    Quitar Dia
                                  </button>
                                </div>
                              )}
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
};

