import React, { useState } from 'react';
import { Sale, Customer, PaymentStatus, Installment } from '../types.ts';

interface AgendaProps {
  sales: Sale[];
  customers: Customer[];
  onUpdateSale: (sale: Sale) => void;
}

interface ConsolidatedCard {
  customerId: string;
  customerName: string;
  dueDate: string;
  totalAmount: number;
  paidAmount: number;
  remainingAmount: number;
  isOverdue: boolean;
  salesIds: string[];
  descriptions: string[];
}

const Agenda: React.FC<AgendaProps> = ({ sales, customers, onUpdateSale }) => {
  const [abatimentoValues, setAbatimentoValues] = useState<Record<string, string>>({});

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 });

  const getGroupedData = () => {
    const months: Record<string, ConsolidatedCard[]> = {};
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    sales.forEach(sale => {
      sale.installments.forEach(inst => {
        const date = new Date(inst.dueDate);
        const monthYear = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
        const customerId = sale.customerId;
        const remaining = inst.amount - inst.paidAmount;

        if (!months[monthYear]) months[monthYear] = [];

        // Chave única para consolidar: Cliente + Data de Vencimento
        let card = months[monthYear].find(c => c.customerId === customerId && c.dueDate === inst.dueDate);

        if (!card) {
          const customer = customerId === 'BALCAO' 
            ? { name: 'Venda Balcão' } 
            : customers.find(c => c.id === customerId);

          card = {
            customerId,
            customerName: (customer?.name || 'Cliente Excluído').toUpperCase(),
            dueDate: inst.dueDate,
            totalAmount: 0,
            paidAmount: 0,
            remainingAmount: 0,
            isOverdue: false,
            salesIds: [],
            descriptions: []
          };
          months[monthYear].push(card);
        }

        card.totalAmount += inst.amount;
        card.paidAmount += inst.paidAmount;
        card.remainingAmount += remaining;

        if (remaining > 0 && new Date(inst.dueDate) < today) {
          card.isOverdue = true;
        }

        if (!card.salesIds.includes(sale.id)) {
          card.salesIds.push(sale.id);
        }

        const shortDesc = sale.description.split(':')[1]?.trim() || sale.description.split(',')[0].substring(0, 15);
        const descUpper = shortDesc.toUpperCase();
        if (!card.descriptions.includes(descUpper)) {
          card.descriptions.push(descUpper);
        }
      });
    });

    // Ordena os meses cronologicamente e os cards por dia
    Object.keys(months).forEach(m => {
      months[m].sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
    });

    return months;
  };

  const handlePaymentAction = (card: ConsolidatedCard, amountStr: string) => {
    let amountToPay = parseFloat(amountStr.replace(',', '.'));
    if (isNaN(amountToPay) || amountToPay <= 0) return;

    const todayStr = new Date().toISOString().split('T')[0];

    card.salesIds.forEach(saleId => {
      const sale = sales.find(s => s.id === saleId);
      if (!sale) return;

      const updatedInstallments = sale.installments.map(inst => {
        if (inst.dueDate === card.dueDate && amountToPay > 0) {
          const debt = inst.amount - inst.paidAmount;
          const payment = Math.min(debt, amountToPay);
          const newPaidAmount = inst.paidAmount + payment;
          amountToPay -= payment;

          return {
            ...inst,
            paidAmount: newPaidAmount,
            paymentDate: newPaidAmount >= inst.amount ? todayStr : inst.paymentDate,
            status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
          };
        }
        return inst;
      });

      const allPaid = updatedInstallments.every(i => i.paidAmount >= i.amount);
      onUpdateSale({
        ...sale,
        installments: updatedInstallments,
        status: allPaid ? PaymentStatus.PAID : PaymentStatus.PARTIAL
      });
    });

    setAbatimentoValues(prev => ({ ...prev, [`${card.customerId}-${card.dueDate}`]: '' }));
  };

  const groupedData = getGroupedData();
  const sortedMonthKeys = Object.keys(groupedData).sort((a, b) => {
    const parseMonth = (str: string) => {
      const parts = str.split(' de ');
      const months = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
      return new Date(parseInt(parts[1]), months.indexOf(parts[0].toLowerCase())).getTime();
    };
    return parseMonth(a) - parseMonth(b);
  });

  return (
    <div className="space-y-8 pb-24">
      <div className="flex flex-col gap-1 px-1">
        <h2 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">Agenda Consolidada</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Acompanhamento direto de recebimentos</p>
      </div>

      {sortedMonthKeys.map(month => {
        const cards = groupedData[month];

        return (
          <div key={month} className="space-y-6">
            <div className="flex items-center gap-3 px-1">
              <span className="text-[11px] font-black text-indigo-600 bg-white px-4 py-1.5 rounded-full border-2 border-indigo-100 uppercase tracking-tighter shadow-sm">{month}</span>
              <div className="h-0.5 flex-1 bg-slate-200/50"></div>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-5">
              {cards.map((card) => {
                const isPaid = card.remainingAmount <= 0;
                const dueDate = new Date(card.dueDate);
                const inputKey = `${card.customerId}-${card.dueDate}`;

                const statusColor = isPaid ? 'emerald' : (card.isOverdue ? 'rose' : 'amber');
                const statusBg = isPaid ? 'bg-emerald-500' : (card.isOverdue ? 'bg-rose-500' : 'bg-amber-400');

                return (
                  <div 
                    key={`${card.customerId}-${card.dueDate}`} 
                    className={`flex flex-col bg-white border-2 rounded-[2rem] p-5 transition-all shadow-sm relative overflow-hidden h-full ${isPaid ? 'opacity-40 border-slate-100' : `border-${statusColor}-100 hover:shadow-xl hover:scale-[1.02]`}`}
                  >
                    {/* Badge de Data Redondo (Top-Left) */}
                    <div className="flex items-center gap-3 mb-4">
                      <div className={`flex items-center justify-center text-[10px] font-black w-10 h-10 rounded-full text-white shadow-md shrink-0 ${statusBg}`}>
                        {dueDate.getDate()}/{dueDate.getMonth() + 1}
                      </div>
                      <div className="min-w-0">
                        <h4 className="text-[11px] font-black text-slate-900 truncate tracking-tight leading-tight">
                          {card.customerName}
                        </h4>
                        <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Cliente</p>
                      </div>
                    </div>

                    {/* Descrição e Valor Centralizados */}
                    <div className="flex-1 mb-5 space-y-1">
                      <h5 className="text-[9px] font-black text-slate-400 uppercase leading-none tracking-tight">
                        {card.descriptions.length > 1 ? 'ACUMULADA: VÁRIAS' : `ACUMULADA: ${card.descriptions[0]}`}
                      </h5>
                      <p className={`text-xl font-black tracking-tighter leading-none ${isPaid ? 'text-emerald-600' : 'text-slate-900'}`}>
                        {formatCurrency(card.remainingAmount)}
                      </p>
                    </div>

                    {/* Controles de Pagamento Diretos */}
                    {!isPaid ? (
                      <div className="space-y-2 mt-auto">
                        <div className="flex items-center bg-white border border-slate-200 rounded-xl overflow-hidden h-10 shadow-sm focus-within:ring-2 focus-within:ring-indigo-500/20 transition-all">
                          <input 
                            type="text" 
                            inputMode="decimal"
                            placeholder="R$"
                            value={abatimentoValues[inputKey] || ''}
                            onChange={e => setAbatimentoValues(prev => ({ ...prev, [inputKey]: e.target.value }))}
                            className="w-full h-full px-3 text-[11px] font-black text-indigo-600 outline-none placeholder:text-slate-300"
                          />
                          <button 
                            onClick={() => handlePaymentAction(card, abatimentoValues[inputKey] || '0')}
                            className="bg-indigo-600 text-white px-4 h-full hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center"
                          >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M12 4v16m8-8H4" /></svg>
                          </button>
                        </div>
                        <button 
                          onClick={() => handlePaymentAction(card, card.remainingAmount.toString())}
                          className="w-full bg-emerald-500 text-white h-10 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 transition active:scale-95 shadow-lg shadow-emerald-50"
                        >
                          Quitar Dia
                        </button>
                      </div>
                    ) : (
                      <div className="flex items-center justify-center py-3 gap-2 text-emerald-500 font-black text-[10px] uppercase bg-emerald-50 rounded-2xl border border-emerald-100">
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                        <span>Recebido</span>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}

      {Object.keys(groupedData).length === 0 && (
        <div className="flex flex-col items-center justify-center py-24 text-slate-300 gap-4">
          <svg className="w-16 h-16 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          <p className="font-black uppercase text-xs tracking-[0.3em]">Nenhum recebimento agendado</p>
        </div>
      )}
    </div>
  );
};

export default Agenda;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { View, Customer, Sale, User, Expense, Product, TrashItem, PaymentStatus } from './types.ts';
import Dashboard from './components/Dashboard.tsx';
import CustomerList from './components/CustomerList.tsx';
import SalesManager from './components/SalesManager.tsx';
import Agenda from './components/Agenda.tsx';
import Settings from './components/Settings.tsx';
import Landing from './components/Landing.tsx';
import Tutorial from './components/Tutorial.tsx';
import ExpenseManager from './components/ExpenseManager.tsx';
import InventoryManager from './components/InventoryManager.tsx';
import TrashManager from './components/TrashManager.tsx';
import RefundManager from './components/RefundManager.tsx';
import { storageService } from './services/storageService.ts';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [trashSales, setTrashSales] = useState<TrashItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const isMounted = useRef(false);

  const FASHION_IMAGE_URL = 'https://images.unsplash.com/photo-1445205170230-053b83016050?q=80&w=2000';

  useEffect(() => {
    const initApp = async () => {
      try {
        const savedUser = await storageService.loadData<User>('gestao93_current_user');

        if (savedUser && savedUser.id) {
          setUser(savedUser);
          const userId = savedUser.id;

          const tutorialSeen = await storageService.loadData<string>(`gestao93_tutorial_seen_${userId}`);
          if (!tutorialSeen) setShowTutorial(true);

          const [loadedCustomers, loadedSales, loadedExpenses, loadedProducts, loadedTrash] = await Promise.all([
            storageService.loadData<Customer[]>(`gestao93_customers_${userId}`),
            storageService.loadData<Sale[]>(`gestao93_sales_${userId}`),
            storageService.loadData<Expense[]>(`gestao93_expenses_${userId}`),
            storageService.loadData<Product[]>(`gestao93_products_${userId}`),
            storageService.loadData<TrashItem[]>(`gestao93_trash_${userId}`)
          ]);

          setCustomers(loadedCustomers || []);
          setSales(loadedSales || []);
          setExpenses(loadedExpenses || []);
          setProducts(loadedProducts || []);

          const thirtyDaysInMs = 30 * 24 * 60 * 60 * 1000;
          const validTrash = (loadedTrash || []).filter((item: TrashItem) => (Date.now() - item.deletedAt) < thirtyDaysInMs);
          setTrashSales(validTrash);
        }
      } catch (e) {
        console.error("Erro ao inicializar banco de dados:", e);
      } finally {
        setLoading(false);
        isMounted.current = true;
      }
    };
    initApp();
  }, []);

  useEffect(() => {
    if (loading || !user || !isMounted.current) return;

    const autoSave = async () => {
      try {
        setSyncStatus('syncing');
        const userId = user.id;

        await Promise.all([
          storageService.saveData(`gestao93_customers_${userId}`, customers),
          storageService.saveData(`gestao93_sales_${userId}`, sales),
          storageService.saveData(`gestao93_expenses_${userId}`, expenses),
          storageService.saveData(`gestao93_products_${userId}`, products),
          storageService.saveData(`gestao93_trash_${userId}`, trashSales),
          storageService.saveData('gestao93_current_user', user)
        ]);

        setSyncStatus('synced');
      } catch (err) {
        console.error("Falha no Auto-Save:", err);
        setSyncStatus('error');
      }
    };

    const timer = setTimeout(autoSave, 800);
    return () => clearTimeout(timer);
  }, [customers, sales, expenses, products, trashSales, user, loading]);

  const handleLogout = async () => {
    await storageService.saveData('gestao93_current_user', null);
    setUser(null);
    setActiveView('dashboard');
  };

  const handleUpdateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  const handleAddProduct = (newProduct: Omit<Product, 'id'>) => {
    setProducts(prev => {
      const existingIndex = prev.findIndex(p => p.sku.toUpperCase() === newProduct.sku.toUpperCase());

      if (existingIndex !== -1) {
        // Lógica de Custo Médio Ponderado
        const existing = prev[existingIndex];
        const totalOldCost = existing.stock * existing.costPrice;
        const totalNewCost = newProduct.stock * newProduct.costPrice;
        const totalStock = existing.stock + newProduct.stock;

        const weightedAverageCost = totalStock > 0 ? (totalOldCost + totalNewCost) / totalStock : newProduct.costPrice;

        const updated = [...prev];
        updated[existingIndex] = {
          ...existing,
          stock: totalStock,
          costPrice: weightedAverageCost,
          price: newProduct.price, // Atualiza para o novo preço de venda
          name: newProduct.name // Atualiza o nome se mudou
        };
        return updated;
      }

      return [...prev, { ...newProduct, id: Math.random().toString(36).substr(2, 9) }];
    });
  };

  const handleAddSale = (s: Omit<Sale, 'id'>) => {
    const isSameMonth = (d1: string, d2: string) => {
      const date1 = new Date(d1);
      const date2 = new Date(d2);
      return date1.getMonth() === date2.getMonth() && date1.getFullYear() === date2.getFullYear();
    };

    if (s.type === 'credit' && s.customerId !== 'BALCAO') {
      const existingSaleIndex = sales.findIndex(prev => 
        prev.customerId === s.customerId && 
        prev.type === 'credit' && 
        prev.status !== PaymentStatus.PAID &&
        isSameMonth(prev.date, s.date)
      );

      if (existingSaleIndex !== -1) {
        const existingSale = sales[existingSaleIndex];
        const updatedItems = [...existingSale.items, ...s.items];
        const updatedBaseAmount = existingSale.baseAmount + s.baseAmount;
        const updatedTotalAmount = existingSale.totalAmount + s.totalAmount;
        const updatedTotalCost = existingSale.totalCost + s.totalCost;
        const updatedNetAmount = existingSale.netAmount + s.netAmount;

        const updatedInstallments = existingSale.installments.map((inst) => {
          const additionalAmount = s.totalAmount / existingSale.installments.length;
          const newAmount = inst.amount + additionalAmount;
          return {
            ...inst,
            amount: newAmount,
            status: inst.paidAmount >= newAmount ? PaymentStatus.PAID : (inst.paidAmount > 0 ? PaymentStatus.PARTIAL : PaymentStatus.PENDING)
          };
        });

        const mergedSale: Sale = {
          ...existingSale,
          items: updatedItems,
          baseAmount: updatedBaseAmount,
          totalAmount: updatedTotalAmount,
          totalCost: updatedTotalCost,
          netAmount: updatedNetAmount,
          description: `Consolidada: ${updatedItems.map(i => i.description.split('-')[1] || i.description).join(', ').substring(0, 80)}`,
          installments: updatedInstallments,
          status: PaymentStatus.PARTIAL
        };

        const newSales = [...sales];
        newSales[existingSaleIndex] = mergedSale;
        setSales(newSales);

        if (s.items && s.items.length > 0) {
          s.items.forEach(item => {
            if (item.productId) {
              setProducts(prev => prev.map(p => 
                p.id === item.productId ? { ...p, stock: Math.max(0, p.stock - item.quantity) } : p
              ));
            }
          });
        }
        return;
      }
    }

    const newId = Math.random().toString(36).substr(2, 9);
    setSales(prev => [...prev, { ...s, id: newId }]);

    if (s.items && s.items.length > 0) {
      s.items.forEach(item => {
        if (item.productId) {
          setProducts(prev => prev.map(p => 
            p.id === item.productId ? { ...p, stock: Math.max(0, p.stock - item.quantity) } : p
          ));
        }
      });
    }
  };

  const handleDeleteSale = useCallback((id: string, isRefund: boolean = false) => {
    const saleToDelete = sales.find(s => s.id === id);
    if (!saleToDelete) return;

    setTrashSales(prevTrash => [
      ...prevTrash, 
      { id: Math.random().toString(36).substr(2, 9), sale: saleToDelete, deletedAt: Date.now() }
    ]);

    if (saleToDelete.productId || (saleToDelete.items && saleToDelete.items.length > 0)) {
      setProducts(prevProducts => {
        let updated = [...prevProducts];

        if (saleToDelete.productId) {
          updated = updated.map(p => p.id === saleToDelete.productId ? { ...p, stock: p.stock + 1 } : p);
        }

        if (saleToDelete.items && saleToDelete.items.length > 0) {
          saleToDelete.items.forEach(item => {
            if (item.productId) {
              updated = updated.map(p => p.id === item.productId ? { ...p, stock: p.stock + item.quantity } : p);
            }
          });
        }
        return updated;
      });
    }

    if (isRefund) {
      const totalAlreadyPaid = saleToDelete.installments.reduce((acc, inst) => acc + inst.paidAmount, 0);
      if (totalAlreadyPaid > 0) {
        const customer = customers.find(c => c.id === saleToDelete.customerId);
        const customerName = customer ? customer.name : (saleToDelete.customerId === 'BALCAO' ? 'Cliente Balcão' : 'Desconhecido');

        setExpenses(prev => [...prev, {
          id: Math.random().toString(36).substr(2, 9),
          description: `ESTORNO (DEVOLUÇÃO): ${customerName}`,
          amount: totalAlreadyPaid,
          category: 'refund',
          date: new Date().toISOString().split('T')[0]
        }]);
      }
    }

    setSales(prev => prev.filter(s => s.id !== id));
  }, [sales, customers]);

  const handleRestoreSale = useCallback((trashId: string) => {
    const item = trashSales.find(i => i.id === trashId);
    if (!item) return;

    if (item.sale.productId || (item.sale.items && item.sale.items.length > 0)) {
      setProducts(prevProducts => {
        let updated = [...prevProducts];

        if (item.sale.productId) {
          updated = updated.map(p => p.id === item.sale.productId ? { ...p, stock: Math.max(0, p.stock - 1) } : p);
        }

        if (item.sale.items && item.sale.items.length > 0) {
          item.sale.items.forEach(saleItem => {
            if (saleItem.productId) {
              updated = updated.map(p => p.id === saleItem.productId ? { ...p, stock: Math.max(0, p.stock - saleItem.quantity) } : p);
            }
          });
        }
        return updated;
      });
    }

    setSales(prev => [...prev, item.sale]);
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
    alert('Venda restaurada com sucesso!');
  }, [trashSales]);

  const handlePermanentDelete = useCallback((trashId: string) => {
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
  }, []);

  const clearUserData = async () => {
    if (!user) return;
    await storageService.clearAll();
    setCustomers([]);
    setSales([]);
    setExpenses([]);
    setProducts([]);
    setTrashSales([]);
    alert("Banco de dados local limpo.");
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-indigo-950">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
          <p className="text-indigo-300 text-xs font-black uppercase tracking-widest">Carregando Gestão 93...</p>
        </div>
      </div>
    );
  }

  if (!user) return <Landing onLogin={setUser} />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
      case 'customers': return <CustomerList customers={customers} sales={sales} onAdd={(c) => setCustomers(prev => [...prev, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])} onDelete={(id) => setCustomers(prev => prev.filter(c => c.id !== id))} />;
      case 'sales-cash': return <SalesManager mode="cash" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={handleUpdateSale} onDeleteSale={handleDeleteSale} />;
      case 'sales-credit': return <SalesManager mode="credit" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={handleUpdateSale} onDeleteSale={handleDeleteSale} />;
      case 'refunds': return <RefundManager sales={sales} customers={customers} expenses={expenses} onRefund={(id) => handleDeleteSale(id, true)} onManualRefund={(desc, amount) => setExpenses(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), description: `ESTORNO: ${desc}`, amount, category: 'refund', date: new Date().toISOString().split('T')[0] }])} />;
      case 'inventory': return <InventoryManager products={products} onAdd={handleAddProduct} onDelete={(id) => setProducts(prev => prev.filter(p => p.id !== id))} onUpdate={(p) => setProducts(prev => prev.map(prod => prod.id === p.id ? p : prod))} />;
      case 'expenses': return <ExpenseManager expenses={expenses} onAdd={(description, amount) => setExpenses(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), description, amount, category: 'fixed', date: new Date().toISOString().split('T')[0] }])} onDelete={(id) => setExpenses(prev => prev.filter(e => e.id !== id))} />;
      case 'agenda': return <Agenda sales={sales} customers={customers} onUpdateSale={handleUpdateSale} />;
      case 'trash': return <TrashManager trashItems={trashSales} customers={customers} onRestore={handleRestoreSale} onDeletePermanent={handlePermanentDelete} />;
      case 'settings': return <Settings user={user} customers={customers} sales={sales} products={products} onUpdateProfile={setUser} onImport={(data) => { setCustomers(data.customers); setSales(data.sales); setProducts(data.products || []); }} onClear={clearUserData} />;
      default: return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div className="fixed inset-0 pointer-events-none z-0 bg-cover bg-center bg-no-repeat opacity-50" style={{ backgroundImage: `url(${FASHION_IMAGE_URL})` }} />
      {showTutorial && <Tutorial activeView={activeView} onClose={async () => { await storageService.saveData(`gestao93_tutorial_seen_${user.id}`, 'true'); setShowTutorial(false); }} />}
      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col shrink-0 z-50 shadow-2xl relative overflow-hidden">
        <div className="relative z-10 p-6 flex items-center gap-3 border-b border-indigo-900/50">
          <div className="bg-indigo-600 p-2 rounded-xl shrink-0 border border-white/20 shadow-lg">
             <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <div className="min-w-0">
            <h1 className="text-xl font-black italic uppercase text-white truncate">Gestão 93</h1>
            <div className="flex items-center gap-1">
              <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-400' : 'bg-amber-400 animate-pulse'}`}></div>
              <span className="text-[8px] font-black uppercase text-indigo-300">
                {syncStatus === 'synced' ? 'Banco Local OK' : 'Gravando...'}
              </span>
            </div>
          </div>
        </div>
        <div className="relative z-10 flex-1 py-4 space-y-1 px-3 overflow-y-auto no-scrollbar">
          <NavItem id="nav-dashboard" icon="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" label="Início" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem id="nav-inventory" icon="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" label="Estoque" active={activeView === 'inventory'} onClick={() => setActiveView('inventory')} />
          <NavItem id="nav-customers" icon="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 005.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" label="Clientes" active={activeView === 'customers'} onClick={() => setActiveView('customers')} />
          <NavItem id="nav-sales-cash" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" label="À Vista" active={activeView === 'sales-cash'} onClick={() => setActiveView('sales-cash')} />
          <NavItem id="nav-sales-credit" icon="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" label="A Prazo" active={activeView === 'sales-credit'} onClick={() => setActiveView('sales-credit')} />
          <NavItem id="nav-refunds" icon="M16 15v-1a4 4 0 00-4-4H8m0 0l3 3m-3-3l3-3m9 14V5a2 2 0 00-2-2H6a2 2 0 00-2 2v14a2 2 0 002 2h12a2 2 0 002-2z" label="Estornos" active={activeView === 'refunds'} onClick={() => setActiveView('refunds')} />
          <NavItem id="nav-agenda" icon="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" label="Agenda" active={activeView === 'agenda'} onClick={() => setActiveView('agenda')} />
          <NavItem id="nav-expenses" icon="M15 12H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" label="Despesas" active={activeView === 'expenses'} onClick={() => setActiveView('expenses')} />
          <NavItem id="nav-trash" icon="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" label="Lixeira" active={activeView === 'trash'} onClick={() => setActiveView('trash')} />
          <NavItem id="nav-settings" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" label="Ajustes" active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
        </div>
        <div className="relative z-10 p-4 bg-black/30 border-t border-indigo-900/50">
           <div className="flex items-center gap-3 p-3 bg-black/20 rounded-2xl border border-white/10 shadow-inner backdrop-blur-sm">
              <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center font-bold text-lg italic shrink-0 overflow-hidden shadow-lg border border-white/20">
                {user.avatarUrl ? <img src={user.avatarUrl} className="w-full h-full object-cover" /> : <span className="text-white">{user.name.charAt(0)}</span>}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-[10px] font-black truncate text-white uppercase">{user.name}</p>
                <p className="text-[8px] text-indigo-300 font-bold uppercase tracking-tighter">Boutique Premium</p>
              </div>
              <button onClick={handleLogout} className="text-indigo-200 hover:text-rose-400 transition transform hover:scale-110">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7" /></svg>
              </button>
           </div>
        </div>
      </nav>
      <main className="relative flex-1 p-4 md:p-8 overflow-y-auto h-screen z-10">
        <div className="max-w-6xl mx-auto pb-12 relative">{renderView()}</div>
      </main>
    </div>
  );
};

const NavItem: React.FC<{ id?: string; icon: string; label: string; active: boolean; onClick: () => void; }> = ({ id, icon, label, active, onClick }) => (
  <button id={id} onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 relative group ${active ? 'bg-indigo-600 text-white shadow-xl translate-x-1 border border-white/10' : 'text-indigo-100 hover:bg-white/10 hover:text-white'}`}>
    <svg className="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={icon} /></svg>
    <span className={`text-sm font-bold tracking-tight whitespace-nowrap ${active ? 'font-black' : ''}`}>{label}</span>
    {active && <div className="absolute right-3 w-1.5 h-1.5 bg-white rounded-full shadow-[0_0_8px_white]"></div>}
  </button>
);

export default App;

import React, { useState, useMemo } from 'react';
import { Product } from '../types';

interface InventoryManagerProps {
  products: Product[];
  onAdd: (product: Omit<Product, 'id'>) => void;
  onDelete: (id: string) => void;
  onUpdate: (product: Product) => void;
}

const InventoryManager: React.FC<InventoryManagerProps> = ({ products, onAdd, onDelete, onUpdate }) => {
  const [showAdd, setShowAdd] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Estados do formulário
  const [sku, setSku] = useState('');
  const [name, setName] = useState('');
  const [category, setCategory] = useState('');
  const [costPrice, setCostPrice] = useState<number>(0);
  const [price, setPrice] = useState<number>(0);
  const [stock, setStock] = useState<number>(0);
  const [minStock, setMinStock] = useState<number>(2);

  const filteredProducts = useMemo(() => {
    const term = searchTerm.toLowerCase().trim();
    if (!term) return products;
    return products.filter(p => 
      p.sku.toLowerCase().includes(term) || 
      p.name.toLowerCase().includes(term)
    );
  }, [products, searchTerm]);

  const totalCostValue = products.reduce((acc, p) => acc + (p.costPrice * p.stock), 0);
  const totalSaleValue = products.reduce((acc, p) => acc + (p.price * p.stock), 0);
  const expectedProfit = totalSaleValue - totalCostValue;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name || price < 0 || stock < 0) return;
    const finalSku = sku.trim().toUpperCase() || Math.random().toString(36).substr(2, 6).toUpperCase();

    onAdd({ sku: finalSku, name, category: category || 'Geral', costPrice, price, stock, minStock });
    resetForm();
    setShowAdd(false);
  };

  const resetForm = () => { setSku(''); setName(''); setCategory(''); setCostPrice(0); setPrice(0); setStock(0); setMinStock(2); };

  const formatCurrency = (val: number) => val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  // Verifica se o SKU digitado já existe para alertar o usuário
  const isExistingSku = useMemo(() => {
    if (!sku.trim()) return false;
    return products.some(p => p.sku.toUpperCase() === sku.trim().toUpperCase());
  }, [sku, products]);

  const existingProduct = useMemo(() => {
    return products.find(p => p.sku.toUpperCase() === sku.trim().toUpperCase());
  }, [sku, products]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-xl font-black text-slate-900 uppercase tracking-tight italic">Estoque & Produtos</h2>
          <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Controle total de peças e lucratividade.</p>
        </div>
        <button 
          onClick={() => setShowAdd(!showAdd)}
          className="bg-indigo-900 text-white px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-indigo-950 transition shadow-lg"
        >
          {showAdd ? 'Cancelar' : 'Entrada de Mercadoria'}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Custo Total em Estoque</p>
           <p className="text-xl font-black text-slate-900">{formatCurrency(totalCostValue)}</p>
        </div>
        <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Valor Total de Venda</p>
           <p className="text-xl font-black text-indigo-800">{formatCurrency(totalSaleValue)}</p>
        </div>
        <div className="bg-emerald-50 p-5 rounded-2xl border border-emerald-200 shadow-sm">
           <p className="text-[10px] font-black text-emerald-700 uppercase tracking-widest mb-1">Lucro Bruto Projetado</p>
           <p className="text-xl font-black text-emerald-800">{formatCurrency(expectedProfit)}</p>
        </div>
      </div>

      {showAdd && (
        <form onSubmit={handleSubmit} className="bg-white p-6 rounded-2xl shadow-xl border border-indigo-100 space-y-4 animate-in fade-in zoom-in duration-200">
           {isExistingSku && (
             <div className="bg-amber-50 border border-amber-200 p-3 rounded-xl mb-4">
               <p className="text-[10px] font-black text-amber-800 uppercase leading-tight">
                 ⚠️ CÓDIGO EXISTENTE: {existingProduct?.name}
               </p>
               <p className="text-[9px] font-bold text-amber-700 uppercase mt-1">
                 O sistema somará a nova quantidade ao estoque e recalculará o **Custo Médio Ponderado** automaticamente.
               </p>
             </div>
           )}

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              <div className="space-y-1">
                <label className="text-[11px] font-black text-slate-800 uppercase tracking-wider">Código (SKU)</label>
                <input 
                  type="text" 
                  value={sku} 
                  onChange={e => {
                    const val = e.target.value;
                    setSku(val);
                    if (products.some(p => p.sku.toUpperCase() === val.toUpperCase())) {
                      const p = products.find(p => p.sku.toUpperCase() === val.toUpperCase());
                      if (p && !name) setName(p.name);
                      if (p && !price) setPrice(p.price);
                    }
                  }} 
                  className="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm font-black text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" 
                  placeholder="Ex: COD123" 
                />
              </div>
              <div className="md:col-span-2 space-y-1">
                <label className="text-[11px] font-black text-slate-800 uppercase tracking-wider">Nome da Peça *</label>
                <input type="text" value={name} onChange={e => setName(e.target.value)} required className="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm font-black text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Nome do Produto" />
              </div>
              <div className="space-y-1">
                <label className="text-[11px] font-black text-slate-800 uppercase tracking-wider">Preço Custo (R$) *</label>
                <input type="number" step="0.01" value={costPrice || ''} onChange={e => setCostPrice(Number(e.target.value))} required className="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm font-black text-rose-700 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-[11px] font-black text-slate-800 uppercase tracking-wider">Preço Venda (R$) *</label>
                <input type="number" step="0.01" value={price || ''} onChange={e => setPrice(Number(e.target.value))} required className="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm font-black text-emerald-700 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-[11px] font-black text-slate-800 uppercase tracking-wider">Quantidade Entrada *</label>
                <input type="number" value={stock || ''} onChange={e => setStock(Number(e.target.value))} required className="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm font-black text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
              <div className="space-y-1">
                <label className="text-[11px] font-black text-slate-800 uppercase tracking-wider">Estoque Mínimo</label>
                <input type="number" value={minStock} onChange={e => setMinStock(Number(e.target.value))} required className="w-full bg-slate-50 border border-slate-300 rounded-lg px-3 py-2 text-sm font-black text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>
           </div>
           <div className="flex justify-end pt-2">
              <button type="submit" className="bg-indigo-900 text-white px-8 py-3 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-indigo-950 transition shadow-lg active:scale-95">
                {isExistingSku ? 'Atualizar Estoque & Custo' : 'Salvar Novo Produto'}
              </button>
           </div>
        </form>
      )}

      <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-4 border-b border-slate-100 bg-slate-50/50">
           <div className="relative max-w-md">
              <input 
                type="text" 
                placeholder="Procurar por Código ou Nome no estoque..." 
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm"
              />
              <svg className="w-4 h-4 absolute right-4 top-3.5 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
           </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 text-[11px] font-black text-slate-800 uppercase tracking-widest">Produto</th>
                <th className="px-6 py-4 text-[11px] font-black text-slate-800 uppercase tracking-widest text-right">Custo Médio</th>
                <th className="px-6 py-4 text-[11px] font-black text-slate-800 uppercase tracking-widest text-right">Venda</th>
                <th className="px-6 py-4 text-[11px] font-black text-slate-800 uppercase tracking-widest text-center">Estoque</th>
                <th className="px-6 py-4 text-[11px] font-black text-slate-800 uppercase tracking-widest text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredProducts.map(p => (
                <tr key={p.id} className="hover:bg-indigo-50/30 transition group">
                  <td className="px-6 py-4">
                    <div className="inline-block bg-slate-200 text-slate-900 text-[9px] font-black px-2 py-0.5 rounded mb-1 uppercase tracking-tighter">{p.sku}</div>
                    <div className="font-black text-slate-900 text-sm uppercase leading-tight">{p.name}</div>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <span className="text-xs font-bold text-rose-700">{formatCurrency(p.costPrice)}</span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <span className="text-sm font-black text-slate-900">{formatCurrency(p.price)}</span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <div className="flex flex-col items-center">
                      <span className={`px-3 py-1 rounded-lg text-xs font-black ${p.stock <= p.minStock ? 'bg-rose-100 text-rose-700 border border-rose-200' : 'bg-emerald-100 text-emerald-800 border border-emerald-200'}`}>
                        {p.stock}
                      </span>
                      {p.stock <= p.minStock && <span className="text-[8px] text-rose-500 font-black uppercase mt-1">Crítico</span>}
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <button onClick={() => { if (confirm('Excluir peça do sistema?')) onDelete(p.id); }} className="p-2 text-slate-400 hover:text-rose-600 transition">
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                    </button>
                  </td>
                </tr>
              ))}
              {filteredProducts.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-slate-400 font-bold uppercase text-xs tracking-widest italic">
                    {searchTerm ? `Nenhum resultado para "${searchTerm}"` : 'O estoque está vazio.'}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default InventoryManager;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { View, Customer, Sale, User, Expense, Product, TrashItem, PaymentStatus } from './types.ts';
import Dashboard from './components/Dashboard.tsx';
import CustomerList from './components/CustomerList.tsx';
import SalesManager from './components/SalesManager.tsx';
import Agenda from './components/Agenda.tsx';
import Settings from './components/Settings.tsx';
import Landing from './components/Landing.tsx';
import Tutorial from './components/Tutorial.tsx';
import ExpenseManager from './components/ExpenseManager.tsx';
import InventoryManager from './components/InventoryManager.tsx';
import TrashManager from './components/TrashManager.tsx';
import RefundManager from './components/RefundManager.tsx';
import { storageService } from './services/storageService.ts';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [trashSales, setTrashSales] = useState<TrashItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);

  const isMounted = useRef(false);

  const FASHION_IMAGE_URL = 'https://images.unsplash.com/photo-1445205170230-053b83016050?q=80&w=2000';

  useEffect(() => {
    const initApp = async () => {
      try {
        const savedUser = await storageService.loadData<User>('gestao93_current_user');

        if (savedUser && savedUser.id) {
          setUser(savedUser);
          const userId = savedUser.id;

          const tutorialSeen = await storageService.loadData<string>(`gestao93_tutorial_seen_${userId}`);
          if (!tutorialSeen) setShowTutorial(true);

          const [loadedCustomers, loadedSales, loadedExpenses, loadedProducts, loadedTrash] = await Promise.all([
            storageService.loadData<Customer[]>(`gestao93_customers_${userId}`),
            storageService.loadData<Sale[]>(`gestao93_sales_${userId}`),
            storageService.loadData<Expense[]>(`gestao93_expenses_${userId}`),
            storageService.loadData<Product[]>(`gestao93_products_${userId}`),
            storageService.loadData<TrashItem[]>(`gestao93_trash_${userId}`)
          ]);

          setCustomers(loadedCustomers || []);
          setSales(loadedSales || []);
          setExpenses(loadedExpenses || []);
          setProducts(loadedProducts || []);

          const thirtyDaysInMs = 30 * 24 * 60 * 60 * 1000;
          const validTrash = (loadedTrash || []).filter((item: TrashItem) => (Date.now() - item.deletedAt) < thirtyDaysInMs);
          setTrashSales(validTrash);
        }
      } catch (e) {
        console.error("Erro ao inicializar banco de dados:", e);
      } finally {
        setLoading(false);
        isMounted.current = true;
      }
    };
    initApp();
  }, []);

  useEffect(() => {
    if (loading || !user || !isMounted.current) return;

    const autoSave = async () => {
      try {
        setSyncStatus('syncing');
        const userId = user.id;

        await Promise.all([
          storageService.saveData(`gestao93_customers_${userId}`, customers),
          storageService.saveData(`gestao93_sales_${userId}`, sales),
          storageService.saveData(`gestao93_expenses_${userId}`, expenses),
          storageService.saveData(`gestao93_products_${userId}`, products),
          storageService.saveData(`gestao93_trash_${userId}`, trashSales),
          storageService.saveData('gestao93_current_user', user)
        ]);

        setSyncStatus('synced');
      } catch (err) {
        console.error("Falha no Auto-Save:", err);
        setSyncStatus('error');
      }
    };

    const timer = setTimeout(autoSave, 800);
    return () => clearTimeout(timer);
  }, [customers, sales, expenses, products, trashSales, user, loading]);

  const handleLogout = async () => {
    await storageService.saveData('gestao93_current_user', null);
    setUser(null);
    setActiveView('dashboard');
  };

  const handleUpdateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  const handleAddProduct = (newProduct: Omit<Product, 'id'>) => {
    setProducts(prev => {
      const existingIndex = prev.findIndex(p => p.sku.toUpperCase() === newProduct.sku.toUpperCase());

      if (existingIndex !== -1) {
        const existing = prev[existingIndex];
        const totalOldCost = Math.max(0, existing.stock) * existing.costPrice;
        const totalNewCost = newProduct.stock * newProduct.costPrice;
        const totalStock = Math.max(0, existing.stock) + newProduct.stock;

        const weightedAverageCost = totalStock > 0 ? (totalOldCost + totalNewCost) / totalStock : newProduct.costPrice;

        const updated = [...prev];
        updated[existingIndex] = {
          ...existing,
          stock: totalStock,
          costPrice: weightedAverageCost,
          price: newProduct.price,
          name: newProduct.name
        };
        return updated;
      }

      return [...prev, { ...newProduct, id: Math.random().toString(36).substr(2, 9) }];
    });
  };

  const handleUpdateProduct = (updatedProduct: Product) => {
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
  };

  const handleAddSale = (s: Omit<Sale, 'id'>) => {
    const isSameMonth = (d1: string, d2: string) => {
      const date1 = new Date(d1);
      const date2 = new Date(d2);
      return date1.getMonth() === date2.getMonth() && date1.getFullYear() === date2.getFullYear();
    };

    if (s.type === 'credit' && s.customerId !== 'BALCAO') {
      const existingSaleIndex = sales.findIndex(prev => 
        prev.customerId === s.customerId && 
        prev.type === 'credit' && 
        prev.status !== PaymentStatus.PAID &&
        isSameMonth(prev.date, s.date)
      );

      if (existingSaleIndex !== -1) {
        const existingSale = sales[existingSaleIndex];
        const updatedItems = [...existingSale.items, ...s.items];
        const updatedBaseAmount = existingSale.baseAmount + s.baseAmount;
        const updatedTotalAmount = existingSale.totalAmount + s.totalAmount;
        const updatedTotalCost = existingSale.totalCost + s.totalCost;
        const updatedNetAmount = existingSale.netAmount + s.netAmount;

        const updatedInstallments = existingSale.installments.map((inst) => {
          const additionalAmount = s.totalAmount / existingSale.installments.length;
          const newAmount = inst.amount + additionalAmount;
          return {
            ...inst,
            amount: newAmount,
            status: inst.paidAmount >= newAmount ? PaymentStatus.PAID : (inst.paidAmount > 0 ? PaymentStatus.PARTIAL : PaymentStatus.PENDING)
          };
        });

        const mergedSale: Sale = {
          ...existingSale,
          items: updatedItems,
          baseAmount: updatedBaseAmount,
          totalAmount: updatedTotalAmount,
          totalCost: updatedTotalCost,
          netAmount: updatedNetAmount,
          description: `Consolidada: ${updatedItems.map(i => i.description.split('-')[1] || i.description).join(', ').substring(0, 80)}`,
          installments: updatedInstallments,
          status: PaymentStatus.PARTIAL
        };

        const newSales = [...sales];
        newSales[existingSaleIndex] = mergedSale;
        setSales(newSales);

        if (s.items && s.items.length > 0) {
          s.items.forEach(item => {
            if (item.productId) {
              setProducts(prev => prev.map(p => 
                p.id === item.productId ? { ...p, stock: Math.max(0, p.stock - item.quantity) } : p
              ));
            }
          });
        }
        return;
      }
    }

    const newId = Math.random().toString(36).substr(2, 9);
    setSales(prev => [...prev, { ...s, id: newId }]);

    if (s.items && s.items.length > 0) {
      s.items.forEach(item => {
        if (item.productId) {
          setProducts(prev => prev.map(p => 
            p.id === item.productId ? { ...p, stock: Math.max(0, p.stock - item.quantity) } : p
          ));
        }
      });
    }
  };

  const handleDeleteSale = useCallback((id: string, isRefund: boolean = false) => {
    const saleToDelete = sales.find(s => s.id === id);
    if (!saleToDelete) return;

    setTrashSales(prevTrash => [
      ...prevTrash, 
      { id: Math.random().toString(36).substr(2, 9), sale: saleToDelete, deletedAt: Date.now() }
    ]);

    if (saleToDelete.productId || (saleToDelete.items && saleToDelete.items.length > 0)) {
      setProducts(prevProducts => {
        let updated = [...prevProducts];

        if (saleToDelete.productId) {
          updated = updated.map(p => p.id === saleToDelete.productId ? { ...p, stock: p.stock + 1 } : p);
        }

        if (saleToDelete.items && saleToDelete.items.length > 0) {
          saleToDelete.items.forEach(item => {
            if (item.productId) {
              updated = updated.map(p => p.id === item.productId ? { ...p, stock: p.stock + item.quantity } : p);
            }
          });
        }
        return updated;
      });
    }

    if (isRefund) {
      const totalAlreadyPaid = saleToDelete.installments.reduce((acc, inst) => acc + inst.paidAmount, 0);
      if (totalAlreadyPaid > 0) {
        const customer = customers.find(c => c.id === saleToDelete.customerId);
        const customerName = customer ? customer.name : (saleToDelete.customerId === 'BALCAO' ? 'Cliente Balcão' : 'Desconhecido');

        setExpenses(prev => [...prev, {
          id: Math.random().toString(36).substr(2, 9),
          description: `ESTORNO (DEVOLUÇÃO): ${customerName}`,
          amount: totalAlreadyPaid,
          category: 'refund',
          date: new Date().toISOString().split('T')[0]
        }]);
      }
    }

    setSales(prev => prev.filter(s => s.id !== id));
  }, [sales, customers]);

  const handleRestoreSale = useCallback((trashId: string) => {
    const item = trashSales.find(i => i.id === trashId);
    if (!item) return;

    if (item.sale.productId || (item.sale.items && item.sale.items.length > 0)) {
      setProducts(prevProducts => {
        let updated = [...prevProducts];

        if (item.sale.productId) {
          updated = updated.map(p => p.id === item.sale.productId ? { ...p, stock: Math.max(0, p.stock - 1) } : p);
        }

        if (item.sale.items && item.sale.items.length > 0) {
          item.sale.items.forEach(saleItem => {
            if (saleItem.productId) {
              updated = updated.map(p => p.id === saleItem.productId ? { ...p, stock: Math.max(0, p.stock - saleItem.quantity) } : p);
            }
          });
        }
        return updated;
      });
    }

    setSales(prev => [...prev, item.sale]);
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
    alert('Venda restaurada com sucesso!');
  }, [trashSales]);

  const handlePermanentDelete = useCallback((trashId: string) => {
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
  }, []);

  const clearUserData = async () => {
    if (!user) return;
    await storageService.clearAll();
    setCustomers([]);
    setSales([]);
    setExpenses([]);
    setProducts([]);
    setTrashSales([]);
    alert("Banco de dados local limpo.");
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-indigo-950">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
          <p className="text-indigo-300 text-xs font-black uppercase tracking-widest">Carregando Gestão 93...</p>
        </div>
      </div>
    );
  }

  if (!user) return <Landing onLogin={setUser} />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
      case 'customers': return <CustomerList customers={customers} sales={sales} onAdd={(c) => setCustomers(prev => [...prev, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])} onDelete={(id) => setCustomers(prev => prev.filter(c => c.id !== id))} />;
      case 'sales-cash': return <SalesManager mode="cash" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={handleUpdateSale} onDeleteSale={handleDeleteSale} />;
      case 'sales-credit': return <SalesManager mode="credit" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={handleUpdateSale} onDeleteSale={handleDeleteSale} />;
      case 'refunds': return <RefundManager sales={sales} customers={customers} expenses={expenses} onRefund={(id) => handleDeleteSale(id, true)} onManualRefund={(desc, amount) => setExpenses(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), description: `ESTORNO: ${desc}`, amount, category: 'refund', date: new Date().toISOString().split('T')[0] }])} />;
      case 'inventory': return <InventoryManager products={products} onAdd={handleAddProduct} onDelete={(id) => setProducts(prev => prev.filter(p => p.id !== id))} onUpdate={handleUpdateProduct} />;
      case 'expenses': return <ExpenseManager expenses={expenses} onAdd={(description, amount) => setExpenses(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), description, amount, category: 'fixed', date: new Date().toISOString().split('T')[0] }])} onDelete={(id) => setExpenses(prev => prev.filter(e => e.id !== id))} />;
      case 'agenda': return <Agenda sales={sales} customers={customers} onUpdateSale={handleUpdateSale} />;
      case 'trash': return <TrashManager trashItems={trashSales} customers={customers} onRestore={handleRestoreSale} onDeletePermanent={handlePermanentDelete} />;
      case 'settings': return <Settings user={user} customers={customers} sales={sales} products={products} onUpdateProfile={setUser} onImport={(data) => { setCustomers(data.customers); setSales(data.sales); setProducts(data.products || []); }} onClear={clearUserData} />;
      default: return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div className="fixed inset-0 pointer-events-none z-0 bg-cover bg-center bg-no-repeat opacity-50" style={{ backgroundImage: `url(${FASHION_IMAGE_URL})` }} />
      {showTutorial && <Tutorial activeView={activeView} onClose={async () => { await storageService.saveData(`gestao93_tutorial_seen_${user.id}`, 'true'); setShowTutorial(false); }} />}
      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col shrink-0 z-50 shadow-2xl relative overflow-hidden">
        <div className="relative z-10 p-6 flex items-center gap-3 border-b border-indigo-900/50">
          <div className="bg-indigo-600 p-2 rounded-xl shrink-0 border border-white/20 shadow-lg">
             <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <div className="min-w-0">
            <h1 className="text-xl font-black italic uppercase text-white truncate">Gestão 93</h1>
            <div className="flex items-center gap-1">
              <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-400' : 'bg-amber-400 animate-pulse'}`}></div>
              <span className="text-[8px] font-black uppercase text-indigo-300">
                {syncStatus === 'synced' ? 'Banco Local OK' : 'Gravando...'}
              </span>
            </div>
          </div>
        </div>
        <div className="relative z-10 flex-1 py-4 space-y-1 px-3 overflow-y-auto no-scrollbar">
          <NavItem id="nav-dashboard" icon="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" label="Início" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem id="nav-inventory" icon="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" label="Estoque" active={activeView === 'inventory'} onClick={() => setActiveView('inventory')} />
          <NavItem id="nav-customers" icon="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 005.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" label="Clientes" active={activeView === 'customers'} onClick={() => setActiveView('customers')} />
          <NavItem id="nav-sales-cash" icon="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" label="À Vista" active={activeView === 'sales-cash'} onClick={() => setActiveView('sales-cash')} />
          <NavItem id="nav-sales-credit" icon="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" label="A Prazo" active={activeView === 'sales-credit'} onClick={() => setActiveView('sales-credit')} />
          <NavItem id="nav-refunds" icon="M16 15v-1a4 4 0 00-4-4H8m0 0l3 3m-3-3l3-3m9 14V5a2 2 0 00-2-2H6a2 2 0 00-2 2v14a2 2 0 002 2h12a2 2 0 002-2z" label="Estornos" active={activeView === 'refunds'} onClick={() => setActiveView('refunds')} />
          <NavItem id="nav-agenda" icon="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" label="Agenda" active={activeView === 'agenda'} onClick={() => setActiveView('agenda')} />
          <NavItem id="nav-expenses" icon="M15 12H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" label="Despesas" active={activeView === 'expenses'} onClick={() => setActiveView('expenses')} />
          <NavItem id="nav-trash" icon="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" label="Lixeira" active={activeView === 'trash'} onClick={() => setActiveView('trash')} />
          <NavItem id="nav-settings" icon="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" label="Ajustes" active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
        </div>
        <div className="relative z-10 p-4 bg-black/30 border-t border-indigo-900/50">
           <div className="flex items-center gap-3 p-3 bg-black/20 rounded-2xl border border-white/10 shadow-inner backdrop-blur-sm">
              <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center font-bold text-lg italic shrink-0 overflow-hidden shadow-lg border border-white/20">
                {user.avatarUrl ? <img src={user.avatarUrl} className="w-full h-full object-cover" /> : <span className="text-white">{user.name.charAt(0)}</span>}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-[10px] font-black truncate text-white uppercase">{user.name}</p>
                <p className="text-[8px] text-indigo-300 font-bold uppercase tracking-tighter">Boutique Premium</p>
              </div>
              <button onClick={handleLogout} className="text-indigo-200 hover:text-rose-400 transition transform hover:scale-110">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7" /></svg>
              </button>
           </div>
        </div>
      </nav>
      <main className="relative flex-1 p-4 md:p-8 overflow-y-auto h-screen z-10">
        <div className="max-w-6xl mx-auto pb-12 relative">{renderView()}</div>
      </main>
    </div>
  );
};

const NavItem: React.FC<{ id?: string; icon: string; label: string; active: boolean; onClick: () => void; }> = ({ id, icon, label, active, onClick }) => (
  <button id={id} onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 relative group ${active ? 'bg-indigo-600 text-white shadow-xl translate-x-1 border border-white/10' : 'text-indigo-100 hover:bg-white/10 hover:text-white'}`}>
    <svg className="w-5 h-5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={icon} /></svg>
    <span className={`text-sm font-bold tracking-tight whitespace-nowrap ${active ? 'font-black' : ''}`}>{label}</span>
    {active && <div className="absolute right-3 w-1.5 h-1.5 bg-white rounded-full shadow-[0_0_8px_white]"></div>}
  </button>
);

export default App;

import React, { useState } from 'react';
import { Sale, Customer, PaymentStatus, Installment } from '../types.ts';

interface AgendaProps {
  sales: Sale[];
  customers: Customer[];
  onUpdateSale: (sale: Sale) => void;
}

interface ConsolidatedCard {
  customerId: string;
  customerName: string;
  dueDate: string;
  totalAmount: number;
  paidAmount: number;
  remainingAmount: number;
  isOverdue: boolean;
  salesIds: string[];
  descriptions: string[];
}

const Agenda: React.FC<AgendaProps> = ({ sales, customers, onUpdateSale }) => {
  const [abatimentoValues, setAbatimentoValues] = useState<Record<string, string>>({});

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 });

  const getGroupedData = () => {
    const months: Record<string, ConsolidatedCard[]> = {};
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    sales.forEach(sale => {
      sale.installments.forEach(inst => {
        const date = new Date(inst.dueDate);
        const monthYear = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
        const customerId = sale.customerId;
        const remaining = inst.amount - inst.paidAmount;

        if (!months[monthYear]) months[monthYear] = [];

        // Consolidamos por CLIENTE e DATA DE VENCIMENTO
        let card = months[monthYear].find(c => c.customerId === customerId && c.dueDate === inst.dueDate);

        if (!card) {
          const customer = customerId === 'BALCAO' 
            ? { name: 'Venda Balcão' } 
            : customers.find(c => c.id === customerId);

          card = {
            customerId,
            customerName: (customer?.name || 'Cliente Excluído').toUpperCase(),
            dueDate: inst.dueDate,
            totalAmount: 0,
            paidAmount: 0,
            remainingAmount: 0,
            isOverdue: false,
            salesIds: [],
            descriptions: []
          };
          months[monthYear].push(card);
        }

        card.totalAmount += inst.amount;
        card.paidAmount += inst.paidAmount;
        card.remainingAmount += remaining;

        if (remaining > 0 && new Date(inst.dueDate) < today) {
          card.isOverdue = true;
        }

        if (!card.salesIds.includes(sale.id)) {
          card.salesIds.push(sale.id);
        }

        const shortDesc = sale.description.split(':')[1]?.trim() || sale.description.split(',')[0].substring(0, 15);
        const descUpper = shortDesc.toUpperCase();
        if (!card.descriptions.includes(descUpper)) {
          card.descriptions.push(descUpper);
        }
      });
    });

    Object.keys(months).forEach(m => {
      months[m].sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
    });

    return months;
  };

  const handlePaymentAction = (card: ConsolidatedCard, amountStr: string) => {
    let amountToPay = parseFloat(amountStr.replace(',', '.'));
    if (isNaN(amountToPay) || amountToPay <= 0) return;

    const todayStr = new Date().toISOString().split('T')[0];

    card.salesIds.forEach(saleId => {
      const sale = sales.find(s => s.id === saleId);
      if (!sale) return;

      const updatedInstallments = sale.installments.map(inst => {
        if (inst.dueDate === card.dueDate && amountToPay > 0) {
          const debt = inst.amount - inst.paidAmount;
          const payment = Math.min(debt, amountToPay);
          const newPaidAmount = inst.paidAmount + payment;
          amountToPay -= payment;

          return {
            ...inst,
            paidAmount: newPaidAmount,
            paymentDate: newPaidAmount >= inst.amount ? todayStr : inst.paymentDate,
            status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
          };
        }
        return inst;
      });

      const allPaid = updatedInstallments.every(i => i.paidAmount >= i.amount);
      onUpdateSale({
        ...sale,
        installments: updatedInstallments,
        status: allPaid ? PaymentStatus.PAID : PaymentStatus.PARTIAL
      });
    });

    setAbatimentoValues(prev => ({ ...prev, [`${card.customerId}-${card.dueDate}`]: '' }));
  };

  const groupedData = getGroupedData();
  const sortedMonthKeys = Object.keys(groupedData).sort((a, b) => {
    const parseMonth = (str: string) => {
      const parts = str.split(' de ');
      const months = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
      return new Date(parseInt(parts[1]), months.indexOf(parts[0].toLowerCase())).getTime();
    };
    return parseMonth(a) - parseMonth(b);
  });

  return (
    <div className="space-y-8 pb-24">
      <div className="flex flex-col gap-1 px-1">
        <h2 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">Agenda Consolidada</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest leading-none">Acompanhamento direto de recebimentos por data</p>
      </div>

      {sortedMonthKeys.map(month => {
        const cards = groupedData[month];

        return (
          <div key={month} className="space-y-6">
            <div className="flex items-center gap-3 px-1">
              <span className="text-[11px] font-black text-indigo-600 bg-white px-4 py-1.5 rounded-full border-2 border-indigo-100 uppercase tracking-tighter shadow-sm">{month}</span>
              <div className="h-0.5 flex-1 bg-slate-200/50"></div>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
              {cards.map((card) => {
                const isPaid = card.remainingAmount <= 0;
                const dueDate = new Date(card.dueDate);
                const inputKey = `${card.customerId}-${card.dueDate}`;

                const statusColor = isPaid ? 'emerald' : (card.isOverdue ? 'rose' : 'amber');
                const statusBg = isPaid ? 'bg-emerald-500' : (card.isOverdue ? 'bg-rose-500' : 'bg-amber-400');

                return (
                  <div 
                    key={`${card.customerId}-${card.dueDate}`} 
                    className={`flex flex-col bg-white border-2 rounded-[2rem] p-5 transition-all shadow-sm relative overflow-hidden h-full ${isPaid ? 'opacity-40 border-slate-100' : `border-${statusColor}-100 hover:shadow-xl hover:scale-[1.02]`}`}
                  >
                    {/* Badge de Data Redondo (Top-Left) */}
                    <div className="flex items-center gap-3 mb-4">
                      <div className={`flex items-center justify-center text-[10px] font-black w-10 h-10 rounded-full text-white shadow-md shrink-0 ${statusBg}`}>
                        {dueDate.getDate()}/{dueDate.getMonth() + 1}
                      </div>
                      <div className="min-w-0">
                        <h4 className="text-[11px] font-black text-slate-900 truncate tracking-tight leading-tight uppercase">
                          {card.customerName}
                        </h4>
                        <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Cliente</p>
                      </div>
                    </div>

                    {/* Descrição e Valor Centralizados */}
                    <div className="flex-1 mb-5 space-y-1">
                      <h5 className="text-[9px] font-black text-slate-400 uppercase leading-none tracking-tight">
                        {card.descriptions.length > 1 ? 'VÁRIAS COMPRAS' : card.descriptions[0]}
                      </h5>
                      <p className={`text-xl font-black tracking-tighter leading-none ${isPaid ? 'text-emerald-600' : 'text-slate-900'}`}>
                        {formatCurrency(card.remainingAmount)}
                      </p>
                    </div>

                    {/* Controles de Pagamento Diretos */}
                    {!isPaid ? (
                      <div className="space-y-2 mt-auto">
                        <div className="flex items-center bg-white border border-slate-200 rounded-xl overflow-hidden h-10 shadow-sm focus-within:ring-2 focus-within:ring-indigo-500/20 transition-all">
                          <input 
                            type="text" 
                            inputMode="decimal"
                            placeholder="R$"
                            value={abatimentoValues[inputKey] || ''}
                            onChange={e => setAbatimentoValues(prev => ({ ...prev, [inputKey]: e.target.value }))}
                            className="w-full h-full px-3 text-[11px] font-black text-indigo-600 outline-none placeholder:text-slate-300"
                          />
                          <button 
                            onClick={() => handlePaymentAction(card, abatimentoValues[inputKey] || '0')}
                            className="bg-indigo-600 text-white px-4 h-full hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center"
                          >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M12 4v16m8-8H4" /></svg>
                          </button>
                        </div>
                        <button 
                          onClick={() => handlePaymentAction(card, card.remainingAmount.toString())}
                          className="w-full bg-emerald-500 text-white h-10 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 transition active:scale-95 shadow-lg shadow-emerald-50"
                        >
                          Quitar Dia
                        </button>
                      </div>
                    ) : (
                      <div className="flex items-center justify-center py-3 gap-2 text-emerald-500 font-black text-[10px] uppercase bg-emerald-50 rounded-2xl border border-emerald-100">
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                        <span>Recebido</span>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}

      {Object.keys(groupedData).length === 0 && (
        <div className="flex flex-col items-center justify-center py-24 text-slate-300 gap-4">
          <svg className="w-16 h-16 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          <p className="font-black uppercase text-xs tracking-[0.3em]">Nenhum recebimento agendado</p>
        </div>
      )}
    </div>
  );
};

