                      </button>
                    )}
                  </td>

                  {/* Coluna Ações (Excluir) */}
                  <td className="px-6 py-4 text-center">
                    <button 
                      type="button"
                      onClick={() => { if (window.confirm('Excluir este produto do estoque permanentemente?')) onDelete(p.id); }} 
