          <div className="h-64 min-h-[256px] w-full relative">
            <ResponsiveContainer width="100%" height="100%" debounce={50}>
              <BarChart data={forecastData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={10} fontWeight="900" stroke="#94a3b8" />
                <YAxis axisLine={false} tickLine={false} fontSize={10} fontWeight="900" stroke="#94a3b8" />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}} 
                  contentStyle={{ borderRadius: '20px', border: 'none', background: '#0f172a', color: '#fff' }}
                  formatter={(value: number) => [formatCurrency(value), '']}
                />
                <Bar dataKey="Pendente" stackId="a" fill="#4f46e5" radius={[0, 0, 0, 0]} barSize={35} />
                <Bar dataKey="Recebido" stackId="a" fill="#10b981" radius={[8, 8, 0, 0]} barSize={35} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-slate-900 p-8 rounded-[2.5rem] shadow-xl text-white">
            <h4 className="font-black text-[9px] uppercase tracking-[0.3em] text-indigo-400 mb-6">Análise Inteligente</h4>
            <p className="text-xs leading-relaxed font-medium italic opacity-90">"{insights}"</p>
            <button onClick={() => fetchInsights(true)} disabled={isSyncing} className="mt-6 text-[9px] font-black uppercase text-indigo-400 underline decoration-indigo-400/30 hover:text-white transition">Recalcular Insights</button>
          </div>

          <div className="bg-indigo-50 p-6 rounded-3xl border border-indigo-100">
            <h4 className="font-black text-indigo-900 text-[10px] uppercase tracking-widest mb-3">DRE Detalhado</h4>
            <p className="text-[10px] text-indigo-400 font-bold uppercase mb-4 leading-tight">Análise profunda entre Venda Efetuada vs Dinheiro em Caixa.</p>
            <button 
              onClick={() => setShowBreakdown(!showBreakdown)}
              className="w-full bg-white text-indigo-600 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest border border-indigo-200 shadow-sm"
            >
              {showBreakdown ? 'Ocultar Detalhes' : 'Ver Demonstrativo Real'}
            </button>
          </div>
        </div>
      </div>

      {showBreakdown && (
        <div className="bg-white p-10 rounded-[3rem] shadow-2xl animate-in fade-in slide-in-from-top-4 duration-500 border border-slate-100">
           <h4 className="text-xl font-black uppercase italic tracking-widest mb-8 text-slate-900 border-b border-slate-100 pb-4">DRE: Faturamento vs Caixa Real ({months[selectedMonth]} {selectedYear})</h4>
           <div className="space-y-4 text-sm font-medium">

              <div className="flex justify-between text-slate-400 font-black uppercase text-xs">
                 <span>Faturamento Bruto (Vendido)</span>
                 <span>{formatCurrency(cur.grossRevenue)}</span>
              </div>

              <div className="h-0.5 bg-slate-50 w-full my-4"></div>

              <div className="flex justify-between text-emerald-600 font-black uppercase text-xs bg-emerald-50 p-4 rounded-2xl border border-emerald-100">
                 <div className="flex flex-col">
                   <span>(+) RECEBIMENTO REAL NO MÊS</span>
                   <span className="text-[8px] opacity-70">Soma de todas as parcelas pagas hoje</span>
                 </div>
                 <span className="text-lg">{formatCurrency(cur.realReceived)}</span>
              </div>

              <div className="flex justify-between text-rose-500 pt-4 px-2">
                 <span>(-) Custo de Mercadorias (CMV)</span>
                 <span>{formatCurrency(cur.totalCostOfGoods)}</span>
              </div>

              <div className="flex justify-between text-rose-500 px-2">
                 <span>(-) Despesas Fixas Operacionais</span>
                 <span>{formatCurrency(cur.totalFixedExpenses)}</span>
              </div>

              <div className="flex justify-between pt-8 mt-6 border-t-2 border-indigo-500/10 text-3xl font-black text-indigo-600 bg-indigo-50/30 p-6 rounded-[2rem]">
                 <div className="flex flex-col">
                   <span>LUCRO LÍQUIDO</span>
                   <span className="text-[10px] uppercase font-bold text-indigo-400 tracking-widest">Saldo Real do Período</span>
                 </div>
                 <span>{formatCurrency(cur.profit)}</span>
              </div>

              <p className="text-[10px] text-slate-400 text-center font-bold uppercase tracking-widest pt-4 italic">
                * O lucro é calculado sobre o valor RECEBIDO, descontando o CUSTO das peças vendidas e DESPESAS.
              </p>
           </div>
        </div>
      )}
    </div>
  );
};

