              </div>
              <div className="h-0.5 bg-slate-50 w-full"></div>

              <div className="flex justify-between text-indigo-600 font-black uppercase text-xs p-3 bg-indigo-50 rounded-xl">
                 <span>(+) RECEBIMENTO REAL NO MÊS</span>
                 <span>{formatCurrency(cur.realReceived)}</span>
