};

export default SalesManager;

import React, { useState } from 'react';
import { Sale, Customer, PaymentStatus, Installment, SaleItem } from '../types.ts';

interface AgendaProps {
  sales: Sale[];
  customers: Customer[];
  onUpdateSale: (sale: Sale) => void;
}

interface ConsolidatedCard {
  id: string; // ID único para controle de estado (customerId + dueDate)
  customerId: string;
  customerName: string;
  dueDate: string;
  totalAmount: number;
  paidAmount: number;
  remainingAmount: number;
  isOverdue: boolean;
  salesIds: string[];
  descriptions: string[];
  items: SaleItem[]; // Lista consolidada de itens vendidos
}

const Agenda: React.FC<AgendaProps> = ({ sales, customers, onUpdateSale }) => {
  const [abatimentoValues, setAbatimentoValues] = useState<Record<string, string>>({});
  const [expandedCardId, setExpandedCardId] = useState<string | null>(null);

  const formatCurrency = (val: number) => 
    val.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 });

  const getGroupedData = () => {
    const months: Record<string, ConsolidatedCard[]> = {};
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    sales.forEach(sale => {
      sale.installments.forEach(inst => {
        const date = new Date(inst.dueDate);
        const monthYear = date.toLocaleString('pt-BR', { month: 'long', year: 'numeric' });
        const customerId = sale.customerId;
        const remaining = inst.amount - inst.paidAmount;

        if (!months[monthYear]) months[monthYear] = [];

        const cardId = `${customerId}-${inst.dueDate}`;
        let card = months[monthYear].find(c => c.id === cardId);

        if (!card) {
          const customer = customerId === 'BALCAO' 
            ? { name: 'Venda Balcão' } 
            : customers.find(c => c.id === customerId);

          card = {
            id: cardId,
            customerId,
            customerName: (customer?.name || 'Cliente Excluído').toUpperCase(),
            dueDate: inst.dueDate,
            totalAmount: 0,
            paidAmount: 0,
            remainingAmount: 0,
            isOverdue: false,
            salesIds: [],
            descriptions: [],
            items: []
          };
          months[monthYear].push(card);
        }

        card.totalAmount += inst.amount;
        card.paidAmount += inst.paidAmount;
        card.remainingAmount += remaining;

        if (remaining > 0 && new Date(inst.dueDate) < today) {
          card.isOverdue = true;
        }

        if (!card.salesIds.includes(sale.id)) {
          card.salesIds.push(sale.id);
          // Adiciona os itens da venda à lista consolidada do card
          if (sale.items && sale.items.length > 0) {
            card.items = [...card.items, ...sale.items];
          }
        }

        const shortDesc = sale.description.split(':')[1]?.trim() || sale.description.split(',')[0].substring(0, 15);
        const descUpper = shortDesc.toUpperCase();
        if (!card.descriptions.includes(descUpper)) {
          card.descriptions.push(descUpper);
        }
      });
    });

    Object.keys(months).forEach(m => {
      months[m].sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
    });

    return months;
  };

  const handlePaymentAction = (card: ConsolidatedCard, amountStr: string) => {
    let amountToPay = parseFloat(amountStr.replace(',', '.'));
    if (isNaN(amountToPay) || amountToPay <= 0) return;

    const todayStr = new Date().toISOString().split('T')[0];

    card.salesIds.forEach(saleId => {
      const sale = sales.find(s => s.id === saleId);
      if (!sale) return;

      const updatedInstallments = sale.installments.map(inst => {
        if (inst.dueDate === card.dueDate && amountToPay > 0) {
          const debt = inst.amount - inst.paidAmount;
          const payment = Math.min(debt, amountToPay);
          const newPaidAmount = inst.paidAmount + payment;
          amountToPay -= payment;

          return {
            ...inst,
            paidAmount: newPaidAmount,
            paymentDate: newPaidAmount >= inst.amount ? todayStr : inst.paymentDate,
            status: newPaidAmount >= inst.amount ? PaymentStatus.PAID : PaymentStatus.PARTIAL
          };
        }
        return inst;
      });

      const allPaid = updatedInstallments.every(i => i.paidAmount >= i.amount);
      onUpdateSale({
        ...sale,
        installments: updatedInstallments,
        status: allPaid ? PaymentStatus.PAID : PaymentStatus.PARTIAL
      });
    });

    setAbatimentoValues(prev => ({ ...prev, [card.id]: '' }));
  };

  const groupedData = getGroupedData();
  const sortedMonthKeys = Object.keys(groupedData).sort((a, b) => {
    const parseMonth = (str: string) => {
      const parts = str.split(' de ');
      const monthsMap = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
      return new Date(parseInt(parts[1]), monthsMap.indexOf(parts[0].toLowerCase())).getTime();
    };
    return parseMonth(a) - parseMonth(b);
  });

  const toggleExpand = (id: string) => {
    setExpandedCardId(expandedCardId === id ? null : id);
  };

  return (
    <div className="space-y-8 pb-24">
      <div className="flex flex-col gap-1 px-1">
        <h2 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">Agenda Consolidada</h2>
        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest leading-none">Acompanhamento direto de recebimentos por data</p>
      </div>

      {sortedMonthKeys.map(month => {
        const cards = groupedData[month];

        return (
          <div key={month} className="space-y-6">
            <div className="flex items-center gap-3 px-1">
              <span className="text-[11px] font-black text-indigo-600 bg-white px-4 py-1.5 rounded-full border-2 border-indigo-100 uppercase tracking-tighter shadow-sm">{month}</span>
              <div className="h-0.5 flex-1 bg-slate-200/50"></div>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
              {cards.map((card) => {
                const isPaid = card.remainingAmount <= 0;
                const isExpanded = expandedCardId === card.id;
                const dueDate = new Date(card.dueDate + 'T12:00:00');
                const inputKey = card.id;

                const statusColor = isPaid ? 'emerald' : (card.isOverdue ? 'rose' : 'amber');
                const statusBg = isPaid ? 'bg-emerald-500' : (card.isOverdue ? 'bg-rose-500' : 'bg-amber-400');

                return (
                  <div 
                    key={card.id} 
                    className={`flex flex-col bg-white border-2 rounded-[2rem] transition-all shadow-sm relative overflow-hidden h-fit ${isPaid ? 'opacity-60 border-slate-100' : `border-${statusColor}-100 hover:shadow-xl ${isExpanded ? 'ring-4 ring-indigo-50' : ''}`} ${isExpanded ? 'col-span-2' : ''}`}
                  >
                    {/* Cabeçalho do Card */}
                    <div 
                      onClick={() => toggleExpand(card.id)}
                      className="p-5 cursor-pointer select-none"
                    >
                      <div className="flex items-center gap-3 mb-4">
                        <div className={`flex items-center justify-center text-[10px] font-black w-10 h-10 rounded-full text-white shadow-md shrink-0 ${statusBg}`}>
                          {dueDate.getDate()}/{dueDate.getMonth() + 1}
                        </div>
                        <div className="min-w-0 flex-1">
                          <h4 className="text-[11px] font-black text-slate-900 truncate tracking-tight leading-tight uppercase">
                            {card.customerName}
                          </h4>
                          <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Cliente</p>
                        </div>
                        <div className="text-slate-300">
                          <svg className={`w-4 h-4 transition-transform ${isExpanded ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 9l-7 7-7-7" /></svg>
                        </div>
                      </div>

                      <div className="flex-1 mb-2 space-y-1">
                        <h5 className="text-[9px] font-black text-slate-400 uppercase leading-none tracking-tight">
                          {card.descriptions.length > 1 ? 'MÚLTIPLOS LANÇAMENTOS' : card.descriptions[0]}
                        </h5>
                        <p className={`text-xl font-black tracking-tighter leading-none ${isPaid ? 'text-emerald-600' : 'text-slate-900'}`}>
                          {formatCurrency(card.remainingAmount)}
                        </p>
                      </div>
                    </div>

                    {/* Conteúdo Expandido: Detalhes dos Produtos */}
                    {isExpanded && (
                      <div className="px-5 pb-5 pt-2 border-t border-slate-50 bg-slate-50/30 animate-in slide-in-from-top-2 duration-300">
                        <h6 className="text-[8px] font-black text-indigo-400 uppercase tracking-widest mb-3 italic">Conteúdo desta Dívida:</h6>
                        <div className="space-y-2 max-h-40 overflow-y-auto no-scrollbar mb-4">
                          {card.items.length > 0 ? card.items.map((item, i) => (
                            <div key={i} className="flex justify-between items-center bg-white p-2 rounded-xl border border-slate-100 shadow-sm">
                              <div className="min-w-0 flex-1 pr-2">
                                <p className="text-[9px] font-black text-slate-800 uppercase truncate">{item.description}</p>
                                <p className="text-[8px] text-slate-400 font-bold uppercase">{item.quantity} UN x {formatCurrency(item.price)}</p>
                              </div>
                              <span className="text-[9px] font-black text-indigo-600 shrink-0">{formatCurrency(item.price * item.quantity)}</span>
                            </div>
                          )) : (
                            <p className="text-[9px] text-slate-400 italic">Detalhes não disponíveis para esta venda antiga.</p>
                          )}
                        </div>

                        {/* Botões de Ação dentro do Detalhe */}
                        {!isPaid && (
                          <div className="space-y-2">
                            <div className="flex items-center bg-white border border-slate-200 rounded-xl overflow-hidden h-10 shadow-sm focus-within:ring-2 focus-within:ring-indigo-500/20 transition-all">
                              <input 
                                type="text" 
                                inputMode="decimal"
                                placeholder="Abater R$"
                                value={abatimentoValues[inputKey] || ''}
                                onChange={e => setAbatimentoValues(prev => ({ ...prev, [inputKey]: e.target.value }))}
                                className="w-full h-full px-3 text-[11px] font-black text-indigo-600 outline-none placeholder:text-slate-300"
                              />
                              <button 
                                onClick={() => handlePaymentAction(card, abatimentoValues[inputKey] || '0')}
                                className="bg-indigo-600 text-white px-4 h-full hover:bg-indigo-700 transition-all flex items-center justify-center"
                              >
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M12 4v16m8-8H4" /></svg>
                              </button>
                            </div>
                            <button 
                              onClick={() => handlePaymentAction(card, card.remainingAmount.toString())}
                              className="w-full bg-emerald-500 text-white h-10 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 transition shadow-lg shadow-emerald-50"
                            >
                              Liquidar Parcela
                            </button>
                          </div>
                        )}
                      </div>
                    )}

                    {/* Footer Visual simples se não estiver pago e não estiver expandido */}
                    {!isPaid && !isExpanded && (
                      <div className="px-5 pb-4 mt-auto">
                        <button 
                          onClick={() => toggleExpand(card.id)}
                          className="w-full py-2 rounded-xl text-[8px] font-black uppercase text-indigo-500 bg-indigo-50 hover:bg-indigo-100 transition"
                        >
                          Ver Detalhes / Abater
                        </button>
                      </div>
                    )}

                    {isPaid && !isExpanded && (
                      <div className="px-5 pb-4 mt-auto">
                        <div className="flex items-center justify-center py-2 gap-2 text-emerald-500 font-black text-[8px] uppercase bg-emerald-50 rounded-xl border border-emerald-100">
                          <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                          <span>Recebido</span>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}

      {Object.keys(groupedData).length === 0 && (
        <div className="flex flex-col items-center justify-center py-24 text-slate-300 gap-4">
          <svg className="w-16 h-16 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          <p className="font-black uppercase text-xs tracking-[0.3em]">Nenhum recebimento agendado</p>
        </div>
      )}
    </div>
  );
};

export default Agenda;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { View, Customer, Sale, User, Expense, Product, TrashItem, PaymentStatus, Installment } from './types.ts';
import Dashboard from './components/Dashboard.tsx';
import CustomerList from './components/CustomerList.tsx';
import SalesManager from './components/SalesManager.tsx';
import Agenda from './components/Agenda.tsx';
import Settings from './components/Settings.tsx';
import Landing from './components/Landing.tsx';
import Tutorial from './components/Tutorial.tsx';
import ExpenseManager from './components/ExpenseManager.tsx';
import InventoryManager from './components/InventoryManager.tsx';
import TrashManager from './components/TrashManager.tsx';
import RefundManager from './components/RefundManager.tsx';
import { storageService } from './services/storageService.ts';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [trashSales, setTrashSales] = useState<TrashItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');
  const [showTutorial, setShowTutorial] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  const isMounted = useRef(false);

  const FASHION_IMAGE_URL = 'https://images.unsplash.com/photo-1445205170230-053b83016050?q=80&w=2000';

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setDeferredPrompt(null);
    }
  };

  useEffect(() => {
    const initApp = async () => {
      try {
        const savedUser = await storageService.loadData<User>('gestao93_current_user');

        if (savedUser && savedUser.id) {
          setUser(savedUser);
          const userId = savedUser.id;

          const tutorialSeen = await storageService.loadData<string>(`gestao93_tutorial_seen_${userId}`);
          if (!tutorialSeen) setShowTutorial(true);

          const [loadedCustomers, loadedSales, loadedExpenses, loadedProducts, loadedTrash] = await Promise.all([
            storageService.loadData<Customer[]>(`gestao93_customers_${userId}`),
            storageService.loadData<Sale[]>(`gestao93_sales_${userId}`),
            storageService.loadData<Expense[]>(`gestao93_expenses_${userId}`),
            storageService.loadData<Product[]>(`gestao93_products_${userId}`),
            storageService.loadData<TrashItem[]>(`gestao93_trash_${userId}`)
          ]);

          setCustomers(loadedCustomers || []);
          setSales(loadedSales || []);
          setExpenses(loadedExpenses || []);
          setProducts(loadedProducts || []);

          const thirtyDaysInMs = 30 * 24 * 60 * 60 * 1000;
          const validTrash = (loadedTrash || []).filter((item: TrashItem) => (Date.now() - item.deletedAt) < thirtyDaysInMs);
          setTrashSales(validTrash);
        }
      } catch (e) {
        console.error("Erro ao inicializar banco de dados:", e);
      } finally {
        setLoading(false);
        isMounted.current = true;
      }
    };
    initApp();
  }, []);

  useEffect(() => {
    if (loading || !user || !isMounted.current) return;

    const autoSave = async () => {
      try {
        setSyncStatus('syncing');
        const userId = user.id;

        await Promise.all([
          storageService.saveData(`gestao93_customers_${userId}`, customers),
          storageService.saveData(`gestao93_sales_${userId}`, sales),
          storageService.saveData(`gestao93_expenses_${userId}`, expenses),
          storageService.saveData(`gestao93_products_${userId}`, products),
          storageService.saveData(`gestao93_trash_${userId}`, trashSales),
          storageService.saveData('gestao93_current_user', user)
        ]);

        setSyncStatus('synced');
      } catch (err) {
        console.error("Falha no Auto-Save:", err);
        setSyncStatus('error');
      }
    };

    const timer = setTimeout(autoSave, 800);
    return () => clearTimeout(timer);
  }, [customers, sales, expenses, products, trashSales, user, loading]);

  const handleLogout = async () => {
    await storageService.saveData('gestao93_current_user', null);
    setUser(null);
    setActiveView('dashboard');
  };

  const handleUpdateSale = (updatedSale: Sale) => {
    setSales(prev => prev.map(s => s.id === updatedSale.id ? updatedSale : s));
  };

  const handleAddProduct = (newProduct: Omit<Product, 'id'>) => {
    setProducts(prev => {
      const existingIndex = prev.findIndex(p => p.sku.toUpperCase() === newProduct.sku.toUpperCase());

      if (existingIndex !== -1) {
        const existing = prev[existingIndex];
        const totalOldCost = Math.max(0, existing.stock) * existing.costPrice;
        const totalNewCost = newProduct.stock * newProduct.costPrice;
        const totalStock = Math.max(0, existing.stock) + newProduct.stock;

        const weightedAverageCost = totalStock > 0 ? (totalOldCost + totalNewCost) / totalStock : newProduct.costPrice;

        const updated = [...prev];
        updated[existingIndex] = {
          ...existing,
          stock: totalStock,
          costPrice: weightedAverageCost,
          price: newProduct.price,
          name: newProduct.name
        };
        return updated;
      }

      return [...prev, { ...newProduct, id: Math.random().toString(36).substr(2, 9) }];
    });
  };

  const handleUpdateProduct = (updatedProduct: Product) => {
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
  };

  const handleAddSale = (s: Omit<Sale, 'id'>) => {
    const isSameMonthYear = (d1: string, d2: string) => {
      const date1 = new Date(d1);
      const date2 = new Date(d2);
      return date1.getMonth() === date2.getMonth() && date1.getFullYear() === date2.getFullYear();
    };

    if (s.type === 'credit' && s.customerId !== 'BALCAO') {
      const existingSaleIndex = sales.findIndex(prev => 
        prev.customerId === s.customerId && 
        prev.type === 'credit' && 
        prev.status !== PaymentStatus.PAID &&
        isSameMonthYear(prev.date, s.date)
      );

      if (existingSaleIndex !== -1) {
        const existingSale = sales[existingSaleIndex];
        const updatedItems = [...existingSale.items, ...s.items];
        const updatedBaseAmount = existingSale.baseAmount + s.baseAmount;
        const updatedTotalAmount = existingSale.totalAmount + s.totalAmount;
        const updatedTotalCost = existingSale.totalCost + s.totalCost;
        const updatedNetAmount = existingSale.netAmount + s.netAmount;

        const mergedInstallments = [...existingSale.installments];

        s.installments.forEach(newInst => {
          const newMonthYear = newInst.dueDate.substring(0, 7);
          const idx = mergedInstallments.findIndex(ei => ei.dueDate.startsWith(newMonthYear));

          if (idx !== -1) {
            const target = mergedInstallments[idx];
            const newAmount = target.amount + newInst.amount;
            const newPaidAmount = target.paidAmount + newInst.paidAmount;

            mergedInstallments[idx] = {
              ...target,
              amount: newAmount,
              paidAmount: newPaidAmount,
              status: newPaidAmount >= newAmount ? PaymentStatus.PAID : (newPaidAmount > 0 ? PaymentStatus.PARTIAL : PaymentStatus.PENDING)
            };
          } else {
            mergedInstallments.push({ ...newInst, saleId: existingSale.id });
          }
        });

        mergedInstallments.sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());

        const mergedSale: Sale = {
          ...existingSale,
          items: updatedItems,
          baseAmount: updatedBaseAmount,
          totalAmount: updatedTotalAmount,
          totalCost: updatedTotalCost,
          netAmount: updatedNetAmount,
          description: `Consolidada: ${updatedItems.map(i => i.description.split('-')[1] || i.description).join(', ').substring(0, 100)}`,
          installments: mergedInstallments,
          status: PaymentStatus.PARTIAL
        };

        const otherSales = sales.filter((_, idx) => idx !== existingSaleIndex);
        setSales([mergedSale, ...otherSales]);

        if (s.items && s.items.length > 0) {
          s.items.forEach(item => {
            if (item.productId) {
              setProducts(prev => prev.map(p => 
                p.id === item.productId ? { ...p, stock: Math.max(0, p.stock - item.quantity) } : p
              ));
            }
          });
        }
        return;
      }
    }

    const newId = Math.random().toString(36).substr(2, 9);
    setSales(prev => [{ ...s, id: newId }, ...prev]);

    if (s.items && s.items.length > 0) {
      s.items.forEach(item => {
        if (item.productId) {
          setProducts(prev => prev.map(p => 
            p.id === item.productId ? { ...p, stock: Math.max(0, p.stock - item.quantity) } : p
          ));
        }
      });
    }
  };

  const handleDeleteSale = useCallback((id: string, isRefund: boolean = false) => {
    const saleToDelete = sales.find(s => s.id === id);
    if (!saleToDelete) return;

    setTrashSales(prevTrash => [
      { id: Math.random().toString(36).substr(2, 9), sale: saleToDelete, deletedAt: Date.now() },
      ...prevTrash
    ]);

    if (saleToDelete.productId || (saleToDelete.items && saleToDelete.items.length > 0)) {
      setProducts(prevProducts => {
        let updated = [...prevProducts];

        if (saleToDelete.productId) {
          updated = updated.map(p => p.id === saleToDelete.productId ? { ...p, stock: p.stock + 1 } : p);
        }

        if (saleToDelete.items && saleToDelete.items.length > 0) {
          saleToDelete.items.forEach(item => {
            if (item.productId) {
              updated = updated.map(p => p.id === item.productId ? { ...p, stock: p.stock + item.quantity } : p);
            }
          });
        }
        return updated;
      });
    }

    if (isRefund) {
      const totalAlreadyPaid = saleToDelete.installments.reduce((acc, inst) => acc + inst.paidAmount, 0);
      if (totalAlreadyPaid > 0) {
        const customer = customers.find(c => c.id === saleToDelete.customerId);
        const customerName = customer ? customer.name : (saleToDelete.customerId === 'BALCAO' ? 'Cliente Balcão' : 'Desconhecido');

        setExpenses(prev => [{
          id: Math.random().toString(36).substr(2, 9),
          description: `ESTORNO (DEVOLUÇÃO): ${customerName}`,
          amount: totalAlreadyPaid,
          category: 'refund',
          date: new Date().toISOString().split('T')[0]
        }, ...prev]);
      }
    }

    setSales(prev => prev.filter(s => s.id !== id));
  }, [sales, customers]);

  const handleRestoreSale = useCallback((trashId: string) => {
    const item = trashSales.find(i => i.id === trashId);
    if (!item) return;

    if (item.sale.productId || (item.sale.items && item.sale.items.length > 0)) {
      setProducts(prevProducts => {
        let updated = [...prevProducts];

        if (item.sale.productId) {
          updated = updated.map(p => p.id === item.sale.productId ? { ...p, stock: Math.max(0, p.stock - 1) } : p);
        }

        if (item.sale.items && item.sale.items.length > 0) {
          item.sale.items.forEach(saleItem => {
            if (saleItem.productId) {
              updated = updated.map(p => p.id === saleItem.productId ? { ...p, stock: Math.max(0, p.stock - saleItem.quantity) } : p);
            }
          });
        }
        return updated;
      });
    }

    setSales(prev => [item.sale, ...prev]);
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
    alert('Venda restaurada com sucesso!');
  }, [trashSales]);

  const handlePermanentDelete = useCallback((trashId: string) => {
    setTrashSales(prev => prev.filter(i => i.id !== trashId));
  }, []);

  const clearUserData = async () => {
    if (!user) return;
    await storageService.clearAll();
    setCustomers([]);
    setSales([]);
    setExpenses([]);
    setProducts([]);
    setTrashSales([]);
    alert("Banco de dados local limpo.");
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-indigo-950">
        <div className="flex flex-col items-center gap-6">
          <div className="w-16 h-16 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
          <p className="text-indigo-300 text-xs font-black uppercase tracking-widest">Carregando Gestão 93...</p>
        </div>
      </div>
    );
  }

  if (!user) return <Landing onLogin={setUser} />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
      case 'customers': return <CustomerList customers={customers} sales={sales} onAdd={(c) => setCustomers(prev => [...prev, { ...c, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now() }])} onDelete={(id) => setCustomers(prev => prev.filter(c => c.id !== id))} />;
      case 'sales-cash': return <SalesManager mode="cash" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={handleUpdateSale} onDeleteSale={handleDeleteSale} />;
      case 'sales-credit': return <SalesManager mode="credit" sales={sales} customers={customers} products={products} onAddSale={handleAddSale} onUpdateSale={handleUpdateSale} onDeleteSale={handleDeleteSale} />;
      case 'refunds': return <RefundManager sales={sales} customers={customers} expenses={expenses} onRefund={(id) => handleDeleteSale(id, true)} onManualRefund={(desc, amount) => setExpenses(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), description: `ESTORNO: ${desc}`, amount, category: 'refund', date: new Date().toISOString().split('T')[0] }])} />;
      case 'inventory': return <InventoryManager products={products} onAdd={handleAddProduct} onDelete={(id) => setProducts(prev => prev.filter(p => p.id !== id))} onUpdate={handleUpdateProduct} />;
      case 'expenses': return <ExpenseManager expenses={expenses} onAdd={(description, amount) => setExpenses(prev => [...prev, { id: Math.random().toString(36).substr(2, 9), description, amount, category: 'fixed', date: new Date().toISOString().split('T')[0] }])} onDelete={(id) => setExpenses(prev => prev.filter(e => e.id !== id))} />;
      case 'agenda': return <Agenda sales={sales} customers={customers} onUpdateSale={handleUpdateSale} />;
      case 'trash': return <TrashManager trashItems={trashSales} customers={customers} onRestore={handleRestoreSale} onDeletePermanent={handlePermanentDelete} />;
      case 'settings': return <Settings user={user} customers={customers} sales={sales} products={products} onUpdateProfile={setUser} onImport={(data) => { setCustomers(data.customers); setSales(data.sales); setProducts(data.products || []); }} onClear={clearUserData} onInstall={deferredPrompt ? handleInstallClick : undefined} />;
      default: return <Dashboard sales={sales} customers={customers} expenses={expenses} products={products} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row relative">
      <div className="fixed inset-0 pointer-events-none z-0 bg-cover bg-center bg-no-repeat opacity-50" style={{ backgroundImage: `url(${FASHION_IMAGE_URL})` }} />
      {showTutorial && <Tutorial activeView={activeView} onClose={async () => { await storageService.saveData(`gestao93_tutorial_seen_${user.id}`, 'true'); setShowTutorial(false); }} />}
      <nav className="w-full md:w-64 bg-indigo-950 text-white flex flex-col shrink-0 z-50 shadow-2xl relative overflow-hidden">
        <div className="relative z-10 p-6 flex items-center gap-3 border-b border-indigo-900/50">
          <div className="bg-indigo-600 p-2 rounded-xl shrink-0 border border-white/20 shadow-lg">
             <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>
          </div>
          <div className="min-w-0">
            <h1 className="text-xl font-black italic uppercase text-white truncate">Gestão 93</h1>
            <div className="flex items-center gap-1">
              <div className={`w-1.5 h-1.5 rounded-full ${syncStatus === 'synced' ? 'bg-emerald-400' : 'bg-amber-400 animate-pulse'}`}></div>
              <span className="text-[8px] font-black uppercase text-indigo-300">
                {syncStatus === 'synced' ? 'Banco Local OK' : 'Gravando...'}
              </span>
            </div>
          </div>
        </div>
        <div className="relative z-10 flex-1 py-4 space-y-1 px-3 overflow-y-auto no-scrollbar">
